# ============================================================
# SAFE HELPERS
# ============================================================

def safe_float(value: Any, default: Optional[float] = None) -> Optional[float]:
        try:
                if value is None:
                        return default
                if isinstance(value, (pd.Series, pd.DataFrame, list, tuple, dict)):
                        return default
                if pd.isna(value):
                        return default
                out = float(value)
                if not np.isfinite(out):
                        return default
                return out
        except Exception:
                return default


def clamp(value: Any, low: float = 0.0, high: float = 100.0) -> float:
        x = safe_float(value, low)
        if x is None:
                x = low
        return float(max(low, min(high, x)))


def first_valid(*values: Any, default: Any = None) -> Any:
        for value in values:
                if value is None:
                        continue
                try:
                        if pd.isna(value):
                                continue
                except Exception:
                        pass
                return value
        return default


def fmt_num(value: Any, digits: int = 2) -> str:
        x = safe_float(value)
        if x is None:
                return "N/A"
        return f"{x:,.{digits}f}"


def fmt_pct(value: Any, digits: int = 2, already_percent: bool = False) -> str:
        x = safe_float(value)
        if x is None:
                return "N/A"
        if already_percent:
                return f"{x:,.{digits}f}%"
        return f"{x:,.{digits}%}"


def fmt_signed(value: Any, digits: int = 2) -> str:
        x = safe_float(value)
        if x is None:
                return "N/A"
        return f"{x:+,.{digits}f}"


def fmt_score(value: Any) -> str:
        x = safe_float(value)
        if x is None:
                return "N/A"
        return f"{round(clamp(x)):.0f}/100"


def pct_change(series: pd.Series, periods: int) -> Optional[float]:
        try:
                s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                if len(s) <= periods:
                        return None
                last = safe_float(s.iloc[-1])
                prev = safe_float(s.iloc[-1 - periods])
                if last is None or prev is None or prev == 0:
                        return None
                return last / prev - 1.0
        except Exception:
                return None


def value_change(series: pd.Series, periods: int) -> Optional[float]:
        try:
                s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                if len(s) <= periods:
                        return None
                last = safe_float(s.iloc[-1])
                prev = safe_float(s.iloc[-1 - periods])
                if last is None or prev is None:
                        return None
                return last - prev
        except Exception:
                return None


def zscore_latest(series: pd.Series, lookback: int = 260) -> Optional[float]:
        try:
                s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                if len(s) < 30:
                        return None
                use = s.tail(min(lookback, len(s)))
                std = safe_float(use.std(ddof=1))
                if std is None or std == 0:
                        return None
                return (float(use.iloc[-1]) - float(use.mean())) / std
        except Exception:
                return None


def status_from_score(score: float) -> str:
        score = clamp(score)
        if score >= 75:
                return "Strong"
        if score >= 60:
                return "Constructive"
        if score >= 40:
                return "Mixed"
        if score >= 25:
                return "Weak"
        return "Stress"


def get_secret_or_env(name: str, default: str = "") -> str:
        try:
                value = st.secrets.get(name, "")
                if value:
                        return str(value).strip()
        except Exception:
                pass
        return str(os.getenv(name, default) or "").strip()


def plotly_config() -> dict:
        return {"displayModeBar": False, "responsive": True}


