# DATA LOADERS — FRED + YAHOO PROXIES
# ============================================================

@st.cache_data(ttl=21600, show_spinner=False)
def fetch_fred_csv_series(series_id: str, start_date: str = "1990-01-01") -> pd.DataFrame:
        """
        Public FRED CSV loader without API key.
        Uses fredgraph.csv. If the endpoint is unavailable, returns an empty frame.
        """
        series_id = str(series_id or "").upper().strip()
        if not series_id:
                return pd.DataFrame(columns=["date", "value", "series_id"])

        url = FRED_CSV_URL.format(series_id=quote(series_id))
        try:
                df = pd.read_csv(url)
                if df is None or df.empty:
                        return pd.DataFrame(columns=["date", "value", "series_id"])

                # FRED CSV can use observation_date or DATE as first column depending on endpoint.
                date_col = df.columns[0]
                value_col = None
                for candidate in [series_id, series_id.upper(), series_id.lower(), "value"]:
                        if candidate in df.columns:
                                value_col = candidate
                                break
                if value_col is None and len(df.columns) >= 2:
                        value_col = df.columns[1]
                if value_col is None:
                        return pd.DataFrame(columns=["date", "value", "series_id"])

                out = df[[date_col, value_col]].copy()
                out.columns = ["date", "value"]
                out["date"] = pd.to_datetime(out["date"], errors="coerce")
                out["value"] = pd.to_numeric(out["value"].replace(".", np.nan), errors="coerce")
                out = out.dropna(subset=["date", "value"]).sort_values("date")
                if start_date:
                        out = out[out["date"] >= pd.to_datetime(start_date)]
                out["series_id"] = series_id
                return out.reset_index(drop=True)
        except Exception:
                return pd.DataFrame(columns=["date", "value", "series_id"])


@st.cache_data(ttl=21600, show_spinner=False)
def load_macro_fred_pack(series_ids: Tuple[str, ...], start_date: str = "1990-01-01") -> Dict[str, pd.DataFrame]:
        pack: Dict[str, pd.DataFrame] = {}
        for sid in series_ids:
                sid = str(sid or "").upper().strip()
                if not sid:
                        continue
                pack[sid] = fetch_fred_csv_series(sid, start_date=start_date)
        return pack


@st.cache_data(ttl=900, show_spinner=False)
def fetch_yahoo_history(symbol: str, period: str = "2y", interval: str = "1d") -> pd.DataFrame:
        symbol = str(symbol or "").strip().upper()
        if not symbol or not YFINANCE_AVAILABLE:
                return pd.DataFrame(columns=["date", "close", "volume"])
        try:
                raw = yf.download(symbol, period=period, interval=interval, progress=False, auto_adjust=True, threads=False)
                if raw is None or raw.empty:
                        return pd.DataFrame(columns=["date", "close", "volume"])
                df = raw.reset_index()
                if isinstance(df.columns, pd.MultiIndex):
                        df.columns = ["_".join([str(x) for x in col if str(x) not in ["", "None"]]).strip("_").lower() for col in df.columns]
                else:
                        df.columns = [str(c).lower().replace(" ", "_") for c in df.columns]
                date_col = "date" if "date" in df.columns else "datetime" if "datetime" in df.columns else df.columns[0]
                close_col = None
                for candidate in ["close", f"close_{symbol.lower()}", "adj_close", f"adj_close_{symbol.lower()}"]:
                        if candidate in df.columns:
                                close_col = candidate
                                break
                if close_col is None:
                        close_like = [c for c in df.columns if "close" in str(c).lower()]
                        close_col = close_like[0] if close_like else None
                if close_col is None:
                        return pd.DataFrame(columns=["date", "close", "volume"])
                out = pd.DataFrame()
                out["date"] = pd.to_datetime(df[date_col], errors="coerce")
                out["close"] = pd.to_numeric(df[close_col], errors="coerce")
                if "volume" in df.columns:
                        out["volume"] = pd.to_numeric(df["volume"], errors="coerce")
                else:
                        out["volume"] = np.nan
                out = out.dropna(subset=["date", "close"]).sort_values("date")
                out["symbol"] = symbol
                return out.reset_index(drop=True)
        except Exception:
                return pd.DataFrame(columns=["date", "close", "volume"])


@st.cache_data(ttl=900, show_spinner=False)
def load_market_proxy_pack(symbols: Tuple[str, ...], period: str = "2y") -> Dict[str, pd.DataFrame]:
        out: Dict[str, pd.DataFrame] = {}
        for symbol in symbols:
                out[symbol] = fetch_yahoo_history(symbol, period=period, interval="1d")
        return out


# ============================================================
# DATA PREPARATION
# ============================================================

def build_macro_indicator_table(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows: List[dict] = []
        for sid, meta in FRED_SERIES.items():
                df = pack.get(sid, pd.DataFrame())
                if not isinstance(df, pd.DataFrame) or df.empty:
                        rows.append({
                                "Series": sid,
                                "Indicator": meta.get("label", sid),
                                "Bloc": meta.get("bloc", "N/A"),
                                "Latest Date": "N/A",
                                "Latest": np.nan,
                                "Short Δ": np.nan,
                                "YoY / 1Y Δ": np.nan,
                                "Z-score": np.nan,
                                "Status": "Unavailable",
                                "Importance": meta.get("importance", "Medium"),
                        })
                        continue

                s = pd.to_numeric(df["value"], errors="coerce").dropna()
                latest = safe_float(s.iloc[-1]) if not s.empty else None
                latest_date = df.dropna(subset=["value"])["date"].iloc[-1] if not df.dropna(subset=["value"]).empty else None
                short_lag = int(meta.get("short_lag", 3) or 3)
                annual_lag = int(meta.get("annual_lag", 12) or 12)

                # Pour les taux / spreads / courbes : variation en points. Pour les indices : %.
                unit = str(meta.get("unit", ""))
                if unit in {"%", "pts", "bps"}:
                        short_delta = value_change(s, short_lag)
                        annual_delta = value_change(s, annual_lag)
                else:
                        short_delta = pct_change(s, short_lag)
                        annual_delta = pct_change(s, annual_lag)

                z = zscore_latest(s, lookback=260)
                status = "OK" if latest is not None else "Unavailable"
                rows.append({
                        "Series": sid,
                        "Indicator": meta.get("label", sid),
                        "Bloc": meta.get("bloc", "N/A"),
                        "Latest Date": pd.to_datetime(latest_date).strftime("%Y-%m-%d") if latest_date is not None else "N/A",
                        "Latest": latest,
                        "Short Δ": short_delta,
                        "YoY / 1Y Δ": annual_delta,
                        "Z-score": z,
                        "Status": status,
                        "Importance": meta.get("importance", "Medium"),
                })
        out = pd.DataFrame(rows)
        return out


def latest_series_value(pack: Dict[str, pd.DataFrame], series_id: str) -> Optional[float]:
        df = pack.get(series_id, pd.DataFrame())
        if not isinstance(df, pd.DataFrame) or df.empty:
                return None
        s = pd.to_numeric(df["value"], errors="coerce").dropna()
        if s.empty:
                return None
        return safe_float(s.iloc[-1])


def series_change(pack: Dict[str, pd.DataFrame], series_id: str, periods: int, pct: bool = False) -> Optional[float]:
        df = pack.get(series_id, pd.DataFrame())
        if not isinstance(df, pd.DataFrame) or df.empty:
                return None
        s = pd.to_numeric(df["value"], errors="coerce").dropna()
        if s.empty:
                return None
        return pct_change(s, periods) if pct else value_change(s, periods)


def series_yoy(pack: Dict[str, pd.DataFrame], series_id: str, default_lag: Optional[int] = None) -> Optional[float]:
        meta = FRED_SERIES.get(series_id, {})
        lag = int(default_lag or meta.get("annual_lag", 12) or 12)
        df = pack.get(series_id, pd.DataFrame())
        if not isinstance(df, pd.DataFrame) or df.empty:
                return None
        unit = str(meta.get("unit", ""))
        s = pd.to_numeric(df["value"], errors="coerce").dropna()
        if unit in {"%", "pts", "bps"}:
                return value_change(s, lag)
        return pct_change(s, lag)


# ============================================================
# MACRO SCORING
# ============================================================

def scale_between(value: Optional[float], low: float, high: float, inverse: bool = False) -> float:
        """Linear score 0-100 between low and high."""
        x = safe_float(value)
        if x is None:
                return 50.0
        if high == low:
                return 50.0
        score = (x - low) / (high - low) * 100.0
        score = clamp(score)
        return 100.0 - score if inverse else score


def build_macro_scores(pack: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
        # Growth block
        gdp_yoy = series_yoy(pack, "GDPC1", 4)
        indpro_yoy = series_yoy(pack, "INDPRO", 12)
        retail_yoy = series_yoy(pack, "RSAFS", 12)
        sentiment = latest_series_value(pack, "UMCSENT")

        growth_score = np.nanmean([
                scale_between(gdp_yoy, -0.02, 0.04),
                scale_between(indpro_yoy, -0.04, 0.04),
                scale_between(retail_yoy, -0.03, 0.08),
                scale_between(sentiment, 55, 95),
        ])

        # Inflation block: score = inflation comfort. High inflation lowers score.
        cpi_yoy = series_yoy(pack, "CPIAUCSL", 12)
        core_cpi_yoy = series_yoy(pack, "CPILFESL", 12)
        pce_yoy = series_yoy(pack, "PCEPI", 12)
        core_pce_yoy = series_yoy(pack, "PCEPILFE", 12)
        breakeven_5y = latest_series_value(pack, "T5YIE")

        inflation_pressure = np.nanmean([
                scale_between(cpi_yoy, 0.015, 0.06),
                scale_between(core_cpi_yoy, 0.015, 0.06),
                scale_between(pce_yoy, 0.015, 0.055),
                scale_between(core_pce_yoy, 0.015, 0.055),
                scale_between(breakeven_5y, 1.5, 3.2),
        ])
        inflation_score = 100.0 - clamp(inflation_pressure)

        # Labor block
        payroll_yoy = series_yoy(pack, "PAYEMS", 12)
        unrate = latest_series_value(pack, "UNRATE")
        unrate_3m_delta = series_change(pack, "UNRATE", 3, pct=False)
        claims_4w_delta = series_change(pack, "ICSA", 4, pct=True)
        wage_yoy = series_yoy(pack, "CES0500000003", 12)

        labor_score = np.nanmean([
                scale_between(payroll_yoy, -0.01, 0.03),
                scale_between(unrate, 3.0, 7.0, inverse=True),
                scale_between(unrate_3m_delta, -0.30, 0.60, inverse=True),
                scale_between(claims_4w_delta, -0.10, 0.25, inverse=True),
        ])
        wage_pressure = scale_between(wage_yoy, 0.02, 0.06)

        # Rates / curve block
        dgs2 = latest_series_value(pack, "DGS2")
        dgs10 = latest_series_value(pack, "DGS10")
        curve_10y2y = latest_series_value(pack, "T10Y2Y")
        curve_10y3m = latest_series_value(pack, "T10Y3M")
        fed_rate = latest_series_value(pack, "DFF") or latest_series_value(pack, "FEDFUNDS")

        curve_score = np.nanmean([
                scale_between(curve_10y2y, -1.00, 1.50),
                scale_between(curve_10y3m, -1.50, 1.50),
                scale_between(dgs2, 1.0, 6.0, inverse=True),
                scale_between(fed_rate, 1.0, 6.0, inverse=True),
        ])

        # Liquidity / credit block
        walcl_13w = series_change(pack, "WALCL", 13, pct=True)
        m2_yoy = series_yoy(pack, "M2SL", 12)
        hy_oas = latest_series_value(pack, "BAMLH0A0HYM2")
        ig_oas = latest_series_value(pack, "BAMLC0A0CM")
        rrp_21d = series_change(pack, "RRPONTSYD", 21, pct=False)

        liquidity_score = np.nanmean([
                scale_between(walcl_13w, -0.04, 0.04),
                scale_between(m2_yoy, -0.04, 0.08),
                scale_between(hy_oas, 250, 800, inverse=True),
                scale_between(ig_oas, 80, 240, inverse=True),
                scale_between(rrp_21d, -400, 400, inverse=True),
        ])

        # Central bank bias: mechanical, based on recent rate direction and inflation.
        fed_3m_change = series_change(pack, "DFF", 63, pct=False) or series_change(pack, "FEDFUNDS", 3, pct=False)
        policy_restrictiveness = np.nanmean([
                scale_between(fed_rate, 1.0, 6.0),
                scale_between(fed_3m_change, -0.50, 0.50),
                clamp(inflation_pressure),
        ])
        central_bank_score = 100.0 - clamp(policy_restrictiveness)

        # Composite macro risk score. This is not a trading signal.
        macro_risk_score = np.nanmean([
                0.22 * growth_score,
                0.18 * inflation_score,
                0.18 * labor_score,
                0.17 * curve_score,
                0.15 * liquidity_score,
                0.10 * central_bank_score,
        ]) * 100.0 / np.nanmean([0.22, 0.18, 0.18, 0.17, 0.15, 0.10])

        macro_risk_score = clamp(macro_risk_score)

        # Regime classification.
        growth_weak = growth_score < 40 or labor_score < 40
        inflation_hot = inflation_pressure > 65 or wage_pressure > 70
        liquidity_stress = liquidity_score < 40
        curve_stress = curve_score < 40
        central_bank_tight = central_bank_score < 40

        if growth_score >= 60 and inflation_pressure <= 45 and liquidity_score >= 55:
                regime = "Goldilocks / Soft Landing"
                regime_read = "Croissance correcte, inflation contrôlée, liquidité non stressée. Régime plutôt favorable au risque."
        elif growth_score >= 55 and inflation_hot:
                regime = "Reflation / Inflation Risk"
                regime_read = "Croissance encore présente mais inflation ou salaires trop fermes. Risque de repricing hawkish."
        elif growth_weak and inflation_hot:
                regime = "Stagflation Watch"
                regime_read = "Croissance/labor fragiles avec pression inflationniste. Régime défavorable aux multiples equity."
        elif growth_weak and not inflation_hot:
                regime = "Disinflation Slowdown"
                regime_read = "Ralentissement avec inflation moins problématique. Duration peut mieux se comporter si crédit reste stable."
        elif liquidity_stress or curve_stress:
                regime = "Liquidity / Curve Stress"
                regime_read = "Courbe, spreads ou liquidité en zone de stress. Réduire la confiance dans les signaux risk-on."
        elif central_bank_tight:
                regime = "Higher-for-Longer"
                regime_read = "Banque centrale restrictive. Le marché peut rester sensible aux données inflation/labor."
        else:
                regime = "Mixed Macro"
                regime_read = "Pas de régime dominant. Lecture par blocs nécessaire avant d'appliquer un overlay macro."

        return {
                "macro_risk_score": macro_risk_score,
                "growth_score": clamp(growth_score),
                "inflation_score": clamp(inflation_score),
                "inflation_pressure": clamp(inflation_pressure),
                "labor_score": clamp(labor_score),
                "wage_pressure": clamp(wage_pressure),
                "curve_score": clamp(curve_score),
                "liquidity_score": clamp(liquidity_score),
                "central_bank_score": clamp(central_bank_score),
                "regime": regime,
                "regime_read": regime_read,
                "inputs": {
                        "gdp_yoy": gdp_yoy,
                        "indpro_yoy": indpro_yoy,
                        "retail_yoy": retail_yoy,
                        "cpi_yoy": cpi_yoy,
                        "core_cpi_yoy": core_cpi_yoy,
                        "pce_yoy": pce_yoy,
                        "core_pce_yoy": core_pce_yoy,
                        "breakeven_5y": breakeven_5y,
                        "payroll_yoy": payroll_yoy,
                        "unrate": unrate,
                        "unrate_3m_delta": unrate_3m_delta,
                        "claims_4w_delta": claims_4w_delta,
                        "wage_yoy": wage_yoy,
                        "dgs2": dgs2,
                        "dgs10": dgs10,
                        "curve_10y2y": curve_10y2y,
                        "curve_10y3m": curve_10y3m,
                        "fed_rate": fed_rate,
                        "fed_3m_change": fed_3m_change,
                        "walcl_13w": walcl_13w,
                        "m2_yoy": m2_yoy,
                        "hy_oas": hy_oas,
                        "ig_oas": ig_oas,
                },
        }


# ============================================================
# CENTRAL BANK MONITOR
# ============================================================

def _policy_bias(latest: Optional[float], change_3m: Optional[float], change_12m: Optional[float]) -> str:
        c3 = safe_float(change_3m)
        c12 = safe_float(change_12m)
        latest = safe_float(latest)
        if latest is None:
                return "N/A"
        if c3 is not None and c3 >= 0.25:
                return "Hawkish / tightening"
        if c3 is not None and c3 <= -0.25:
                return "Dovish / easing"
        if c12 is not None and c12 >= 0.75:
                return "Restrictive trend"
        if c12 is not None and c12 <= -0.75:
                return "Easing trend"
        if latest >= 4.0:
                return "Restrictive hold"
        if latest <= 1.0:
                return "Accommodative / low-rate"
        return "Neutral hold"


def build_central_bank_monitor(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows: List[dict] = []
        for bank, spec in POLICY_RATE_SERIES.items():
                selected_series = None
                df_selected = pd.DataFrame()
                for sid in spec.get("series", []):
                        df = pack.get(sid, pd.DataFrame())
                        if isinstance(df, pd.DataFrame) and not df.empty:
                                selected_series = sid
                                df_selected = df.copy()
                                break

                if selected_series is None or df_selected.empty:
                        rows.append({
                                "Central Bank": bank,
                                "Country/Area": spec.get("country", ""),
                                "Policy Proxy": "Unavailable",
                                "Latest Date": "N/A",
                                "Latest Rate": np.nan,
                                "3M Δ": np.nan,
                                "12M Δ": np.nan,
                                "Bias": "Data unavailable",
                                "Asset Sensitivity": spec.get("asset_sensitivity", ""),
                                "Source Status": "Missing public proxy",
                        })
                        continue

                s = pd.to_numeric(df_selected["value"], errors="coerce").dropna()
                latest = safe_float(s.iloc[-1]) if not s.empty else None
                latest_date = df_selected.dropna(subset=["value"])["date"].iloc[-1] if not df_selected.dropna(subset=["value"]).empty else None
                c3 = value_change(s, 63 if selected_series == "DFF" else 3)
                c12 = value_change(s, 252 if selected_series == "DFF" else 12)
                rows.append({
                        "Central Bank": bank,
                        "Country/Area": spec.get("country", ""),
                        "Policy Proxy": selected_series,
                        "Latest Date": pd.to_datetime(latest_date).strftime("%Y-%m-%d") if latest_date is not None else "N/A",
                        "Latest Rate": latest,
                        "3M Δ": c3,
                        "12M Δ": c12,
                        "Bias": _policy_bias(latest, c3, c12),
                        "Asset Sensitivity": spec.get("asset_sensitivity", ""),
                        "Source Status": "OK public proxy",
                })
        return pd.DataFrame(rows)


def build_policy_divergence_matrix(policy_df: pd.DataFrame) -> pd.DataFrame:
        if policy_df is None or policy_df.empty or "Latest Rate" not in policy_df.columns:
                return pd.DataFrame()
        clean = policy_df.dropna(subset=["Latest Rate"]).copy()
        if clean.empty:
                return pd.DataFrame()
        rates = clean.set_index("Central Bank")["Latest Rate"].astype(float)
        banks = list(rates.index)
        matrix = pd.DataFrame(index=banks, columns=banks, dtype=float)
        for a in banks:
                for b in banks:
                        matrix.loc[a, b] = rates.loc[a] - rates.loc[b]
        return matrix.reset_index().rename(columns={"index": "Rate spread: row minus column"})


