def build_rates_curve_table(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        mapping = [
                ("3M", "DGS3MO"),
                ("2Y", "DGS2"),
                ("5Y", "DGS5"),
                ("10Y", "DGS10"),
                ("30Y", "DGS30"),
        ]
        rows = []
        for maturity, sid in mapping:
                val = latest_series_value(pack, sid)
                c1m = series_change(pack, sid, 21, pct=False)
                c1y = series_change(pack, sid, 252, pct=False)
                rows.append({"Maturity": maturity, "Series": sid, "Yield": val, "1M Δ": c1m, "1Y Δ": c1y})
        curve = pd.DataFrame(rows)
        return curve


def curve_state(pack: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
        y2 = latest_series_value(pack, "DGS2")
        y10 = latest_series_value(pack, "DGS10")
        y30 = latest_series_value(pack, "DGS30")
        slope_10_2 = latest_series_value(pack, "T10Y2Y")
        slope_10_3m = latest_series_value(pack, "T10Y3M")

        if slope_10_2 is None and y10 is not None and y2 is not None:
                slope_10_2 = y10 - y2

        if slope_10_2 is None:
                state = "Unavailable"
                read = "Courbe indisponible."
        elif slope_10_2 < -0.75:
                state = "Deep inversion"
                read = "Courbe très inversée : le marché price souvent un ralentissement ou des baisses futures."
        elif slope_10_2 < 0:
                state = "Inversion"
                read = "Courbe inversée : signal de pression sur croissance future / politique restrictive."
        elif slope_10_2 < 0.75:
                state = "Flat / early steepening"
                read = "Courbe proche de plat. Surveiller bull steepening vs bear steepening."
        else:
                state = "Steep"
                read = "Courbe pentue : régime plus favorable aux banques/cycliques si croissance tient."

        return {
                "2Y": y2,
                "10Y": y10,
                "30Y": y30,
                "10Y-2Y": slope_10_2,
                "10Y-3M": slope_10_3m,
                "state": state,
                "read": read,
        }


def build_market_proxy_table(proxy_pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows: List[dict] = []
        for symbol, meta in MARKET_PROXIES.items():
                df = proxy_pack.get(symbol, pd.DataFrame())
                if not isinstance(df, pd.DataFrame) or df.empty:
                        rows.append({
                                "Symbol": symbol,
                                "Instrument": meta.get("label", symbol),
                                "Type": meta.get("type", "N/A"),
                                "Last": np.nan,
                                "1D": np.nan,
                                "5D": np.nan,
                                "20D": np.nan,
                                "Vol 20D": np.nan,
                                "Status": "Unavailable",
                        })
                        continue
                s = pd.to_numeric(df["close"], errors="coerce").dropna()
                ret = s.pct_change().dropna()
                last = safe_float(s.iloc[-1])
                rows.append({
                        "Symbol": symbol,
                        "Instrument": meta.get("label", symbol),
                        "Type": meta.get("type", "N/A"),
                        "Last": last,
                        "1D": pct_change(s, 1),
                        "5D": pct_change(s, 5),
                        "20D": pct_change(s, 20),
                        "Vol 20D": safe_float(ret.tail(20).std(ddof=1) * math.sqrt(TRADING_DAYS)) if len(ret) >= 20 else np.nan,
                        "Status": "OK",
                })
        return pd.DataFrame(rows)


def normalize_price_frame(price_data: pd.DataFrame) -> pd.DataFrame:
        if price_data is None or not isinstance(price_data, pd.DataFrame) or price_data.empty:
                return pd.DataFrame()
        df = price_data.copy()
        if isinstance(df.columns, pd.MultiIndex):
                df.columns = ["_".join([str(x) for x in col if str(x) not in ["", "None"]]).strip("_").lower() for col in df.columns]
        else:
                df.columns = [str(c).lower().replace(" ", "_") for c in df.columns]
        if "date" not in df.columns:
                df = df.reset_index().rename(columns={"index": "date", "datetime": "date"})
        if "close" not in df.columns and "adj_close" in df.columns:
                df["close"] = df["adj_close"]
        if "date" not in df.columns or "close" not in df.columns:
                return pd.DataFrame()
        out = df[["date", "close"]].copy()
        out["date"] = pd.to_datetime(out["date"], errors="coerce").dt.tz_localize(None)
        out["close"] = pd.to_numeric(out["close"], errors="coerce")
        out = out.dropna(subset=["date", "close"]).sort_values("date")
        out = out.drop_duplicates("date", keep="last")
        return out.reset_index(drop=True)


def build_macro_beta_table(ticker: str, price_data: pd.DataFrame, proxy_pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        base = normalize_price_frame(price_data)
        if base.empty:
                return pd.DataFrame()
        base_series = base.set_index("date")["close"].astype(float)
        base_ret = base_series.pct_change().dropna()
        rows: List[dict] = []
        for symbol, meta in MARKET_PROXIES.items():
                df = proxy_pack.get(symbol, pd.DataFrame())
                if not isinstance(df, pd.DataFrame) or df.empty:
                        continue
                proxy_series = df.copy()
                proxy_series["date"] = pd.to_datetime(proxy_series["date"], errors="coerce").dt.tz_localize(None)
                proxy_close = proxy_series.dropna(subset=["date", "close"]).set_index("date")["close"].astype(float)
                proxy_ret = proxy_close.pct_change().dropna()
                aligned = pd.concat([base_ret.rename("asset"), proxy_ret.rename("proxy")], axis=1).dropna()
                if len(aligned) < 40:
                        continue
                var_proxy = aligned["proxy"].var(ddof=1)
                beta = np.nan if var_proxy == 0 else aligned["asset"].cov(aligned["proxy"]) / var_proxy
                corr = aligned["asset"].corr(aligned["proxy"])
                rows.append({
                        "Ticker": str(ticker).upper(),
                        "Macro Proxy": symbol,
                        "Instrument": meta.get("label", symbol),
                        "Type": meta.get("type", "N/A"),
                        "Beta": beta,
                        "Correlation": corr,
                        "Obs": len(aligned),
                        "Read": beta_read(symbol, beta, corr),
                })
        if not rows:
                return pd.DataFrame()
        out = pd.DataFrame(rows)
        return out.sort_values("Correlation", key=lambda s: s.abs(), ascending=False)


def beta_read(symbol: str, beta: Any, corr: Any) -> str:
        b = safe_float(beta)
        c = safe_float(corr)
        if b is None or c is None:
                return "N/A"
        if abs(c) < 0.20:
                return "Faible lien historique"
        if symbol in {"TLT"}:
                return "Duration-sensitive" if b > 0 else "Pressure from duration rally / inverse duration"
        if symbol in {"UUP", "USDJPY=X"}:
                return "Dollar-positive beta" if b > 0 else "Dollar-negative beta"
        if symbol == "^VIX":
                return "Risk-off positive beta" if b > 0 else "Risk-off vulnerable"
        if symbol in {"GC=F"}:
                return "Gold-positive beta" if b > 0 else "Gold hedge inverse"
        if symbol in {"CL=F"}:
                return "Oil/cyclical beta" if b > 0 else "Inverse oil beta"
        return "Positive macro beta" if b > 0 else "Negative macro beta"


