def display_macro_table(df: pd.DataFrame, height: int = 420) -> None:
        if df is None or df.empty:
                st.info("Table indisponible.")
                return
        st.dataframe(df, use_container_width=True, hide_index=True, height=height)


def plot_score_bars(scores: Dict[str, Any]) -> None:
        labels = [
                "Growth",
                "Inflation comfort",
                "Labor",
                "Rates / Curve",
                "Liquidity / Credit",
                "Central Bank",
                "Composite",
        ]
        values = [
                scores.get("growth_score"),
                scores.get("inflation_score"),
                scores.get("labor_score"),
                scores.get("curve_score"),
                scores.get("liquidity_score"),
                scores.get("central_bank_score"),
                scores.get("macro_risk_score"),
        ]
        fig = go.Figure()
        fig.add_trace(go.Bar(x=labels, y=values, text=[fmt_score(v) for v in values], textposition="auto"))
        fig.update_layout(
                height=360,
                margin=dict(l=20, r=20, t=40, b=20),
                title="Macro regime score map",
                yaxis=dict(range=[0, 100]),
        )
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def plot_fred_series(pack: Dict[str, pd.DataFrame], series_ids: List[str], title: str, normalize: bool = False) -> None:
        fig = go.Figure()
        added = 0
        for sid in series_ids:
                df = pack.get(sid, pd.DataFrame())
                if not isinstance(df, pd.DataFrame) or df.empty:
                        continue
                use = df.dropna(subset=["date", "value"]).copy()
                if use.empty:
                        continue
                y = pd.to_numeric(use["value"], errors="coerce")
                if normalize and y.dropna().shape[0] > 0:
                        first = y.dropna().iloc[0]
                        if first != 0:
                                y = y / first * 100.0
                fig.add_trace(go.Scatter(x=use["date"], y=y, mode="lines", name=FRED_SERIES.get(sid, {}).get("label", sid)))
                added += 1
        if added <= 0:
                st.info(f"{title} indisponible.")
                return
        fig.update_layout(height=420, margin=dict(l=20, r=20, t=45, b=20), title=title, legend=dict(orientation="h"))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def plot_yield_curve(curve_df: pd.DataFrame) -> None:
        if curve_df is None or curve_df.empty or "Yield" not in curve_df.columns:
                st.info("Courbe des taux indisponible.")
