                {"Provider": "BIS SDMX", "Status": "Prepared for V2", "Use": "Global liquidity, credit, banking, FX, derivatives", "Key required": "No"},
                {"Provider": "Trading Economics", "Status": "Recommended V2", "Use": "Economic calendar, actual/consensus/previous/revisions", "Key required": "Yes"},
                {"Provider": "Bloomberg / LSEG / Macrobond / Haver", "Status": "Premium V3", "Use": "Institutional real-time data, consensus, central bank tooling", "Key required": "Subscription"},
