def _cb_profile_v3(bank: str) -> Dict[str, Any]:
        return CENTRAL_BANK_PROFILES_V3.get(str(bank), CENTRAL_BANK_PROFILES_V3["Federal Reserve"])


def _cb_bank_order_v3() -> List[str]:
        return list(CENTRAL_BANK_PROFILES_V3.keys())


def _numeric_from_macro_value_v3(value: Any) -> Optional[float]:
        """Parse actual/consensus/previous values from providers or uploaded calendars."""
        x = safe_float(value)
        if x is not None:
                return x
        if value is None:
                return None
        text = str(value).strip()
        if not text or text.lower() in {"nan", "none", "n/a", "na", "--"}:
                return None
        multiplier = 1.0
        if text.endswith("%"):
                text = text[:-1]
        if text.upper().endswith("K"):
                multiplier = 1_000.0
                text = text[:-1]
        elif text.upper().endswith("M"):
                multiplier = 1_000_000.0
                text = text[:-1]
        elif text.upper().endswith("B"):
                multiplier = 1_000_000_000.0
                text = text[:-1]
        text = text.replace(",", "").replace(" ", "")
        try:
                out = float(text) * multiplier
                return out if np.isfinite(out) else None
        except Exception:
                return None


def _infer_central_bank_from_event_v3(country: Any = None, event: Any = None, central_bank: Any = None) -> str:
        raw_cb = str(central_bank or "").strip()
        if raw_cb:
                low = raw_cb.lower()
                for bank, profile in CENTRAL_BANK_PROFILES_V3.items():
                        names = [bank, profile.get("short", "")]
                        if any(str(x).lower() in low or low in str(x).lower() for x in names if x):
                                return bank

        c = str(country or "").strip().lower()
        e = str(event or "").strip().lower()
        joined = f"{c} {e}"

        for bank, profile in CENTRAL_BANK_PROFILES_V3.items():
                aliases = [str(x).lower() for x in profile.get("country_aliases", [])]
                short = str(profile.get("short", "")).lower()
                if any(alias and alias in joined for alias in aliases):
                        return bank
                if short and short.lower() in joined:
                        return bank
                if bank.lower() in joined:
                        return bank
                for ev in profile.get("decision_events", []):
                        if str(ev).lower() in joined:
                                return bank

        return "Federal Reserve"


def _classify_event_bloc_v3(event: Any, central_bank: Any = None) -> str:
        text = f"{central_bank or ''} {event or ''}".lower()
        if any(k in text for k in ["rate decision", "interest rate", "fomc", "ecb", "boe", "boj", "snb", "boc", "rba", "minutes", "speech", "press conference", "dot plot", "sep"]):
                return "Central Bank"
        if any(k in text for k in ["cpi", "pce", "hicp", "inflation", "prices paid", "ppi", "trimmed mean"]):
                return "Inflation"
        if any(k in text for k in ["payroll", "nfp", "unemployment", "employment", "jobless", "claims", "wage", "earnings", "claimant"]):
                return "Labor"
        if any(k in text for k in ["gdp", "pmi", "ism", "retail", "industrial", "production", "sentiment", "confidence", "ifo", "zew", "tankan"]):
                return "Growth"
        if any(k in text for k in ["credit", "spread", "oas", "lending", "loan"]):
                return "Credit"
        return "Macro"


def _importance_score_v3(value: Any) -> str:
        txt = str(value or "").strip()
        if not txt:
                return "Medium"
        low = txt.lower()
        if low in {"3", "high", "important", "critical"}:
                return "High"
        if low in {"2", "medium", "moderate"}:
                return "Medium"
        if low in {"1", "low"}:
                return "Low"
        return txt.title()


def _hawkish_dovish_read_v3(bloc: str, actual: Optional[float], consensus: Optional[float], previous: Optional[float], event: str) -> Tuple[str, str]:
        """Mechanical macro interpretation of a release surprise."""
        if actual is None or consensus is None:
                return "No consensus", "Actual/consensus missing; use qualitative playbook."

        surprise = actual - consensus
        event_low = str(event or "").lower()

        # Higher-than-consensus inflation and wages are usually hawkish for CBs.
        if bloc == "Inflation" or "wage" in event_low or "earnings" in event_low:
                if surprise > 0:
                        return "Hawkish surprise", "Inflation/wage data above consensus: front-end rates and currency may reprice higher."
                if surprise < 0:
                        return "Dovish surprise", "Inflation/wage data below consensus: duration and risk assets may get relief."
                return "In line", "No clear policy surprise."

        # Labor can be ambiguous. Strong jobs is hawkish unless unemployment/claims are the metric.
        if bloc == "Labor":
                inverse_labor = any(k in event_low for k in ["unemployment", "jobless", "claims", "claimant"])
                effective = -surprise if inverse_labor else surprise
                if effective > 0:
                        return "Hawkish growth surprise", "Labor strength above consensus: cuts can be pushed out if inflation is not solved."
                if effective < 0:
                        return "Dovish slowdown surprise", "Labor weakness vs consensus: growth risk and easing probability can rise."
                return "In line", "No clear labor surprise."

        if bloc == "Growth":
                if surprise > 0:
                        return "Growth-positive / potentially hawkish", "Growth above consensus supports cyclicals but can reduce urgency for cuts."
                if surprise < 0:
                        return "Growth-negative / potentially dovish", "Growth below consensus supports easing narrative but can hurt cyclicals/credit."
                return "In line", "No clear growth surprise."

        if bloc == "Central Bank":
                if surprise > 0:
                        return "Hawkish policy surprise", "Decision/rate above expectation: currency and front-end yields may rise; risk multiples vulnerable."
                if surprise < 0:
                        return "Dovish policy surprise", "Decision/rate below expectation: duration and risk assets may get initial relief; watch credibility."
                return "In line policy", "Decision near consensus; statement and press conference matter more."

        if surprise > 0:
                return "Positive surprise", "Macro value above consensus. Direction depends on inflation/growth context."
        if surprise < 0:
                return "Negative surprise", "Macro value below consensus. Direction depends on inflation/growth context."
        return "In line", "No clear surprise."


def normalize_calendar_frame_v3(raw: pd.DataFrame) -> pd.DataFrame:
        """Normalize Trading Economics / uploaded CSV calendar to a stable schema."""
        if raw is None or not isinstance(raw, pd.DataFrame) or raw.empty:
                return pd.DataFrame(columns=[
                        "Date", "Time", "Central Bank", "Country", "Currency", "Bloc", "Event", "Actual", "Consensus", "Previous", "Revised", "Raw Surprise", "Revision Shock", "Surprise Read", "Market Read", "Importance", "Source", "Status"
                ])

        df = raw.copy()
        df.columns = [str(c).strip() for c in df.columns]
        lower_map = {str(c).strip().lower().replace(" ", "_"): c for c in df.columns}

        def pick(*names: str) -> Optional[str]:
                for name in names:
                        key = name.lower().replace(" ", "_")
                        if key in lower_map:
                                return lower_map[key]
                return None

        date_col = pick("date", "datetime", "calendar_date", "release_date")
        time_col = pick("time", "release_time")
        country_col = pick("country", "area", "region")
        currency_col = pick("currency", "ccy")
        bank_col = pick("central_bank", "central bank", "bank")
        event_col = pick("event", "category", "indicator", "name")
        actual_col = pick("actual", "latest")
        consensus_col = pick("consensus", "forecast", "estimate", "expected")
        previous_col = pick("previous", "prev")
        revised_col = pick("revised", "revision", "revised_previous")
        importance_col = pick("importance", "impact", "priority")
        source_col = pick("source", "provider")

        out = pd.DataFrame()
        out["Date"] = pd.to_datetime(df[date_col], errors="coerce") if date_col else pd.NaT
        out["Time"] = df[time_col].astype(str) if time_col else ""
        out["Country"] = df[country_col].astype(str) if country_col else ""
        out["Currency"] = df[currency_col].astype(str) if currency_col else ""
        out["Event"] = df[event_col].astype(str) if event_col else ""
        out["Central Bank"] = [
                _infer_central_bank_from_event_v3(
                        country=out["Country"].iloc[i] if i < len(out) else "",
                        event=out["Event"].iloc[i] if i < len(out) else "",
                        central_bank=df[bank_col].iloc[i] if bank_col else "",
                )
                for i in range(len(df))
        ]
        out["Bloc"] = [_classify_event_bloc_v3(ev, cb) for ev, cb in zip(out["Event"], out["Central Bank"])]
        out["Actual"] = df[actual_col].map(_numeric_from_macro_value_v3) if actual_col else np.nan
        out["Consensus"] = df[consensus_col].map(_numeric_from_macro_value_v3) if consensus_col else np.nan
        out["Previous"] = df[previous_col].map(_numeric_from_macro_value_v3) if previous_col else np.nan
        out["Revised"] = df[revised_col].map(_numeric_from_macro_value_v3) if revised_col else np.nan
        out["Raw Surprise"] = out["Actual"] - out["Consensus"]
        out["Revision Shock"] = out["Revised"] - out["Previous"]
        reads = [_hawkish_dovish_read_v3(bloc, a, c, p, ev) for bloc, a, c, p, ev in zip(out["Bloc"], out["Actual"], out["Consensus"], out["Previous"], out["Event"])]
        out["Surprise Read"] = [r[0] for r in reads]
        out["Market Read"] = [r[1] for r in reads]
        out["Importance"] = df[importance_col].map(_importance_score_v3) if importance_col else "Medium"
        out["Source"] = df[source_col].astype(str) if source_col else "Uploaded / Provider"
        out["Status"] = np.where(out["Actual"].notna() & out["Consensus"].notna(), "Scored", "Awaiting actual/consensus")
        out = out.sort_values(["Date", "Central Bank", "Event"], na_position="last").reset_index(drop=True)
        return out


def load_uploaded_calendar_v3(uploaded_file: Any) -> pd.DataFrame:
        if uploaded_file is None:
                return pd.DataFrame()
        try:
                name = str(getattr(uploaded_file, "name", "")).lower()
                if name.endswith(('.xlsx', '.xls')):
                        raw = pd.read_excel(uploaded_file)
                else:
                        raw = pd.read_csv(uploaded_file)
                return normalize_calendar_frame_v3(raw)
        except Exception as exc:
                st.warning(f"Impossible de lire le calendrier uploadé : {exc}")
                return pd.DataFrame()


def get_trading_economics_auth_v3() -> str:
        """Accepts either TRADING_ECONOMICS_CLIENT + TRADING_ECONOMICS_KEY or TRADING_ECONOMICS_API_KEY."""
        client = get_secret_or_env("TRADING_ECONOMICS_CLIENT", "")
        key = get_secret_or_env("TRADING_ECONOMICS_KEY", "")
        combined = get_secret_or_env("TRADING_ECONOMICS_API_KEY", "") or get_secret_or_env("TE_API_KEY", "")
        if client and key:
                return f"{client}:{key}"
        return combined


@st.cache_data(ttl=900, show_spinner=False)
def fetch_trading_economics_calendar_v3(days_back: int = 5, days_forward: int = 30) -> pd.DataFrame:
        auth = get_trading_economics_auth_v3()
        if not auth or not REQUESTS_AVAILABLE:
                return pd.DataFrame()
        try:
                start = (datetime.utcnow() - timedelta(days=int(days_back))).strftime("%Y-%m-%d")
                end = (datetime.utcnow() + timedelta(days=int(days_forward))).strftime("%Y-%m-%d")
                url = "https://api.tradingeconomics.com/calendar"
                params = {"c": auth, "d1": start, "d2": end, "f": "json"}
                resp = requests.get(url, params=params, timeout=20)
                resp.raise_for_status()
                payload = resp.json()
                raw = pd.DataFrame(payload if isinstance(payload, list) else payload.get("data", []))
                if raw.empty:
                        return pd.DataFrame()
                raw["Source"] = "Trading Economics"
                return normalize_calendar_frame_v3(raw)
        except Exception:
                return pd.DataFrame()


def build_structural_calendar_v3() -> pd.DataFrame:
        """Provider-free central-bank calendar skeleton. It is not a real date feed; it is a readiness/playbook table."""
        rows: List[dict] = []
        for bank, profile in CENTRAL_BANK_PROFILES_V3.items():
                for event in profile.get("decision_events", [])[:3]:
                        rows.append({
                                "Date": pd.NaT,
                                "Time": "Provider required",
                                "Central Bank": bank,
                                "Country": profile.get("country", ""),
                                "Currency": profile.get("currency", ""),
                                "Bloc": "Central Bank",
                                "Event": event,
                                "Actual": np.nan,
                                "Consensus": np.nan,
                                "Previous": np.nan,
                                "Revised": np.nan,
                                "Raw Surprise": np.nan,
                                "Revision Shock": np.nan,
                                "Surprise Read": "Awaiting provider",
                                "Market Read": f"Watch {profile.get('sensitivity', '')}",
                                "Importance": "High",
                                "Source": "Structural playbook",
                                "Status": "No live calendar provider",
                        })
                for event in profile.get("macro_events", [])[:6]:
                        bloc = _classify_event_bloc_v3(event, bank)
                        rows.append({
                                "Date": pd.NaT,
                                "Time": "Provider required",
                                "Central Bank": bank,
                                "Country": profile.get("country", ""),
                                "Currency": profile.get("currency", ""),
                                "Bloc": bloc,
                                "Event": event,
                                "Actual": np.nan,
                                "Consensus": np.nan,
                                "Previous": np.nan,
                                "Revised": np.nan,
                                "Raw Surprise": np.nan,
                                "Revision Shock": np.nan,
                                "Surprise Read": "Awaiting provider",
                                "Market Read": f"Map surprise through {profile.get('short', bank)} reaction function.",
                                "Importance": "High" if bloc in {"Central Bank", "Inflation", "Labor"} else "Medium",
                                "Source": "Structural playbook",
                                "Status": "No live calendar provider",
                        })
        return pd.DataFrame(rows)


def build_calendar_dataset_v3(source_mode: str, uploaded_file: Any = None, days_back: int = 5, days_forward: int = 30) -> pd.DataFrame:
        mode = str(source_mode or "Structural fallback")
        if "Upload" in mode:
                df = load_uploaded_calendar_v3(uploaded_file)
                return df if not df.empty else build_structural_calendar_v3()
        if "Trading Economics" in mode:
                df = fetch_trading_economics_calendar_v3(days_back=days_back, days_forward=days_forward)
                return df if not df.empty else build_structural_calendar_v3()
        return build_structural_calendar_v3()


def format_calendar_display_v3(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
                return pd.DataFrame()
        out = df.copy()
        if "Date" in out.columns:
                out["Date"] = pd.to_datetime(out["Date"], errors="coerce").dt.strftime("%Y-%m-%d").fillna("Provider required")
        for col in ["Actual", "Consensus", "Previous", "Revised", "Raw Surprise", "Revision Shock"]:
                if col in out.columns:
                        out[col] = out[col].map(lambda x: fmt_num(x, 3))
        keep = [
                "Date", "Time", "Central Bank", "Country", "Currency", "Bloc", "Event",
                "Actual", "Consensus", "Previous", "Revised", "Raw Surprise", "Revision Shock",
                "Surprise Read", "Importance", "Source", "Status",
        ]
        return out[[c for c in keep if c in out.columns]]


def _central_bank_policy_row_v3(policy_df: pd.DataFrame, bank: str) -> Dict[str, Any]:
        if policy_df is None or policy_df.empty or "Central Bank" not in policy_df.columns:
                return {}
        sub = policy_df.loc[policy_df["Central Bank"].astype(str) == str(bank)]
        if sub.empty:
                return {}
        return dict(sub.iloc[0])


