def build_bank_dashboard_rows_v3(bank: str, pack: Dict[str, pd.DataFrame], policy_df: pd.DataFrame, scores: Dict[str, Any]) -> pd.DataFrame:
        profile = _cb_profile_v3(bank)
        policy = _central_bank_policy_row_v3(policy_df, bank)
        rows = []
        latest_rate = policy.get("Latest Rate", np.nan)
        c3 = policy.get("3M Δ", np.nan)
        c12 = policy.get("12M Δ", np.nan)
        rows.append({"Metric": "Policy proxy", "Value": policy.get("Policy Proxy", "Unavailable"), "Read": policy.get("Source Status", "N/A")})
        rows.append({"Metric": "Latest policy rate", "Value": fmt_num(latest_rate, 2), "Read": policy.get("Bias", "N/A")})
        rows.append({"Metric": "3M policy momentum", "Value": fmt_num(c3, 2), "Read": "Tightening" if safe_float(c3) and safe_float(c3) > 0 else "Easing/flat"})
        rows.append({"Metric": "12M policy momentum", "Value": fmt_num(c12, 2), "Read": "Restrictive trend" if safe_float(c12) and safe_float(c12) > 0 else "Easing/flat"})
        rows.append({"Metric": "Currency", "Value": profile.get("currency", "N/A"), "Read": profile.get("sensitivity", "")})

        if bank == "Federal Reserve":
                rows.extend([
                        {"Metric": "Fed inflation comfort", "Value": fmt_score(scores.get("inflation_score")), "Read": "Lower score = more policy pressure"},
                        {"Metric": "Fed labor score", "Value": fmt_score(scores.get("labor_score")), "Read": "Lower score = labor/growth fragility"},
                        {"Metric": "US curve score", "Value": fmt_score(scores.get("curve_score")), "Read": "Lower score = restrictive curve/rates state"},
                ])
        else:
                rows.append({"Metric": "Macro data depth", "Value": "Proxy only", "Read": "V3 keeps official non-US macro ready for ECB/BIS/OECD/TE integration."})
        return pd.DataFrame(rows)


def build_central_bank_event_summary_v3(calendar_df: pd.DataFrame) -> pd.DataFrame:
        if calendar_df is None or calendar_df.empty:
                return pd.DataFrame()
        work = calendar_df.copy()
        rows = []
        for bank in _cb_bank_order_v3():
                sub = work.loc[work["Central Bank"].astype(str) == bank] if "Central Bank" in work.columns else pd.DataFrame()
                if sub.empty:
                        rows.append({"Central Bank": bank, "Events": 0, "Scored": 0, "High Impact": 0, "Next Event": "N/A", "Main Risk": "No calendar data"})
                        continue
                scored = int((sub.get("Status", "") == "Scored").sum()) if "Status" in sub.columns else 0
                high = int((sub.get("Importance", "").astype(str).str.lower() == "high").sum()) if "Importance" in sub.columns else 0
                dated = sub.dropna(subset=["Date"]) if "Date" in sub.columns else pd.DataFrame()
                next_event = "Provider required"
                if not dated.empty:
                        future = dated.sort_values("Date").head(1)
                        next_event = str(future.iloc[0].get("Event", "N/A"))
                # Main risk from most recent/scored surprise.
                scored_sub = sub.loc[sub.get("Status", pd.Series(index=sub.index, dtype=str)).astype(str) == "Scored"] if "Status" in sub.columns else pd.DataFrame()
                if not scored_sub.empty:
                        main_risk = str(scored_sub.tail(1).iloc[0].get("Surprise Read", "Scored"))
                else:
                        main_risk = "Awaiting actual/consensus"
                rows.append({"Central Bank": bank, "Events": len(sub), "Scored": scored, "High Impact": high, "Next Event": next_event, "Main Risk": main_risk})
        return pd.DataFrame(rows)


def render_central_bank_one_bank_v3(bank: str, pack: Dict[str, pd.DataFrame], policy_df: pd.DataFrame, scores: Dict[str, Any], calendar_df: pd.DataFrame) -> None:
        profile = _cb_profile_v3(bank)
        policy = _central_bank_policy_row_v3(policy_df, bank)

        st.markdown(f"### {profile.get('short', bank)} — {bank}")
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Policy rate", fmt_num(policy.get("Latest Rate"), 2))
        c2.metric("3M Δ", fmt_num(policy.get("3M Δ"), 2))
        c3.metric("12M Δ", fmt_num(policy.get("12M Δ"), 2))
        c4.metric("Currency", profile.get("currency", "N/A"))
        st.caption(f"Sensitivity: {profile.get('sensitivity', '')}")

        left, right = st.columns([0.9, 1.1])
        with left:
                st.markdown("#### Policy dashboard")
                display_macro_table(build_bank_dashboard_rows_v3(bank, pack, policy_df, scores), height=300)
        with right:
                st.markdown("#### Reaction function")
                display_macro_table(build_bank_reaction_function_v3(bank), height=300)

        st.markdown("#### Calendar / surprises for this central bank")
        if calendar_df is not None and not calendar_df.empty and "Central Bank" in calendar_df.columns:
                sub = calendar_df.loc[calendar_df["Central Bank"].astype(str) == bank].copy()
        else:
                sub = pd.DataFrame()
        display_macro_table(format_calendar_display_v3(sub), height=360)

        st.markdown("#### Required events")
        required = []
        for e in profile.get("decision_events", []):
                required.append({"Type": "Central Bank", "Event": e, "Priority": "High", "Why it matters": "Direct policy-rate / guidance repricing."})
        for e in profile.get("macro_events", []):
                required.append({"Type": _classify_event_bloc_v3(e, bank), "Event": e, "Priority": "High" if _classify_event_bloc_v3(e, bank) in {"Inflation", "Labor"} else "Medium", "Why it matters": "Feeds the central-bank reaction function."})
        display_macro_table(pd.DataFrame(required), height=300)


def render_central_bank_section(pack: Dict[str, pd.DataFrame], policy_df: pd.DataFrame, scores: Optional[Dict[str, Any]] = None, calendar_df: Optional[pd.DataFrame] = None) -> None:
        """V3 override: Central Bank Monitor is explicitly organized by central bank."""
        scores = scores or {}
        calendar_df = calendar_df if isinstance(calendar_df, pd.DataFrame) else build_structural_calendar_v3()

        st.subheader("Central Bank Monitor — by central bank")
        st.caption(
                "V3 organise la couche macro par banque centrale : policy proxy, reaction function, required events, calendar/surprise table and asset transmission."
        )

        summary = build_central_bank_event_summary_v3(calendar_df)
        top = st.columns(4)
        top[0].metric("Central banks", str(len(CENTRAL_BANK_PROFILES_V3)))
        top[1].metric("Calendar rows", str(len(calendar_df) if calendar_df is not None else 0))
        top[2].metric("Scored surprises", str(int((calendar_df.get("Status", pd.Series(dtype=str)).astype(str) == "Scored").sum()) if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and "Status" in calendar_df.columns else 0))
        top[3].metric("Provider", str(calendar_df["Source"].dropna().iloc[0]) if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and "Source" in calendar_df.columns else "Structural")

        overview_tab, banks_tab, matrix_tab = st.tabs(["Overview", "By Central Bank", "Policy Divergence"])

        with overview_tab:
                st.markdown("#### Central-bank coverage summary")
                display_macro_table(summary, height=300)
                st.markdown("#### Policy proxies")
                display_macro_table(format_policy_display(policy_df), height=330)

        with banks_tab:
                bank_tabs = st.tabs([_cb_profile_v3(b).get("short", b) for b in _cb_bank_order_v3()])
                for tab, bank in zip(bank_tabs, _cb_bank_order_v3()):
                        with tab:
                                render_central_bank_one_bank_v3(bank, pack, policy_df, scores, calendar_df)

        with matrix_tab:
                matrix = build_policy_divergence_matrix(policy_df)
                st.markdown("#### Policy divergence matrix")
                if matrix.empty:
                        st.info("Matrice indisponible : pas assez de proxies banques centrales chargés.")
                else:
                        display = matrix.copy()
                        for col in display.columns:
                                if col != "Rate spread: row minus column":
                                        display[col] = display[col].map(lambda x: fmt_num(x, 2))
                        st.dataframe(display, use_container_width=True, hide_index=True, height=420)
                plot_fred_series(pack, ["DFF", "DGS2", "DGS10"], "Fed / US rates monitor", normalize=False)


