def _relative_surprise_v4(actual: Any, consensus: Any, previous: Any = None) -> Optional[float]:
        """Raw surprise scaled by the best available base. Kept robust for rates, percentages and levels."""
        a = safe_float(actual)
        c = safe_float(consensus)
        p = safe_float(previous)
        if a is None or c is None:
                return None
        raw = a - c
        base = abs(c) if c not in [None, 0] else abs(p) if p not in [None, 0] else None
        if base is None or base == 0:
                return raw
        return raw / base


def _policy_score_from_event_v4(bloc: Any, event: Any, actual: Any, consensus: Any, previous: Any = None) -> tuple[float, str, str]:
        """
        Returns: policy_score, policy_read, direction.
        policy_score > 0 = hawkish / less easing.
        policy_score < 0 = dovish / more easing or growth shock.
        """
        a = safe_float(actual)
        c = safe_float(consensus)
        p = safe_float(previous)
        if a is None or c is None:
                return 0.0, "Awaiting actual/consensus", "Unscored"

        raw = a - c
        rel = _relative_surprise_v4(a, c, p)
        bloc_s = str(bloc or "Macro")
        e = str(event or "").lower()

        inverse = any(k in e for k in ["unemployment", "jobless", "claims", "claimant", "vacancy", "layoff"])
        inflation_like = bloc_s == "Inflation" or any(k in e for k in ["cpi", "pce", "hicp", "ppi", "inflation", "wage", "earnings", "prices paid", "trimmed mean"])
        policy_like = bloc_s == "Central Bank" or any(k in e for k in ["rate decision", "interest rate", "fomc", "deposit facility", "refinancing", "mpc"])
        growth_like = bloc_s in {"Growth", "Labor"}

        effective = -raw if inverse else raw

        if policy_like:
                # Rate decisions: use raw percentage-point surprise. 25 bp is material.
                score = raw / 0.25 if abs(raw) <= 2.0 else raw
                label = "Hawkish policy surprise" if raw > 0 else "Dovish policy surprise" if raw < 0 else "In-line policy"
        elif inflation_like:
                scale = rel if rel is not None else raw
                score = scale * 10.0 if abs(scale) < 1 else scale
                label = "Hawkish inflation surprise" if raw > 0 else "Dovish inflation surprise" if raw < 0 else "In-line inflation"
        elif growth_like:
                scale = _relative_surprise_v4(a, c, p)
                score = (scale * 8.0 if scale is not None and abs(scale) < 1 else effective)
                label = "Growth/labor hawkish" if effective > 0 else "Growth/labor dovish" if effective < 0 else "In-line growth/labor"
        else:
                scale = rel if rel is not None else raw
                score = scale * 5.0 if abs(scale) < 1 else scale
                label = "Positive macro surprise" if raw > 0 else "Negative macro surprise" if raw < 0 else "In-line macro"

        score = float(max(-3.0, min(3.0, score))) if np.isfinite(score) else 0.0
        if score >= 1.0:
                direction = "Hawkish"
        elif score <= -1.0:
                direction = "Dovish / slowdown"
        else:
                direction = "Mild / in-line"
        return score, label, direction


def _asset_transmission_v4(bank: str, bloc: Any, policy_score: Any, event: Any) -> tuple[str, str, str, str]:
        profile = _cb_profile_v3(bank)
        ccy = profile.get("currency", "")
        score = safe_float(policy_score, 0.0) or 0.0
        bloc_s = str(bloc or "Macro")
        if score >= 1.0:
                return (
                        "Front-end yields higher / curve can bear-flatten",
                        f"{ccy} supported if growth holds",
                        "Duration and high-multiple equity vulnerable",
                        "Gold can weaken if real yields rise",
                )
        if score <= -1.0:
                if bloc_s in {"Growth", "Labor"}:
                        return (
                                "Yields lower / bull-steepening risk",
                                f"{ccy} vulnerable on growth scare",
                                "Credit/small caps vulnerable; quality duration defensive",
                                "Gold can benefit from lower real yields / risk hedge",
                        )
                return (
                        "Front-end yields lower / easing repricing",
                        f"{ccy} softer unless risk-on dominates",
                        "Duration and quality growth can benefit initially",
                        "Gold supported if real yields fall",
                )
        return (
                "Limited rate impulse; watch revisions and next release",
                f"{ccy} mixed",
                "Market reaction depends on positioning",
                "No dominant impulse",
        )


def normalize_calendar_frame_v3(raw: pd.DataFrame) -> pd.DataFrame:
        """V4 override: robust provider/upload calendar normalization with scored surprises."""
        columns = [
                "Date", "Time", "Central Bank", "Country", "Currency", "Bloc", "Event", "Actual", "Consensus", "Previous", "Revised",
                "Raw Surprise", "Relative Surprise", "Revision Shock", "Policy Score", "Policy Direction", "Surprise Read", "Market Read",
                "Rates Impact", "FX Impact", "Risk Impact", "Gold Impact", "Importance", "Source", "Status", "Notes",
        ]
        if raw is None or not isinstance(raw, pd.DataFrame) or raw.empty:
                return pd.DataFrame(columns=columns)

        df = raw.copy()
        df.columns = [str(c).strip() for c in df.columns]
        lower_map = {str(c).strip().lower().replace(" ", "_").replace("-", "_"): c for c in df.columns}

        def pick(*names: str) -> Optional[str]:
                for name in names:
                        key = name.lower().replace(" ", "_").replace("-", "_")
                        if key in lower_map:
                                return lower_map[key]
                return None

        date_col = pick("date", "datetime", "calendar_date", "release_date", "date_time")
        time_col = pick("time", "release_time")
        country_col = pick("country", "area", "region", "zone")
        currency_col = pick("currency", "ccy")
        bank_col = pick("central_bank", "central bank", "bank")
        bloc_col = pick("bloc", "block", "category_group")
        event_col = pick("event", "category", "indicator", "name", "title")
        actual_col = pick("actual", "latest")
        consensus_col = pick("consensus", "forecast", "estimate", "expected")
        previous_col = pick("previous", "prev")
        revised_col = pick("revised", "revision", "revised_previous")
        importance_col = pick("importance", "impact", "priority")
        source_col = pick("source", "provider")
        notes_col = pick("notes", "note", "comment")

        out = pd.DataFrame(index=df.index)
        out["Date"] = pd.to_datetime(df[date_col], errors="coerce") if date_col else pd.NaT
        out["Time"] = df[time_col].astype(str) if time_col else ""
        out["Country"] = df[country_col].astype(str) if country_col else ""
        out["Currency"] = df[currency_col].astype(str) if currency_col else ""
        out["Event"] = df[event_col].astype(str) if event_col else ""
        out["Central Bank"] = [
                _infer_central_bank_from_event_v3(
                        country=out["Country"].iloc[i] if i < len(out) else "",
                        event=out["Event"].iloc[i] if i < len(out) else "",
                        central_bank=df[bank_col].iloc[i] if bank_col else "",
                )
                for i in range(len(df))
        ]
        out["Bloc"] = df[bloc_col].astype(str) if bloc_col else [_classify_event_bloc_v3(ev, cb) for ev, cb in zip(out["Event"], out["Central Bank"])]
        out["Actual"] = df[actual_col].map(_numeric_from_macro_value_v3) if actual_col else np.nan
        out["Consensus"] = df[consensus_col].map(_numeric_from_macro_value_v3) if consensus_col else np.nan
        out["Previous"] = df[previous_col].map(_numeric_from_macro_value_v3) if previous_col else np.nan
        out["Revised"] = df[revised_col].map(_numeric_from_macro_value_v3) if revised_col else np.nan
        out["Raw Surprise"] = out["Actual"] - out["Consensus"]
        out["Relative Surprise"] = [_relative_surprise_v4(a, c, p) for a, c, p in zip(out["Actual"], out["Consensus"], out["Previous"])]
        out["Revision Shock"] = out["Revised"] - out["Previous"]

        policy_rows = [
                _policy_score_from_event_v4(bloc, event, actual, consensus, previous)
                for bloc, event, actual, consensus, previous in zip(out["Bloc"], out["Event"], out["Actual"], out["Consensus"], out["Previous"])
        ]
        out["Policy Score"] = [x[0] for x in policy_rows]
        out["Surprise Read"] = [x[1] for x in policy_rows]
        out["Policy Direction"] = [x[2] for x in policy_rows]

        impacts = [
                _asset_transmission_v4(bank, bloc, score, event)
                for bank, bloc, score, event in zip(out["Central Bank"], out["Bloc"], out["Policy Score"], out["Event"])
        ]
        out["Rates Impact"] = [x[0] for x in impacts]
        out["FX Impact"] = [x[1] for x in impacts]
        out["Risk Impact"] = [x[2] for x in impacts]
        out["Gold Impact"] = [x[3] for x in impacts]
        out["Market Read"] = out["Rates Impact"] + " · " + out["FX Impact"] + " · " + out["Risk Impact"]
        out["Importance"] = df[importance_col].map(_importance_score_v3) if importance_col else "Medium"
        out["Source"] = df[source_col].astype(str) if source_col else "Uploaded / Provider"
        out["Notes"] = df[notes_col].astype(str) if notes_col else ""
        out["Status"] = np.where(out["Actual"].notna() & out["Consensus"].notna(), "Scored", "Awaiting actual/consensus")

        # Fill missing currency from bank profile.
        out["Currency"] = [
                cur if str(cur).strip() and str(cur).lower() not in {"nan", "none"} else _cb_profile_v3(bank).get("currency", "")
                for cur, bank in zip(out["Currency"], out["Central Bank"])
        ]
        out = out.sort_values(["Date", "Central Bank", "Event"], na_position="last").reset_index(drop=True)
        return out[[c for c in columns if c in out.columns]]


def build_structural_calendar_v3() -> pd.DataFrame:
        """V4 override: provider-free readiness calendar with V4 schema."""
        rows: list[dict] = []
        for bank, profile in CENTRAL_BANK_PROFILES_V3.items():
                for event in profile.get("decision_events", [])[:3]:
                        rows.append({
                                "date": pd.NaT,
                                "time": "Provider required",
                                "country": profile.get("country", ""),
                                "central_bank": bank,
                                "currency": profile.get("currency", ""),
                                "event": event,
                                "actual": np.nan,
                                "consensus": np.nan,
                                "previous": np.nan,
                                "revised": np.nan,
                                "importance": "High",
                                "source": "Structural playbook",
                                "notes": "Requires actual/consensus feed.",
                        })
                for event in profile.get("macro_events", [])[:6]:
                        rows.append({
                                "date": pd.NaT,
                                "time": "Provider required",
                                "country": profile.get("country", ""),
                                "central_bank": bank,
                                "currency": profile.get("currency", ""),
                                "event": event,
                                "actual": np.nan,
                                "consensus": np.nan,
                                "previous": np.nan,
                                "revised": np.nan,
                                "importance": "High" if _classify_event_bloc_v3(event, bank) in {"Inflation", "Labor"} else "Medium",
                                "source": "Structural playbook",
                                "notes": "Feeds the central-bank reaction function.",
                        })
        cal = normalize_calendar_frame_v3(pd.DataFrame(rows))
        if not cal.empty:
                cal["Status"] = "No live calendar provider"
                cal["Surprise Read"] = "Awaiting provider"
                cal["Policy Direction"] = "Unscored"
        return cal


def build_calendar_dataset_v4(source_mode: str, uploaded_file: Any = None, days_back: int = 5, days_forward: int = 30) -> pd.DataFrame:
        mode = str(source_mode or "Structural fallback")
        if "Upload" in mode:
                uploaded = load_uploaded_calendar_v3(uploaded_file)
                if uploaded is not None and not uploaded.empty:
                        return uploaded
                return build_structural_calendar_v3()
        if "Trading Economics" in mode:
                te = fetch_trading_economics_calendar_v3(days_back=days_back, days_forward=days_forward)
                if te is not None and not te.empty:
                        return te
                return build_structural_calendar_v3()
        return build_structural_calendar_v3()


