def render_central_bank_one_bank_v3(bank: str, pack: Dict[str, pd.DataFrame], policy_df: pd.DataFrame, scores: Dict[str, Any], calendar_df: pd.DataFrame) -> None:
        """V4 override: adds surprise tape per central bank."""
        profile = _cb_profile_v3(bank)
        policy = _central_bank_policy_row_v3(policy_df, bank)
        bank_cal = calendar_df.loc[calendar_df["Central Bank"].astype(str) == bank].copy() if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and "Central Bank" in calendar_df.columns else pd.DataFrame()
        bank_scored = build_surprise_tape_v4(bank_cal, bank=None)

        st.markdown(f"### {profile.get('short', bank)} — {bank}")
        c1, c2, c3, c4, c5 = st.columns(5)
        c1.metric("Policy rate", fmt_num(policy.get("Latest Rate"), 2))
        c2.metric("3M Δ", fmt_num(policy.get("3M Δ"), 2))
        c3.metric("12M Δ", fmt_num(policy.get("12M Δ"), 2))
        c4.metric("Currency", profile.get("currency", "N/A"))
        c5.metric("Scored surprises", str(len(bank_scored) if bank_scored is not None else 0))
        st.caption(f"Sensitivity: {profile.get('sensitivity', '')}")

        left, right = st.columns([0.9, 1.1])
        with left:
                st.markdown("#### Policy dashboard")
                display_macro_table(build_bank_dashboard_rows_v3(bank, pack, policy_df, scores), height=300)
        with right:
                st.markdown("#### Reaction function")
                display_macro_table(build_bank_reaction_function_v3(bank), height=300)

        st.markdown("#### Surprise tape for this central bank")
        if bank_scored is None or bank_scored.empty:
                st.info("Aucune surprise scorée pour cette banque centrale. Charge un CSV/XLSX avec actual et consensus, ou configure Trading Economics.")
        else:
                display_macro_table(format_surprise_tape_v4(bank_scored), height=260)

        st.markdown("#### Calendar / surprises for this central bank")
        display_macro_table(format_calendar_display_v3(bank_cal), height=360)

        st.markdown("#### Required events")
        required = []
        for e in profile.get("decision_events", []):
                required.append({"Type": "Central Bank", "Event": e, "Priority": "High", "Why it matters": "Direct policy-rate / guidance repricing."})
        for e in profile.get("macro_events", []):
                bloc = _classify_event_bloc_v3(e, bank)
                required.append({"Type": bloc, "Event": e, "Priority": "High" if bloc in {"Inflation", "Labor"} else "Medium", "Why it matters": "Feeds the central-bank reaction function."})
        display_macro_table(pd.DataFrame(required), height=300)


def render_event_calendar_playbook(calendar_df: Optional[pd.DataFrame] = None, proxy_pack: Optional[Dict[str, pd.DataFrame]] = None) -> None:
        """V4 override: real calendar, surprise tape and event impact journal."""
        st.subheader("Economic Calendar / Surprise Engine — by central bank")
        st.caption(
                "V4 finalise le moteur actual/consensus/previous/revised : upload CSV/XLSX, Trading Economics optionnel, surprise tape et impact journal sur proxies marché."
        )
        render_calendar_template_controls_v4()

        cal = calendar_df if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty else build_structural_calendar_v3()
        surprise_tape = build_surprise_tape_v4(cal)
        impact_journal = build_event_impact_journal_v4(cal, proxy_pack or {}, max_events=25)

        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Calendar rows", str(len(cal)))
        c2.metric("Scored surprises", str(len(surprise_tape)))
        c3.metric("Central banks", str(len(CENTRAL_BANK_PROFILES_V3)))
        c4.metric("Provider", str(cal["Source"].dropna().iloc[0]) if "Source" in cal.columns and not cal["Source"].dropna().empty else "Structural")

        summary_tab, tape_tab, by_bank_tab, impact_tab, framework_tab = st.tabs([
                "Summary", "Surprise Tape", "By Central Bank", "Event Impact", "Framework"
        ])

        with summary_tab:
                st.markdown("#### Calendar summary")
                display_macro_table(build_central_bank_event_summary_v3(cal), height=290)
                st.markdown("#### Full normalized calendar")
                display_macro_table(format_calendar_display_v3(cal), height=470)

        with tape_tab:
                st.markdown("#### Scored surprise tape")
                if surprise_tape.empty:
                        st.info("Aucune surprise scorée : il faut des colonnes actual et consensus dans le calendrier.")
                else:
                        display_macro_table(format_surprise_tape_v4(surprise_tape), height=500)

        with by_bank_tab:
                bank_tabs = st.tabs([_cb_profile_v3(b).get("short", b) for b in _cb_bank_order_v3()])
                for tab, bank in zip(bank_tabs, _cb_bank_order_v3()):
                        with tab:
                                profile = _cb_profile_v3(bank)
                                st.markdown(f"#### {profile.get('short', bank)} — calendar and surprise table")
                                sub = cal.loc[cal["Central Bank"].astype(str) == bank].copy() if "Central Bank" in cal.columns else pd.DataFrame()
                                display_macro_table(format_calendar_display_v3(sub), height=420)
                                st.markdown("#### Transmission map")
                                display_macro_table(build_bank_reaction_function_v3(bank), height=280)

        with impact_tab:
                st.markdown("#### Event impact journal")
                st.caption("Daily proxy reaction around event date. For true Bloomberg-grade intraday event windows, connect an intraday provider later.")
                if impact_journal.empty:
                        st.info("Impact journal indisponible : il faut des surprises datées/scorées et des proxies marché disponibles.")
                else:
                        display_macro_table(format_event_impact_journal_v4(impact_journal), height=520)

        with framework_tab:
                framework = pd.DataFrame([
                        {"Metric": "Raw surprise", "Formula": "Actual - Consensus", "Use": "Mesure directe de l'écart à l'attente."},
                        {"Metric": "Relative surprise", "Formula": "(Actual - Consensus) / abs(Consensus or Previous)", "Use": "Rend les surprises comparables sans historique provider."},
                        {"Metric": "Revision shock", "Formula": "Revised previous - Previous", "Use": "Détecte un changement de trajectoire macro masqué par le chiffre actuel."},
                        {"Metric": "Policy score", "Formula": "Event bloc + sign + reaction function", "Use": "+ hawkish / - dovish-slowdown, borné entre -3 et +3."},
                        {"Metric": "Transmission map", "Formula": "Policy score → rates / FX / risk / gold", "Use": "Transforme la surprise en lecture exploitable par banque centrale."},
                        {"Metric": "Event impact", "Formula": "T0, T+1, T+5 proxy returns", "Use": "Vérifie si le marché confirme la surprise."},
                ])
                display_macro_table(framework, height=340)


def render_data_quality(pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame, calendar_df: Optional[pd.DataFrame] = None) -> None:
        """V4 override with calendar/surprise readiness."""
        st.subheader("Data Quality & Provider Roadmap")
        total = len(FRED_SERIES)
        ok = int((indicator_df["Status"] == "OK").sum()) if isinstance(indicator_df, pd.DataFrame) and not indicator_df.empty else 0
        high_total = int((indicator_df["Importance"] == "High").sum()) if isinstance(indicator_df, pd.DataFrame) and not indicator_df.empty else 0
        high_ok = int(((indicator_df["Importance"] == "High") & (indicator_df["Status"] == "OK")).sum()) if isinstance(indicator_df, pd.DataFrame) and not indicator_df.empty else 0
        cal_rows = len(calendar_df) if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty else 0
        surprise_tape = build_surprise_tape_v4(calendar_df) if isinstance(calendar_df, pd.DataFrame) else pd.DataFrame()

        c1, c2, c3, c4, c5 = st.columns(5)
        c1.metric("FRED series", f"{ok}/{total}")
        c2.metric("High-impact", f"{high_ok}/{high_total}")
        c3.metric("Yahoo proxies", f"{sum(1 for df in proxy_pack.values() if isinstance(df, pd.DataFrame) and not df.empty)}/{len(MARKET_PROXIES)}")
        c4.metric("Calendar rows", str(cal_rows))
        c5.metric("Scored surprises", str(len(surprise_tape)))

        st.caption(f"Module version: {MACRO_CB_VERSION}. Calendar schema: actual/consensus/previous/revised → policy score → event impact.")

        cb_readiness = []
        for bank, profile in CENTRAL_BANK_PROFILES_V3.items():
                policy_loaded = any(isinstance(pack.get(sid), pd.DataFrame) and not pack.get(sid).empty for sid in profile.get("policy_series", []))
                cal_count = int((calendar_df["Central Bank"].astype(str) == bank).sum()) if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and "Central Bank" in calendar_df.columns else 0
                scored_count = int(((calendar_df["Central Bank"].astype(str) == bank) & (calendar_df["Status"].astype(str) == "Scored")).sum()) if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and all(c in calendar_df.columns for c in ["Central Bank", "Status"]) else 0
                cb_readiness.append({
                        "Central Bank": bank,
                        "Policy proxy": "OK" if policy_loaded else "Missing proxy",
                        "Calendar events": cal_count,
                        "Scored surprises": scored_count,
                        "Currency": profile.get("currency", ""),
                        "Next requirement": "Actual/consensus feed" if scored_count == 0 else "Intraday event-window provider",
                })
        st.markdown("#### Central-bank readiness")
        display_macro_table(pd.DataFrame(cb_readiness), height=310)

        roadmap = pd.DataFrame([
                {"Provider": "FRED CSV", "Status": "Implemented", "Use": "US macro, rates, inflation, labor, liquidity, credit", "Key required": "No"},
                {"Provider": "Yahoo Finance", "Status": "Implemented", "Use": "Daily market proxies and event impact approximation", "Key required": "No"},
                {"Provider": "CSV/XLSX calendar upload", "Status": "Implemented V4", "Use": "Real actual/consensus/previous/revised by central bank", "Key required": "No"},
                {"Provider": "Trading Economics", "Status": "Implemented optional V4", "Use": "Economic calendar actual/consensus/previous/revisions", "Key required": "Yes"},
                {"Provider": "ECB/BIS/OECD APIs", "Status": "Prepared next", "Use": "Official non-US macro and cross-border liquidity", "Key required": "Mostly no"},
                {"Provider": "Bloomberg / LSEG / Macrobond / Haver", "Status": "Premium", "Use": "Institutional real-time calendar, consensus and intraday event studies", "Key required": "Subscription"},
        ])
        st.markdown("#### Provider roadmap")
        display_macro_table(roadmap, height=350)

        st.markdown("#### Calendar template")
        render_calendar_template_controls_v4()
        display_macro_table(build_calendar_template_v4(), height=190)

        with st.expander("Raw indicator coverage", expanded=False):
                display_macro_table(format_indicator_display(indicator_df), height=600)


def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V4 final Streamlit entry point: central-bank calendar and surprise engine."""
        ticker = str(ticker or "").upper().strip()
        analysis = analysis or {}

        st.title("Macro Intelligence & Central Bank Monitor")
        st.caption(
                f"{MACRO_CB_VERSION} · central-bank-first cockpit : FRED CSV, Yahoo proxies, CSV/XLSX or Trading Economics calendar, "
                "actual/consensus surprise tape, policy reaction functions and event impact journal. Ce n'est pas un signal d'achat/vente."
        )

        uploaded_calendar = None
        with st.expander("Paramètres macro", expanded=True):
                c1, c2, c3, c4 = st.columns([1.0, 1.0, 1.0, 1.2])
                with c1:
                        start_date = st.selectbox(
                                "Historique macro",
                                ["1990-01-01", "2000-01-01", "2010-01-01", "2020-01-01"],
                                index=1,
                                key="macro_v4_start_date",
                        )
                with c2:
                        proxy_period = st.selectbox(
                                "Proxies marché",
                                ["6mo", "1y", "2y", "5y"],
                                index=2,
                                key="macro_v4_proxy_period",
                        )
                with c3:
                        show_all_series = st.toggle(
                                "Charger toutes les séries",
                                value=True,
                                key="macro_v4_show_all_series",
                        )
                with c4:
                        calendar_source = st.selectbox(
                                "Calendar source",
                                ["Structural fallback", "Upload CSV/XLSX", "Trading Economics API if configured"],
                                index=0,
                                key="macro_v4_calendar_source",
                        )

                c5, c6, c7 = st.columns([1.2, 0.9, 0.9])
                with c5:
                        if calendar_source == "Upload CSV/XLSX":
                                uploaded_calendar = st.file_uploader(
                                        "Upload economic calendar",
                                        type=["csv", "xlsx", "xls"],
                                        key="macro_v4_calendar_upload",
                                        help="Colonnes recommandées : date, time, country, central_bank, currency, event, actual, consensus, previous, revised, importance, source.",
                                )
                        else:
                                st.caption("Calendar upload désactivé pour cette source.")
                        render_calendar_template_controls_v4()
                with c6:
                        days_back = st.number_input("Calendar days back", min_value=0, max_value=90, value=5, step=1, key="macro_v4_days_back")
                with c7:
                        days_forward = st.number_input("Calendar days forward", min_value=1, max_value=180, value=30, step=1, key="macro_v4_days_forward")

        series_ids = tuple(FRED_SERIES.keys()) if show_all_series else tuple(
                sid for sid, meta in FRED_SERIES.items() if meta.get("importance") == "High"
        )

        pack = load_macro_fred_pack(series_ids, start_date=start_date)
        proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
        calendar_df = build_calendar_dataset_v4(calendar_source, uploaded_calendar, int(days_back), int(days_forward))

        indicator_df = build_macro_indicator_table(pack)
        scores = build_macro_scores(pack)
        policy_df = build_central_bank_monitor(pack)
        curve_df = build_rates_curve_table(pack)
        curve_info = curve_state(pack)
        proxy_df = build_market_proxy_table(proxy_pack)
        beta_df = build_macro_beta_table(ticker, price_data, proxy_pack)

        tabs = st.tabs([
                "Dashboard",
                "Central Banks by Bank",
                "Rates / Curve",
                "Inflation · Growth · Labor",
                "Liquidity / Credit",
                "Cross-Asset Impact",
                "Calendar / Surprises",
                "Data Quality",
        ])

        with tabs[0]:
                render_macro_dashboard(pack, scores, indicator_df, proxy_df)
        with tabs[1]:
                render_central_bank_section(pack, policy_df, scores=scores, calendar_df=calendar_df)
        with tabs[2]:
                render_rates_section(pack, curve_df, curve_info)
        with tabs[3]:
                render_inflation_growth_labor(pack, indicator_df)
        with tabs[4]:
                render_liquidity_credit(pack, indicator_df)
        with tabs[5]:
                render_cross_asset_impact(ticker, price_data, proxy_df, beta_df)
        with tabs[6]:
                render_event_calendar_playbook(calendar_df, proxy_pack=proxy_pack)
        with tabs[7]:
                render_data_quality(pack, proxy_pack, indicator_df, calendar_df=calendar_df)

        st.caption(
                f"Macro {MACRO_CB_VERSION} COMPLETE — final actual/consensus central-bank calendar layer. "
                "Pour le niveau Bloomberg réel, ajouter un flux continu et intraday event windows."
        )

