def _macro_v5_plot_config() -> dict:
        try:
                return plotly_config()
        except Exception:
                return {"displayModeBar": False, "responsive": True}


def _bank_order_v5() -> List[str]:
        try:
                return list(_cb_bank_order_v3())
        except Exception:
                try:
                        return list(CENTRAL_BANK_PROFILES_V3.keys())
                except Exception:
                        return [
                                "Federal Reserve",
                                "European Central Bank",
                                "Bank of England",
                                "Bank of Japan",
                                "Swiss National Bank",
                                "Bank of Canada",
                                "Reserve Bank of Australia",
                        ]


def _profile_v5(bank: str) -> Dict[str, Any]:
        try:
                return dict(_cb_profile_v3(bank))
        except Exception:
                try:
                        return dict(CENTRAL_BANK_PROFILES_V3.get(bank, {}))
                except Exception:
                        return {}


def _bank_label_v5(bank: str) -> str:
        profile = _profile_v5(bank)
        short = profile.get("short", bank)
        currency = profile.get("currency", "")
        return f"{short} · {bank} · {currency}" if currency else f"{short} · {bank}"


def _source_label_v5(calendar_df: pd.DataFrame) -> str:
        try:
                if isinstance(calendar_df, pd.DataFrame) and not calendar_df.empty and "Source" in calendar_df.columns:
                        return str(calendar_df["Source"].dropna().iloc[0])
        except Exception:
                pass
        return "Structural"


def _safe_policy_df_v5(policy_df: pd.DataFrame) -> pd.DataFrame:
        if isinstance(policy_df, pd.DataFrame) and not policy_df.empty:
                return policy_df.copy()
        return pd.DataFrame(columns=[
                "Central Bank", "Country/Area", "Policy Proxy", "Latest Date", "Latest Rate",
                "3M Δ", "12M Δ", "Bias", "Asset Sensitivity", "Source Status"
        ])


def _policy_row_v5(policy_df: pd.DataFrame, bank: str) -> Dict[str, Any]:
        try:
                row = _central_bank_policy_row_v3(policy_df, bank)
                if isinstance(row, dict):
                        return row
        except Exception:
                pass
        try:
                sub = policy_df.loc[policy_df["Central Bank"].astype(str) == str(bank)]
                return dict(sub.iloc[0]) if not sub.empty else {}
        except Exception:
                return {}


def _fmt_v5(value: Any, digits: int = 2) -> str:
        try:
                return fmt_num(value, digits)
        except Exception:
                try:
                        x = float(value)
                        if not np.isfinite(x):
                                return "N/A"
                        return f"{x:,.{digits}f}"
                except Exception:
                        return "N/A"


def _fmt_score_v5(value: Any) -> str:
        try:
                return fmt_score(value)
        except Exception:
                try:
                        x = max(0, min(100, float(value)))
                        return f"{x:.0f}/100"
                except Exception:
                        return "N/A"


def _safe_display_table_v5(df: pd.DataFrame, height: int = 340) -> None:
        try:
                display_macro_table(df, height=height)
        except Exception:
                if df is None or df.empty:
                        st.info("Table indisponible.")
                else:
                        st.dataframe(df, use_container_width=True, hide_index=True, height=height)


def _build_calendar_v5(source_mode: str, uploaded_file: Any, days_back: int, days_forward: int) -> pd.DataFrame:
        if "build_calendar_dataset_v4" in globals():
                try:
                        return build_calendar_dataset_v4(source_mode, uploaded_file, days_back, days_forward)
                except Exception:
                        pass
        if "build_calendar_dataset_v3" in globals():
                try:
                        return build_calendar_dataset_v3(source_mode, uploaded_file, days_back, days_forward)
                except Exception:
                        pass
        try:
                return build_structural_calendar_v3()
        except Exception:
                return pd.DataFrame()


def _calendar_for_bank_v5(calendar_df: pd.DataFrame, bank: str) -> pd.DataFrame:
        if not isinstance(calendar_df, pd.DataFrame) or calendar_df.empty or "Central Bank" not in calendar_df.columns:
                return pd.DataFrame()
        return calendar_df.loc[calendar_df["Central Bank"].astype(str) == str(bank)].copy()


def _format_calendar_v5(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
                return pd.DataFrame()
        if "format_calendar_display_v4" in globals():
                try:
                        return format_calendar_display_v4(df)
                except Exception:
                        pass
        if "format_calendar_display_v3" in globals():
                try:
                        return format_calendar_display_v3(df)
                except Exception:
                        pass
        out = df.copy()
        if "Date" in out.columns:
                out["Date"] = pd.to_datetime(out["Date"], errors="coerce").dt.strftime("%Y-%m-%d").fillna("Provider required")
        return out


def _surprise_tape_v5(calendar_df: pd.DataFrame, bank: Optional[str] = None) -> pd.DataFrame:
        if "build_surprise_tape_v4" in globals():
                try:
                        return build_surprise_tape_v4(calendar_df, bank=bank)
                except Exception:
                        pass
        if not isinstance(calendar_df, pd.DataFrame) or calendar_df.empty:
                return pd.DataFrame()
        work = calendar_df.copy()
        if bank and "Central Bank" in work.columns:
                work = work.loc[work["Central Bank"].astype(str) == str(bank)].copy()
        scored_cols = [c for c in ["Date", "Time", "Central Bank", "Currency", "Bloc", "Event", "Actual", "Consensus", "Raw Surprise", "Revision Shock", "Policy Score", "Policy Direction", "Surprise Read", "Importance", "Source", "Status"] if c in work.columns]
        return work[scored_cols].copy() if scored_cols else work


def _format_surprise_tape_v5(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
                return pd.DataFrame()
        if "format_surprise_tape_v4" in globals():
                try:
                        return format_surprise_tape_v4(df)
                except Exception:
                        pass
        return _format_calendar_v5(df)


def _bank_event_kpis_v5(calendar_df: pd.DataFrame, bank: str) -> Dict[str, Any]:
        sub = _calendar_for_bank_v5(calendar_df, bank)
        if sub.empty:
                return {"events": 0, "scored": 0, "high": 0, "next_event": "N/A", "last_read": "No calendar"}
        scored = 0
        if "Status" in sub.columns:
                scored = int((sub["Status"].astype(str) == "Scored").sum())
        high = 0
        if "Importance" in sub.columns:
                high = int((sub["Importance"].astype(str).str.lower() == "high").sum())
        next_event = "Provider required"
        if "Date" in sub.columns:
                dated = sub.dropna(subset=["Date"]).sort_values("Date")
                if not dated.empty:
                        today = pd.Timestamp.today().normalize()
                        future = dated.loc[pd.to_datetime(dated["Date"], errors="coerce") >= today]
                        row = future.iloc[0] if not future.empty else dated.iloc[-1]
                        next_event = str(row.get("Event", "N/A"))
        last_read = "Awaiting actual/consensus"
        if "Surprise Read" in sub.columns:
                scored_sub = sub.loc[sub.get("Status", pd.Series(index=sub.index, dtype=str)).astype(str) == "Scored"] if "Status" in sub.columns else pd.DataFrame()
                if not scored_sub.empty:
                        last_read = str(scored_sub.tail(1).iloc[0].get("Surprise Read", last_read))
        return {"events": len(sub), "scored": scored, "high": high, "next_event": next_event, "last_read": last_read}


