def _plot_bank_policy_path_v5(pack: Dict[str, pd.DataFrame], bank: str) -> None:
        profile = _profile_v5(bank)
        policy_series = list(profile.get("policy_series", []))
        if bank == "Federal Reserve":
                policy_series = list(dict.fromkeys(policy_series + ["DGS2", "DGS10"]))
        fig = go.Figure()
        added = 0
        for sid in policy_series:
                df = pack.get(sid, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
                if not isinstance(df, pd.DataFrame) or df.empty or not all(c in df.columns for c in ["date", "value"]):
                        continue
                use = df.dropna(subset=["date", "value"]).tail(900).copy()
                if use.empty:
                        continue
                label = FRED_SERIES.get(sid, {}).get("label", sid) if "FRED_SERIES" in globals() else sid
                fig.add_trace(go.Scatter(x=use["date"], y=use["value"], mode="lines", name=label))
                added += 1
        if added == 0:
                st.info("Policy path indisponible pour cette banque centrale avec les proxies publics actuels.")
                return
        fig.update_layout(
                height=390,
                margin=dict(l=20, r=20, t=45, b=20),
                title=f"Policy path / rates proxies — {_bank_label_v5(bank)}",
                legend=dict(orientation="h"),
                hovermode="x unified",
        )
        st.plotly_chart(fig, use_container_width=True, config=_macro_v5_plot_config())


def _plot_bank_proxy_performance_v5(proxy_pack: Dict[str, pd.DataFrame], bank: str) -> None:
        profile = _profile_v5(bank)
        proxies = list(profile.get("market_proxies", []))
        fig = go.Figure()
        added = 0
        for symbol in proxies:
                df = proxy_pack.get(symbol, pd.DataFrame()) if isinstance(proxy_pack, dict) else pd.DataFrame()
                if not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
                        continue
                use = df.dropna(subset=["date", "close"]).copy()
                close = pd.to_numeric(use["close"], errors="coerce").dropna()
                if close.empty:
                        continue
                base = close.iloc[0]
                if not base:
                        continue
                y = close / base * 100.0
                dates = use.loc[close.index, "date"] if "date" in use.columns else use.index
                label = MARKET_PROXIES.get(symbol, {}).get("label", symbol) if "MARKET_PROXIES" in globals() else symbol
                fig.add_trace(go.Scatter(x=dates, y=y, mode="lines", name=label))
                added += 1
        if added == 0:
                st.info("Market proxy performance indisponible.")
                return
        fig.update_layout(
                height=380,
                margin=dict(l=20, r=20, t=45, b=20),
                title=f"Asset transmission proxies — {_bank_label_v5(bank)} · normalized 100",
                legend=dict(orientation="h"),
                hovermode="x unified",
        )
        st.plotly_chart(fig, use_container_width=True, config=_macro_v5_plot_config())


def _plot_policy_divergence_v5(policy_df: pd.DataFrame, selected_bank: str) -> None:
        if policy_df is None or policy_df.empty or "Latest Rate" not in policy_df.columns:
                st.info("Policy divergence indisponible.")
                return
        clean = policy_df.dropna(subset=["Latest Rate"]).copy()
        if clean.empty:
                st.info("Policy divergence indisponible : pas assez de taux chargés.")
                return
        clean["Latest Rate"] = pd.to_numeric(clean["Latest Rate"], errors="coerce")
        fig = go.Figure()
        fig.add_trace(go.Bar(x=clean["Central Bank"], y=clean["Latest Rate"], text=[_fmt_v5(x, 2) for x in clean["Latest Rate"]], textposition="auto"))
        fig.update_layout(height=360, margin=dict(l=20, r=20, t=45, b=80), title="Latest policy-rate proxies")
        st.plotly_chart(fig, use_container_width=True, config=_macro_v5_plot_config())

        row = _policy_row_v5(policy_df, selected_bank)
        selected_rate = safe_float(row.get("Latest Rate")) if "safe_float" in globals() else None
        if selected_rate is not None:
                spread = clean[["Central Bank", "Latest Rate", "Bias"]].copy()
                spread[f"Spread vs {selected_bank}"] = spread["Latest Rate"] - selected_rate
                spread[f"Spread vs {selected_bank}"] = spread[f"Spread vs {selected_bank}"].map(lambda x: _fmt_v5(x, 2))
                spread["Latest Rate"] = spread["Latest Rate"].map(lambda x: _fmt_v5(x, 2))
                _safe_display_table_v5(spread, height=300)


def _build_required_events_v5(bank: str) -> pd.DataFrame:
        profile = _profile_v5(bank)
        rows = []
        for event in profile.get("decision_events", []):
                rows.append({
                        "Type": "Central Bank",
                        "Event": event,
                        "Priority": "High",
                        "Use": "Direct policy path / guidance repricing.",
                })
        for event in profile.get("macro_events", []):
                try:
                        bloc = _classify_event_bloc_v3(event, bank)
                except Exception:
                        bloc = "Macro"
                rows.append({
                        "Type": bloc,
                        "Event": event,
                        "Priority": "High" if bloc in {"Inflation", "Labor", "Central Bank"} else "Medium",
                        "Use": "Feeds the selected central-bank reaction function.",
                })
        return pd.DataFrame(rows)


