def render_macro_central_bank_lab(
        ticker: str,
        price_data: pd.DataFrame,
        analysis: Optional[dict] = None,
) -> None:
        """V5 final Streamlit entry point: interactive central-bank workstation."""
        ticker = str(ticker or "").upper().strip() or "SPY"
        analysis = analysis or {}
        inject_macro_v5_css()

        st.title("Macro Intelligence & Central Bank Monitor")
        st.caption(
                f"{MACRO_CB_VERSION} · choose a central bank first, then inspect policy path, calendar surprises, reaction function, divergence and cross-asset transmission. Ce n'est pas un signal d'achat/vente."
        )

        uploaded_calendar = None
        banks = _bank_order_v5()

        with st.expander("Control center — central bank, providers, horizon", expanded=True):
                r1c1, r1c2, r1c3, r1c4 = st.columns([1.35, .85, .85, 1.05])
                with r1c1:
                        selected_bank = st.selectbox(
                                "Central bank focus",
                                banks,
                                index=0,
                                key="macro_v5_selected_bank",
                                format_func=_bank_label_v5,
                        )
                with r1c2:
                        start_date = st.selectbox(
                                "Historique macro",
                                ["1990-01-01", "2000-01-01", "2010-01-01", "2020-01-01"],
                                index=1,
                                key="macro_v5_start_date",
                        )
                with r1c3:
                        proxy_period = st.selectbox(
                                "Proxies marché",
                                ["6mo", "1y", "2y", "5y"],
                                index=2,
                                key="macro_v5_proxy_period",
                        )
                with r1c4:
                        calendar_source = st.selectbox(
                                "Calendar source",
                                ["Structural fallback", "Upload CSV/XLSX", "Trading Economics API if configured"],
                                index=0,
                                key="macro_v5_calendar_source",
                        )

                r2c1, r2c2, r2c3, r2c4 = st.columns([1.15, .75, .75, .85])
                with r2c1:
                        if calendar_source == "Upload CSV/XLSX":
                                uploaded_calendar = st.file_uploader(
                                        "Upload economic calendar",
                                        type=["csv", "xlsx", "xls"],
                                        key="macro_v5_calendar_upload",
                                        help="Colonnes recommandées : date, time, country, central_bank, event, actual, consensus, previous, revised, importance, currency.",
                                )
                        else:
                                st.caption("Calendar upload désactivé pour cette source.")
                with r2c2:
                        days_back = st.number_input("Days back", min_value=0, max_value=90, value=5, step=1, key="macro_v5_days_back")
                with r2c3:
                        days_forward = st.number_input("Days forward", min_value=1, max_value=180, value=30, step=1, key="macro_v5_days_forward")
                with r2c4:
                        show_all_series = st.toggle("Load full macro pack", value=True, key="macro_v5_show_all_series")

        series_ids = tuple(FRED_SERIES.keys()) if show_all_series else tuple(
                sid for sid, meta in FRED_SERIES.items() if meta.get("importance") == "High"
        )

        pack = load_macro_fred_pack(series_ids, start_date=start_date)
        proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
        calendar_df = _build_calendar_v5(calendar_source, uploaded_calendar, int(days_back), int(days_forward))

        indicator_df = build_macro_indicator_table(pack)
        scores = build_macro_scores(pack)
        policy_df = _safe_policy_df_v5(build_central_bank_monitor(pack))
        curve_df = build_rates_curve_table(pack)
        curve_info = curve_state(pack)
        proxy_df = build_market_proxy_table(proxy_pack)
        beta_df = build_macro_beta_table(ticker, price_data, proxy_pack)

        _render_macro_v5_hero(selected_bank, calendar_df)
        _render_bank_kpi_strip_v5(selected_bank, policy_df, calendar_df, scores)

        tabs = st.tabs([
                "Bank Cockpit",
                "Surprise Tape",
                "Policy Path",
                "Divergence",
                "Macro Blocks",
                "Cross-Asset Transmission",
                "Data Quality",
        ])

        with tabs[0]:
                _render_selected_bank_cockpit_v5(selected_bank, pack, policy_df, scores, calendar_df, proxy_pack)
        with tabs[1]:
                _render_surprise_workbench_v5(calendar_df, selected_bank)
        with tabs[2]:
                _render_policy_path_workbench_v5(selected_bank, pack, policy_df, calendar_df)
        with tabs[3]:
                _render_divergence_workbench_v5(policy_df, selected_bank)
        with tabs[4]:
                _render_macro_blocks_v5(pack, scores, indicator_df, proxy_df, curve_df, curve_info)
        with tabs[5]:
                _render_cross_asset_v5(selected_bank, ticker, price_data, proxy_df, beta_df, proxy_pack, calendar_df)
        with tabs[6]:
                _render_data_quality_v5(pack, proxy_pack, indicator_df, calendar_df)

        st.caption(
                f"Macro {MACRO_CB_VERSION} COMPLETE — interactive central-bank workstation. "
                "Next institutional layer: continuous actual/consensus calendar feed + intraday event windows."
        )

