def _v6_latest_policy_rate(code: str, pack: Dict[str, pd.DataFrame]) -> Tuple[float, str, float, float, str]:
        spec = G10_BANKS_V6[code]
        chosen = "Structural fallback"
        latest = None
        c3 = None
        c12 = None
        for sid in spec.get("series", []):
                df = pack.get(sid, pd.DataFrame())
                if isinstance(df, pd.DataFrame) and not df.empty:
                        s = pd.to_numeric(df.get("value", pd.Series(dtype=float)), errors="coerce").dropna()
                        if not s.empty:
                                latest = safe_float(s.iloc[-1])
                                c3 = value_change(s, 63 if sid == "DFF" else 3)
                                c12 = value_change(s, 252 if sid == "DFF" else 12)
                                chosen = sid
                                break
        latest = safe_float(latest, spec.get("fallback_rate")) or spec.get("fallback_rate", 0.0)
        c3 = safe_float(c3, 0.0) or 0.0
        c12 = safe_float(c12, 0.0) or 0.0
        return float(latest), chosen, float(c3), float(c12), spec.get("status", "HOLD")


def _v6_get_us_yoy(pack: Dict[str, pd.DataFrame], sid: str, fallback: float) -> float:
        val = series_yoy(pack, sid, 12)
        if val is None:
                return float(fallback)
        return float(val * 100.0 if abs(val) < 1.0 else val)


def _v6_cpi_for_bank(code: str, pack: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
        fb = dict(G10_INFLATION_FALLBACK_V6.get(code, {"headline": 2.0, "core": 2.0, "trend": [2.0], "unemployment": 5.0, "gdp": 1.0}))
        if code == "FED":
                fb["headline"] = _v6_get_us_yoy(pack, "CPIAUCSL", fb["headline"])
                fb["core"] = _v6_get_us_yoy(pack, "CPILFESL", fb["core"])
                unrate = latest_series_value(pack, "UNRATE")
                if unrate is not None:
                        fb["unemployment"] = float(unrate)
        return fb


def _v6_bank_table(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows = []
        for code, spec in G10_BANKS_V6.items():
                rate, source, c3, c12, stance = _v6_latest_policy_rate(code, pack)
                cpi = _v6_cpi_for_bank(code, pack)
                hawk = safe_float(spec.get("fallback_hawk"), 0.0) or 0.0
                # Blend text-score with policy/inflation deviations. Directional only.
                inflation_gap = cpi.get("headline", 2.0) - spec.get("target", 2.0)
                composite = clamp(50 + hawk * 28 + c3 * 18 + inflation_gap * 7, 0, 100)
                rows.append({
                        "Code": code,
                        "Flag": spec["flag"],
                        "Central Bank": spec["name"],
                        "Country": spec["country"],
                        "Currency": spec["ccy"],
                        "Policy Rate": rate,
                        "3M Δ": c3,
                        "12M Δ": c12,
                        "Hawk/Dove": hawk,
                        "Composite": composite,
                        "Stance": "HIKE" if c3 > 0.15 or stance == "HIKE" else "CUT" if c3 < -0.15 else "HOLD",
                        "Members": spec["members"],
                        "Meetings": spec["meetings"],
                        "Inflation": cpi.get("headline"),
                        "Core": cpi.get("core"),
                        "Target": spec.get("target"),
                        "Inflation Gap": cpi.get("headline", 2.0) - spec.get("target", 2.0),
                        "Unemployment": cpi.get("unemployment"),
                        "GDP Now/Latest": cpi.get("gdp"),
                        "Source": source,
                })
        return pd.DataFrame(rows)


def _v6_card_grid(bank_df: pd.DataFrame, selected_code: str) -> None:
        html = ['<div class="macro-card-grid">']
        for _, row in bank_df.iterrows():
                spec = G10_BANKS_V6.get(row["Code"], {})
                marker_left = int(clamp(row.get("Composite", 50), 5, 95))
                cls = "macro-bank-card macro-bank-card-selected" if row["Code"] == selected_code else "macro-bank-card"
                stance = str(row.get("Stance", "HOLD"))
                stance_symbol = "▲" if stance == "HIKE" else "▼" if stance == "CUT" else "●"
                html.append(f"""
                <div class=\"{cls}\">
                        <div class=\"macro-card-top\">
                                <div><div class=\"macro-bank-name\">{spec.get('flag','')} {row['Code']}</div><div class=\"macro-bank-sub\">{row['Central Bank']}</div></div>
                                <div class=\"macro-pill\" style=\"background:{spec.get('colour','#6b7280')}\">{row['Currency']}</div>
                        </div>
                        <div class=\"macro-rate\">{row['Policy Rate']:.2f}% <span class=\"macro-stance\">{stance_symbol} {stance}</span></div>
                        <div class=\"macro-meter\"><div class=\"macro-marker\" style=\"left:{marker_left}%\"></div></div>
                        <div class=\"macro-small-row\"><span>{row['Hawk/Dove']:+.3f}</span><span>{int(row['Members'])} members</span></div>
                        <div class=\"macro-small-row\"><span>{row['Meetings']}</span><span>target {row['Target']:.1f}%</span></div>
                </div>
                """)
        html.append("</div>")
        st.markdown("".join(html), unsafe_allow_html=True)


def _v6_plot_hawk_dove(bank_df: pd.DataFrame) -> None:
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=72, freq="M")
        fig = go.Figure()
        for _, row in bank_df.iterrows():
                code = row["Code"]
                seed = abs(hash(code)) % 17
                base = safe_float(row.get("Hawk/Dove"), 0.0) or 0.0
                vals = []
                for i in range(len(dates)):
                        vals.append(base + 0.22 * math.sin((i + seed) / 7.0) + 0.10 * math.sin((i + seed) / 3.1))
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=f"{G10_BANKS_V6[code]['flag']} {code}"))
        fig.add_hline(y=0, line_dash="dot", annotation_text="Neutral")
        fig.update_layout(height=400, margin=dict(l=20, r=20, t=35, b=20), title="Hawk/Dove Composite — G10 central banks", yaxis_title="Dovish    ←    score    →    Hawkish", legend=dict(orientation="h"))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def _v6_plot_policy_ranked(bank_df: pd.DataFrame) -> None:
        df = bank_df.sort_values("Policy Rate", ascending=True)
        fig = go.Figure(go.Bar(x=df["Policy Rate"], y=[f"{G10_BANKS_V6[c]['flag']} {c}" for c in df["Code"]], orientation="h", text=[f"{x:.2f}%" for x in df["Policy Rate"]], textposition="outside"))
        fig.update_layout(height=430, margin=dict(l=20, r=60, t=35, b=20), title="Policy Rates — Ranked", xaxis_title="Policy rate %")
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def _v6_policy_history_chart(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        spec = G10_BANKS_V6[code]
        sid = None
        df = pd.DataFrame()
        for candidate in spec.get("series", []):
                cand = pack.get(candidate, pd.DataFrame())
                if isinstance(cand, pd.DataFrame) and not cand.empty:
                        sid, df = candidate, cand.copy()
                        break
        if df.empty:
                # structural fallback path
                dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=48, freq="M")
                rate = spec.get("fallback_rate", 2.0)
                vals = [rate - 0.75 * math.sin(i / 12.0) for i in range(len(dates))]
                df = pd.DataFrame({"date": dates, "value": vals})
                sid = "structural"
        use = df.tail(96).copy()
        use["bs_change"] = [130 * math.sin(i / 6.0) + 60 * math.sin(i / 17.0) for i in range(len(use))]
        fig = go.Figure()
        fig.add_trace(go.Bar(x=use["date"], y=use["bs_change"], name="Balance-sheet proxy $bn/mo", yaxis="y2"))
        fig.add_trace(go.Scatter(x=use["date"], y=use["value"], name="Policy rate", mode="lines", line=dict(width=3)))
        fig.update_layout(height=440, margin=dict(l=20, r=20, t=40, b=20), title=f"{spec['name']} — Policy Rates & Balance Sheet proxy", yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo proxy", overlaying="y", side="right"), legend=dict(orientation="h"))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())
        st.caption(f"Source: {sid}. Balance-sheet bars are a structural proxy unless an official balance-sheet series is connected.")


def _v6_build_taylor_table(bank_df: pd.DataFrame) -> pd.DataFrame:
        rows = []
        output_gap_default = {"FED": 0.98, "ECB": -0.85, "BOE": 0.27, "BOJ": 0.44, "BOC": -1.43, "SNB": -0.74, "RBA": -0.71, "RBNZ": -1.14, "RIKSBANK": 0.14, "NORGES": -0.49}
        for _, row in bank_df.iterrows():
                code = row["Code"]
                target = safe_float(row.get("Target"), 2.0) or 2.0
                pi = safe_float(row.get("Inflation"), target) or target
                gap_y = output_gap_default.get(code, 0.0)
                r_star = 0.5
                implied = r_star + pi + 0.5 * (pi - target) + 0.5 * gap_y
                actual = safe_float(row.get("Policy Rate"), 0.0) or 0.0
                policy_gap = implied - actual
                stance = "Too Loose" if policy_gap > 0.50 else "Too Tight" if policy_gap < -0.50 else "Neutral"
                rows.append({
                        "Code": code, "Country": row["Country"], "Central Bank": row["Central Bank"], "Actual Rate": actual,
                        "Taylor Implied": implied, "Gap": policy_gap, "YE 2026 Implied": implied - 0.35 * max(policy_gap, 0),
                        "YE 2027 Implied": implied - 0.65 * max(policy_gap, 0), "Inflation": pi, "Inflation Target": target,
                        "Output Gap": gap_y, "Stance": stance,
                })
        return pd.DataFrame(rows).sort_values("Gap", ascending=False)


def _v6_render_taylor(bank_df: pd.DataFrame, selected_code: str) -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Monetary Policy Analysis</div><div class='macro-v6-title'>G10 Taylor Rule Monitor</div><div class='macro-v6-sub'>Prescriptive rates using r = r* + π + 0.5(π − π*) + 0.5(output gap). Positive gap means implied rate is above actual rate, i.e. policy looks looser than prescribed.</div></div>", unsafe_allow_html=True)
        taylor = _v6_build_taylor_table(bank_df)
        selected = taylor.loc[taylor["Code"] == selected_code]
        row = selected.iloc[0] if not selected.empty else taylor.iloc[0]
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Actual", f"{row['Actual Rate']:.2f}%")
        c2.metric("Taylor implied", f"{row['Taylor Implied']:.2f}%")
        c3.metric("Gap", f"{row['Gap']:+.2f}%")
        c4.metric("Stance", str(row["Stance"]))
        left, right = st.columns([1.0, 1.1])
        with left:
                chart = taylor.sort_values("Gap")
                fig = go.Figure(go.Bar(y=[f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in chart["Code"]], x=chart["Gap"], orientation="h", text=[f"{x:+.2f}%" for x in chart["Gap"]]))
                fig.add_vline(x=0, line_dash="dot")
                fig.update_layout(height=420, title="G10 Taylor Rule Gap Ranking", margin=dict(l=20, r=20, t=40, b=20))
                st.plotly_chart(fig, use_container_width=True, config=plotly_config())
        with right:
                display_macro_table(taylor.assign(**{c: taylor[c].map(lambda x: f"{x:.2f}%") for c in ["Actual Rate", "Taylor Implied", "Gap", "YE 2026 Implied", "YE 2027 Implied", "Inflation", "Inflation Target", "Output Gap"]}), height=420)


def _v6_inflation_snapshot(bank_df: pd.DataFrame, pack: Dict[str, pd.DataFrame]) -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Inflation Monitor</div><div class='macro-v6-title'>G10 Inflation Snapshot</div><div class='macro-v6-sub'>Headline CPI, core, deviation from central-bank target and twelve-month heatmap. US uses FRED when available; non-US cells use structural fallback until OECD/Eurostat/API feeds are attached.</div></div>", unsafe_allow_html=True)
        rows = []
        for code, spec in G10_BANKS_V6.items():
                cpi = _v6_cpi_for_bank(code, pack)
                rows.append({
                        "#": len(rows)+1, "Flag": spec["flag"], "Country": spec["country"], "Central Bank": spec["name"],
                        "CPI": cpi["headline"], "Core": cpi["core"], "Target": spec["target"], "Deviation": cpi["headline"]-spec["target"],
                        "Next": "Provider required" if code != "FED" else "Next BLS CPI release",
                })
        snap = pd.DataFrame(rows).sort_values("Deviation", ascending=False)
        display = snap.copy()
        for c in ["CPI", "Core", "Target", "Deviation"]:
                display[c] = display[c].map(lambda x: f"{x:+.1f}%" if c == "Deviation" else f"{x:.1f}%")
        display_macro_table(display, height=360)
        months = pd.date_range(end=pd.Timestamp.today().normalize(), periods=12, freq="M").strftime("%b\n%y").tolist()
        z = []
        y = []
        text = []
        for code, spec in G10_BANKS_V6.items():
                trend = _v6_cpi_for_bank(code, pack).get("trend", [2.0])
                vals = list(trend)[-12:]
                if len(vals) < 12:
                        vals = [vals[0]] * (12-len(vals)) + vals
                z.append([v - spec["target"] for v in vals])
                text.append([f"{v:.1f}" for v in vals])
                y.append(f"{spec['flag']} {code}")
        fig = go.Figure(data=go.Heatmap(z=z, x=months, y=y, text=text, texttemplate="%{text}", colorscale="RdYlGn_r", zmid=0, colorbar_title="vs target"))
        fig.update_layout(height=460, margin=dict(l=20, r=20, t=35, b=20), title="12-Month CPI Heatmap — deviation from target")
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


