def _v6_render_misery(pack: Dict[str, pd.DataFrame]) -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Social Macro Risk</div><div class='macro-v6-title'>Misery Indices — Classic & Housing-Augmented</div><div class='macro-v6-sub'>Classic Misery = inflation + unemployment. Neo-Misery adds a housing-affordability burden. The gap between the two lines is the housing burden.</div></div>", unsafe_allow_html=True)
        rows = []
        for country, (code, inf, unemp, housing) in MISERY_COUNTRIES_V6.items():
                if code == "FED":
                        inf = _v6_get_us_yoy(pack, "CPIAUCSL", inf)
                        un = latest_series_value(pack, "UNRATE")
                        if un is not None:
                                unemp = float(un)
                classic = inf + unemp
                neo = classic + housing
                rows.append({"Country": country, "Classic": classic, "Inflation": inf, "Unemployment": unemp, "Housing burden": housing, "Neo-Misery": neo, "Gap": housing})
        table = pd.DataFrame(rows).sort_values("Neo-Misery", ascending=False)
        top = table.head(12)
        fig = go.Figure()
        fig.add_trace(go.Bar(x=top["Country"], y=top["Classic"], name="Classic"))
        fig.add_trace(go.Bar(x=top["Country"], y=top["Gap"], name="Housing burden"))
        fig.update_layout(height=430, barmode="stack", title="Classic vs Neo-Misery", margin=dict(l=20,r=20,t=40,b=80))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())
        display_macro_table(table.assign(**{c: table[c].map(lambda x: f"{x:.1f}") for c in ["Classic", "Inflation", "Unemployment", "Housing burden", "Neo-Misery", "Gap"]}), height=420)


