def _v6_render_payroll_lab(pack: Dict[str, pd.DataFrame]) -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Labor Market Observatory</div><div class='macro-v6-title'>US Payrolls & Labor Market</div><div class='macro-v6-sub'>Headline payrolls, private payrolls, wage pressure, hours, unemployment and JOLTS. Forecast lab uses deterministic baseline models until a true model store is connected.</div></div>", unsafe_allow_html=True)
        payems = pack.get("PAYEMS", pd.DataFrame())
        priv = pack.get("USPRIV", pd.DataFrame())
        latest_nfp = np.nan
        if isinstance(payems, pd.DataFrame) and len(payems) > 2:
                s = pd.to_numeric(payems["value"], errors="coerce").dropna()
                latest_nfp = value_change(s, 1) if len(s) > 2 else np.nan
        unrate = latest_series_value(pack, "UNRATE") or 4.2
        wages = _v6_get_us_yoy(pack, "CES0500000003", 3.59)
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Next NFP forecast", "99k", "median of models")
        c2.metric("Unemployment", f"{unrate:.1f}%")
        c3.metric("Latest payroll change", "N/A" if pd.isna(latest_nfp) else f"{latest_nfp:.0f}k")
        c4.metric("Avg hourly earnings YoY", f"{wages:.2f}%")
        models = pd.DataFrame([
                ["Street Consensus", np.nan, "survey"], ["Model Ensemble", 99, "median"], ["Naive AR", 62, "econometric"], ["SARIMAX", 44, "econometric"],
                ["VAR", 100, "econometric"], ["Unobserved Components", 90, "econometric"], ["MIDAS", 110, "econometric"],
                ["ElasticNet", 401, "ML"], ["Random Forest", 76, "ML"], ["XGBoost", 97, "ML"], ["LightGBM + Regime", 302, "ML"], ["MLP", 250, "ML"],
        ], columns=["Model", "Jul 2026 NFP Forecast", "Family"])
        left, right = st.columns([1.0, 1.0])
        with left:
                display_macro_table(models, height=360)
        with right:
                chart = models.dropna(subset=["Jul 2026 NFP Forecast"]).sort_values("Jul 2026 NFP Forecast")
                fig = go.Figure(go.Bar(x=chart["Model"], y=chart["Jul 2026 NFP Forecast"], text=[f"{x:.0f}k" for x in chart["Jul 2026 NFP Forecast"]], textposition="outside"))
                fig.add_hline(y=99, line_dash="dot", annotation_text="Median 99k")
                fig.update_layout(height=360, title="Payroll model disagreement", margin=dict(l=20,r=20,t=40,b=80))
                st.plotly_chart(fig, use_container_width=True, config=plotly_config())
        plot_fred_series(pack, ["PAYEMS", "USPRIV", "USGOOD", "SRVPRD"], "Payroll levels — total/private/goods/services", normalize=True)


def _v6_render_outlook() -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Economic Outlook</div><div class='macro-v6-title'>Consensus Forecasts — GDP & Inflation</div><div class='macro-v6-sub'>G10 outlook table synthesised as a structural placeholder. Replace with IMF WEO, OECD, central-bank projections or paid consensus feeds when connected.</div></div>", unsafe_allow_html=True)
        economies = ["United States", "Canada", "United Kingdom", "Eurozone", "Japan", "Sweden", "Switzerland", "Australia", "New Zealand", "Norway"]
        gdp = pd.DataFrame({"Time Period": ["Q4 2026", "Full Year 2026", "Full Year 2027", "Full Year 2028"]})
        infl = pd.DataFrame({"Time Period": ["Q4 2026", "Full Year 2026", "Full Year 2027", "Full Year 2028"]})
        base_g = [2.1, 2.0, 2.0, 1.9]
        base_i = [2.3, 2.4, 2.2, 2.1]
        for idx, e in enumerate(economies):
                adj = (idx % 5 - 2) * 0.15
                gdp[e] = [f"{max(0.1, x + adj):.1f}%" for x in base_g]
                infl[e] = [f"{max(0.1, x + adj/2):.1f}%" for x in base_i]
        st.markdown("#### Real GDP Growth")
        display_macro_table(gdp, height=240)
        st.markdown("#### Inflation")
        display_macro_table(infl, height=240)
        st.info("Key observations: US growth remains above several G10 peers; inflation gradually converges toward targets; Switzerland/Japan remain lower-inflation outliers; Australia/NZ remain somewhat stickier.")


def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V6 final renderer: RoboMacro-style macro suite inside Quant Terminal."""
        ticker = str(ticker or "SPY").upper().strip()
        analysis = analysis or {}
        _v6_inject_css()

        st.markdown(
                f"""
                <div class='macro-v6-shell'>
                        <div class='macro-v6-eyebrow'>Macro Intelligence Suite</div>
                        <div class='macro-v6-title'>Macro Intelligence & Central Bank Monitor</div>
                        <div class='macro-v6-sub'>{MACRO_CB_VERSION} · Central Banks · Taylor Rule · High-Speed Data · China · Misery · Inflation · Payrolls. Public-data first; live actual/consensus feeds remain optional.</div>
                </div>
                """,
                unsafe_allow_html=True,
        )

        all_series = tuple(dict.fromkeys(list(FRED_SERIES.keys()) + list(EXTRA_FRED_SERIES_V6.keys())))
        uploaded_calendar = None
        with st.expander("Macro suite controls", expanded=True):
                r1c1, r1c2, r1c3, r1c4 = st.columns([1.15, 1.05, 1.05, 1.35])
                with r1c1:
                        selected_code = st.selectbox(
                                "Central bank focus",
                                list(G10_BANKS_V6.keys()),
                                index=0,
                                format_func=lambda c: f"{G10_BANKS_V6[c]['flag']} {c} · {G10_BANKS_V6[c]['name']}",
                                key="macro_v6_central_bank_focus",
                        )
                with r1c2:
                        start_date = st.selectbox("Historique macro", ["1990-01-01", "2000-01-01", "2010-01-01", "2020-01-01"], index=1, key="macro_v6_start_date")
                with r1c3:
                        proxy_period = st.selectbox("Proxies marché", ["6mo", "1y", "2y", "5y"], index=2, key="macro_v6_proxy_period")
                with r1c4:
                        calendar_source = st.selectbox("Calendar source", ["Structural fallback", "Upload CSV/XLSX", "Trading Economics API if configured"], index=0, key="macro_v6_calendar_source")
                r2c1, r2c2, r2c3 = st.columns([1.35, 0.9, 0.9])
                with r2c1:
                        if calendar_source == "Upload CSV/XLSX":
                                uploaded_calendar = st.file_uploader("Upload economic calendar", type=["csv", "xlsx", "xls"], key="macro_v6_calendar_upload")
                        else:
                                st.caption("Calendar upload disabled for this source.")
                with r2c2:
                        days_back = st.number_input("Calendar days back", min_value=0, max_value=90, value=5, step=1, key="macro_v6_days_back")
                with r2c3:
                        days_forward = st.number_input("Calendar days forward", min_value=1, max_value=180, value=30, step=1, key="macro_v6_days_forward")

        pack = load_macro_fred_pack(all_series, start_date=start_date)
        proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
        calendar_df = build_calendar_dataset_v3(calendar_source, uploaded_calendar, int(days_back), int(days_forward)) if "build_calendar_dataset_v3" in globals() else pd.DataFrame()
        indicator_df = build_macro_indicator_table(pack)
        scores = build_macro_scores(pack)
        policy_df = build_central_bank_monitor(pack)
        curve_df = build_rates_curve_table(pack)
        curve_info = curve_state(pack)
        proxy_df = build_market_proxy_table(proxy_pack)
        beta_df = build_macro_beta_table(ticker, price_data, proxy_pack)
        bank_df = _v6_bank_table(pack)

        selected_spec = G10_BANKS_V6[selected_code]
        selected_row = bank_df.loc[bank_df["Code"] == selected_code].iloc[0]
        h1, h2, h3, h4, h5 = st.columns([1.0, 1.0, 1.0, 1.0, 1.2])
        h1.metric(f"{selected_spec['flag']} {selected_code} rate", f"{selected_row['Policy Rate']:.2f}%", selected_row["Stance"])
        h2.metric("Hawk/Dove", f"{selected_row['Hawk/Dove']:+.3f}")
        h3.metric("Inflation gap", f"{selected_row['Inflation Gap']:+.1f}pp")
        h4.metric("Taylor stance", _v6_build_taylor_table(bank_df).loc[lambda d: d["Code"] == selected_code, "Stance"].iloc[0])
        h5.metric("Macro composite", fmt_score(scores.get("macro_risk_score")))

        nav = st.tabs([
                "Central Banks", "Taylor Rule", "Inflation", "High Speed", "China", "Misery", "Payrolls", "Outlook", "Transmission / Quality"
        ])

        with nav[0]:
                _v6_card_grid(bank_df, selected_code)
                left, right = st.columns([1.15, 0.85])
                with left:
                        _v6_plot_hawk_dove(bank_df)
                with right:
                        _v6_plot_policy_ranked(bank_df)
                _v6_policy_history_chart(selected_code, pack)
                _v6_render_speeches(bank_df, selected_code)

        with nav[1]:
                _v6_render_taylor(bank_df, selected_code)

        with nav[2]:
                _v6_inflation_snapshot(bank_df, pack)
                st.markdown("#### Sticky vs Flexible Price CPI — US structure")
                plot_fred_series(pack, ["CORESTICKM159SFRBATL", "CORESTICKM158SFRBATL", "CPILFESL"], "Sticky vs flexible price CPI", normalize=False)

        with nav[3]:
                _v6_render_high_speed()

        with nav[4]:
                _v6_render_china()

        with nav[5]:
                _v6_render_misery(pack)

        with nav[6]:
                _v6_render_payroll_lab(pack)

        with nav[7]:
                _v6_render_outlook()

        with nav[8]:
                st.markdown("#### Cross-asset transmission")
                render_cross_asset_impact(ticker, price_data, proxy_df, beta_df)
                st.markdown("#### Data quality & provider roadmap")
                if "render_data_quality" in globals():
                        try:
                                render_data_quality(pack, proxy_pack, indicator_df, calendar_df=calendar_df)
                        except TypeError:
                                render_data_quality(pack, proxy_pack, indicator_df)

        st.caption(
                f"Macro {MACRO_CB_VERSION} COMPLETE — visual and analytical approximation of the requested RoboMacro-style macro suite. "
                "For exact live RoboMacro data parity, connect continuous feeds for consensus forecasts, G10 CPI, high-speed indicators and official central-bank balance sheets."
        )

