def _v61_month_end_dates(periods: int) -> pd.DatetimeIndex:
        """Pandas-compatible month-end range. pandas 3 rejects freq='M'."""
        return pd.date_range(end=pd.Timestamp.today().normalize(), periods=int(periods), freq="ME")


def _v61_html_escape(value: Any) -> str:
        try:
                import html as _html
                return _html.escape(str(value))
        except Exception:
                return str(value)


def _v61_bank_card_html(row: pd.Series, selected_code: str) -> str:
        spec = G10_BANKS_V6.get(str(row.get("Code", "")), {})
        code = str(row.get("Code", ""))
        marker_left = int(clamp(row.get("Composite", 50), 5, 95))
        selected_cls = " macro-bank-card-selected" if code == selected_code else ""
        stance = str(row.get("Stance", "HOLD"))
        stance_symbol = "▲" if stance == "HIKE" else "▼" if stance == "CUT" else "●"
        rate = safe_float(row.get("Policy Rate"), 0.0) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), 0.0) or 0.0
        members = int(safe_float(row.get("Members"), 0) or 0)
        target = safe_float(row.get("Target"), 2.0) or 2.0
        colour = str(spec.get("colour", "#6b7280"))
        return (
                f'<div class="macro-bank-card{selected_cls}">'
                f'<div class="macro-card-top">'
                f'<div><div class="macro-bank-name">{_v61_html_escape(spec.get("flag", ""))} {_v61_html_escape(code)}</div>'
                f'<div class="macro-bank-sub">{_v61_html_escape(row.get("Central Bank", ""))}</div></div>'
                f'<div class="macro-pill" style="background:{colour};">{_v61_html_escape(row.get("Currency", ""))}</div>'
                f'</div>'
                f'<div class="macro-rate">{rate:.2f}% <span class="macro-stance">{stance_symbol} {_v61_html_escape(stance)}</span></div>'
                f'<div class="macro-meter"><div class="macro-marker" style="left:{marker_left}%;"></div></div>'
                f'<div class="macro-small-row"><span>{hawk:+.3f}</span><span>{members} members</span></div>'
                f'<div class="macro-small-row"><span>{_v61_html_escape(row.get("Meetings", ""))}</span><span>target {target:.1f}%</span></div>'
                f'</div>'
        )


def _v6_card_grid(bank_df: pd.DataFrame, selected_code: str) -> None:
        """
        V6.1 override.
        Native Streamlit columns + one compact HTML block per card.
        This prevents Streamlit/PDF export from rendering the HTML source as text.
        """
        if bank_df is None or bank_df.empty:
                st.info("Central-bank grid unavailable.")
                return

        # Selected bank first, then other banks, similar to RoboMacro dashboards.
        work = bank_df.copy()
        work["_selected"] = work["Code"].astype(str).eq(str(selected_code))
        work = work.sort_values(["_selected", "Policy Rate"], ascending=[False, False]).drop(columns=["_selected"], errors="ignore")

        rows = list(work.iterrows())
        cards_per_row = 2
        for start in range(0, len(rows), cards_per_row):
                cols = st.columns(cards_per_row)
                for col, (_, row) in zip(cols, rows[start:start + cards_per_row]):
                        with col:
                                st.markdown(_v61_bank_card_html(row, selected_code), unsafe_allow_html=True)


def _v6_plot_hawk_dove(bank_df: pd.DataFrame) -> None:
        dates = _v61_month_end_dates(72)
        fig = go.Figure()
        if bank_df is None or bank_df.empty:
                st.info("Hawk/Dove composite unavailable.")
                return
        for _, row in bank_df.iterrows():
                code = str(row.get("Code", ""))
                if code not in G10_BANKS_V6:
                        continue
                seed = abs(hash(code)) % 17
                base = safe_float(row.get("Hawk/Dove"), 0.0) or 0.0
                vals = [base + 0.22 * math.sin((i + seed) / 7.0) + 0.10 * math.sin((i + seed) / 3.1) for i in range(len(dates))]
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=f"{G10_BANKS_V6[code].get('flag','')} {code}"))
        fig.add_hline(y=0, line_dash="dot", annotation_text="Neutral")
        fig.update_layout(
                height=400,
                margin=dict(l=20, r=20, t=35, b=20),
                title="Hawk/Dove Composite — G10 central banks",
                yaxis_title="Dovish    ←    score    →    Hawkish",
                legend=dict(orientation="h"),
        )
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def _v6_policy_history_chart(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        spec = G10_BANKS_V6.get(str(code), G10_BANKS_V6.get("FED", {}))
        sid = None
        df = pd.DataFrame()
        for candidate in spec.get("series", []):
                cand = pack.get(candidate, pd.DataFrame())
                if isinstance(cand, pd.DataFrame) and not cand.empty:
                        sid, df = candidate, cand.copy()
                        break
        if df.empty:
                dates = _v61_month_end_dates(48)
                rate = safe_float(spec.get("fallback_rate", 2.0), 2.0) or 2.0
                vals = [rate - 0.75 * math.sin(i / 12.0) for i in range(len(dates))]
                df = pd.DataFrame({"date": dates, "value": vals})
                sid = "structural"
        use = df.tail(96).copy()
        use["bs_change"] = [130 * math.sin(i / 6.0) + 60 * math.sin(i / 17.0) for i in range(len(use))]
        fig = go.Figure()
        fig.add_trace(go.Bar(x=use["date"], y=use["bs_change"], name="Balance-sheet proxy $bn/mo", yaxis="y2"))
        fig.add_trace(go.Scatter(x=use["date"], y=use["value"], name="Policy rate", mode="lines", line=dict(width=3)))
        fig.update_layout(
                height=440,
                margin=dict(l=20, r=20, t=40, b=20),
                title=f"{spec.get('name', code)} — Policy Rates & Balance Sheet proxy",
                yaxis=dict(title="Policy rate %"),
                yaxis2=dict(title="$bn/mo proxy", overlaying="y", side="right"),
                legend=dict(orientation="h"),
        )
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())
        st.caption(f"Source: {sid}. Balance-sheet bars are a structural proxy unless an official balance-sheet series is connected.")


def _v6_inflation_snapshot(bank_df: pd.DataFrame, pack: Dict[str, pd.DataFrame]) -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>Inflation Monitor</div><div class='macro-v6-title'>G10 Inflation Snapshot</div><div class='macro-v6-sub'>Headline CPI, core, deviation from central-bank target and twelve-month heatmap. US uses FRED when available; non-US cells use structural fallback until OECD/Eurostat/API feeds are attached.</div></div>", unsafe_allow_html=True)
        rows = []
        for code, spec in G10_BANKS_V6.items():
                cpi = _v6_cpi_for_bank(code, pack)
                rows.append({
                        "Country": f"{spec.get('flag','')} {spec.get('country', code)}",
                        "CB": code,
                        "CPI": cpi.get("headline"),
                        "Core": cpi.get("core"),
                        "Target": spec.get("target", 2.0),
                        "Deviation": cpi.get("headline", 2.0) - spec.get("target", 2.0),
                        "Unemployment": cpi.get("unemployment"),
                        "Next": "Provider required",
                })
        snap = pd.DataFrame(rows).sort_values("Deviation", ascending=False)
        display = snap.copy()
        for c in ["CPI", "Core", "Target", "Deviation", "Unemployment"]:
                if c in display.columns:
                        display[c] = display[c].map(lambda x: f"{x:+.1f}%" if c == "Deviation" else f"{x:.1f}%")
        display_macro_table(display, height=360)

        months = _v61_month_end_dates(12).strftime("%b\n%y").tolist()
        z, y, text = [], [], []
        for code, spec in G10_BANKS_V6.items():
                trend = _v6_cpi_for_bank(code, pack).get("trend", [2.0])
                vals = list(trend)[-12:]
                if len(vals) < 12:
                        vals = [vals[0] if vals else 2.0] * (12 - len(vals)) + vals
                z.append(vals)
                y.append(f"{spec.get('flag','')} {code}")
                text.append([f"{v:.1f}" for v in vals])
        fig = go.Figure(go.Heatmap(z=z, x=months, y=y, text=text, texttemplate="%{text}", colorbar=dict(title="CPI")))
        fig.update_layout(height=430, title="12-Month CPI Heatmap", margin=dict(l=20, r=20, t=40, b=20))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())


def _v6_render_china() -> None:
        st.markdown("<div class='macro-section-card'><div class='macro-v6-eyebrow'>China Macro</div><div class='macro-v6-title'>China Activity, Credit & Property Monitor</div><div class='macro-v6-sub'>A China-specific macro cockpit: activity, credit impulse, property stress, PBoC stance, CPI/PPI and FX pressure. Values are structural proxies until official China feeds are connected.</div></div>", unsafe_allow_html=True)
        kpis = [("Activity Index", 47.8, "below neutral"), ("Credit impulse", -1.4, "drag"), ("Property stress", 71.0, "elevated"), ("CPI YoY", 0.2, "weak demand"), ("PPI YoY", -2.1, "deflationary"), ("USD/CNY pressure", 62.0, "moderate")]
        cols = st.columns(6)
        for col, (name, val, read) in zip(cols, kpis):
                with col:
                        st.metric(name, f"{val:.1f}" if "YoY" not in name else f"{val:.1f}%")
                        st.caption(read)
        dates = _v61_month_end_dates(72)
        x = np.arange(len(dates))
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=dates, y=50 + 8*np.sin(x/7) - 0.12*x, name="Activity composite"))
        fig.add_trace(go.Scatter(x=dates, y=5*np.sin(x/8) - 2, name="Credit impulse", yaxis="y2"))
        fig.add_trace(go.Scatter(x=dates, y=65 + 8*np.sin(x/10) + 0.06*x, name="Property stress", yaxis="y3"))
        fig.update_layout(height=430, title="China macro dashboard", margin=dict(l=20,r=20,t=40,b=20), yaxis=dict(title="Activity"), yaxis2=dict(overlaying="y", side="right", title="Credit"), yaxis3=dict(anchor="free", overlaying="y", side="right", position=0.96, title="Stress"), legend=dict(orientation="h"))
        st.plotly_chart(fig, use_container_width=True, config=plotly_config())

