def _v7_esc(x: Any) -> str:
        s = "" if x is None else str(x)
        if _macro_html_v7 is not None:
                return _macro_html_v7.escape(s)
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


