def _v7_html_table(df: pd.DataFrame, max_rows: int = 60, index: bool = False) -> None:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
                st.markdown('<div class="v7-note">No table data available.</div>', unsafe_allow_html=True)
                return
        use = df.head(max_rows).copy()
        if index:
                use = use.reset_index()
        header = "".join([f"<th>{_v7_esc(c)}</th>" for c in use.columns])
        rows = []
        for _, r in use.iterrows():
                cells = "".join([f"<td>{_v7_esc(v)}</td>" for v in r.tolist()])
                rows.append(f"<tr>{cells}</tr>")
        st.markdown(f'<table class="v7-table"><thead><tr>{header}</tr></thead><tbody>{"".join(rows)}</tbody></table>', unsafe_allow_html=True)


