def _v7_policy_balance_chart(code: str, bank_df: pd.DataFrame, pack: Dict[str, pd.DataFrame]) -> None:
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6.get("FED", {}))
        rate = safe_float(bank_df.loc[bank_df["Code"] == code, "Policy Rate"].iloc[0]) if code in set(bank_df["Code"]) else spec.get("fallback_rate", 0.0)
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=88, freq="W")
        x = np.arange(len(dates))
        # If FED balance sheet exists, use monthly changes, otherwise structural proxy.
        bs = None
        if code == "FED":
                walcl = pack.get("WALCL", pd.DataFrame())
                if isinstance(walcl, pd.DataFrame) and not walcl.empty:
                        tmp = walcl.dropna(subset=["date", "value"]).copy()
                        tmp["date"] = pd.to_datetime(tmp["date"])
                        tmp = tmp.set_index("date")["value"].resample("ME").last().diff() / 1000.0
                        if len(tmp.dropna()) > 5:
                                bs = tmp.tail(36)
        if bs is None:
                bs = pd.Series(75*np.sin(x/7) - 35*np.cos(x/13), index=dates)
        rate_line = pd.Series(rate + 0.2*np.sin(np.arange(len(bs))/11), index=bs.index)
        if code == "FED":
                dff = pack.get("DFF", pd.DataFrame())
                if isinstance(dff, pd.DataFrame) and not dff.empty:
                        try:
                                r = dff.dropna(subset=["date", "value"]).copy()
                                r["date"] = pd.to_datetime(r["date"])
                                rate_line = r.set_index("date")["value"].resample("ME").last().tail(len(bs))
                        except Exception:
                                pass
        fig = go.Figure()
        fig.add_trace(go.Bar(x=bs.index, y=bs.values, name="Balance sheet change $bn/mo", yaxis="y2", opacity=0.72))
        fig.add_trace(go.Scatter(x=rate_line.index, y=rate_line.values, mode="lines", name="Policy rate", line=dict(width=3)))
        fig.update_layout(yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo", overlaying="y", side="right"))
        st.plotly_chart(_v7_line_template(fig, 440, f"{spec.get('name', code)} — Policy Rates & Balance Sheet"), use_container_width=True, config=plotly_config())
        st.markdown('<div class="v7-source">Source: public FRED/OECD proxies where available. Balance-sheet bars are provider-ready; non-US values use structural placeholders until official series are connected.</div>', unsafe_allow_html=True)


