def _v7_taylor_df(bank_df: pd.DataFrame) -> pd.DataFrame:
        df = _v6_build_taylor_table(bank_df).copy()
        # Keep RoboMacro-like display columns.
        if "Central Bank" not in df.columns:
                df["Central Bank"] = df["Code"].map(lambda c: G10_BANKS_V6.get(c, {}).get("name", c))
        if "Country" not in df.columns:
                df["Country"] = df["Code"].map(lambda c: G10_BANKS_V6.get(c, {}).get("country", c))
        for col in ["Actual Rate", "Taylor Implied", "Gap", "YE 2026 Implied", "YE 2027 Implied", "Inflation", "Target", "Output Gap"]:
                if col in df.columns:
                        df[col] = pd.to_numeric(df[col], errors="coerce")
        return df.sort_values("Gap", ascending=False)


def _v7_render_taylor(bank_df: pd.DataFrame, selected_code: str) -> None:
        _v7_hero("Monetary Policy Analysis", "G10 Taylor Rule Monitor", "Prescriptive monetary-policy rates using r = r* + π + 0.5(π − π*) + 0.5(output gap). Positive gap means policy looks looser than prescribed.")
        taylor = _v7_taylor_df(bank_df)
        row = taylor[taylor["Code"] == selected_code]
        if row.empty:
                row = taylor.head(1)
        r = row.iloc[0]
        _v7_metric_cards([
                ("Actual", _v7_pct(r.get("Actual Rate")), G10_BANKS_V6.get(str(r.get("Code")), {}).get("name", "")),
                ("Taylor implied", _v7_pct(r.get("Taylor Implied")), "prescriptive rate"),
                ("Gap", _v7_pct(r.get("Gap")), "implied minus actual"),
                ("Stance", str(r.get("Stance", "Neutral")), "rule-of-thumb diagnosis"),
        ])
        c1, c2 = st.columns([.95, 1.05])
        with c1:
                fig = go.Figure(go.Bar(y=[f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in taylor["Code"]], x=taylor["Gap"], orientation="h", text=[f"{x:+.2f}%" for x in taylor["Gap"]], textposition="outside"))
                fig.add_vline(x=0, line_dash="dot")
                st.plotly_chart(_v7_line_template(fig, 455, "G10 Taylor Rule Gap Ranking"), use_container_width=True, config=plotly_config())
        with c2:
                disp = taylor[["Code", "Country", "Central Bank", "Actual Rate", "Taylor Implied", "Gap", "YE 2026 Implied", "YE 2027 Implied", "Inflation", "Target", "Output Gap", "Stance"]].copy()
                for col in ["Actual Rate", "Taylor Implied", "Gap", "YE 2026 Implied", "YE 2027 Implied", "Inflation", "Target", "Output Gap"]:
                        disp[col] = disp[col].map(lambda x: _v7_pct(x))
                _v7_html_table(disp, max_rows=12)


def _v7_inflation_table(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows = []
        order = ["FED", "RBA", "BOC", "RBNZ", "ECB", "BOE", "NORGES", "BOJ", "SNB", "RIKSBANK"]
        for code in order:
                spec = G10_BANKS_V6.get(code, {})
                cpi = _v6_cpi_for_bank(code, pack)
                target = safe_float(spec.get("target"), 2.0) or 2.0
                rows.append({
                        "Country": f"{spec.get('flag','')} {spec.get('country', code)}",
                        "CB": code,
                        "CPI": f"{safe_float(cpi.get('headline'), 0.0):.1f}%",
                        "Core": f"{safe_float(cpi.get('core'), 0.0):.1f}%",
                        "Target": f"{target:.1f}%",
                        "Deviation": f"{safe_float(cpi.get('headline'),0.0) - target:+.1f}pp",
                        "Unemployment": f"{safe_float(cpi.get('unemployment'), 0.0):.1f}%",
                        "Next": "Provider required",
                })
        return pd.DataFrame(rows)


def _v7_inflation_heatmap(pack: Dict[str, pd.DataFrame]) -> None:
        codes = ["FED", "BOE", "BOJ", "ECB", "BOC", "RBA", "RBNZ", "SNB", "RIKSBANK", "NORGES"]
        months = pd.date_range(end=pd.Timestamp.today().normalize(), periods=12, freq="ME").strftime("%b\n%y").tolist()
        z = []
        for i, code in enumerate(codes):
                trend = _v6_cpi_for_bank(code, pack).get("trend", [])
                vals = list(trend) if isinstance(trend, list) else []
                if len(vals) < 12:
                        base = safe_float(_v6_cpi_for_bank(code, pack).get("headline"), 2.0) or 2.0
                        vals = [base + 0.35*np.sin(j/2 + i*.4) for j in range(12)]
                z.append(vals[-12:])
        labels = [f"{G10_BANKS_V6[c].get('flag','')} {c}" for c in codes]
        fig = go.Figure(go.Heatmap(z=z, x=months, y=labels, colorscale="RdYlGn_r", text=[[f"{v:.1f}" for v in row] for row in z], texttemplate="%{text}", colorbar=dict(title="CPI")))
        st.plotly_chart(_v7_line_template(fig, 460, "12-Month CPI Heatmap"), use_container_width=True, config=plotly_config())


def _v7_us_yoy_series(pack: Dict[str, pd.DataFrame], sid: str, fallback_level: float = 2.0) -> pd.Series:
        df = pack.get(sid, pd.DataFrame())
        if isinstance(df, pd.DataFrame) and not df.empty:
                try:
                        s = df.dropna(subset=["date", "value"]).copy()
                        s["date"] = pd.to_datetime(s["date"])
                        vals = pd.to_numeric(s["value"], errors="coerce")
                        yoy = vals.pct_change(12) * 100.0
                        out = pd.Series(yoy.values, index=s["date"]).dropna()
                        if len(out) > 24:
                                return out.tail(84)
                except Exception:
                        pass
        dates = _v7_month_dates(84)
        x = np.arange(len(dates))
        return pd.Series(fallback_level + .4*np.sin(x/8) + .2*np.cos(x/17), index=dates)


def _v7_sticky_flexible(pack: Dict[str, pd.DataFrame]) -> None:
        dates = _v7_month_dates(84)
        # Try FRED Atlanta sticky/flexible YoY series; fallback to generated YoY-like lines.
        sticky_df = fetch_fred_csv_series("CORESTICKM159SFRBATL", "2000-01-01") if 'fetch_fred_csv_series' in globals() else pd.DataFrame()
        flex_df = fetch_fred_csv_series("COREXAPFESL", "2000-01-01") if 'fetch_fred_csv_series' in globals() else pd.DataFrame()
        core = _v7_us_yoy_series(pack, "CPILFESL", 2.8)
        if isinstance(sticky_df, pd.DataFrame) and not sticky_df.empty:
                sticky = pd.Series(pd.to_numeric(sticky_df["value"], errors="coerce").values, index=pd.to_datetime(sticky_df["date"])).dropna().tail(84)
        else:
                x = np.arange(len(core)); sticky = pd.Series(3.1 + .25*np.sin(x/9), index=core.index)
        if isinstance(flex_df, pd.DataFrame) and not flex_df.empty:
                # If value is index, convert to yoy, otherwise use as level.
                tmp = pd.Series(pd.to_numeric(flex_df["value"], errors="coerce").values, index=pd.to_datetime(flex_df["date"])).dropna()
                flex = (tmp.pct_change(12)*100).dropna().tail(84)
        else:
                x = np.arange(len(core)); flex = pd.Series(1.4 + .8*np.sin(x/6), index=core.index)
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=sticky.index, y=sticky.values, mode="lines", name="Sticky-Price Core"))
        fig.add_trace(go.Scatter(x=flex.index, y=flex.values, mode="lines", name="Flexible-Price Core"))
        fig.add_trace(go.Scatter(x=core.index, y=core.values, mode="lines", name="BLS Core CPI", line=dict(dash="dash")))
        fig.add_hline(y=2.0, line_dash="dot", annotation_text="2% target", annotation_position="right")
        st.plotly_chart(_v7_line_template(fig, 420, "Sticky vs Flexible Price CPI"), use_container_width=True, config=plotly_config())


def _v7_render_inflation(pack: Dict[str, pd.DataFrame]) -> None:
        _v7_hero("Inflation Monitor", "G10 Inflation Snapshot", "Headline CPI, core CPI, deviation from central-bank target and next release readiness — all in one view.")
        _v7_html_table(_v7_inflation_table(pack), max_rows=12)
