def _v7_render_misery() -> None:
        _v7_hero("Economy", "Misery Indices — G20", "Classic misery = unemployment + inflation. Neo-misery adds a housing-affordability burden, so the gap between the two series is the housing stress component.")
        countries = ["Australia", "Canada", "New Zealand", "Sweden", "United States", "Brazil", "Eurozone", "France", "China", "United Kingdom", "India", "Norway"]
        infl = np.array([4.0, 3.2, 3.1, .7, 4.3, 5.3, 2.8, 1.1, .2, 2.8, 3.2, 2.7])
        unemp = np.array([4.3, 6.9, 5.0, 8.3, 4.2, 6.2, 6.4, 7.5, 5.4, 4.9, 7.8, 4.0])
        housing = np.array([11.0, 8.8, 9.5, 7.5, 8.0, 4.7, 6.5, 7.0, 9.6, 7.0, 3.0, 6.7])
        classic = infl + unemp
        neo = classic + housing
        df = pd.DataFrame({"Country": countries, "Classic": classic.round(1), "Inflation": infl, "Unemployment": unemp, "Housing burden": housing, "Neo-Misery": neo.round(1), "Gap": housing})
        fig = go.Figure()
        fig.add_trace(go.Bar(x=countries, y=classic, name="Classic"))
        fig.add_trace(go.Bar(x=countries, y=housing, name="Housing burden"))
        fig.update_layout(barmode="stack")
        st.plotly_chart(_v7_line_template(fig, 430, "Classic vs Neo-Misery"), use_container_width=True, config=plotly_config())
        _v7_html_table(df.sort_values("Neo-Misery", ascending=False), max_rows=20)


