def _v7_render_outlook() -> None:
        _v7_hero("Economic Outlook", "Consensus Forecasts — GDP & Inflation", "G10 outlook table synthesised as a structural placeholder. Replace with IMF WEO, OECD, central-bank projections or paid consensus feeds when connected.")
        countries = ["United States", "Canada", "United Kingdom", "Eurozone", "Japan", "Sweden", "Switzerland", "Australia", "New Zealand", "Norway"]
        periods = ["Q4 2026", "Full Year 2026", "Full Year 2027", "Full Year 2028"]
        growth = pd.DataFrame([[p] + [f"{2.1 - .12*i - .08*j:.1f}%" for j, _ in enumerate(countries)] for i, p in enumerate(periods)], columns=["Time Period"] + countries)
        inflation = pd.DataFrame([[p] + [f"{2.3 - .10*i + .05*(j%3):.1f}%" for j, _ in enumerate(countries)] for i, p in enumerate(periods)], columns=["Time Period"] + countries)
        st.markdown('<div class="v7-section-title">Real GDP Growth</div>', unsafe_allow_html=True)
        _v7_html_table(growth, max_rows=8)
        st.markdown('<div class="v7-section-title">Inflation</div>', unsafe_allow_html=True)
        _v7_html_table(inflation, max_rows=8)
        st.markdown('<div class="v7-note">Key observations: US growth remains above several G10 peers; inflation gradually converges toward targets; Switzerland/Japan remain lower-inflation outliers; Australia/NZ remain somewhat stickier.</div>', unsafe_allow_html=True)


def _v7_render_quality(pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame) -> None:
        _v7_hero("Data Architecture", "Transmission & Data Quality", "Provider roadmap for converting the visual layer into a live institutional macro terminal.")
        total = len(FRED_SERIES)
        ok = int((indicator_df["Status"] == "OK").sum()) if isinstance(indicator_df, pd.DataFrame) and not indicator_df.empty else 0
        proxies = sum(1 for df in proxy_pack.values() if isinstance(df, pd.DataFrame) and not df.empty)
        _v7_metric_cards([
                ("FRED series", f"{ok}/{total}", "public data"), ("Market proxies", f"{proxies}/{len(MARKET_PROXIES)}", "Yahoo"),
                ("G10 live data", "Partial", "provider-ready"), ("Calendar consensus", "Optional", "TE/Bloomberg/LSEG")
        ])
        roadmap = pd.DataFrame([
                ["Central Banks", "Policy rates, balance sheets, speeches", "FRED/OECD fallback now; official CB feeds next"],
                ["Taylor Rule", "Actual rates, CPI, output gap, consensus path", "US stronger; non-US needs OECD/IMF/CB projections"],
                ["Inflation", "G10 CPI/core/targets/releases", "Attach OECD/Eurostat/ONS/StatsCan/ABS"],
                ["High-Speed", "Power, traffic, cards, job ads, tax", "Requires country-specific APIs/scrapers"],
                ["China", "NBS/PBoC/BIS/OECD/SAFE/market data", "Provider integration required for live parity"],
                ["Misery", "Inflation + unemployment + housing burden", "Official statistics plus housing affordability datasets"],
                ["Payrolls", "FRED/BLS + forecast models", "Can be upgraded with local model training"],
        ], columns=["Module", "Data needed", "Status"])
        _v7_html_table(roadmap, max_rows=12)


def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V7 RoboMacro-like renderer. No generic macro control expander."""
        ticker = str(ticker or "SPY").upper().strip()
        _v7_css()
        _v7_open_shell()
        try:
                # Fixed desk defaults; no macro-suite control panel.
                start_date = "2000-01-01"
                proxy_period = "2y"
                series_ids = tuple(set(list(FRED_SERIES.keys()) + ["USPRIV", "USGOOD", "SRVPRD", "CORESTICKM159SFRBATL", "COREXAPFESL"]))
                pack = load_macro_fred_pack(series_ids, start_date=start_date)
                proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
                indicator_df = build_macro_indicator_table(pack)
                scores = build_macro_scores(pack)
                bank_df = _v7_structural_bank_df(pack)
                selected_default = "FED" if "macro_v7_selected_bank" not in st.session_state else st.session_state.get("macro_v7_selected_bank", "FED")

                _v7_topbar("Central Banks")
                page = st.radio(
                        "Economy section",
                        ["Central Banks", "Taylor Rule", "Inflation", "High Speed", "China", "Misery", "Payrolls", "Outlook", "Transmission / Quality"],
                        horizontal=True,
                        label_visibility="collapsed",
                        key="macro_v7_page",
                )
                bank_choice = st.radio(
                        "Central bank selector",
                        list(G10_BANKS_V6.keys()),
                        index=list(G10_BANKS_V6.keys()).index(selected_default) if selected_default in G10_BANKS_V6 else 0,
                        horizontal=True,
                        format_func=lambda c: f"{G10_BANKS_V6[c].get('flag','')} {c}",
                        label_visibility="collapsed",
                        key="macro_v7_selected_bank",
                )

                if page == "Central Banks":
                        _v7_render_central_banks(bank_df, bank_choice, pack)
                elif page == "Taylor Rule":
                        _v7_render_taylor(bank_df, bank_choice)
                elif page == "Inflation":
                        _v7_render_inflation(pack)
                elif page == "High Speed":
                        _v7_render_high_speed()
                elif page == "China":
                        _v7_render_china()
                elif page == "Misery":
                        _v7_render_misery()
                elif page == "Payrolls":
                        _v7_render_payrolls(pack)
                elif page == "Outlook":
                        _v7_render_outlook()
                else:
                        _v7_render_quality(pack, proxy_pack, indicator_df)

                st.markdown(
                        '<div class="v7-footer">Macro V7 · RoboMacro-like economy workspace. Structural/public-data approximation; for exact live parity connect continuous feeds for G10 CPI, consensus forecasts, high-speed indicators, central-bank balance sheets, speeches and event calendars.</div>',
                        unsafe_allow_html=True,
                )
        finally:
                _v7_close_shell()

