def _v8_query_get(name: str, default: str = "") -> str:
        try:
                q = st.query_params.get(name, default)
                if isinstance(q, list):
                        return str(q[0]) if q else default
                return str(q) if q is not None else default
        except Exception:
                try:
                        q = st.experimental_get_query_params().get(name, [default])
                        return str(q[0]) if q else default
                except Exception:
                        return default


def _v8_href(page: str, bank: Optional[str] = None, view: Optional[str] = None) -> str:
        parts = [f"macro_page={quote(str(page))}"]
        if bank:
                parts.append(f"macro_bank={quote(str(bank))}")
        if view:
                parts.append(f"macro_view={quote(str(view))}")
        return "?" + "&".join(parts)


