def _v8_html_table(df: pd.DataFrame, max_rows: int = 60) -> None:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
                st.markdown('<div class="v8-panel">No table data available.</div>', unsafe_allow_html=True)
                return
        use = df.head(max_rows).copy()
        header = "".join([f"<th>{_v7_esc(c)}</th>" for c in use.columns])
        rows = []
        for _, r in use.iterrows():
                cells = "".join([f"<td>{_v7_esc(v)}</td>" for v in r.tolist()])
                rows.append(f"<tr>{cells}</tr>")
        st.markdown(f'<table class="v8-table"><thead><tr>{header}</tr></thead><tbody>{"".join(rows)}</tbody></table>', unsafe_allow_html=True)


def _v8_bank_card(row: pd.Series, selected_code: str = "FED") -> str:
        code = str(row.get("Code", ""))
        spec = G10_BANKS_V6.get(code, {})
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
        status = str(row.get("Status", spec.get("status", "HOLD"))).upper()
        stance_cls = "hike" if "HIKE" in status else "cut" if "CUT" in status else "hold"
        icon = "▲" if "HIKE" in status else "▼" if "CUT" in status else "●"
        marker = max(4, min(96, 50 + hawk * 45 + (rate - 2.0) * 4))
        selected = " selected" if code == selected_code else ""
        href = _v8_href("central-banks", code, "bank")
        return f"""
        <a class="v8-bank-card{selected}" href="{href}" target="_self">
                <div class="v8-card-head">
                        <div><div class="v8-bank-code">{_v7_esc(spec.get('flag',''))} {_v7_esc(code)}</div><div class="v8-bank-name">{_v7_esc(spec.get('name', row.get('Name','')))}</div></div>
                        <div class="v8-ccy" style="background:{_v7_esc(spec.get('colour','#2f6688'))}">{_v7_esc(spec.get('ccy', row.get('Currency','')))}</div>
                </div>
                <div class="v8-rate">{rate:.2f}% <span class="v8-stance {stance_cls}">{icon} {status}</span></div>
                <div class="v8-meter"><div class="v8-marker" style="left:{marker:.1f}%"></div></div>
                <div class="v8-card-row"><span>{hawk:+.3f}</span><span>{_v7_esc(row.get('Members', spec.get('members','')))} members</span></div>
                <div class="v8-card-row"><span>{_v7_esc(row.get('Meetings', spec.get('meetings','')))}</span><span>target {safe_float(row.get('Target'), spec.get('target',2.0)):.1f}%</span></div>
        </a>
        """


def _v8_cards_grid(bank_df: pd.DataFrame, selected_code: str) -> None:
        order = ["RBA", "NORGES", "BOE", "FED", "RBNZ", "ECB", "BOC", "RIKSBANK", "BOJ", "SNB"]
        use = bank_df.copy()
        use["_order"] = use["Code"].map({c: i for i, c in enumerate(order)}).fillna(99)
        use = use.sort_values("_order")
        cards = "".join([_v8_bank_card(row, selected_code) for _, row in use.iterrows()])
        st.markdown(f'<div class="v8-bank-grid">{cards}</div>', unsafe_allow_html=True)


def _v8_bank_switch(selected_code: str) -> None:
        chips = []
        for code, spec in G10_BANKS_V6.items():
                cls = " active" if code == selected_code else ""
                chips.append(f'<a class="v8-chip{cls}" href="{_v8_href("central-banks", code, "bank")}" target="_self">{_v7_esc(spec.get("flag",""))} {code}</a>')
        st.markdown(f'<div class="v8-bank-switch">{"".join(chips)}</div>', unsafe_allow_html=True)


def _v8_selected_row(bank_df: pd.DataFrame, code: str) -> pd.Series:
        sub = bank_df.loc[bank_df["Code"].astype(str) == str(code)] if isinstance(bank_df, pd.DataFrame) and not bank_df.empty else pd.DataFrame()
        if not sub.empty:
                return sub.iloc[0]
        # fallback row
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6.get("FED", {}))
        return pd.Series({
                "Code": code, "Bank": spec.get("bank", code), "Name": spec.get("name", code), "Country": spec.get("country", ""),
                "Currency": spec.get("ccy", ""), "Policy Rate": spec.get("fallback_rate", np.nan),
                "Hawk/Dove": spec.get("fallback_hawk", 0.0), "Status": spec.get("status", "HOLD"),
                "Members": spec.get("members", ""), "Meetings": spec.get("meetings", ""), "Target": spec.get("target", 2.0), "Source": "Structural fallback"
        })


def _v8_metric_row(items: List[Tuple[str, str, str]]) -> None:
        cols = st.columns(len(items))
        for col, (label, value, sub) in zip(cols, items):
                with col:
                        st.markdown(
                                f"""
                                <div class="v8-panel" style="min-height:112px;">
                                        <div style="font-size:.76rem;color:#8a929d;font-weight:900;text-transform:uppercase;letter-spacing:.08em;">{_v7_esc(label)}</div>
                                        <div style="font-family:Georgia,serif;font-size:2rem;font-weight:900;margin-top:7px;">{_v7_esc(value)}</div>
                                        <div style="color:#8b929d;font-weight:700;font-size:.82rem;">{_v7_esc(sub)}</div>
                                </div>
                                """,
                                unsafe_allow_html=True,
                        )


def _v8_render_central_banks_overview(bank_df: pd.DataFrame, selected_code: str, pack: Dict[str, pd.DataFrame]) -> None:
        _v8_hero("Global Monetary Policy Observatory", "Hawk/Dove Monitor — G10 Central Banks", "Click any central-bank square to open the dedicated bank page, matching the /central-banks/BOE style workflow.")
        _v8_cards_grid(bank_df, selected_code)
        c1, c2 = st.columns([1.2, .9])
        with c1:
                _v7_plot_hawk_dove(bank_df)
        with c2:
                _v7_policy_ranked(bank_df)
        _v7_policy_balance_chart(selected_code, bank_df, pack)
        st.markdown('<div class="v8-section-title">Recent Speeches</div><div class="v8-section-sub">Hawk/dove NLP tape. Scores are structural until an official speeches feed is connected.</div>', unsafe_allow_html=True)
        _v7_speeches_table(selected_code)


def _v8_policy_reaction_table(code: str) -> pd.DataFrame:
        spec = G10_BANKS_V6.get(code, {})
        ccy = spec.get("ccy", "")
        return pd.DataFrame([
                ["Inflation surprise above consensus", "Hawkish", "Front-end yields higher", f"{ccy} supported if growth stable", "Duration/growth equity vulnerable"],
                ["Inflation surprise below consensus", "Dovish", "Front-end yields lower", f"{ccy} softer unless risk rally offsets", "Duration relief / risk support"],
                ["Growth/labor above consensus", "Less urgency to ease", "Bear-flattening risk", f"{ccy} supported", "Cyclicals supported unless rates shock dominates"],
                ["Growth/labor below consensus", "Cuts/recession pricing", "Bull-steepening risk", f"{ccy} vulnerable", "Credit and small caps vulnerable"],
                ["Hawkish speech cluster", "Guidance reprices higher", "2Y-led selloff", f"{ccy} support", "Multiple compression risk"],
                ["Dovish speech cluster", "Easing optionality rises", "2Y-led rally", f"{ccy} softer", "Initial risk relief; watch credibility"],
        ], columns=["Shock", "Policy read", "Rates", "FX", "Risk assets"])


def _v8_bank_event_tape(code: str) -> pd.DataFrame:
        rows = [
                ["Next decision", "Provider required", "Rate decision", "High", "Actual/consensus feed needed"],
                ["Statement / minutes", "Provider required", "Guidance", "High", "Language shift drives hawk/dove score"],
                ["Inflation release", "Provider required", "Reaction function", "High", "Compare actual vs consensus and target"],
                ["Labor / growth release", "Provider required", "Growth balance", "Medium", "Determines tolerance for tight policy"],
        ]
        return pd.DataFrame(rows, columns=["Event", "Date", "Type", "Importance", "Read"])


def _v8_render_bank_detail(bank_df: pd.DataFrame, code: str, pack: Dict[str, pd.DataFrame]) -> None:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6[code]
        row = _v8_selected_row(bank_df, code)
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
        status = str(row.get("Status", spec.get("status", "HOLD"))).upper()
        target = safe_float(row.get("Target"), spec.get("target", 2.0)) or 2.0

        st.markdown(f'<a class="v8-back" href="{_v8_href("central-banks")}" target="_self">← Central Banks</a>', unsafe_allow_html=True)
        _v8_bank_switch(code)
        _v8_hero(
                "Central Bank Workstation",
                f"{spec.get('flag','')} {code} — {spec.get('name', code)}",
                f"Dedicated policy page: rate stance, hawk/dove tilt, Taylor prescription, balance-sheet proxy, decision tape and speeches. URL-style route: /central-banks/{code}.",
        )
        _v8_metric_row([
                ("Policy rate", f"{rate:.2f}%", status),
                ("Hawk/Dove", f"{hawk:+.3f}", "positive = hawkish"),
                ("Inflation target", f"{target:.1f}%", spec.get("country", "")),
                ("Currency", str(spec.get("ccy", "")), spec.get("meetings", "")),
        ])

        c1, c2 = st.columns([.85, 1.15])
        with c1:
                st.markdown('<div class="v8-section-title">Policy Card</div>', unsafe_allow_html=True)
                st.markdown(_v8_bank_card(row, code), unsafe_allow_html=True)
                st.markdown('<div class="v8-section-title">Event Tape</div>', unsafe_allow_html=True)
                _v8_html_table(_v8_bank_event_tape(code), max_rows=8)
        with c2:
                _v7_policy_balance_chart(code, bank_df, pack)

        c3, c4 = st.columns([1.0, 1.0])
        with c3:
                st.markdown('<div class="v8-section-title">Reaction Function</div>', unsafe_allow_html=True)
                _v8_html_table(_v8_policy_reaction_table(code), max_rows=8)
        with c4:
                st.markdown('<div class="v8-section-title">Taylor Snapshot</div>', unsafe_allow_html=True)
                taylor = _v6_taylor_table(bank_df)
                sub = taylor.loc[taylor["Code"] == code] if isinstance(taylor, pd.DataFrame) and not taylor.empty else pd.DataFrame()
                _v8_html_table(sub if not sub.empty else taylor.head(1), max_rows=4)

        st.markdown('<div class="v8-section-title">Recent Speeches</div>', unsafe_allow_html=True)
        _v7_speeches_table(code)


