def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V8 RoboMacro-like routed renderer. Query-param navigation and clickable bank cards."""
        ticker = str(ticker or "SPY").upper().strip()
        _v7_css()
        _v8_css()
        st.markdown('<div class="v8-shell">', unsafe_allow_html=True)
        try:
                raw_page = _v8_query_get("macro_page", "central-banks").strip().lower().replace("_", "-")
                aliases = {
                        "central": "central-banks", "central-bank": "central-banks", "banks": "central-banks",
                        "taylor": "taylor-rule", "payrolls": "us-payrolls", "nfp": "us-payrolls",
                        "outlook": "consensus-forecasts", "forecast": "consensus-forecasts", "forecasts": "consensus-forecasts",
                        "misery": "misery-indices", "quality": "quality", "sources": "quality",
                }
                page = aliases.get(raw_page, raw_page)
                if page not in V8_PAGE_LABELS:
                        page = "central-banks"
                selected_code = _v8_query_get("macro_bank", "FED").upper().strip()
                if selected_code not in G10_BANKS_V6:
                        selected_code = "FED"
                view = _v8_query_get("macro_view", "overview").lower().strip()

                # Fixed desk defaults: no visible macro-suite controls.
                start_date = "2000-01-01"
                proxy_period = "2y"
                series_ids = tuple(set(list(FRED_SERIES.keys()) + [
                        "USPRIV", "USGOOD", "SRVPRD", "CORESTICKM159SFRBATL", "CORESTICKM158SFRBATL",
                        "USEHS", "LNS12026620", "U6RATE", "JTSJOL", "AWHNONAG", "TEMPHELPS",
                        "IRSTCI01NZM156N", "IRSTCI01SEM156N", "IRSTCI01NOM156N",
                ]))
                pack = load_macro_fred_pack(series_ids, start_date=start_date)
                proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
                indicator_df = build_macro_indicator_table(pack)
                bank_df = _v7_structural_bank_df(pack)

                _v8_topnav(page)
                st.markdown('<div class="v8-body">', unsafe_allow_html=True)

                if page == "central-banks":
                        if view == "bank":
                                _v8_render_bank_detail(bank_df, selected_code, pack)
                        else:
                                _v8_render_central_banks_overview(bank_df, selected_code, pack)
                elif page == "taylor-rule":
                        _v8_render_taylor(bank_df, selected_code)
                elif page == "inflation":
                        _v8_render_inflation(pack)
                elif page == "high-speed":
                        _v8_render_high_speed()
                elif page == "china":
                        _v8_render_china()
                elif page == "misery-indices":
                        _v8_render_misery()
                elif page == "us-payrolls":
                        _v8_render_payrolls(pack)
                elif page == "consensus-forecasts":
                        _v8_render_outlook()
                else:
                        _v8_render_quality(pack, proxy_pack, indicator_df)

                st.markdown(
                        '<div class="v8-footer">Macro V8 · RoboMacro-like routed economy workspace. Central-bank cards are clickable and route to bank-level pages. Structural/public-data approximation; exact live parity requires continuous feeds for G10 CPI, policy rates, central-bank balance sheets, speeches, high-speed indicators, consensus forecasts and event calendars.</div>',
                        unsafe_allow_html=True,
                )
                st.markdown('</div>', unsafe_allow_html=True)
        finally:
                st.markdown('</div>', unsafe_allow_html=True)

