def _v9_normalize_page(raw: str) -> str:
        aliases = {
                "central": "central-banks", "central-bank": "central-banks", "banks": "central-banks",
                "payrolls": "us-payrolls", "nfp": "us-payrolls",
                "outlook": "consensus-forecasts", "forecast": "consensus-forecasts", "forecasts": "consensus-forecasts",
                "taylor": "taylor-rule", "misery": "misery-indices", "sources": "quality", "quality": "quality",
        }
        page = str(raw or "central-banks").strip().lower().replace("_", "-")
        page = aliases.get(page, page)
        return page if page in V9_PAGE_LABELS else "central-banks"


def _v9_init_state() -> None:
        if "macro_v9_page" not in st.session_state:
                try:
                        st.session_state["macro_v9_page"] = _v9_normalize_page(_v8_query_get("macro_page", "central-banks"))
                except Exception:
                        st.session_state["macro_v9_page"] = "central-banks"
        if "macro_v9_bank" not in st.session_state:
                try:
                        bank = _v8_query_get("macro_bank", "FED").upper().strip()
                except Exception:
                        bank = "FED"
                st.session_state["macro_v9_bank"] = bank if bank in G10_BANKS_V6 else "FED"
        if "macro_v9_view" not in st.session_state:
                try:
                        view = _v8_query_get("macro_view", "overview").lower().strip()
                except Exception:
                        view = "overview"
                st.session_state["macro_v9_view"] = "bank" if view == "bank" else "overview"


def _v9_set_page(page: str) -> None:
        st.session_state["macro_v9_page"] = _v9_normalize_page(page)
        st.session_state["macro_v9_view"] = "overview"
        st.rerun()


