        code = str(code or "FED").upper().strip()
        st.session_state["macro_v9_page"] = "central-banks"
        st.session_state["macro_v9_bank"] = code if code in G10_BANKS_V6 else "FED"
        st.session_state["macro_v9_view"] = "bank"
