V10_BANK_ORDER = ["RBA", "NORGES", "BOE", "FED", "RBNZ", "ECB", "BOC", "RIKSBANK", "BOJ", "SNB"]


def _v10_esc(x: Any) -> str:
        s = "" if x is None else str(x)
        return (
                s.replace("&", "&amp;")
                  .replace("<", "&lt;")
                  .replace(">", "&gt;")
                  .replace('"', "&quot;")
                  .replace("'", "&#39;")
        )


