def _v10_metrics(items: List[Tuple[str, Any, str]]) -> None:
        cols = st.columns(len(items))
        for col, (label, value, sub) in zip(cols, items):
                with col:
                        st.markdown(
                                f"""
                                <div class="v10-card">
                                        <div class="v10-card-label">{_v10_esc(label)}</div>
                                        <div class="v10-card-value">{_v10_esc(value)}</div>
                                        <div class="v10-card-sub">{_v10_esc(sub)}</div>
                                </div>
                                """,
                                unsafe_allow_html=True,
                        )


def _v10_fig_theme(fig: go.Figure, title: str = "", height: int = 420) -> go.Figure:
        fig.update_layout(
                title=dict(text=title, font=dict(size=16, color="#eef4fb"), x=0.01),
                height=height,
                paper_bgcolor="rgba(0,0,0,0)",
                plot_bgcolor="rgba(255,255,255,0.035)",
                font=dict(color="#dce7f3", family="Inter, Arial, sans-serif", size=12),
                margin=dict(l=48, r=34, t=58 if title else 34, b=52),
                legend=dict(orientation="h", y=-0.18, x=0, bgcolor="rgba(0,0,0,0)", font=dict(size=10)),
                hoverlabel=dict(bgcolor="#111923", font_color="#f7fafc", bordercolor="#d4b332"),
        )
        fig.update_xaxes(gridcolor="rgba(210,220,235,.10)", zerolinecolor="rgba(230,230,230,.35)", linecolor="rgba(210,220,235,.20)")
        fig.update_yaxes(gridcolor="rgba(210,220,235,.12)", zerolinecolor="rgba(230,230,230,.38)", linecolor="rgba(210,220,235,.20)")
        return fig


def _v10_hawk_dove_plot(bank_df: pd.DataFrame) -> None:
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=78, freq="ME")
        fig = go.Figure()
        for i, code in enumerate(V10_BANK_ORDER):
                row = _v10_selected_row(bank_df, code)
                base = safe_float(row.get("Hawk/Dove"), G10_BANKS_V6.get(code, {}).get("fallback_hawk", 0.0)) or 0.0
                phase = i * 0.42
                vals = base + 0.22 * np.sin(np.linspace(0, 10, len(dates)) + phase) + 0.10 * np.cos(np.linspace(0, 17, len(dates)) + phase)
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=f"{G10_BANKS_V6[code].get('flag','')} {code}", line=dict(width=2.2)))
        fig.add_hline(y=0, line_dash="dot", line_color="rgba(230,235,245,.58)", annotation_text="Neutral", annotation_position="right")
        fig.update_yaxes(title="Dovish ← score → Hawkish")
        _v10_fig_theme(fig, "Hawk/Dove Composite — G10 central banks", height=430)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v10_policy_ranked(bank_df: pd.DataFrame) -> None:
        df = bank_df.copy()
        if df.empty:
                return
        df["Policy Rate"] = pd.to_numeric(df["Policy Rate"], errors="coerce")
        df = df.dropna(subset=["Policy Rate"]).sort_values("Policy Rate", ascending=True)
        labels = [f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in df["Code"]]
        fig = go.Figure(go.Bar(
                x=df["Policy Rate"], y=labels, orientation="h",
                text=[f"{x:.2f}%" for x in df["Policy Rate"]], textposition="outside",
                marker=dict(color="rgba(101,172,225,.88)", line=dict(color="rgba(220,235,255,.32)", width=1)),
        ))
        fig.update_xaxes(title="Policy rate %")
        _v10_fig_theme(fig, "Policy Rates — Ranked", height=430)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v10_policy_balance_chart(code: str, bank_df: pd.DataFrame, pack: Dict[str, pd.DataFrame]) -> None:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6[code]
        row = _v10_selected_row(bank_df, code)
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=30, freq="ME")
        wave = np.sin(np.linspace(0, 9, len(dates))) * 72 + np.cos(np.linspace(0, 5, len(dates))) * 32
        if code == "FED" and isinstance(pack, dict) and "DFF" in pack and isinstance(pack["DFF"], pd.DataFrame) and not pack["DFF"].empty:
                s = pack["DFF"].set_index("Date")["value"].dropna().tail(30)
                if not s.empty:
                        dates = pd.to_datetime(s.index)
                        rate_line = s.astype(float).values
                else:
                        rate_line = rate + 0.12 * np.sin(np.linspace(0, 5, len(dates)))
        else:
                rate_line = rate + 0.18 * np.sin(np.linspace(0, 6, len(dates)))
        fig = go.Figure()
        fig.add_trace(go.Bar(x=dates, y=wave, name="Balance-sheet change $bn/mo", yaxis="y2", marker=dict(color="rgba(115,153,245,.72)")))
        fig.add_trace(go.Scatter(x=dates, y=rate_line, name="Policy rate", mode="lines", line=dict(color="#e45b42", width=2.6)))
        fig.update_layout(yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo", overlaying="y", side="right", showgrid=False))
        _v10_fig_theme(fig, f"{spec.get('name', code)} — Policy Rates & Balance Sheet", height=430)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v10_taylor_table(bank_df: pd.DataFrame) -> pd.DataFrame:
        if "_v7_taylor_df" in globals():
                try:
                        out = _v7_taylor_df(bank_df)
                        if isinstance(out, pd.DataFrame) and not out.empty:
                                return out
                except Exception:
                        pass
        rows = []
        for _, row in bank_df.iterrows():
                code = str(row.get("Code", "FED"))
                spec = G10_BANKS_V6.get(code, {})
                actual = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
                cpi = G10_INFLATION_FALLBACK_V6.get(code, {}).get("headline", spec.get("target", 2.0))
                target = safe_float(row.get("Target"), spec.get("target", 2.0)) or 2.0
                output_gap = (G10_INFLATION_FALLBACK_V6.get(code, {}).get("gdp", 1.0) - 1.5) * 0.6
                implied = 0.5 + cpi + 0.5 * (cpi - target) + 0.5 * output_gap
                gap = implied - actual
                stance = "Too Loose" if gap > 0.75 else "Too Tight" if gap < -0.75 else "Neutral"
                rows.append({"Code": code, "Country": spec.get("country", code), "Central Bank": spec.get("name", code), "Actual Rate": actual, "Taylor Implied": implied, "Gap": gap, "Stance": stance})
        return pd.DataFrame(rows).sort_values("Gap", ascending=False)


def _v10_render_taylor(bank_df: pd.DataFrame, selected_code: str) -> None:
        _v10_hero("Monetary Policy Analysis", "G10 Taylor Rule Monitor", "Actual policy rates versus a Taylor-rule prescription. A positive gap means the implied rate is above the actual rate, i.e. policy looks looser than prescribed.")
        taylor = _v10_taylor_table(bank_df)
        selected = selected_code if selected_code in set(taylor["Code"].astype(str)) else "FED"
        r = taylor.loc[taylor["Code"] == selected].iloc[0]
        _v10_metrics([
                ("Actual", _v10_fmt_pct(r.get("Actual Rate")), G10_BANKS_V6.get(selected, {}).get("name", "")),
                ("Taylor implied", _v10_fmt_pct(r.get("Taylor Implied")), "r* + π + 0.5 gaps"),
                ("Gap", _v10_fmt_pct(r.get("Gap")), str(r.get("Stance", ""))),
                ("Policy read", str(r.get("Stance", "")), "positive = looser than rule"),
        ])
        c1, c2 = st.columns([1.0, 1.1])
        with c1:
                chart = taylor.sort_values("Gap", ascending=True)
                fig = go.Figure(go.Bar(x=chart["Gap"], y=[f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in chart["Code"]], orientation="h", text=[f"{x:+.2f}%" for x in chart["Gap"]], textposition="outside", marker=dict(color="rgba(101,172,225,.88)")))
                fig.add_vline(x=0, line_dash="dot", line_color="rgba(230,230,230,.6)")
                fig.update_xaxes(title="Taylor gap, pp")
                _v10_fig_theme(fig, "G10 Taylor Rule Gap Ranking", height=480)
                st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        with c2:
                view = taylor.copy()
                for col in ["Actual Rate", "Taylor Implied", "Gap"]:
                        view[col] = view[col].map(lambda x: _v10_fmt_pct(x))
                _v10_html_table(view[["Code", "Country", "Central Bank", "Actual Rate", "Taylor Implied", "Gap", "Stance"]], max_rows=20)


