                ["2026-07-06", "ECB", "Philip Lane", "AI and monetary policy", "+0.05"],
                ["2026-07-02", "ECB", "Christine Lagarde", "Interview with Les Échos", "+0.45"],
                ["2026-07-02", "BOE", "Catherine Mann", "Mixed signals, research findings, and policy judgements", "+0.60"],
                ["2026-07-01", "BOJ", "Naoki Tamura", "Economic activity, prices and monetary policy in Japan", "+0.10"],
                ["2026-06-30", "ECB", "Philip Lane", "Introductory remarks", "+0.35"],
                ["2026-06-30", "BOJ", "Ryozo Himino", "Semiannual Report on Currency and Monetary Control", "+0.70"],
