def _v10_render_inflation(pack: Dict[str, pd.DataFrame]) -> None:
        _v10_hero("Inflation Monitor", "G10 Inflation Snapshot", "Headline CPI, core CPI, deviation from central-bank targets and twelve-month heatmap. Non-US cells are structural until OECD/Eurostat/national API feeds are connected.")
        df = _v7_inflation_table(pack) if "_v7_inflation_table" in globals() else pd.DataFrame()
        _v10_html_table(df, max_rows=20)
        codes = [c for c in V10_BANK_ORDER if c in G10_INFLATION_FALLBACK_V6]
        z = []
        for c in codes:
                trend = G10_INFLATION_FALLBACK_V6[c].get("trend", [])[-12:]
                z.append(trend + [None] * (12 - len(trend)))
        months = ["M-11", "M-10", "M-9", "M-8", "M-7", "M-6", "M-5", "M-4", "M-3", "M-2", "M-1", "Latest"]
        fig = go.Figure(go.Heatmap(z=z, x=months, y=[f"{G10_BANKS_V6[c].get('flag','')} {c}" for c in codes], colorscale="Blues", text=[[f"{v:.1f}" if v is not None else "" for v in row] for row in z], texttemplate="%{text}", hovertemplate="%{y}<br>%{x}: %{z:.1f}%<extra></extra>"))
        _v10_fig_theme(fig, "12-Month CPI Heatmap", height=460)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        st.markdown('<div class="v10-section-title">Sticky vs Flexible Price CPI — US structure</div>', unsafe_allow_html=True)
        s1 = _v7_us_yoy_series(pack, "CORESTICKM159SFRBATL", 3.1) if "_v7_us_yoy_series" in globals() else pd.Series(dtype=float)
        s2 = _v7_us_yoy_series(pack, "CORESTICKM158SFRBATL", 1.4) if "_v7_us_yoy_series" in globals() else pd.Series(dtype=float)
        s3 = _v7_us_yoy_series(pack, "CPILFESL", 2.8) if "_v7_us_yoy_series" in globals() else pd.Series(dtype=float)
        fig2 = go.Figure()
        for name, s in [("US Sticky-Price Core CPI", s1), ("US Flexible-Price Core CPI", s2), ("US Core CPI", s3)]:
                if isinstance(s, pd.Series) and not s.empty:
                        fig2.add_trace(go.Scatter(x=s.index, y=s.values, mode="lines", name=name, line=dict(width=2.2)))
        fig2.add_hline(y=2.0, line_dash="dash", line_color="rgba(212,179,50,.7)", annotation_text="2% target")
        _v10_fig_theme(fig2, "Sticky vs flexible price CPI", height=430)
        st.plotly_chart(fig2, use_container_width=True, config={"displayModeBar": False})


