def _v11_esc(x: Any) -> str:
        s = "" if x is None else str(x)
        return (
                s.replace("&", "&amp;")
                  .replace("<", "&lt;")
                  .replace(">", "&gt;")
                  .replace('"', "&quot;")
                  .replace("'", "&#39;")
        )


def _v11_pct(x: Any, digits: int = 2) -> str:
        val = safe_float(x)
        if val is None:
                return "N/A"
        return f"{val:.{digits}f}%"


def _v11_signed(x: Any, digits: int = 3) -> str:
        val = safe_float(x)
        if val is None:
                return "N/A"
        return f"{val:+.{digits}f}"


