def _v11_bank_switch(code: str) -> None:
        labels = [f"{G10_BANKS_V6[c].get('flag','')} {c}" for c in V11_BANK_ORDER]
        active = f"{G10_BANKS_V6[code].get('flag','')} {code}" if code in G10_BANKS_V6 else labels[0]
        choice = st.radio("Central bank", labels, index=labels.index(active) if active in labels else 0, horizontal=True, label_visibility="collapsed", key="macro_v11_bank_radio")
        new_code = choice.split()[-1].strip().upper()
        if new_code != code:
                _v11_open_bank(new_code)


def _v11_stance_bar(row: pd.Series) -> None:
        hawk = safe_float(row.get("Hawk/Dove"), 0.0) or 0.0
        pos = int(clamp(50 + hawk * 48, 4, 94))
        st.markdown(
                f"""
                <div class="v11-ivory-panel">
                    <div class="v11-ivory-title">Hawk/Dove Stance</div>
                    <div class="v11-hawkbar"><div class="v11-hawkmarker" style="left:{pos}%"></div></div>
                    <div class="v11-hawk-labels"><span>Dovish</span><span>Neutral</span><span>Hawkish</span></div>
                </div>
                """,
                unsafe_allow_html=True,
        )


def _v11_bank_tabs() -> str:
        current = st.session_state.get("macro_v11_bank_tab", "Overview")
        if current not in V11_BANK_TABS:
                current = "Overview"
        choice = st.radio("Bank section", V11_BANK_TABS, index=V11_BANK_TABS.index(current), horizontal=True, label_visibility="collapsed", key="macro_v11_bank_tab_radio")
        st.session_state["macro_v11_bank_tab"] = choice
        return choice


