def _v11_render_bank_scorecard(code: str) -> None:
        spec = G10_BANKS_V6.get(code, {})
        members = _v11_bank_members(code)
        avg = safe_float(members["Score"].mean(), 0.0) or 0.0
        _v11_hero("Committee Scorecard", f"{spec.get('flag','')} {spec.get('name', code)} — Committee Scorecard", "Hawk/dove stance for committee members, scored from NLP-analysed speeches. Recent = smoothed latest; lifetime = time-decayed placeholder until live speech corpus is connected.")
        _v11_stance_bar(pd.Series({"Hawk/Dove": avg}))
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=30, freq="ME")
        fig = go.Figure()
        for i, r in members.iterrows():
                base = safe_float(r.get("Score"), 0.0) or 0.0
                vals = base + 0.22 * np.sin(np.linspace(0, 7, len(dates)) + i)
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=str(r.get("Member", "Member")).split()[-1], line=dict(width=2.4)))
        fig.add_hline(y=0, line_dash="dot", line_color="rgba(255,255,255,.35)")
        fig.update_yaxes(title="Dove ← Neutral → Hawk", range=[-0.75, 0.95])
        _v11_fig_theme(fig, "The Committee", height=470)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        _v11_html_table(_v11_meetings_table(code), max_rows=12)
        _v11_section(f"Individual Members ({len(members)})")
        _v11_member_cards(code)


