def _v11_render_bank_detail(bank_df: pd.DataFrame, code: str, pack: Dict[str, pd.DataFrame]) -> None:
        code = str(code or "FED").upper()
        if code not in G10_BANKS_V6:
                code = "FED"
        row = _v11_selected_row(bank_df, code)
        spec = G10_BANKS_V6.get(code, {})
        if st.button("← Central Banks overview", key="macro_v11_back_banks", type="secondary"):
                _v11_back_to_banks()
        _v11_bank_switch(code)
        _v11_hero("Central Bank Workstation", f"{spec.get('flag','')} {code} — {spec.get('name', code)}", f"Bank-level page: overview, scorecard, speeches and meetings. Workflow equivalent to /central-banks/{code} inside the terminal.")
        _v11_metrics([
                ("Policy Rate", _v11_pct(row.get("Policy Rate")), str(row.get("Stance", "HOLD"))),
                ("Hawk/Dove", _v11_signed(row.get("Hawk/Dove"), 3), "positive = hawkish"),
                ("Inflation Target", _v11_pct(row.get("Target"), 1), str(row.get("Country", ""))),
                ("Currency", spec.get("ccy", ""), spec.get("meetings", "")),
        ])
        tab = _v11_bank_tabs()
        if tab == "Overview":
                _v11_render_bank_overview(bank_df, code, pack)
        elif tab == "Scorecard":
                _v11_render_bank_scorecard(code)
        elif tab == "Speeches":
                _v11_render_bank_speeches(code)
        else:
                _v11_render_bank_meetings(code)
        _v11_section("Reaction Function", "Directional transmission map for surprises and guidance shocks.")
        _v11_html_table(_v11_reaction_table(code), max_rows=8)
        taylor = _v11_taylor_table(bank_df)
        sub = taylor.loc[taylor["Code"] == code].copy()
        if not sub.empty:
                for col in ["Actual Rate", "Taylor Implied", "Gap", "Inflation", "Output Gap"]:
                        sub[col] = sub[col].map(lambda x: f"{x:+.2f}%" if col in ["Gap", "Output Gap"] else f"{x:.2f}%")
                _v11_section("Taylor Snapshot")
                _v11_html_table(sub[["Code", "Central Bank", "Actual Rate", "Taylor Implied", "Gap", "Inflation", "Output Gap", "Stance"]], max_rows=4)


def _v11_render_inflation(pack: Dict[str, pd.DataFrame]) -> None:
        _v11_hero("Inflation Monitor", "G10 Inflation Snapshot", "Headline CPI, core CPI, deviation from central-bank target and 12-month heatmap. US uses FRED when available; non-US values are provider-ready structural proxies.")
        df = _v7_inflation_snapshot_df(pack) if "_v7_inflation_snapshot_df" in globals() else pd.DataFrame()
        if isinstance(df, pd.DataFrame) and not df.empty:
                _v11_html_table(df, max_rows=20)
        codes = [c for c in V11_BANK_ORDER if c in G10_INFLATION_FALLBACK_V6]
        months = [f"M-{i}" for i in range(11, -1, -1)]
        z = []
        for c in codes:
                trend = list(G10_INFLATION_FALLBACK_V6[c].get("trend", [2.0]))
                vals = (trend + [trend[-1]] * 12)[-12:]
                z.append(vals)
        fig = go.Figure(go.Heatmap(z=z, x=months, y=[f"{G10_BANKS_V6[c].get('flag','')} {c}" for c in codes], colorscale=[[0,"#1f4f8f"],[.5,"#c6c2a2"],[1,"#bd6048"]], text=[[f"{v:.1f}" for v in row] for row in z], texttemplate="%{text}", showscale=True, colorbar=dict(title="CPI")))
        _v11_fig_theme(fig, "12-Month CPI Heatmap", height=460)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        # Sticky/flexible chart, intentionally dark and compact.
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=90, freq="ME")
        sticky = 3.5 + 0.4 * np.sin(np.linspace(0, 5, len(dates)))
        flexible = 1.2 + 1.1 * np.sin(np.linspace(0, 8, len(dates)) + 1.2)
        core = 2.8 + 0.3 * np.cos(np.linspace(0, 5, len(dates)))
        fig2 = go.Figure()
        fig2.add_trace(go.Scatter(x=dates, y=sticky, name="Sticky-Price Core", mode="lines", line=dict(color="#bd6048", width=3)))
        fig2.add_trace(go.Scatter(x=dates, y=flexible, name="Flexible-Price Core", mode="lines", line=dict(color="#aa8d18", width=3)))
        fig2.add_trace(go.Scatter(x=dates, y=core, name="BLS Core CPI", mode="lines", line=dict(color="#8b95a3", dash="dash", width=2)))
        fig2.add_hline(y=2.0, line_dash="dash", line_color="rgba(212,179,50,.75)", annotation_text="2% target")
        _v11_fig_theme(fig2, "Sticky vs Flexible Price CPI — US structure", height=440)
        st.plotly_chart(fig2, use_container_width=True, config={"displayModeBar": False})


def _v11_render_high_speed() -> None:
        _v11_hero("High-Frequency Economy", "High-Speed Economic Data", "Daily and weekly indicators across activity, transport, retail, labour, energy and payments. The UK workstation mirrors the nowcast-vs-official workflow.")
        if "_v7_high_speed_df" in globals():
                df = _v7_high_speed_df()
        else:
                df = pd.DataFrame()
        if isinstance(df, pd.DataFrame) and not df.empty:
                cards = df.head(6)
                cols = st.columns(3)
                for i, (_, r) in enumerate(cards.iterrows()):
                        with cols[i % 3]:
                                st.markdown(f'<div class="v11-metric-card"><div class="v11-metric-label">{_v11_esc(r.get("Economy"))}</div><div class="v11-metric-value">{safe_float(r.get("Latest Activity"),0):.1f}</div><div class="v11-metric-sub">{_v11_esc(r.get("Datasets"))} datasets · freshness {_v11_esc(r.get("Freshness"))}</div></div>', unsafe_allow_html=True)
                _v11_html_table(df, max_rows=20)
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=36, freq="ME")
        for title, left, right in [
                ("United Kingdom — Nowcast Index vs GDP", "Nowcast Index", "GDP MoM %"),
                ("United Kingdom — Consumer Index vs Retail Sales", "Consumer Index", "Retail Sales YoY"),
                ("United Kingdom — Job Adverts vs Unemployment", "Job adverts", "Unemployment"),
        ]:
                fig = go.Figure()
                fig.add_trace(go.Scatter(x=dates, y=55 + 7*np.sin(np.linspace(0,8,len(dates))), name=left, mode="lines", line=dict(color="#73a7d4", width=3)))
                fig.add_trace(go.Scatter(x=dates, y=3 + .7*np.cos(np.linspace(0,6,len(dates))), name=right, mode="lines", yaxis="y2", line=dict(color="#2f80ed", width=2.5)))
                fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False))
                _v11_fig_theme(fig, title, height=340)
                st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


