def _v11_render_page(page: str, selected_code: str, pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame, bank_df: pd.DataFrame) -> None:
        view = st.session_state.get("macro_v11_view", "overview")
        if page == "central-banks":
                if view == "bank":
                        _v11_render_bank_detail(bank_df, selected_code, pack)
                else:
                        _v11_render_central_banks_overview(bank_df, selected_code, pack)
        elif page == "taylor-rule":
                _v11_render_taylor(bank_df, selected_code)
        elif page == "inflation":
                _v11_render_inflation(pack)
        elif page == "high-speed":
                _v11_render_high_speed()
        elif page == "china":
                _v11_render_china()
        elif page == "misery-indices":
                _v11_render_misery()
        elif page == "us-payrolls":
                _v11_render_payrolls(pack)
        elif page == "consensus-forecasts":
                _v11_render_outlook()
        else:
                _v11_render_quality(pack, proxy_pack, indicator_df)


def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V11 renderer: original-like central-bank desk with dark terminal integration."""
        ticker = str(ticker or "SPY").upper().strip()
        _v11_css()
        _v11_init_state()

        page = _v11_normalize_page(st.session_state.get("macro_v11_page", "central-banks"))
        selected_code = str(st.session_state.get("macro_v11_bank", "FED")).upper().strip()
        if selected_code not in G10_BANKS_V6:
                selected_code = "FED"
                st.session_state["macro_v11_bank"] = selected_code

        start_date = "2000-01-01"
        proxy_period = "2y"
        series_ids = tuple(set(list(FRED_SERIES.keys()) + [
                "USPRIV", "USGOOD", "SRVPRD", "CORESTICKM159SFRBATL", "CORESTICKM158SFRBATL",
                "USEHS", "LNS12026620", "U6RATE", "JTSJOL", "AWHNONAG", "TEMPHELPS",
                "IRSTCI01NZM156N", "IRSTCI01SEM156N", "IRSTCI01NOM156N",
        ]))
        pack = load_macro_fred_pack(series_ids, start_date=start_date)
        proxy_pack = load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=proxy_period)
        indicator_df = build_macro_indicator_table(pack)
        bank_df = _v7_structural_bank_df(pack) if "_v7_structural_bank_df" in globals() else _v6_bank_table(pack)

        st.markdown('<div class="v11-shell">', unsafe_allow_html=True)
        try:
                _v11_topbar(page)
                _v11_render_page(page, selected_code, pack, proxy_pack, indicator_df, bank_df)
                st.markdown(
                        '<div class="v11-footer">Macro V11 · original-like central-bank desk rework. Fixed: blue card language removed, card hierarchy rebuilt, bank-level Overview/Scorecard/Speeches/Meetings added, charts integrated in dark terminal panels, Taylor snapshot stable, provider-ready roadmap preserved.</div>',
                        unsafe_allow_html=True,
                )
        finally:
                st.markdown('</div>', unsafe_allow_html=True)

# ============================================================
# END MACRO CENTRAL BANKS V11 — ORIGINAL-LIKE PRESENTATION REWORK
# ============================================================

# ============================================================
# MACRO CENTRAL BANKS V12 — ORIGINAL-LIKE DESIGN FINAL REWORK
# ============================================================
# Design goals:
# - Keep dark Quant Terminal integration but move inner economy pages closer to RoboMacro layout.
# - Remove blue button-card language.
# - Use warm ivory central-bank cards and ivory chart/table panels on dark shell.
# - Keep state-driven navigation for pages and bank detail pages.
# - Use HTML only through compact, non-indented strings to avoid raw HTML rendering.
# ============================================================

V12_BANK_ORDER = ["RBA", "NORGES", "BOE", "FED", "RBNZ", "ECB", "BOC", "RIKSBANK", "BOJ", "SNB"]
V12_NAV = {
        "central-banks": "Central Banks",
        "inflation": "Inflation",
        "us-payrolls": "US Payrolls",
        "consensus-forecasts": "Consensus Forecasts",
        "taylor-rule": "Taylor Rule",
        "high-speed": "High Speed",
        "china": "China",
        "misery-indices": "Misery Indices",
        "sources-quality": "Sources / Quality",
}
V12_BANK_VIEWS = {"overview": "Overview", "scorecard": "Scorecard", "speeches": "Speeches", "meetings": "Meetings"}


def _v12_esc(x: Any) -> str:
        import html as _html
        return _html.escape("" if x is None else str(x), quote=True)


def _v12_html(html: str) -> None:
        # Avoid leading indentation; indented HTML is rendered as a code block by Markdown.
        import textwrap
        cleaned = textwrap.dedent(str(html)).strip()
        st.markdown(cleaned, unsafe_allow_html=True)


def _v12_query_get(name: str, default: Optional[str] = None) -> Optional[str]:
        try:
                val = st.query_params.get(name, default)    # type: ignore[attr-defined]
                if isinstance(val, list):
                        return val[0] if val else default
                return val
        except Exception:
                try:
                        q = st.experimental_get_query_params()
                        val = q.get(name, [default])
                        return val[0] if isinstance(val, list) and val else default
                except Exception:
                        return default


def _v12_sync_query_state() -> None:
        q_page = _v12_query_get("macro_page") or _v12_query_get("macro_v12_page")
        q_bank = _v12_query_get("macro_bank") or _v12_query_get("macro_v12_bank")
        q_view = _v12_query_get("macro_view") or _v12_query_get("macro_v12_view")
        if q_page:
                st.session_state["macro_v12_page"] = _v12_normalize_page(q_page)
        if q_bank and str(q_bank).upper() in G10_BANKS_V6:
                st.session_state["macro_v12_bank"] = str(q_bank).upper()
        if q_view in {"bank", "overview"}:
                st.session_state["macro_v12_route"] = str(q_view)
        if q_view in V12_BANK_VIEWS:
                st.session_state["macro_v12_bank_view"] = str(q_view)


def _v12_normalize_page(page: Any) -> str:
        p = str(page or "central-banks").strip().lower().replace("_", "-")
        aliases = {
                "central banks": "central-banks", "central-bank": "central-banks", "banks": "central-banks",
                "payrolls": "us-payrolls", "us payrolls": "us-payrolls",
                "consensus": "consensus-forecasts", "forecast": "consensus-forecasts", "forecasts": "consensus-forecasts",
                "taylor": "taylor-rule", "taylor rule": "taylor-rule",
                "high speed": "high-speed", "highspeed": "high-speed",
                "misery": "misery-indices", "misery indices": "misery-indices",
                "quality": "sources-quality", "sources": "sources-quality", "data quality": "sources-quality",
        }
        return aliases.get(p, p if p in V12_NAV else "central-banks")


def _v12_init_state() -> None:
        if "macro_v12_page" not in st.session_state:
                st.session_state["macro_v12_page"] = st.session_state.get("macro_v11_page", "central-banks")
        if "macro_v12_bank" not in st.session_state:
                st.session_state["macro_v12_bank"] = st.session_state.get("macro_v11_bank", "FED")
        if "macro_v12_route" not in st.session_state:
                st.session_state["macro_v12_route"] = "overview"
        if "macro_v12_bank_view" not in st.session_state:
                st.session_state["macro_v12_bank_view"] = "overview"
        _v12_sync_query_state()
        st.session_state["macro_v12_page"] = _v12_normalize_page(st.session_state.get("macro_v12_page"))
        if st.session_state.get("macro_v12_bank") not in G10_BANKS_V6:
                st.session_state["macro_v12_bank"] = "FED"
        if st.session_state.get("macro_v12_bank_view") not in V12_BANK_VIEWS:
                st.session_state["macro_v12_bank_view"] = "overview"


