def _v12_member_cards(code: str) -> None:
        members = _v12_bank_members(code)
        if members.empty:
                st.caption("Member-level scorecard requires speech feed.")
                return
        sparks = ["▁▃▅▆▅▇▆▅▆▇▅▇", "▁▁▂▂▂▁▁▂▂▁▁▂", "▃▃▃▄▃▂▂▃▃▂▂▃", "▂▂▂▁▁▂▂▂▁▁▁▂", "▂▃▃▂▂▁▁▂▃▂▂▃"]
        html = ['<div class="v12-member-grid">']
        for i, r in members.iterrows():
                score = safe_float(r.get("Score"), 0.0) or 0.0
                border = "#151922" if i == 0 else "#6c7a89" if score <= 0.05 else "#bd6048"
                score_bg = "#bd6048" if score > 0.25 else "#c99666" if score > 0.05 else "#8d96a4"
                html.append(f'<div class="v12-member-card" style="border-left-color:{border}"><span class="v12-member-score" style="background:{score_bg}">{score:+.2f}</span><div class="v12-member-name">{_v12_esc(r.get("Member", ""))}</div><div class="v12-member-role">{_v12_esc(r.get("Role", ""))}</div><div class="v12-mini-spark">{sparks[i % len(sparks)]}</div><div class="v12-member-tags"><span>{_v12_esc(r.get("Tag", ""))}</span><span>Voter</span><span>{int(safe_float(r.get("Speeches"), 0) or 0)} speeches</span></div></div>')
        html.append('</div>')
        _v12_html("".join(html))


def _v12_plot_hawk_dove(bank_df: pd.DataFrame, height: int = 440, light: bool = True) -> None:
        dates = pd.date_range("2020-01-01", periods=80, freq="ME")
        fig = go.Figure()
        palette = ["#1d5b7e", "#d99000", "#bd3a32", "#703a85", "#2b8c55", "#319177", "#bf7a00", "#263b56", "#338fc2", "#c7372f"]
        for idx, code in enumerate(V12_BANK_ORDER):
                spec = G10_BANKS_V6.get(code, {})
                row = _v12_selected_row(bank_df, code)
                base = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
                vals = base + 0.24 * np.sin(np.linspace(0, 7.0, len(dates)) + idx * 0.55) + 0.10 * np.cos(np.linspace(0, 3.2, len(dates)) + idx)
                vals = np.clip(vals, -0.85, 0.85)
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=f"{spec.get('flag','')} {code}", line=dict(width=2.2, color=palette[idx % len(palette)])))
        fig.add_hline(y=0, line_dash="dot", line_color="#818b9a" if light else "rgba(255,255,255,.45)", annotation_text="Neutral")
        fig.update_yaxes(title="Dovish ← score → Hawkish")
        _v12_fig_theme(fig, "Hawk/Dove Composite", height=height, light=light)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v12_plot_rates_ranked(bank_df: pd.DataFrame, height: int = 440, light: bool = True) -> None:
        df = bank_df.copy() if isinstance(bank_df, pd.DataFrame) else pd.DataFrame()
        if df.empty:
                return
        df["Policy Rate"] = df["Policy Rate"].map(lambda x: safe_float(x, 0.0) or 0.0)
        df = df.sort_values("Policy Rate", ascending=True)
        labels = [f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in df["Code"]]
        fig = go.Figure(go.Bar(x=df["Policy Rate"], y=labels, orientation="h", text=[f"{x:.2f}%" for x in df["Policy Rate"]], textposition="outside", marker=dict(color="#6f9fc5" if light else "#70a7d2")))
        fig.update_xaxes(title="Policy rate %")
        _v12_fig_theme(fig, "Policy Rates — Ranked", height=height, light=light)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v12_policy_history_chart(code: str, bank_df: pd.DataFrame, height: int = 450, light: bool = True) -> None:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6["FED"])
        row = _v12_selected_row(bank_df, code)
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        dates = pd.date_range("2024-01-01", periods=31, freq="ME")
        rate_vals = rate + 0.18 * np.sin(np.linspace(0, 6.2, len(dates)))
        bs = 85 * np.sin(np.linspace(0, 9.0, len(dates)) - 0.5) + 18 * np.cos(np.linspace(0, 4.5, len(dates)))
        fig = go.Figure()
        bar_colors = np.where(bs >= 0, "#6f9fc5" if light else "rgba(116,169,213,.82)", "#bd6048")
        fig.add_trace(go.Bar(x=dates, y=bs, name="Balance sheet change $bn/mo", marker=dict(color=bar_colors), yaxis="y2"))
        fig.add_trace(go.Scatter(x=dates, y=rate_vals, name="Policy rate", mode="lines", line=dict(color="#bd6048", width=3.2)))
        fig.update_layout(yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo", overlaying="y", side="right", showgrid=False))
        _v12_fig_theme(fig, f"{spec.get('name', code)} — Policy Rates & Balance Sheet", height=height, light=light)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v12_taylor_table(bank_df: pd.DataFrame) -> pd.DataFrame:
        try:
                return _v11_taylor_table(bank_df)
        except Exception:
                rows = []
                for code in V12_BANK_ORDER:
                        spec = G10_BANKS_V6.get(code, {})
                        row = _v12_selected_row(bank_df, code)
                        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
                        infl = safe_float(G10_INFLATION_FALLBACK_V6.get(code, {}).get("headline", spec.get("target", 2.0)), spec.get("target", 2.0)) or 2.0
                        target = safe_float(spec.get("target"), 2.0) or 2.0
                        output_gap = (safe_float(G10_INFLATION_FALLBACK_V6.get(code, {}).get("gdp", 1.0), 1.0) or 1.0) - 1.4
                        implied = 0.5 + infl + 0.5 * (infl - target) + 0.5 * output_gap
                        gap = implied - rate
                        stance = "Too Loose" if gap > 0.75 else "Too Tight" if gap < -0.75 else "Neutral"
                        rows.append({"Code": code, "Country": spec.get("country", code), "Central Bank": spec.get("name", code), "Actual Rate": rate, "Taylor Implied": implied, "Gap": gap, "Inflation": infl, "Output Gap": output_gap, "Stance": stance})
                return pd.DataFrame(rows).sort_values("Gap", ascending=False)


def _v12_reaction_table(code: str) -> pd.DataFrame:
        try:
                return _v11_reaction_table(code)
        except Exception:
                ccy = G10_BANKS_V6.get(code, {}).get("ccy", "FX")
                return pd.DataFrame([
                        ["Inflation surprise above consensus", "Hawkish", "Front-end yields higher", f"{ccy} supported if growth stable", "Duration/growth equity vulnerable"],
                        ["Inflation surprise below consensus", "Dovish", "Front-end yields lower", f"{ccy} softer unless risk rally offsets", "Duration relief / risk support"],
                        ["Growth/labor above consensus", "Less urgency to ease", "Bear-flattening risk", f"{ccy} supported", "Cyclicals supported unless rates shock dominates"],
                        ["Growth/labor below consensus", "Cuts/recession pricing", "Bull-steepening risk", f"{ccy} vulnerable", "Credit and small caps vulnerable"],
                        ["Hawkish speech cluster", "Guidance reprices higher", "2Y-led selloff", f"{ccy} support", "Multiple compression risk"],
                        ["Dovish speech cluster", "Easing optionality rises", "2Y-led rally", f"{ccy} softer", "Initial risk relief; watch credibility"],
                ], columns=["Shock", "Policy read", "Rates", "FX", "Risk assets"])


