# ============================================================
# MACRO CENTRAL BANKS V13 — NAVIGATION STABILITY + DESIGN POLISH
# ============================================================
# Goals:
# - Preserve the V12 RoboMacro-like visual layer.
# - Fix the regression where a stale Streamlit radio state can force the page
#      back to the default Central Banks overview after a redirect/query click.
# - Make all navigation state-first, query-compatible, and robust to reruns.
# - Repair CSS variable scope so non-selected bank cards keep the ivory design.
# - Slightly rebalance colours: less cyan/blue, more ivory/slate/gold.
# ============================================================

from typing import Any, Dict, Optional, List, Tuple
from urllib.parse import quote

MACRO_CB_VERSION = "V13 FINAL · NAV STABILITY + ORIGINAL-LIKE DESIGN POLISH"


def _v13_set_query_params(page: str, bank: Optional[str] = None, route: Optional[str] = None, bank_view: Optional[str] = None) -> None:
        """Best-effort URL sync. State remains the source of truth; URL is only a deep-link mirror."""
        try:
                st.query_params["macro_page"] = _v12_normalize_page(page)
                if bank:
                        st.query_params["macro_bank"] = str(bank).upper()
                if route:
                        st.query_params["macro_view"] = str(route)
                if bank_view:
                        st.query_params["macro_bank_view"] = str(bank_view)
        except Exception:
                try:
                        params = {"macro_page": _v12_normalize_page(page)}
                        if bank:
                                params["macro_bank"] = str(bank).upper()
                        if route:
                                params["macro_view"] = str(route)
                        if bank_view:
                                params["macro_bank_view"] = str(bank_view)
                        st.experimental_set_query_params(**params)
                except Exception:
                        pass


def _v12_sync_query_state() -> None:
        """V13 override: query params can open deep links, but stale widget state cannot push us back to start."""
        q_page = _v12_query_get("macro_page") or _v12_query_get("macro_v12_page")
        q_bank = _v12_query_get("macro_bank") or _v12_query_get("macro_v12_bank")
        q_route = _v12_query_get("macro_view") or _v12_query_get("macro_v12_view")
        q_bank_view = _v12_query_get("macro_bank_view") or _v12_query_get("macro_v12_bank_view")

        if q_page:
                st.session_state["macro_v12_page"] = _v12_normalize_page(q_page)

        if q_bank and str(q_bank).upper() in G10_BANKS_V6:
                st.session_state["macro_v12_page"] = "central-banks"
                st.session_state["macro_v12_bank"] = str(q_bank).upper()
                st.session_state["macro_v12_route"] = "bank"

        if q_route in {"bank", "overview"}:
                st.session_state["macro_v12_route"] = str(q_route)

        if q_bank_view in V12_BANK_VIEWS:
                st.session_state["macro_v12_bank_view"] = str(q_bank_view)
        elif q_route in V12_BANK_VIEWS:
                st.session_state["macro_v12_bank_view"] = str(q_route)

        # If user deep-links to a non-central-bank page, bank route should not leak back
        # when they later interact with the economy navigation.
        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
        if page != "central-banks":
                st.session_state["macro_v12_route"] = "overview"


def _v12_init_state() -> None:
        """V13 override: initialize once, then let query/state drive navigation without stale radio resets."""
        if "macro_v12_page" not in st.session_state:
                st.session_state["macro_v12_page"] = st.session_state.get("macro_v11_page", "central-banks")
        if "macro_v12_bank" not in st.session_state:
                st.session_state["macro_v12_bank"] = st.session_state.get("macro_v11_bank", "FED")
        if "macro_v12_route" not in st.session_state:
                st.session_state["macro_v12_route"] = "overview"
        if "macro_v12_bank_view" not in st.session_state:
                st.session_state["macro_v12_bank_view"] = "overview"

        _v12_sync_query_state()

        st.session_state["macro_v12_page"] = _v12_normalize_page(st.session_state.get("macro_v12_page"))
        if st.session_state.get("macro_v12_bank") not in G10_BANKS_V6:
                st.session_state["macro_v12_bank"] = "FED"
        if st.session_state.get("macro_v12_bank_view") not in V12_BANK_VIEWS:
                st.session_state["macro_v12_bank_view"] = "overview"
        if st.session_state.get("macro_v12_page") != "central-banks":
                st.session_state["macro_v12_route"] = "overview"


