def _v12_bank_card_html(row: pd.Series, selected_code: str) -> str:
        """V13 override: keep full-card click, but use explicit URL state and explicit colours."""
        code = str(row.get("Code", "")).upper()
        spec = G10_BANKS_V6.get(code, {})
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
        target = safe_float(row.get("Target"), spec.get("target", 2.0)) or 2.0
        icon, status, klass = _v12_status_parts(row.get("Status", spec.get("status", "HOLD")))
        marker = max(3.0, min(96.0, 50 + hawk * 48 + (rate - 2.0) * 3.2))
        selected = " selected" if code == selected_code else ""
        colour = spec.get("colour", "#1d5b7e")
        href = f"?macro_page=central-banks&macro_view=bank&macro_bank={quote(code)}&macro_bank_view=overview"
        return (
                f'<a class="v12-bank-card{selected}" href="{href}" target="_self" data-bank="{_v12_esc(code)}">'
                f'<div class="v12-card-head"><div><div class="v12-bank-code">{_v12_esc(spec.get("flag", ""))} {code}</div><div class="v12-bank-name">{_v12_esc(spec.get("name", row.get("Name", "")))}</div></div><div class="v12-ccy" style="background:{_v12_esc(colour)}">{_v12_esc(spec.get("ccy", row.get("Currency", "")))}</div></div>'
                f'<div class="v12-rate">{rate:.2f}% <span class="v12-stance {klass}">{icon} {status}</span></div>'
                f'<div class="v12-meter"><span class="v12-neutral"></span><span class="v12-marker" style="left:{marker:.1f}%"></span></div>'
                f'<div class="v12-row"><span class="{ "v12-score-red" if hawk >= 0 else "v12-score-blue" }">{hawk:+.3f}</span><span>{_v12_esc(row.get("Members", spec.get("members", "")))} members</span></div>'
                f'<div class="v12-row" style="margin-top:12px"><span>{_v12_esc(row.get("Meetings", spec.get("meetings", "")))}</span><span>target {target:.1f}%</span></div>'
                f'</a>'
        )


