def _v12_topbar(page: str) -> None:
        """V13 override: dynamic-key radio avoids stale widget state forcing navigation back to the start page."""
        page = _v12_normalize_page(page)
        _v12_html('<div class="v12-top"><div><span class="v12-logo">MacroDesk</span><small>Economy · Policy · High-speed macro</small></div><div class="v12-top-right">central banks · inflation · Taylor rule · high-speed · China · misery · payrolls · outlook</div></div>')
        st.markdown('<div class="v12-nav-label">Economy navigation</div><div class="v13-nav-caption">State-driven navigation. URL deep-links are accepted, but widget state no longer pushes the workspace back to the default page.</div>', unsafe_allow_html=True)

        labels = list(V12_NAV.values())
        keys = list(V12_NAV.keys())
        current = page if page in keys else "central-banks"

        # Dynamic key is deliberate: Streamlit preserves widget values by key. A fixed key
        # caused the old selected value to override query/state after redirects.
        radio_key = f"macro_v13_nav_radio_{current}"
        choice = st.radio(
                "",
                labels,
                horizontal=True,
                index=keys.index(current),
                label_visibility="collapsed",
                key=radio_key,
        )
        new_page = keys[labels.index(choice)]
        if new_page != current:
                st.session_state["macro_v12_page"] = new_page
                st.session_state["macro_v12_route"] = "overview"
                st.session_state["macro_v12_bank_view"] = "overview"
                _v13_set_query_params(new_page, bank=st.session_state.get("macro_v12_bank", "FED"), route="overview")
                st.rerun()


