def _v15_pct(x: Any, digits: int = 2) -> str:
        v = safe_float(x)
        if v is None:
                return "N/A"
        return f"{v:.{digits}f}%"


def _v15_signed(x: Any, digits: int = 3) -> str:
        v = safe_float(x)
        if v is None:
                return "N/A"
        return f"{v:+.{digits}f}"


def _v15_button_rerun() -> None:
        try:
                st.rerun()
        except Exception:
                try:
                        st.experimental_rerun()
                except Exception:
                        pass


def _v15_apply_bank_display_overrides(bank_df: pd.DataFrame) -> pd.DataFrame:
        """Return a stable G10 bank table ordered and aligned with the reference UI."""
        if isinstance(bank_df, pd.DataFrame) and not bank_df.empty:
                df = bank_df.copy()
        else:
                df = pd.DataFrame([_v12_selected_row(pd.DataFrame(), c) for c in V12_BANK_ORDER])

        if "Code" not in df.columns:
                df["Code"] = [c for c in V12_BANK_ORDER[:len(df)]]

        rows = []
        for code in V12_BANK_ORDER:
                sub = df.loc[df["Code"].astype(str).str.upper() == code]
                row = sub.iloc[0].copy() if not sub.empty else _v12_selected_row(df, code).copy()
                spec = G10_BANKS_V6.get(code, {})
                row["Code"] = code
                row["Central Bank"] = row.get("Central Bank", spec.get("name", code))
                row["Country"] = row.get("Country", spec.get("country", code))
                row["Currency"] = row.get("Currency", spec.get("ccy", ""))
                row["Members"] = row.get("Members", spec.get("members", ""))
                row["Meetings"] = row.get("Meetings", spec.get("meetings", ""))
                row["Target"] = safe_float(row.get("Target"), spec.get("target", 2.0)) or spec.get("target", 2.0)
                row["Hawk/Dove"] = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
                row["Composite"] = clamp(row.get("Composite", 50 + row["Hawk/Dove"] * 40), 0, 100)
                if code in V15_BANK_DISPLAY_OVERRIDES:
                        for k, v in V15_BANK_DISPLAY_OVERRIDES[code].items():
                                row[k] = v
                row["Policy Rate"] = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
                row["Stance"] = str(row.get("Stance", spec.get("status", "HOLD"))).upper()
                rows.append(row)
        out = pd.DataFrame(rows)
        out["_order"] = out["Code"].map({c: i for i, c in enumerate(V12_BANK_ORDER)}).fillna(99)
        return out.sort_values("_order").drop(columns=["_order"], errors="ignore")


