def _v15_html_table(df: pd.DataFrame, max_rows: int = 60) -> None:
        if not isinstance(df, pd.DataFrame) or df.empty:
                st.caption("No rows available.")
                return
        use = df.head(max_rows).copy()
        header = "".join(f"<th>{_v12_esc(c)}</th>" for c in use.columns)
        rows = []
        for _, r in use.iterrows():
                rows.append("<tr>" + "".join(f"<td>{_v12_esc(v)}</td>" for v in r.tolist()) + "</tr>")
        _v12_html(f'<table class="v15-table"><thead><tr>{header}</tr></thead><tbody>{"".join(rows)}</tbody></table>')


def _v15_hero(kicker: str, title: str, subtitle: str) -> None:
        _v12_html(
                f'<div class="v15-hero"><div class="v15-kicker">{_v12_esc(kicker)}</div><div class="v15-title">{_v12_esc(title)}</div><div class="v15-subtitle">{_v12_esc(subtitle)}</div></div>'
        )


def _v15_section(title: str, sub: str = "") -> None:
        _v12_html(f'<div class="v15-section-title">{_v12_esc(title)}</div>')
        if sub:
                _v12_html(f'<div class="v15-section-sub">{_v12_esc(sub)}</div>')


def _v15_topbar(page: str) -> None:
        _v12_html(
                '<div class="v15-topbar">'
                '<div><span class="v15-logo">MacroDesk</span><small>Economy · Policy · High-speed macro</small></div>'
                '<div class="v15-top-right">central banks · inflation · Taylor rule · high-speed · China · misery · payrolls · outlook</div>'
                '</div>'
        )
        _v12_html('<div class="v15-nav-kicker">Economy</div>')
        st.markdown('<div class="v15-nav-row">', unsafe_allow_html=True)
        cols = st.columns([1.05, .88, .92, 1.25, 1.0, .92, .76, 1.08, 1.08])
        for col, (key, label) in zip(cols, V15_ECONOMY_ITEMS):
                with col:
                        active = "● " if _v12_normalize_page(page) == key else ""
                        if st.button(active + label, key=f"macro_v15_nav_{key}", use_container_width=True):
                                _v15_go_page(key)
        st.markdown('</div>', unsafe_allow_html=True)


def _v15_bank_card_html(row: pd.Series, selected_code: str) -> str:
        code = str(row.get("Code", "FED")).upper()
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6.get("FED", {}))
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
        comp = clamp(row.get("Composite", 50 + hawk * 40), 3, 97)
        stance = str(row.get("Stance", spec.get("status", "HOLD"))).upper()
        symbol = "▲" if stance == "HIKE" else "▼" if stance == "CUT" else "●"
        stance_class = "hike" if stance == "HIKE" else "cut" if stance == "CUT" else "hold"
        score_class = "pos" if hawk >= 0 else "neg"
        selected = " selected" if code == str(selected_code).upper() else ""
        return (
                f'<div class="v15-bank-card{selected}">'
                f'<div class="v15-bank-head"><div><div class="v15-bank-code">{_v12_esc(spec.get("flag", ""))} {code}</div><div class="v15-bank-name">{_v12_esc(spec.get("name", code))}</div></div><div class="v15-ccy" style="background:{_v12_esc(spec.get("colour", "#64748b"))}">{_v12_esc(spec.get("ccy", row.get("Currency", "")))}</div></div>'
                f'<div class="v15-rate">{rate:.2f}% <span class="v15-stance {stance_class}">{symbol} {stance}</span></div>'
                f'<div class="v15-meter"><span class="v15-marker" style="left:{comp:.1f}%"></span></div>'
                f'<div class="v15-card-row"><span class="{score_class}">{hawk:+.3f}</span><span>{_v12_esc(row.get("Members", spec.get("members", "")))} members</span></div>'
                f'<div class="v15-card-row" style="margin-top:12px"><span>{_v12_esc(row.get("Meetings", spec.get("meetings", "")))}</span><span>target {safe_float(row.get("Target"), spec.get("target", 2.0)):.1f}%</span></div>'
                '</div>'
        )


def _v15_render_bank_cards(bank_df: pd.DataFrame, selected_code: str) -> None:
        ordered = _v15_apply_bank_display_overrides(bank_df)
        for start in range(0, len(ordered), 4):
                cols = st.columns(4)
                for col, (_, row) in zip(cols, ordered.iloc[start:start + 4].iterrows()):
                        code = str(row.get("Code", "")).upper()
                        with col:
                                st.markdown('<div class="v15-card-wrap">', unsafe_allow_html=True)
                                _v12_html(_v15_bank_card_html(row, selected_code))
                                if st.button(f"Open {code}", key=f"macro_v15_open_bank_{code}", use_container_width=True):
                                        _v15_open_bank(code, "overview")
                                st.markdown('</div>', unsafe_allow_html=True)


def _v15_fig_template(fig: go.Figure, title: str = "", height: int = 430) -> go.Figure:
        fig.update_layout(
                template="plotly_white",
                title=dict(text=title, font=dict(size=18, color="#151922", family="Georgia, 'Times New Roman', serif"), x=0.01),
                paper_bgcolor="#fbfaf6",
                plot_bgcolor="#f5f6f8",
                height=height,
                margin=dict(l=58, r=42, t=58, b=62),
                font=dict(color="#202733", family="Inter, Arial"),
                legend=dict(orientation="h", y=-0.20, x=0, bgcolor="rgba(0,0,0,0)", font=dict(size=10)),
        )
        fig.update_xaxes(gridcolor="#e3e6eb", zerolinecolor="#c8cdd5", linecolor="#cfd4dc")
        fig.update_yaxes(gridcolor="#e3e6eb", zerolinecolor="#c8cdd5", linecolor="#cfd4dc")
        return fig


def _v15_plot_hawk_dove(bank_df: pd.DataFrame, selected_code: Optional[str] = None, height: int = 420) -> None:
        df = _v15_apply_bank_display_overrides(bank_df)
        dates = pd.date_range("2020-01-01", periods=80, freq="ME")
        fig = go.Figure()
        for idx, code in enumerate(V12_BANK_ORDER):
                row = _v12_selected_row(df, code)
                spec = G10_BANKS_V6.get(code, {})
                base = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
                vals = base + 0.23 * np.sin(np.linspace(0, 7.0, len(dates)) + idx * 0.52) + 0.08 * np.cos(np.linspace(0, 3.4, len(dates)) + idx)
                vals = np.clip(vals, -0.78, 0.88)
                opacity = 1.0 if not selected_code or code == selected_code else 0.38
                width = 2.8 if code == selected_code else 1.8
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines", name=f"{spec.get('flag','')} {code}", opacity=opacity, line=dict(width=width, color=V15_LINE_PALETTE[idx % len(V15_LINE_PALETTE)])))
        fig.add_hline(y=0, line_dash="dot", line_color="#6f7782", annotation_text="Neutral", annotation_position="right")
        fig.update_yaxes(title="Dovish ← score → Hawkish", range=[-0.85, 0.95])
        _v15_fig_template(fig, "Hawk/Dove Composite", height=height)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v15_plot_rates_ranked(bank_df: pd.DataFrame, height: int = 420) -> None:
        df = _v15_apply_bank_display_overrides(bank_df)
        df["Policy Rate"] = df["Policy Rate"].map(lambda x: safe_float(x, 0.0) or 0.0)
        df = df.sort_values("Policy Rate", ascending=True)
        y = [f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in df["Code"]]
        fig = go.Figure(go.Bar(
                x=df["Policy Rate"], y=y, orientation="h",
                text=[f"{x:.2f}%" for x in df["Policy Rate"]], textposition="outside",
                marker=dict(color="#7aa8c8")
        ))
        fig.update_xaxes(title="Policy rate %")
        _v15_fig_template(fig, "Policy Rates — Ranked", height=height)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v15_policy_history_chart(code: str, bank_df: pd.DataFrame, height: int = 450) -> None:
        code = code if code in G10_BANKS_V6 else "FED"
        df = _v15_apply_bank_display_overrides(bank_df)
        row = _v12_selected_row(df, code)
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6.get("FED", {}))
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        dates = pd.date_range("2024-01-01", periods=31, freq="ME")
        rate_vals = rate + 0.17 * np.sin(np.linspace(0, 6.2, len(dates)))
        bs = 85 * np.sin(np.linspace(0, 9.0, len(dates)) - 0.5) + 18 * np.cos(np.linspace(0, 4.5, len(dates)))
        fig = go.Figure()
        bar_colors = np.where(bs >= 0, "#7aa8c8", "#bd6048")
        fig.add_trace(go.Bar(x=dates, y=bs, name="Balance sheet change $bn/mo", marker=dict(color=bar_colors), yaxis="y2"))
        fig.add_trace(go.Scatter(x=dates, y=rate_vals, name="Policy rate", mode="lines", line=dict(color="#bd6048", width=3.2)))
        fig.update_layout(yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo", overlaying="y", side="right", showgrid=False))
        _v15_fig_template(fig, f"{spec.get('name', code)} — Policy Rates & Balance Sheet", height=height)
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def _v15_speeches_df(code: Optional[str] = None) -> pd.DataFrame:
        try:
                base = _v12_speeches_df(None)
        except Exception:
                base = pd.DataFrame()
        if isinstance(base, pd.DataFrame) and not base.empty:
                if code:
                        filt = base.loc[base.get("CB", pd.Series(dtype=str)).astype(str).str.upper() == str(code).upper()]
                        if not filt.empty:
                                return filt
                elif not code:
                        return base
        # Bank-specific structural fallback so a bank page never displays another bank's speeches as its primary tape.
        use_code = str(code or "ECB").upper()
        spec = G10_BANKS_V6.get(use_code, G10_BANKS_V6.get("FED", {}))
        members = _v12_bank_members(use_code)
        names = members["Member"].tolist() if isinstance(members, pd.DataFrame) and not members.empty and "Member" in members.columns else [spec.get("name", use_code)]
        titles = [
                "Policy rate decision and monetary-policy outlook",
                "Inflation persistence and the reaction function",
                "Financial stability and monetary-policy transmission",
                "Economic activity, prices and policy guidance",
                "Research-based models in monetary policy decision-making",
        ]
        today = pd.Timestamp.today().normalize()
        rows = []
        for i in range(8 if code else 14):
                cb = use_code if code else V12_BANK_ORDER[i % len(V12_BANK_ORDER)]
                spec_i = G10_BANKS_V6.get(cb, {})
                mems_i = _v12_bank_members(cb)
                if isinstance(mems_i, pd.DataFrame) and not mems_i.empty and "Member" in mems_i.columns:
                        speaker = str(mems_i.iloc[i % len(mems_i)]["Member"])
                        score = safe_float(mems_i.iloc[i % len(mems_i)].get("Score"), spec_i.get("fallback_hawk", 0.0)) or 0.0
                else:
                        speaker = str(spec_i.get("name", cb))
                        score = safe_float(spec_i.get("fallback_hawk", 0.0), 0.0) or 0.0
                rows.append({
                        "Date": (today - pd.Timedelta(days=5 + i * 7)).strftime("%Y-%m-%d"),
                        "CB": cb,
                        "Speaker": speaker,
                        "Title": titles[i % len(titles)],
                        "Score": f"{score:+.2f}",
                })
        return pd.DataFrame(rows)


def _v15_speeches_list(code: Optional[str] = None, max_rows: int = 12) -> None:
        df = _v15_speeches_df(code).head(max_rows)
        if not isinstance(df, pd.DataFrame) or df.empty:
                st.caption("No speech tape rows available.")
                return
        rows = ['<div class="v15-speech-list">']
        for _, r in df.iterrows():
                rows.append(
                        f'<div class="v15-speech-row"><div><div class="v15-speech-title">{_v12_esc(r.get("Speaker", ""))} — {_v12_esc(r.get("Title", ""))}</div><div class="v15-speech-date">{_v12_esc(r.get("Date", ""))} · {_v12_esc(r.get("CB", ""))}</div></div><div class="v15-speech-score">{_v12_esc(r.get("Score", ""))}</div></div>'
                )
        rows.append('</div>')
        _v12_html("".join(rows))


def _v15_metrics(items: List[Tuple[str, Any, str]]) -> None:
        html = ['<div class="v15-metric-grid">']
        for label, value, sub in items:
                html.append(f'<div class="v15-metric"><div class="v15-metric-label">{_v12_esc(label)}</div><div class="v15-metric-value">{_v12_esc(value)}</div><div class="v15-metric-sub">{_v12_esc(sub)}</div></div>')
        html.append('</div>')
        _v12_html("".join(html))


def _v15_bank_pager(selected_code: str) -> None:
        st.markdown('<div class="v15-bank-pager">', unsafe_allow_html=True)
        cols = st.columns([1.20, .76, .92, .74, .74, .80, .82, .90, .88, .70, .72])
        with cols[0]:
                if st.button("← Overview", key="macro_v15_bank_overview", use_container_width=True):
                        _v15_central_banks_overview()
        for col, code in zip(cols[1:], V12_BANK_ORDER):
                spec = G10_BANKS_V6.get(code, {})
                with col:
                        active = "● " if code == selected_code else ""
                        if st.button(f"{active}{spec.get('flag','')} {code}", key=f"macro_v15_bank_pager_{code}", use_container_width=True):
                                _v15_open_bank(code, st.session_state.get("macro_v12_bank_view", "overview"))
        st.markdown('</div>', unsafe_allow_html=True)


def _v15_bank_view_tabs(selected_code: str, active_view: str) -> None:
        st.markdown('<div class="v15-bank-tabs">', unsafe_allow_html=True)
        cols = st.columns(4)
        for col, (view_key, label) in zip(cols, V12_BANK_VIEWS.items()):
                with col:
                        active = "● " if active_view == view_key else ""
                        if st.button(active + label, key=f"macro_v15_bank_tab_{selected_code}_{view_key}", use_container_width=True):
                                _v15_open_bank(selected_code, view_key)
        st.markdown('</div>', unsafe_allow_html=True)


def _v15_member_cards(code: str) -> None:
        # Reuse V12 member cards; they are already close to the reference scorecard cards.
        _v12_member_cards(code)


def _v15_render_central_banks_overview(bank_df: pd.DataFrame, selected_code: str, pack: Optional[Dict[str, pd.DataFrame]] = None) -> None:
        ordered = _v15_apply_bank_display_overrides(bank_df)
        _v15_hero(
                "Global Monetary Policy Observatory",
                "Hawk/Dove Monitor — G10 Central Banks",
                "Desk-style policy dashboard: G10 policy cards, hawk/dove composite, ranked policy rates, balance-sheet impulse and speeches tape. Use each card footer to enter the bank workstation.",
        )
        _v15_render_bank_cards(ordered, selected_code)
        c1, c2 = st.columns([1.1, .9])
        with c1:
                _v15_plot_hawk_dove(ordered, selected_code=None, height=420)
        with c2:
                _v15_plot_rates_ranked(ordered, height=420)
        _v15_policy_history_chart(selected_code if selected_code in G10_BANKS_V6 else "FED", ordered, height=455)
        _v15_section("Recent Speeches", "Hawk/dove NLP tape. Structural rows are used until an official speeches feed is connected.")
        _v15_speeches_list(None, max_rows=12)


def _v15_render_bank_detail(bank_df: pd.DataFrame, selected_code: str, pack: Dict[str, pd.DataFrame]) -> None:
        ordered = _v15_apply_bank_display_overrides(bank_df)
        code = selected_code if selected_code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6.get(code, G10_BANKS_V6["FED"])
        row = _v12_selected_row(ordered, code)
        rate = safe_float(row.get("Policy Rate"), spec.get("fallback_rate", 0.0)) or 0.0
        hawk = safe_float(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0)) or 0.0
        target = safe_float(row.get("Target"), spec.get("target", 2.0)) or 2.0
        stance = str(row.get("Stance", spec.get("status", "HOLD"))).upper()
        view = str(st.session_state.get("macro_v12_bank_view", "overview"))
        view = view if view in V12_BANK_VIEWS else "overview"
        st.session_state["macro_v12_bank_view"] = view

        _v15_bank_pager(code)
        _v15_hero(
                "Central Bank Workstation",
                f"{spec.get('flag','')} {spec.get('name', code)}",
                f"Bank-level workflow: overview, hawk/dove scorecard, speeches and meetings. Session-state route equivalent to /central-banks/{code}, without URL redirects.",
        )
        _v15_metrics([
                ("Policy rate", f"{rate:.2f}%", stance),
                ("Hawk/Dove", f"{hawk:+.3f}", "positive = hawkish"),
                ("Inflation target", f"{target:.1f}%", str(spec.get("country", ""))),
                ("Currency", str(spec.get("ccy", "")), str(spec.get("meetings", ""))),
        ])
        _v15_bank_view_tabs(code, view)

        if view == "overview":
                marker = max(2, min(98, 50 + hawk * 48))
                _v12_html(f'<div class="v15-ivory"><h3>Hawk/Dove Stance</h3><div class="v15-hawkbar"><span class="v15-hawkmarker" style="left:{marker:.1f}%"></span></div><div class="v15-hawklabels"><span>Dovish</span><span>Neutral</span><span>Hawkish</span></div></div>')
                c1, c2 = st.columns([1, 1])
                with c1:
                        _v15_policy_history_chart(code, ordered, height=420)
                with c2:
                        _v15_plot_hawk_dove(ordered, selected_code=code, height=420)
                _v15_section("Recent Speeches", "Bank-filtered speech tape. Fallback rows are generated per selected bank until an official speech/NLP feed is connected.")
                _v15_speeches_list(code, max_rows=8)
                _v15_section("Reaction Function", "Directional transmission map for surprises and guidance shocks.")
                _v15_html_table(_v12_reaction_table(code), max_rows=10)
                _v15_section("Taylor Snapshot")
                taylor = _v12_taylor_table(ordered)
                snap = taylor.loc[taylor["Code"].astype(str).str.upper() == code].copy()
                if not snap.empty:
                        for col in ["Actual Rate", "Taylor Implied", "Inflation"]:
                                if col in snap.columns:
                                        snap[col] = snap[col].map(lambda x: f"{safe_float(x, 0.0):.2f}%")
                        for col in ["Gap", "Output Gap"]:
                                if col in snap.columns:
                                        snap[col] = snap[col].map(lambda x: f"{safe_float(x, 0.0):+.2f}%")
                        _v15_html_table(snap[[c for c in ["Code", "Central Bank", "Actual Rate", "Taylor Implied", "Gap", "Inflation", "Output Gap", "Stance"] if c in snap.columns]], max_rows=5)

        elif view == "scorecard":
                _v15_section(f"{spec.get('name', code)} — Hawk/Dove Scorecard", "Member-level stance cards. Live parity requires official speeches feed and NLP scoring.")
                members = _v12_bank_members(code)
                if not members.empty:
                        avg = safe_float(members["Score"].mean(), 0.0) or 0.0
                        marker = max(2, min(98, 50 + avg * 48))
                        _v12_html(f'<div class="v15-ivory"><h3>The Committee</h3><div style="color:#8b95a3;font-weight:800;margin-bottom:10px;">All members hawk/dove scores over time — recent score = {avg:+.2f}</div><div class="v15-hawkbar"><span class="v15-hawkmarker" style="left:{marker:.1f}%"></span></div><div class="v15-hawklabels"><span>Dovish</span><span>Neutral</span><span>Hawkish</span></div></div>')
                _v15_member_cards(code)
                _v15_section("Meeting score history")
                _v15_html_table(_v12_meetings_table(code), max_rows=12)

        elif view == "speeches":
                _v15_section("Recent Speeches", "Bank-filtered speech tape with score badge. Exact parity requires official speech scraping/NLP feed.")
                _v15_speeches_list(code, max_rows=20)

        elif view == "meetings":
                _v15_section("Meetings", "Decision tape and average hawk/dove score. Actual/consensus decision feeds are provider-ready.")
                _v15_html_table(_v12_event_tape(code), max_rows=10)
                _v15_html_table(_v12_meetings_table(code), max_rows=20)


def _v15_render_taylor(bank_df: pd.DataFrame, selected_code: str) -> None:
        ordered = _v15_apply_bank_display_overrides(bank_df)
        _v15_hero(
                "Monetary Policy Analysis",
                "G10 Taylor Rule Monitor",
                "Prescriptive rates using r = r* + π + 0.5(π − π*) + 0.5(output gap). Positive gap means implied rate is above actual rate.",
        )
        taylor = _v12_taylor_table(ordered)
        row = taylor.loc[taylor["Code"].astype(str).str.upper() == selected_code]
        r = row.iloc[0] if not row.empty else taylor.iloc[0]
        _v15_metrics([
                ("Actual", _v15_pct(r.get("Actual Rate")), str(r.get("Central Bank", ""))),
                ("Taylor implied", _v15_pct(r.get("Taylor Implied")), "rule-implied prescription"),
                ("Gap", f'{safe_float(r.get("Gap"), 0.0):+.2f}%', str(r.get("Stance", ""))),
                ("Inflation", _v15_pct(r.get("Inflation")), "headline proxy"),
        ])
        c1, c2 = st.columns([.96, 1.04])
        with c1:
                fig = go.Figure(go.Bar(y=[f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in taylor["Code"]], x=taylor["Gap"], orientation="h", text=[f"{x:+.2f}%" for x in taylor["Gap"]], textposition="outside", marker=dict(color=np.where(taylor["Gap"] >= 0, "#bd6048", "#6f9fc5"))))
                fig.add_vline(x=0, line_dash="dot", line_color="#818b9a")
                _v15_fig_template(fig, "G10 Taylor Rule Gap Ranking", height=470)
                st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        with c2:
                view = taylor[["Code", "Country", "Central Bank", "Actual Rate", "Taylor Implied", "Gap", "Inflation", "Output Gap", "Stance"]].copy()
                for col in ["Actual Rate", "Taylor Implied", "Inflation"]:
                        view[col] = view[col].map(lambda x: f"{safe_float(x, 0.0):.2f}%")
                for col in ["Gap", "Output Gap"]:
                        view[col] = view[col].map(lambda x: f"{safe_float(x, 0.0):+.2f}%")
                _v15_html_table(view, max_rows=20)


def _v15_render_page(page: str, selected_code: str, pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame, bank_df: pd.DataFrame) -> None:
        page = _v12_normalize_page(page)
        route = st.session_state.get("macro_v12_route", "overview")
        bank_df = _v15_apply_bank_display_overrides(bank_df)
        if page == "central-banks":
                if route == "bank":
                        _v15_render_bank_detail(bank_df, selected_code, pack)
                else:
                        _v15_render_central_banks_overview(bank_df, selected_code, pack)
        elif page == "taylor-rule":
                _v15_render_taylor(bank_df, selected_code)
        else:
                # Preserve all existing V11/V12 non-central-bank pages but with V15 shell/topbar.
                _v12_render_page(page, selected_code, pack, proxy_pack, indicator_df, bank_df)


def render_macro_central_bank_lab(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
        """V15 renderer: robust session routing plus closer RoboMacro-style layout."""
        _v12_css()
        _v13_css()
        _v14_css()
        _v15_css()
        _v12_init_state()

        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
        selected_code = str(st.session_state.get("macro_v12_bank", "FED")).upper().strip()
        if selected_code not in G10_BANKS_V6:
                selected_code = "FED"
                st.session_state["macro_v12_bank"] = selected_code
        if page != "central-banks":
                st.session_state["macro_v12_route"] = "overview"

        with st.spinner("Loading macro / central bank data…"):
                pack = build_macro_pack_cached("2000-01-01", True)
                proxy_pack = fetch_market_proxy_pack("2y")
                indicator_df = compute_indicator_table(pack)
                bank_df = _v6_bank_table(pack)
                bank_df = _v15_apply_bank_display_overrides(bank_df)

        st.markdown('<div class="v15-shell">', unsafe_allow_html=True)
        try:
                _v15_topbar(page)
                _v15_render_page(page, selected_code, pack, proxy_pack, indicator_df, bank_df)
                _v12_html('<div class="v15-footer">Macro V15 · audit parity + robust original-like design. Navigation remains Streamlit session_state only; visual layers use HTML/CSS; charts use Plotly; bank pages use bank-filtered structural speech fallbacks until live provider feeds are connected.</div>')
        finally:
                st.markdown('</div>', unsafe_allow_html=True)

