# MACRO CENTRAL BANKS V15.1 — NAMEERROR HOTFIX
# ============================================================
# Fixes V15 regression:
#      NameError: name 'build_macro_pack_cached' is not defined
# Reason:
#      V15 renderer reused historical wrapper names from earlier patches, while
#      the active base file exposes load_macro_fred_pack(), load_market_proxy_pack()
#      and build_macro_indicator_table().
# This block is append-only and safe: it defines missing compatibility wrappers
# without changing routing, navigation or visual design.
# ============================================================

try:
        _MACRO_V151_ST_CACHE = st.cache_data
except Exception:
        _MACRO_V151_ST_CACHE = None


def _macro_v151_identity_cache(*args, **kwargs):
        def _decorator(fn):
                return fn
        return _decorator


_macro_v151_cache = _MACRO_V151_ST_CACHE if callable(_MACRO_V151_ST_CACHE) else _macro_v151_identity_cache


if "build_macro_pack_cached" not in globals():
        @_macro_v151_cache(ttl=21600, show_spinner=False)
        def build_macro_pack_cached(start_date: str = "2000-01-01", show_all_series: bool = True):
                """Compatibility wrapper expected by the V15 renderer."""
                try:
                        if show_all_series:
                                series_ids = tuple(FRED_SERIES.keys())
                        else:
                                series_ids = tuple(
                                        sid for sid, meta in FRED_SERIES.items()
                                        if isinstance(meta, dict) and meta.get("importance") == "High"
                                )
                        return load_macro_fred_pack(series_ids, start_date=start_date)
                except Exception:
                        return {}


if "fetch_market_proxy_pack" not in globals():
        @_macro_v151_cache(ttl=900, show_spinner=False)
        def fetch_market_proxy_pack(period: str = "2y"):
                """Compatibility wrapper expected by the V15 renderer."""
                try:
                        return load_market_proxy_pack(tuple(MARKET_PROXIES.keys()), period=period)
                except Exception:
                        return {}


if "compute_indicator_table" not in globals():
        def compute_indicator_table(pack):
                """Compatibility wrapper expected by the V15 renderer."""
                try:
                        return build_macro_indicator_table(pack)
                except Exception:
                        try:
                                return pd.DataFrame()
                        except Exception:
                                return None


# Soft guard for empty pack objects, useful when FRED/Yahoo calls fail.
if "_macro_v151_safe_pack" not in globals():
        def _macro_v151_safe_pack(obj):
                return obj if isinstance(obj, dict) else {}


try:
        _previous_render_macro_central_bank_lab_v151 = render_macro_central_bank_lab
except Exception:
        _previous_render_macro_central_bank_lab_v151 = None


def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
        """V15.1 renderer guard: preserves V15 UI, guarantees missing wrappers exist."""
        try:
                if callable(_previous_render_macro_central_bank_lab_v151):
                        return _previous_render_macro_central_bank_lab_v151(ticker, price_data, analysis)
        except NameError as exc:
                # If another legacy compatibility name appears, render a clear diagnostic
                # instead of crashing the whole terminal.
                try:
                        st.error(f"Macro module compatibility error: {exc}")
                        st.caption(
                                "V15.1 wrappers are active. If this appears, another legacy wrapper name "
                                "is missing and should be mapped to the active base functions."
                        )
                except Exception:
                        raise
        except Exception:
                raise


