def _v16_safe(x: Any, default: float = 0.0) -> float:
        try:
                v = safe_float(x, default)
                return float(default if v is None else v)
        except Exception:
                return float(default)


def _v16_fmt_pct(x: Any, digits: int = 2, signed: bool = False) -> str:
        v = _v16_safe(x, 0.0)
        return f"{v:+.{digits}f}%" if signed else f"{v:.{digits}f}%"


def _v16_html(s: str) -> None:
        st.markdown(s, unsafe_allow_html=True)


def _v16_esc(x: Any) -> str:
        try:
                import html as _html
                return _html.escape(str(x))
        except Exception:
                return str(x).replace("<", "&lt;").replace(">", "&gt;")


