def _v16_button_rerun() -> None:
        try:
                st.rerun()
        except Exception:
                try:
                        st.experimental_rerun()
                except Exception:
                        pass


def _v16_go_page(page: str) -> None:
        st.session_state["macro_v12_page"] = _v12_normalize_page(page)
        st.session_state["macro_v12_route"] = "overview"
        st.session_state["macro_v12_bank_view"] = "overview"
        _v16_button_rerun()


def _v16_open_bank(code: str, view: str = "overview") -> None:
        code = str(code or "FED").upper().strip()
        if code not in G10_BANKS_V6:
                code = "FED"
        view = view if view in V16_BANK_VIEWS else "overview"
        st.session_state["macro_v12_page"] = "central-banks"
        st.session_state["macro_v12_route"] = "bank"
        st.session_state["macro_v12_bank"] = code
        st.session_state["macro_v12_bank_view"] = view
        _v16_button_rerun()


def _v16_central_overview() -> None:
        st.session_state["macro_v12_page"] = "central-banks"
        st.session_state["macro_v12_route"] = "overview"
        st.session_state["macro_v12_bank_view"] = "overview"
        _v16_button_rerun()


