def _v16_hero(kicker: str, title: str, subtitle: str = "") -> None:
        _v16_html(f'<div class="m16-hero"><div class="m16-kicker">{_v16_esc(kicker)}</div><h1 class="m16-title">{_v16_esc(title)}</h1><div class="m16-sub">{_v16_esc(subtitle)}</div></div>')


def _v16_section(title: str, subtitle: str = "") -> None:
        _v16_html(f'<div class="m16-section"><h3>{_v16_esc(title)}</h3><p>{_v16_esc(subtitle)}</p></div>')


def _v16_html_table(df: pd.DataFrame, max_rows: int = 40, numfmt: Optional[Dict[str, str]] = None) -> None:
        if not isinstance(df, pd.DataFrame) or df.empty:
                _v16_html('<div class="m16-warning">No rows available for this table.</div>')
                return
        use = df.head(max_rows).copy()
        numfmt = numfmt or {}
        html = ['<div style="overflow:auto"><table class="m16-table"><thead><tr>']
        for col in use.columns:
                html.append(f'<th>{_v16_esc(col)}</th>')
        html.append('</tr></thead><tbody>')
        for _, row in use.iterrows():
                html.append('<tr>')
                for col in use.columns:
                        val = row[col]
                        if col in numfmt and isinstance(val, (int, float, np.integer, np.floating)):
                                try:
                                        val = numfmt[col].format(val)
                                except Exception:
                                        pass
                        html.append(f'<td>{_v16_esc(val)}</td>')
                html.append('</tr>')
        html.append('</tbody></table></div>')
        _v16_html(''.join(html))


def _v16_plot_config() -> Dict[str, Any]:
        return {
                "displayModeBar": True,
                "displaylogo": False,
                "responsive": True,
                "modeBarButtonsToRemove": ["lasso2d", "select2d"],
                "toImageButtonOptions": {"format": "png", "filename": "macrodesk_chart", "height": 900, "width": 1400, "scale": 2},
        }


def _v16_fig(fig: go.Figure, title: str = "", height: int = 420, x_is_date: bool = False) -> go.Figure:
        fig.update_layout(
                title=dict(text=title, font=dict(size=16, color="#f2f6fb", family="Georgia"), x=0.02),
                height=height,
                paper_bgcolor=V16_BG,
                plot_bgcolor="#07101b",
                font=dict(color="#d9e3ee", family=V16_FONT, size=12),
                margin=dict(l=56, r=52, t=52, b=54),
                hovermode="x unified",
                legend=dict(orientation="h", yanchor="bottom", y=-0.24, xanchor="left", x=0, bgcolor="rgba(0,0,0,0)", font=dict(size=11)),
        )
        fig.update_xaxes(showgrid=True, gridcolor=V16_GRID, zeroline=False, linecolor="rgba(180,198,214,.28)", tickfont=dict(color="#c8d2dd"), showspikes=True, spikemode="across", spikecolor="#d6bd65", spikethickness=1)
        fig.update_yaxes(showgrid=True, gridcolor=V16_GRID, zeroline=False, linecolor="rgba(180,198,214,.28)", tickfont=dict(color="#c8d2dd"), showspikes=True, spikemode="across", spikecolor="#d6bd65", spikethickness=1)
        if x_is_date:
                fig.update_xaxes(
                        rangeselector=dict(
                                buttons=[
                                        dict(count=1, label="1Y", step="year", stepmode="backward"),
                                        dict(count=3, label="3Y", step="year", stepmode="backward"),
                                        dict(count=5, label="5Y", step="year", stepmode="backward"),
                                        dict(step="all", label="Max"),
                                ],
                                bgcolor="#0b1826", activecolor="#b39a2e", bordercolor="rgba(205,181,88,.30)", font=dict(color="#dce6ef"),
                        ),
                        rangeslider=dict(visible=False),
                )
        return fig


def _v16_metric_cards(items: List[Tuple[str, Any, str]]) -> None:
        html = ['<div class="m16-metrics">']
        for label, value, sub in items:
                html.append(f'<div class="m16-metric"><div class="m16-ml">{_v16_esc(label)}</div><div class="m16-mv">{_v16_esc(value)}</div><div class="m16-ms">{_v16_esc(sub)}</div></div>')
        html.append('</div>')
        _v16_html(''.join(html))


def _v16_bank_df(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        try:
                df = _v6_bank_table(pack)
        except Exception:
                df = pd.DataFrame()
        try:
                return _v15_apply_bank_display_overrides(df)
        except Exception:
                rows = []
                for code in V16_BANK_ORDER:
                        spec = G10_BANKS_V6.get(code, {})
                        rows.append({
                                "Code": code, "Flag": spec.get("flag", ""), "Central Bank": spec.get("name", code), "Country": spec.get("country", code),
                                "Currency": spec.get("ccy", ""), "Policy Rate": spec.get("fallback_rate", 0.0), "Hawk/Dove": spec.get("fallback_hawk", 0.0),
                                "Composite": 50 + float(spec.get("fallback_hawk", 0.0)) * 48, "Stance": spec.get("status", "HOLD"), "Members": spec.get("members", ""),
                                "Meetings": spec.get("meetings", ""), "Target": spec.get("target", 2.0),
                                "Inflation": G10_INFLATION_FALLBACK_V6.get(code, {}).get("headline", 2.0), "Core": G10_INFLATION_FALLBACK_V6.get(code, {}).get("core", 2.0),
                                "Unemployment": G10_INFLATION_FALLBACK_V6.get(code, {}).get("unemployment", np.nan),
                        })
                return pd.DataFrame(rows)


def _v16_bank_card_html(row: pd.Series, selected_code: str) -> str:
        code = str(row.get("Code", ""))
        spec = G10_BANKS_V6.get(code, {})
        accent = spec.get("colour", V16_GOLD)
        stance = str(row.get("Stance", "HOLD")).upper()
        sym = "▲" if stance == "HIKE" else "▼" if stance == "CUT" else "●"
        stance_cls = "hike" if stance == "HIKE" else "cut" if stance == "CUT" else ""
        score = _v16_safe(row.get("Hawk/Dove"), spec.get("fallback_hawk", 0.0))
        marker = max(3, min(94, 50 + score * 55))
        selected = "selected" if code == selected_code else ""
        return f"""
        <div class="m16-card {selected}" style="--accent:{accent}">
            <div class="m16-card-top">
                <div><div class="m16-bank-code">{_v16_esc(spec.get('flag',''))} {_v16_esc(code)}</div><div class="m16-bank-name">{_v16_esc(row.get('Central Bank', spec.get('name', code)))}</div></div>
                <div class="m16-ccy">{_v16_esc(row.get('Currency', spec.get('ccy','')))}</div>
            </div>
            <div class="m16-rate">{_v16_safe(row.get('Policy Rate')):.2f}% <span class="m16-stance {stance_cls}">{sym} {stance}</span></div>
            <div class="m16-meter"><span class="m16-marker" style="left:{marker:.1f}%"></span></div>
            <div class="m16-small"><span>{score:+.3f}</span><span>{_v16_esc(row.get('Members', spec.get('members','')))} members</span></div>
            <div class="m16-small"><span>{_v16_esc(row.get('Meetings', spec.get('meetings','')))}</span><span>target {_v16_safe(row.get('Target', spec.get('target',2.0))):.1f}%</span></div>
        </div>
        """


def _v16_render_bank_cards(bank_df: pd.DataFrame, selected_code: str) -> None:
        for start in range(0, len(V16_BANK_ORDER), 4):
                cols = st.columns(4, gap="medium")
                for col, code in zip(cols, V16_BANK_ORDER[start:start + 4]):
                        sub = bank_df.loc[bank_df["Code"].astype(str).str.upper() == code]
                        if sub.empty:
                                continue
                        row = sub.iloc[0]
                        with col:
                                st.markdown(_v16_bank_card_html(row, selected_code), unsafe_allow_html=True)
                                st.markdown('<div class="m16-open">', unsafe_allow_html=True)
                                if st.button(f"Open {code}", key=f"m16_open_bank_{code}", use_container_width=True):
                                        _v16_open_bank(code, "overview")
                                st.markdown('</div>', unsafe_allow_html=True)


def _v16_plot_hawk_dove(bank_df: pd.DataFrame, selected_code: Optional[str] = None, mode: str = "Level", height: int = 440) -> go.Figure:
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=76, freq="ME")
        fig = go.Figure()
        for idx, code in enumerate(V16_BANK_ORDER):
                row = bank_df.loc[bank_df["Code"].astype(str).str.upper() == code]
                if row.empty:
                        continue
                r = row.iloc[0]
                base = _v16_safe(r.get("Hawk/Dove"), G10_BANKS_V6.get(code, {}).get("fallback_hawk", 0.0))
                seed = (sum(ord(c) for c in code) % 31) / 10
                vals = np.array([base + 0.18 * math.sin(i / 8.0 + seed) + 0.09 * math.cos(i / 17.0 + seed) for i in range(len(dates))])
                if mode == "3m/3m Change":
                        vals = pd.Series(vals).diff(3).fillna(0).values
                opacity = 1.0 if not selected_code or code == selected_code else 0.26
                width = 3.5 if code == selected_code else 1.9
                fig.add_trace(go.Scatter(x=dates, y=vals, mode="lines+markers" if code == selected_code else "lines", name=f"{G10_BANKS_V6.get(code,{}).get('flag','')} {code}", line=dict(color=V16_PALETTE[idx % len(V16_PALETTE)], width=width), opacity=opacity, hovertemplate="%{fullData.name}<br>%{x|%b %Y}<br>Score %{y:.3f}<extra></extra>"))
        fig.add_hline(y=0, line_dash="dot", line_color="#d6bd65", annotation_text="Neutral", annotation_font_color="#d6bd65")
        _v16_fig(fig, "Hawk/Dove Composite", height=height, x_is_date=True)
        fig.update_yaxes(title="Dovish    ← score →    Hawkish")
        return fig


def _v16_plot_rates_ranked(bank_df: pd.DataFrame, height: int = 440) -> go.Figure:
        df = bank_df.copy().sort_values("Policy Rate", ascending=True)
        colors = [G10_BANKS_V6.get(c, {}).get("colour", V16_BLUE) for c in df["Code"]]
        fig = go.Figure(go.Bar(x=df["Policy Rate"], y=[f"{G10_BANKS_V6.get(c,{}).get('flag','')} {c}" for c in df["Code"]], orientation="h", text=[f"{x:.2f}%" for x in df["Policy Rate"]], textposition="outside", marker=dict(color=colors, line=dict(color="rgba(255,255,255,.25)", width=1)), hovertemplate="%{y}<br>Policy rate %{x:.2f}%<extra></extra>"))
        _v16_fig(fig, "Policy Rates — Ranked", height=height)
        fig.update_xaxes(title="Policy rate %", rangemode="tozero")
        return fig


def _v16_policy_history_chart(code: str, bank_df: pd.DataFrame, height: int = 430) -> go.Figure:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6.get(code, {})
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=42, freq="ME")
        base = _v16_safe(bank_df.loc[bank_df["Code"].astype(str).str.upper() == code, "Policy Rate"].iloc[0] if code in set(bank_df["Code"].astype(str).str.upper()) else spec.get("fallback_rate", 0.0))
        # Smooth synthetic history around current level; live provider can replace this later.
        idx = np.arange(len(dates))
        path = base - 0.55 * np.sin((idx - len(idx) * .35) / 8.2) + 0.12 * np.sin(idx / 3.5)
        path = path - path[-1] + base
        bs = 55 * np.sin(np.linspace(0, 2.55 * math.pi, len(dates))) + 35 * np.cos(np.linspace(0, 1.4 * math.pi, len(dates)))
        colors = np.where(bs >= 0, "#6d9fc1", "#bd6048")
        fig = go.Figure()
        fig.add_trace(go.Bar(x=dates, y=bs, yaxis="y2", name="Balance sheet Δ $bn/mo", marker=dict(color=colors, opacity=.82), hovertemplate="%{x|%b %Y}<br>BS Δ %{y:.1f} $bn/mo<extra></extra>"))
        fig.add_trace(go.Scatter(x=dates, y=path, mode="lines", name="Policy rate", line=dict(color="#d6bd65", width=3), hovertemplate="%{x|%b %Y}<br>Policy rate %{y:.2f}%<extra></extra>"))
        _v16_fig(fig, f"{spec.get('name', code)} — Policy Rate & Balance Sheet", height=height, x_is_date=True)
        fig.update_layout(yaxis=dict(title="Policy rate %"), yaxis2=dict(title="$bn/mo", overlaying="y", side="right", showgrid=False, zeroline=False, tickfont=dict(color="#c8d2dd")))
        return fig


def _v16_taylor_df(bank_df: Optional[pd.DataFrame] = None) -> pd.DataFrame:
        rows = []
        for code in V16_BANK_ORDER:
                spec = G10_BANKS_V6.get(code, {})
                d = dict(V16_TAYLOR_PARITY.get(code, {}))
                rows.append({
                        "Code": code,
                        "Country": d.get("country", spec.get("country", code)),
                        "Central Bank": spec.get("name", code),
                        "Actual Rate": d.get("actual", spec.get("fallback_rate", 0.0)),
                        "Taylor Implied": d.get("implied", spec.get("fallback_rate", 0.0)),
                        "Gap": d.get("gap", 0.0),
                        "YE 2026 Implied": d.get("ye26", np.nan),
                        "YE 2027 Implied": d.get("ye27", np.nan),
                        "Inflation": d.get("inflation", G10_INFLATION_FALLBACK_V6.get(code, {}).get("headline", 2.0)),
                        "Target": d.get("target", spec.get("target", 2.0)),
                        "Output Gap": d.get("output_gap", 0.0),
                        "Stance": d.get("stance", "Neutral"),
                        "Latest Quarter": d.get("q", "N/A"),
                })
        return pd.DataFrame(rows).sort_values("Gap", ascending=False).reset_index(drop=True)


def _v16_taylor_country_chart(code: str, height: int = 420) -> go.Figure:
        code = code if code in G10_BANKS_V6 else "FED"
        d = V16_TAYLOR_PARITY.get(code, V16_TAYLOR_PARITY["FED"])
        dates = pd.period_range("2017Q1", periods=38, freq="Q").to_timestamp()
        idx = np.arange(len(dates))
        actual = np.linspace(float(d["actual"]) - 1.2, float(d["actual"]), len(dates)) + 0.35 * np.sin(idx / 5)
        implied = np.linspace(float(d["implied"]) - 1.0, float(d["implied"]), len(dates)) + 0.55 * np.cos(idx / 6)
        actual = actual - actual[-1] + float(d["actual"])
        implied = implied - implied[-1] + float(d["implied"])
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=dates, y=actual, mode="lines", name="Actual policy rate", line=dict(color=V16_BLUE, width=3)))
        fig.add_trace(go.Scatter(x=dates, y=implied, mode="lines", name="Taylor implied", line=dict(color=V16_RUST, width=3, dash="dash")))
        fig.add_trace(go.Scatter(x=list(dates)+list(dates[::-1]), y=list(implied)+list(actual[::-1]), fill="toself", fillcolor="rgba(189,96,72,.16)", line=dict(color="rgba(0,0,0,0)"), name="Gap", hoverinfo="skip"))
        _v16_fig(fig, f"{G10_BANKS_V6.get(code,{}).get('country', code)} — actual vs Taylor implied", height=height, x_is_date=True)
        fig.update_yaxes(title="Policy rate %")
        return fig


def _v16_speeches_df(code: Optional[str] = None) -> pd.DataFrame:
        try:
                df = _v15_speeches_df(code)
                if isinstance(df, pd.DataFrame) and not df.empty:
                        return df
        except Exception:
                pass
        rows = []
        base = [
                ("2026-07-08", "RBA", "Andrew Hauser", "Understanding Supply Shocks and Their Implications for Monetary Policy", 0.10),
                ("2026-07-06", "ECB", "Philip Lane", "AI and monetary policy", 0.05),
                ("2026-07-02", "ECB", "Christine Lagarde", "Interview with Les Échos", 0.45),
                ("2026-07-02", "BOE", "Catherine Mann", "Mixed signals, research findings, and policy judgements", 0.60),
                ("2026-07-01", "BOJ", "Naoki Tamura", "Economic activity, prices and monetary policy in Japan", 0.10),
                ("2026-06-30", "ECB", "Philip Lane", "Introductory remarks", 0.35),
                ("2026-06-30", "BOJ", "Ryozo Himino", "Semiannual Report on Currency and Monetary Control", 0.70),
                ("2026-06-25", "ECB", "Isabel Schnabel", "Interview with Die Zeit", 0.70),
                ("2026-06-23", "BOE", "Alan Taylor", "Central reservations", -0.40),
        ]
        for d, cb, sp, title, score in base:
                rows.append({"Date": d, "CB": cb, "Speaker": sp, "Title": title, "Score": score})
        out = pd.DataFrame(rows)
        if code:
                sub = out[out["CB"].astype(str).str.upper() == str(code).upper()]
                if not sub.empty:
                        return sub
        return out


def _v16_speeches_list(code: Optional[str] = None, max_rows: int = 12) -> None:
        df = _v16_speeches_df(code).head(max_rows)
        html = ['<div class="m16-panel">']
        for _, r in df.iterrows():
                score = _v16_safe(r.get("Score"), 0.0)
                klass = "red" if score > 0.25 else "blue" if score < -0.15 else "gold"
                html.append(f'<div class="m16-speech"><div class="m16-muted">{_v16_esc(r.get("Date",""))}</div><div><span class="m16-badge {klass}">{_v16_esc(r.get("CB",""))}</span></div><div><div class="m16-speech-title">{_v16_esc(r.get("Speaker",""))} — {_v16_esc(r.get("Title",""))}</div></div><div><span class="m16-badge {klass}">{score:+.2f}</span></div></div>')
        html.append('</div>')
        _v16_html(''.join(html))


