def _v16_china_pair(title: str, left: str, right: str, height: int = 390) -> go.Figure:
        dates = pd.date_range("2021-01-01", periods=66, freq="ME")
        t = np.linspace(0, 2.5 * math.pi, len(dates))
        y1 = 100 + 20 * np.sin(t + .2) + np.linspace(-5, 8, len(dates))
        y2 = 70 + 12 * np.cos(t - .7) + np.linspace(3, -3, len(dates))
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=dates, y=y1, name=left, line=dict(color=V16_BLUE, width=3)))
        fig.add_trace(go.Scatter(x=dates, y=y2, name=right, yaxis="y2", line=dict(color=V16_RUST, width=3)))
        _v16_fig(fig, title, height=height, x_is_date=True)
        fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False, tickfont=dict(color="#c8d2dd")))
        return fig


def _v16_render_china() -> None:
        _v16_hero("China Macro", "China Dashboard — Growth, PBoC, Trade & Markets", "Growth, inflation, PBoC policy, trade flows, yuan, credit, property stress and Chinese equity markets. Charts pair two related series so the relationship is visible, not just the level.")
        groups = ["Activity", "Inflation & Policy", "External", "Markets"]
        for g in groups:
                rows = [x for x in V16_CHINA_METRICS if x[3] == g]
                cols = st.columns(4, gap="medium")
                for col, (label, value, date, _) in zip(cols, rows):
                        with col:
                                _v16_html(f'<div class="m16-metric"><div class="m16-ml">{_v16_esc(g)}</div><div class="m16-mv">{_v16_esc(value)}</div><div class="m16-ms">{_v16_esc(label)} · {date}</div></div>')
        c1, c2 = st.columns(2, gap="large")
        with c1:
                st.plotly_chart(_v16_china_pair("Growth & Inflation", "Real GDP YoY", "CPI YoY (RHS)"), use_container_width=True, config=_v16_plot_config())
                st.plotly_chart(_v16_china_pair("Chinese Equities", "CSI 300", "Hang Seng (RHS)"), use_container_width=True, config=_v16_plot_config())
                st.plotly_chart(_v16_china_pair("Credit Impulse & Property Stress", "Credit impulse", "Property stress (RHS)"), use_container_width=True, config=_v16_plot_config())
        with c2:
                st.plotly_chart(_v16_china_pair("The Yuan", "USD/CNY", "CNY NEER (RHS)"), use_container_width=True, config=_v16_plot_config())
                st.plotly_chart(_v16_china_pair("Trade & External", "Exports YoY", "Imports YoY (RHS)"), use_container_width=True, config=_v16_plot_config())
                st.plotly_chart(_v16_china_pair("PBoC Policy & Inflation", "Policy rate", "PPI YoY (RHS)"), use_container_width=True, config=_v16_plot_config())


def _v16_misery_df() -> pd.DataFrame:
        rows = []
        for c, (infl, unemp, housing, group) in V16_MISERY.items():
                classic = infl + unemp
                rows.append({"Country": c, "Group": group, "Inflation": infl, "Unemployment": unemp, "Classic": classic, "Housing burden": housing, "Neo-Misery": classic + housing, "Gap": housing})
        return pd.DataFrame(rows).sort_values("Neo-Misery", ascending=False)


def _v16_render_misery() -> None:
        _v16_hero("Social Macro", "Misery Indices — Classic & Housing-Augmented", "Classic misery = inflation + unemployment. Neo-misery adds housing affordability stress, so the gap between the two is the housing burden.")
        df = _v16_misery_df()
        cols = st.columns([1,1,1,3])
        with cols[0]:
                filt_all = st.button("All", key="m16_misery_all", use_container_width=True)
        with cols[1]:
                filt_adv = st.button("Advanced", key="m16_misery_adv", use_container_width=True)
        with cols[2]:
                filt_em = st.button("Emerging", key="m16_misery_em", use_container_width=True)
        if filt_adv:
                st.session_state["m16_misery_filter"] = "Advanced"
        elif filt_em:
                st.session_state["m16_misery_filter"] = "Emerging"
        elif filt_all or "m16_misery_filter" not in st.session_state:
                st.session_state["m16_misery_filter"] = "All"
        flt = st.session_state.get("m16_misery_filter", "All")
        use = df if flt == "All" else df[df["Group"] == flt]
        fig = go.Figure()
        fig.add_trace(go.Bar(x=use["Country"], y=use["Classic"], name="Classic", marker_color=V16_BLUE, hovertemplate="%{x}<br>Classic %{y:.1f}<extra></extra>"))
        fig.add_trace(go.Bar(x=use["Country"], y=use["Housing burden"], name="Housing burden", marker_color="#496dc7", hovertemplate="%{x}<br>Housing burden %{y:.1f}<extra></extra>"))
        _v16_fig(fig, "Classic vs Neo-Misery", height=520)
        fig.update_layout(barmode="stack")
        st.plotly_chart(fig, use_container_width=True, config=_v16_plot_config())
        _v16_html_table(use, max_rows=20)
        _v16_section("Country charts", "One chart per economy can be expanded into line-history when real time series are connected.")
        c1, c2 = st.columns(2, gap="large")
        for col, (_, r) in zip([c1, c2], use.head(2).iterrows()):
                with col:
                        dates = pd.date_range("2019-01-01", periods=90, freq="ME")
                        classic = r["Classic"] + 1.2 * np.sin(np.linspace(0, 6, len(dates)))
                        neo = classic + r["Housing burden"] + .8 * np.cos(np.linspace(0, 4, len(dates)))
                        fig2 = go.Figure()
                        fig2.add_trace(go.Scatter(x=dates, y=classic, name="Classic: u/e + inflation", line=dict(color=V16_BLUE, width=3)))
                        fig2.add_trace(go.Scatter(x=dates, y=neo, name="Neo-Misery: + housing", line=dict(color=V16_RUST, width=3)))
                        _v16_fig(fig2, f"{r['Country']} — misery index", height=360, x_is_date=True)
                        st.plotly_chart(fig2, use_container_width=True, config=_v16_plot_config())


def _v16_render_payrolls(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_hero("Labor Market Observatory", "US Payrolls & Labor Market", "NFP forecast lab, model disagreement, payroll levels, unemployment, wages and labour-market chart book.")
        _v16_metric_cards([
                ("Next NFP forecast", "99k", "median of models"),
                ("Unemployment", "4.2%", "latest print"),
                ("Latest payroll change", "57k", "monthly"),
                ("Avg hourly earnings YoY", "3.52%", "wage pressure"),
        ])
        models = pd.DataFrame([
                ("Street Consensus", 110, "survey"), ("Model Ensemble", 99, "median"), ("Naive AR", 62, "econometric"), ("SARIMAX", 44, "econometric"),
                ("VAR", 100, "econometric"), ("Unobserved Components", 90, "econometric"), ("MIDAS", 110, "econometric"),
                ("ElasticNet", 401, "ML"), ("Random Forest", 76, "ML"), ("XGBoost", 97, "ML"), ("LightGBM + Regime", 302, "ML"), ("MLP", 250, "ML"),
        ], columns=["Model", "Jul 2026 NFP Forecast", "Family"])
        c1, c2 = st.columns([.9, 1.1], gap="large")
        with c1:
                _v16_html_table(models, max_rows=20)
        with c2:
                m = models.sort_values("Jul 2026 NFP Forecast")
                fig = go.Figure(go.Bar(x=m["Model"], y=m["Jul 2026 NFP Forecast"], marker_color=V16_BLUE, text=m["Jul 2026 NFP Forecast"], textposition="outside"))
                fig.add_hline(y=99, line_dash="dot", line_color=V16_GOLD, annotation_text="Median 99k")
                _v16_fig(fig, "Payroll model disagreement", height=420)
                fig.update_xaxes(tickangle=-35)
                st.plotly_chart(fig, use_container_width=True, config=_v16_plot_config())
        dates = pd.date_range("2017-01-01", periods=118, freq="ME")
        x = np.linspace(0, 1, len(dates))
        base = 100 + 29 * x + 2*np.sin(np.linspace(0,8,len(dates)))
        private = base - 2 + 1.5*np.sin(np.linspace(.5,7.8,len(dates)))
        goods = 92 + 2*np.sin(np.linspace(0,14,len(dates))) - 6*x
        services = 100 + 31*x + 1.8*np.cos(np.linspace(.7,9,len(dates)))
        fig = go.Figure()
        for name, y, color in [("US Nonfarm Payrolls", base, V16_BLUE), ("US Private Payrolls", private, "#3d86ff"), ("US Goods-Producing Employment", goods, "#ffb5b5"), ("US Service-Providing Employment", services, "#ff4f55")]:
                fig.add_trace(go.Scatter(x=dates, y=y, name=name, line=dict(color=color, width=2.5)))
        _v16_fig(fig, "Payroll levels — total/private/goods/services", height=480, x_is_date=True)
        st.plotly_chart(fig, use_container_width=True, config=_v16_plot_config())


def _v16_render_outlook() -> None:
        _v16_hero("Economic Outlook", "Consensus Forecasts — GDP & Inflation", "G10 outlook table synthesised as a structural placeholder. Replace with IMF WEO, OECD, central-bank projections or paid consensus feeds when connected.")
        countries = ["United States", "Canada", "United Kingdom", "Eurozone", "Japan", "Sweden", "Switzerland", "Australia", "New Zealand", "Norway"]
        periods = ["Q4 2026", "Full Year 2026", "Full Year 2027", "Full Year 2028"]
        gdp = pd.DataFrame({"Time Period": periods})
        inf = pd.DataFrame({"Time Period": periods})
        for i, c in enumerate(countries):
                gdp[c] = [f"{2.1 - .08*i + j*.05:.1f}%" for j in [0, -1, 0, -1]]
                inf[c] = [f"{2.3 + .02*i - j*.1:.1f}%" for j in [0, -1, -2, -3]]
        _v16_section("Real GDP Growth", "Annual average, % unless noted.")
        _v16_html_table(gdp, max_rows=10)
        _v16_section("Inflation", "Annual average, % — provider-ready consensus view.")
        _v16_html_table(inf, max_rows=10)
        _v16_html('<div class="m16-warning">Key observations: US growth remains above several G10 peers; inflation gradually converges toward targets; Switzerland/Japan remain lower-inflation outliers; Australia/NZ remain stickier.</div>')


def _v16_render_quality(pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame) -> None:
        _v16_hero("Sources / Quality", "Provider Roadmap & Data Quality", "This page separates public/structural proxies from live-provider requirements. It is designed to avoid confusing structural placeholders with executable macro signals.")
        rows = [
                {"Layer": "Central-bank cards", "Current": "Structural + public FRED/OECD where available", "Needed for parity": "Official policy calendars, balance sheets, speech feeds"},
                {"Layer": "Taylor Rule", "Current": "Structural G10 table", "Needed for parity": "Output gaps, CPI targets, consensus forecast paths"},
                {"Layer": "Inflation", "Current": "US FRED + G10 fallbacks", "Needed for parity": "OECD/Eurostat/ONS/NBS/National CPI APIs"},
                {"Layer": "High Speed", "Current": "Coverage model + structural trends", "Needed for parity": "ONS faster indicators, ENTSO-E, TSA, EIA, mobility, card, traffic feeds"},
                {"Layer": "China", "Current": "Structural pairs", "Needed for parity": "NBS, PBoC, SAFE, BIS, Caixin, market feeds"},
                {"Layer": "Misery", "Current": "Classic + housing burden model", "Needed for parity": "Country CPI/unemployment/history + housing affordability series"},
        ]
        _v16_html_table(pd.DataFrame(rows), max_rows=20)
        if isinstance(indicator_df, pd.DataFrame) and not indicator_df.empty:
                _v16_section("Loaded public macro indicators")
                _v16_html_table(indicator_df.head(40), max_rows=40)


def _v16_render_page(page: str, selected_code: str, pack: Dict[str, pd.DataFrame], proxy_pack: Dict[str, pd.DataFrame], indicator_df: pd.DataFrame, bank_df: pd.DataFrame) -> None:
        page = _v12_normalize_page(page)
        route = st.session_state.get("macro_v12_route", "overview")
        if page == "central-banks":
                if route == "bank":
                        _v16_render_bank_detail(bank_df, selected_code, pack)
                else:
                        _v16_render_central_banks(bank_df, selected_code, pack)
        elif page == "inflation":
                _v16_render_inflation(pack, bank_df)
        elif page == "taylor-rule":
                _v16_render_taylor(bank_df, selected_code)
        elif page == "high-speed":
                _v16_render_high_speed()
        elif page == "china":
                _v16_render_china()
        elif page == "misery-indices":
                _v16_render_misery()
        elif page == "us-payrolls":
                _v16_render_payrolls(pack)
        elif page == "consensus-forecasts":
                _v16_render_outlook()
        else:
                _v16_render_quality(pack, proxy_pack, indicator_df)


