def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
        """V16 renderer: dark, robust, interactive macro desk; session_state navigation only."""
        _v12_css()
        _v13_css()
        _v14_css()
        _v15_css()
        _v16_css()
        _v12_init_state()

        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
        selected_code = str(st.session_state.get("macro_v12_bank", "FED")).upper().strip()
        if selected_code not in G10_BANKS_V6:
                selected_code = "FED"
                st.session_state["macro_v12_bank"] = selected_code
        if page != "central-banks":
                st.session_state["macro_v12_route"] = "overview"

        with st.spinner("Loading macro desk data…"):
                try:
                        pack = build_macro_pack_cached("2000-01-01", True)
                except Exception:
                        pack = {}
                try:
                        proxy_pack = fetch_market_proxy_pack("2y")
                except Exception:
                        proxy_pack = {}
                try:
                        indicator_df = compute_indicator_table(pack)
                except Exception:
                        indicator_df = pd.DataFrame()
                bank_df = _v16_bank_df(pack)

        _v16_html('<div class="m16-shell">')
        try:
                _v16_topbar(page)
                _v16_render_page(page, selected_code, pack, proxy_pack, indicator_df, bank_df)
                _v16_html('<div class="m16-footer">Macro V16 · deep RoboMacro-like dark data workstation. Navigation remains Streamlit session_state only; all internal links are disabled; charts use Plotly with hover/range controls; structural datasets are clearly marked until live provider feeds are connected.</div>')
        finally:
                _v16_html('</div>')

