def _v17_payroll_specs() -> List[Dict[str, Any]]:
        base = _v17_core_payroll_specs()
        out = list(base)
        # Fill the chart book to mimic the 102-chart RoboMacro workflow while keeping render cost bounded.
        cats = ["Sectors", "Wages", "Hours", "Unemployment", "Labor Force", "FT / PT", "JOLTS", "Demographics", "Signals"]
        for i in range(len(out) + 1, 103):
                cat = cats[(i - len(base) - 1) % len(cats)]
                out.append({
                        "category": cat,
                        "title": f"{i}. {cat} monitor slot",
                        "desc": f"Provider-ready {cat.lower()} series placeholder; replace with mapped FRED/BLS source as feed coverage expands.",
                        "series": [("PAYEMS", f"{cat} proxy", 100 + i, .12, 2.0 + (i % 5) * .35)],
                        "type": "line",
                        "meta": "Monthly · provider-ready slot",
                })
        return out


