        _v16_html(f"""
        <div class='m17-chart-card'>
            <div class='sector'>{_v16_esc(spec.get('category',''))}</div>
            <div class='title'>{_v16_esc(spec.get('title',''))}</div>
            <div class='desc'>{_v16_esc(spec.get('desc',''))}</div>
        """)
        fig = _v17_chart_from_specs(pack, spec, view=view, height=245)
        st.plotly_chart(fig, use_container_width=True, config=_v17_plot_config())
        _v16_html(f"""
            <div class='meta'><span>Frequency: monthly</span><span>Series: {len(spec.get('series', []))}</span><span>{_v16_esc(spec.get('meta','FRED/BLS'))}</span></div>
        </div>
        """)


