def _v17_model_cards(models: pd.DataFrame, family: str) -> None:
        sub = models[models["Family"].str.lower().eq(family.lower())].copy()
        if sub.empty:
                return
        cols = st.columns(min(5, len(sub)), gap="medium")
        for col, (_, r) in zip(cols, sub.iterrows()):
                with col:
                        acc = r.get("Accuracy", "")
                        low, high = r.get("Range", ""), r.get("Range", "")
                        _v16_html(f"""
                        <div class='m17-model-card'>
                            <span class='tag'>{_v16_esc(r.get('Tag',''))}</span>
                            <div class='name'>{_v16_esc(r.get('Model',''))}</div>
                            <div style='font-size:.65rem;text-transform:uppercase;letter-spacing:.12em;color:#9faebd;font-weight:900;'>NFP forecast</div>
                            <div class='forecast'>{int(r.get('Forecast', 0))}k</div>
                            <div class='range'>{_v16_esc(str(r.get('Range','')))}</div>
                            <div class='acc'><span>Dir. accuracy</span><b>{_v16_esc(str(acc))}</b></div>
                        </div>
                        """)


def _v17_render_central_banks(bank_df: pd.DataFrame, selected_code: str, pack: Dict[str, pd.DataFrame]) -> None:
        _v16_hero("Global Monetary Policy Observatory", "Hawk/Dove Monitor — G10 Central Banks", "Desk-style policy dashboard: G10 policy cards, hawk/dove composite, policy-rate ranking, QE/QT impulse and speech tape. Cards route to bank-level workstations without URL redirects.")
        _v16_render_bank_cards(bank_df, selected_code)

        _v16_section("Policy stance dashboard", "Full-width chart stack. Legends are clickable, hover gives exact values, and range buttons are available on time-series charts.")
        c0, c1, c2 = st.columns([.72, .78, 1.20], gap="large")
        with c0:
                mode = st.selectbox("Hawk/Dove display", ["Level", "3m/3m Change"], index=0, key="m17_hd_mode")
        with c1:
                focus = st.selectbox("Focus bank", V16_BANK_ORDER, index=V16_BANK_ORDER.index(selected_code) if selected_code in V16_BANK_ORDER else 0, key="m17_focus_bank")
        with c2:
                _v16_html("<div class='m17-desk-note'>Layout corrigé : le composite, le ranking et le QE/QT ne sont plus compressés côte-à-côte. Chaque bloc devient lisible et interactif.</div>")

        fig = _v16_plot_hawk_dove(bank_df, focus, mode=mode, height=560)
        _v17_fig(fig, "Hawk/Dove Composite", height=560, x_is_date=True)
        st.plotly_chart(fig, use_container_width=True, config=_v17_plot_config())

        fig = _v16_plot_rates_ranked(bank_df, height=520)
        _v17_fig(fig, "Policy Rates — Ranked", height=520, legend_bottom=False)
        fig.update_layout(margin=dict(l=105, r=75, t=58, b=58), showlegend=False)
        st.plotly_chart(fig, use_container_width=True, config=_v17_plot_config())

        fig = _v16_policy_history_chart(focus, bank_df, height=560)
        _v17_fig(fig, f"{G10_BANKS_V6.get(focus,{}).get('name', focus)} — Policy Rate & Balance Sheet", height=560, x_is_date=True)
        st.plotly_chart(fig, use_container_width=True, config=_v17_plot_config())

        _v16_section("Recent Speeches", "Hawk/dove NLP tape. Structural rows are used until official speech scraping/NLP feeds are connected.")
        _v16_speeches_list(None, max_rows=12)


def _v17_render_payrolls(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_html("""
        <div class='m17-payroll-hero'>
            <div class='k'>Labor Market Observatory</div>
            <div class='t'>US Payrolls & Labor Market</div>
            <div class='s'>Chart book, payroll forecast lab, model track record, wages, hours, unemployment, labor force, JOLTS and recession-signal monitors. This keeps the dark terminal shell while moving much closer to the dense RoboMacro payroll workflow.</div>
        </div>
        """)

        # category navigation
        if "m17_payroll_category" not in st.session_state:
                st.session_state["m17_payroll_category"] = "All"
        if "m17_payroll_view" not in st.session_state:
                st.session_state["m17_payroll_view"] = "Levels"
        if "m17_payroll_smooth" not in st.session_state:
                st.session_state["m17_payroll_smooth"] = "Raw"
        if "m17_payroll_page" not in st.session_state:
                st.session_state["m17_payroll_page"] = 1

        _v16_html("<div class='m17-filter-title'>Chart book filters</div>")
        for group in [V17_PAYROLL_CATEGORIES[:6], V17_PAYROLL_CATEGORIES[6:]]:
                cols = st.columns(len(group), gap="small")
                for col, cat in zip(cols, group):
                        with col:
                                label = ("● " if st.session_state["m17_payroll_category"] == cat else "") + cat
                                if st.button(label, key=f"m17_cat_{cat}", use_container_width=True):
                                        st.session_state["m17_payroll_category"] = cat
                                        st.session_state["m17_payroll_page"] = 1
                                        _v16_button_rerun()
        c1, c2, c3 = st.columns([.55, .65, 1.4], gap="large")
        with c1:
                st.session_state["m17_payroll_view"] = st.radio("View", V17_PAYROLL_VIEW, horizontal=True, key="m17_payroll_view_radio")
        with c2:
                st.session_state["m17_payroll_smooth"] = st.radio("Smoothing", V17_PAYROLL_SMOOTH, horizontal=True, key="m17_payroll_smooth_radio")
        with c3:
                st.caption("Cache: structural/FRED where available · chart panels use Plotly hover, zoom and export · source labels remain explicit.")

        _v16_metric_cards([
                ("Nonfarm payrolls", "99k", "median forecast · 80% range 61k → 312k"),
                ("Unemployment rate", "4.2%", "80% range 4.1% → 5.4%"),
                ("Part-time workers", "4692k", "underemployment pressure"),
                ("Avg hourly earnings YoY", "3.59%", "80% range 3.38% → 3.80%"),
        ])

        specs = _v17_payroll_specs()
        cat = st.session_state["m17_payroll_category"]
        if cat != "All":
                specs = [s for s in specs if s.get("category") == cat]
        per_page = 10
        pages = max(1, int(np.ceil(len(specs) / per_page)))
        st.session_state["m17_payroll_page"] = min(max(1, int(st.session_state.get("m17_payroll_page", 1))), pages)
        page = st.session_state["m17_payroll_page"]
        start, end = (page - 1) * per_page, min(page * per_page, len(specs))
        _v16_html(f"<div class='m17-countbar'><div><b>Showing {start+1}–{end} of {len(specs)} chart slots</b></div><div>Page {page} of {pages}</div></div>")

        # chart book grid
        visible = specs[start:end]
        for i in range(0, len(visible), 2):
                cols = st.columns(2, gap="large")
                for col, spec in zip(cols, visible[i:i+2]):
                        with col:
                                _v17_chart_card(pack, spec, st.session_state["m17_payroll_view"])

        nav1, nav2, nav3 = st.columns([.22, .22, 1])
        with nav1:
                if st.button("← Previous", key="m17_payroll_prev", use_container_width=True, disabled=page <= 1):
                        st.session_state["m17_payroll_page"] = max(1, page - 1)
                        _v16_button_rerun()
