def _v18_model_deep_dive(models: pd.DataFrame) -> None:
        tags = models["Tag"].tolist()
        selected = st.selectbox("Model deep dive", tags, index=0, format_func=lambda t: f"{t} · {models.loc[models['Tag']==t,'Model'].iloc[0]}", key="m18_model_deep_dive")
        row = models.loc[models["Tag"] == selected].iloc[0]
        _v16_html(f"""
        <div class='m18-model-detail'>
            <div class='name'>{_v16_esc(row['Tag'])} · {_v16_esc(row['Model'])}</div>
            <div class='sub'>Structural model diagnostics. Replace the fallback history with persisted genuine out-of-sample predictions when the forecast pipeline is connected.</div>
            <div class='grid'>
                <div class='cell'><div class='k'>Next NFP</div><div class='v'>{int(row['Forecast']):+d}k</div></div>
                <div class='cell'><div class='k'>Forecast Range</div><div class='v'>{_v16_esc(row['Range'])}</div></div>
                <div class='cell'><div class='k'>Directional Accuracy</div><div class='v'>{_v16_esc(row['Accuracy'])}</div></div>
            </div>
        </div>
        """)
        dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=24, freq="ME")
        seed = sum(ord(c) for c in selected)
        actual = 145 + 70 * np.sin(np.arange(24) / 3.1) + 25 * np.cos(np.arange(24) / 5.4)
        forecast = actual + (seed % 41 - 20) + 35 * np.sin(np.arange(24) / 2.7 + seed / 13)
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=dates, y=actual, name="Actual NFP", mode="lines+markers", line=dict(color="#d6bd65", width=2.7)))
        fig.add_trace(go.Scatter(x=dates, y=forecast, name=f"{selected} forecast", mode="lines+markers", line=dict(color="#79c8ff", width=2.4)))
        fig.add_trace(go.Bar(x=dates, y=forecast-actual, name="Forecast error", yaxis="y2", marker_color=np.where((forecast-actual)>=0,"rgba(90,150,190,.48)","rgba(189,96,72,.52)")))
        _v18_fig(fig, f"{selected} — Out-of-Sample Forecast History", height=430, x_is_date=True)
        fig.update_layout(yaxis=dict(title="NFP change, k"), yaxis2=dict(title="Error, k", overlaying="y", side="right", showgrid=False))
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"{selected.lower()}_forecast_history"))


def _v18_render_payroll_charts(pack: Dict[str, pd.DataFrame]) -> None:
        specs = _v18_payroll_specs()
