@st.cache_data(ttl=21600, show_spinner=False)
def _v19_load_policy_pack(start_date: str = "1990-01-01") -> Dict[str, pd.DataFrame]:
        ids = {"DFF", "FEDFUNDS", "WALCL"}
        for spec in G10_BANKS_V6.values():
                ids.update(spec.get("series", []))
        try:
                return load_macro_fred_pack(tuple(sorted(ids)), start_date=start_date)
        except Exception:
                return {}


def _v19_merge_pack(base: Dict[str, pd.DataFrame], extra: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
        out = dict(base or {})
        for key, value in (extra or {}).items():
                if isinstance(value, pd.DataFrame) and not value.empty:
                        out[key] = value
                elif key not in out:
                        out[key] = value
        return out


def _v19_rate_series(pack: Dict[str, pd.DataFrame], code: str) -> Tuple[pd.DataFrame, str, Optional[pd.Timestamp]]:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6[code]
        official = float(spec.get("fallback_rate", 0.0))
        chosen = "Current public snapshot"
        raw = pd.DataFrame()
        chosen_sid = None
        for sid in spec.get("series", []):
                df = _v18_clean_series((pack or {}).get(sid, pd.DataFrame()))
                if not df.empty:
                        raw = df
                        chosen_sid = sid
                        break
        if raw.empty:
                # Step-like structural fallback, used only when the public series cannot
                # be retrieved. It is anchored to the current official snapshot.
                dates = pd.date_range("2016-01-31", pd.Timestamp.today().normalize() + pd.offsets.MonthEnd(0), freq="ME")
                n = len(dates)
                turning = np.linspace(0, 1, n)
                path = official + 0.4 * np.sin(turning * 3.2 * np.pi) - 0.25 * np.sin(turning * 7.1 * np.pi)
                path = np.round((path - path[-1] + official) * 4) / 4
                out = pd.DataFrame({"date": dates, "value": np.clip(path, -1.0, 12.0)})
                return out, chosen, None
        out = raw.set_index("date")["value"].resample("ME").last().ffill().dropna().reset_index()
        last_date = pd.to_datetime(out["date"].iloc[-1]) if not out.empty else None
        current_month = pd.Timestamp.today().normalize() + pd.offsets.MonthEnd(0)
        append_anchor = out.empty or last_date is None or last_date < current_month or abs(float(out["value"].iloc[-1]) - official) > 0.015
        if append_anchor:
                out = pd.concat([out, pd.DataFrame({"date": [current_month], "value": [official]})], ignore_index=True)
                out = out.sort_values("date").drop_duplicates("date", keep="last")
                chosen = f"FRED {chosen_sid} + current snapshot"
        else:
                chosen = f"FRED {chosen_sid}"
        return out.reset_index(drop=True), chosen, last_date


def _v19_bank_df(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows = []
        for code in V16_BANK_ORDER:
                spec = G10_BANKS_V6[code]
                rate_df, source, last_date = _v19_rate_series(pack, code)
                latest = float(spec.get("fallback_rate", rate_df["value"].iloc[-1] if not rate_df.empty else 0.0))
                rows.append({
                        "Code": code,
                        "Central Bank": spec.get("name", code),
                        "Country": spec.get("country", ""),
                        "Currency": spec.get("ccy", ""),
                        "Policy Rate": latest,
                        "Hawk/Dove": float(spec.get("fallback_hawk", 0.0)),
                        "Stance": spec.get("status", "HOLD"),
                        "Members": int(spec.get("members", 0)),
                        "Meetings": spec.get("meetings", ""),
                        "Target": float(spec.get("target", 2.0)),
                        "Policy Source": source,
                        "Last Public Observation": last_date,
                })
        return pd.DataFrame(rows)


def _v19_xml_local(tag: str) -> str:
        return str(tag or "").split("}")[-1].lower()


def _v19_xml_text(node, names: Iterable[str]) -> str:
        wanted = {str(x).lower() for x in names}
        for child in node.iter():
                if _v19_xml_local(child.tag) in wanted and child.text:
                        return str(child.text).strip()
        return ""


def _v19_parse_date(value: str) -> Optional[pd.Timestamp]:
        value = str(value or "").strip()
        if not value:
                return None
        try:
                dt = _v19_parse_rfc_date(value)
                if dt.tzinfo is not None:
                        dt = dt.astimezone(_v19_timezone.utc).replace(tzinfo=None)
                return pd.Timestamp(dt).normalize()
        except Exception:
                pass
        try:
                return pd.to_datetime(value, errors="coerce", utc=True).tz_convert(None).normalize()
        except Exception:
                return None


def _v19_clean_text(value: str) -> str:
        txt = _v19_html_lib.unescape(str(value or ""))
        txt = _v19_re.sub(r"<[^>]+>", " ", txt)
        txt = _v19_re.sub(r"\s+", " ", txt).strip()
        return txt


def _v19_classify_bank(text: str, forced: Optional[str] = None) -> Optional[str]:
        if forced in G10_BANKS_V6:
                return forced
        low = _v19_clean_text(text).lower()
        for token, code in _V19_SPEAKER_BANK.items():
                if token in low:
                        return code
        for code, patterns in _V19_BANK_PATTERNS.items():
                if any(p in low for p in patterns):
                        return code
        return None


def _v19_extract_speaker(title: str, description: str, code: str) -> str:
        title = _v19_clean_text(title)
        desc = _v19_clean_text(description)
        patterns = [
                r"^(?:speech|remarks|testimony)\s+by\s+([^:–—-]+)",
                r"^([^:]{3,60}):\s+",
                r"^([^–—]{3,60})\s+[–—]\s+",
        ]
        for source in [title, desc]:
                for pattern in patterns:
                        m = _v19_re.search(pattern, source, flags=_v19_re.I)
                        if m:
                                name = m.group(1).strip(" -–—:")
                                if 2 <= len(name.split()) <= 8:
                                        return name
        return G10_BANKS_V6.get(code, {}).get("name", code)


def _v19_score_text(title: str, description: str) -> float:
        text = f"{title} {description}".lower()
        score = 0.0
        for phrase, weight in _V19_HAWK_WORDS.items():
                score += text.count(phrase) * weight
        for phrase, weight in _V19_DOVE_WORDS.items():
                score += text.count(phrase) * weight
        return float(np.clip(np.tanh(score * 1.45), -1.0, 1.0))


def _v19_parse_rss(payload: bytes, source: str, forced_bank: Optional[str] = None) -> List[Dict[str, Any]]:
        rows: List[Dict[str, Any]] = []
        try:
                root = _v19_ET.fromstring(payload)
        except Exception:
                return rows
        entries = [n for n in root.iter() if _v19_xml_local(n.tag) in {"item", "entry"}]
        for entry in entries:
                title = _v19_xml_text(entry, ["title"])
                description = _v19_xml_text(entry, ["description", "summary", "content"])
                link = _v19_xml_text(entry, ["link", "guid"])
                if not link:
                        for child in entry.iter():
                                if _v19_xml_local(child.tag) == "link" and child.attrib.get("href"):
                                        link = child.attrib.get("href", "")
                                        break
                date_raw = _v19_xml_text(entry, ["pubdate", "published", "updated", "date"])
                date = _v19_parse_date(date_raw)
                combined = f"{title} {description}"
                code = _v19_classify_bank(combined, forced=forced_bank)
                if code not in G10_BANKS_V6 or not title:
                        continue
                speaker = _v19_extract_speaker(title, description, code)
                rows.append({
                        "Date": date if date is not None else pd.Timestamp.today().normalize(),
                        "Bank": code,
                        "Speaker": speaker,
                        "Title": _v19_clean_text(title),
                        "Score": _v19_score_text(title, description),
                        "Source": source,
                        "URL": str(link or ""),
                        "Status": "Live RSS",
                })
        return rows


@st.cache_data(ttl=3600, show_spinner=False)
def _v19_live_speeches() -> pd.DataFrame:
        rows: List[Dict[str, Any]] = []
        if REQUESTS_AVAILABLE and requests is not None:
                headers = {"User-Agent": "Mozilla/5.0 QuantTerminal/1.0 (+public macro research)"}
                for source, url in V19_RSS_FEEDS.items():
                        try:
                                response = requests.get(url, timeout=14, headers=headers)
                                if response.ok and response.content:
                                        forced = source if source in {"FED", "ECB", "BOE"} else None
                                        rows.extend(_v19_parse_rss(response.content, source, forced_bank=forced))
                        except Exception:
                                continue
        live = pd.DataFrame(rows)
        fallback = pd.DataFrame([
                {"Date": pd.Timestamp(d), "Bank": b, "Speaker": s, "Title": t, "Score": float(sc), "Source": "Public snapshot", "URL": "", "Status": "Fallback"}
                for d, b, s, t, sc in V19_SPEECH_FALLBACK
        ])
        combined = pd.concat([live, fallback], ignore_index=True, sort=False)
        if combined.empty:
                return fallback
        combined["Date"] = pd.to_datetime(combined["Date"], errors="coerce")
        combined["Score"] = pd.to_numeric(combined["Score"], errors="coerce").fillna(0.0).clip(-1, 1)
        combined["_key"] = (
                combined["Bank"].astype(str) + "|" + combined["Title"].astype(str).str.lower().str.replace(r"\W+", "", regex=True).str[:120]
        )
        combined = combined.sort_values(["Date", "Status"], ascending=[False, True]).drop_duplicates("_key", keep="first")
        return combined.drop(columns=["_key"]).head(80).reset_index(drop=True)


def _v19_speech_tape() -> pd.DataFrame:
        try:
                return _v19_live_speeches()
        except Exception:
                return pd.DataFrame([
                        {"Date": pd.Timestamp(d), "Bank": b, "Speaker": s, "Title": t, "Score": float(sc), "Source": "Public snapshot", "URL": "", "Status": "Fallback"}
                        for d, b, s, t, sc in V19_SPEECH_FALLBACK
                ])


def _v19_speech_monthly(tape: pd.DataFrame, code: str, index: pd.DatetimeIndex) -> pd.Series:
        if not isinstance(tape, pd.DataFrame) or tape.empty:
                return pd.Series(0.0, index=index)
        sub = tape[tape["Bank"].astype(str).eq(code)].copy()
        if sub.empty:
                return pd.Series(0.0, index=index)
        sub["Date"] = pd.to_datetime(sub["Date"], errors="coerce")
        sub["Score"] = pd.to_numeric(sub["Score"], errors="coerce")
        monthly = sub.dropna(subset=["Date", "Score"]).set_index("Date")["Score"].resample("ME").mean()
        monthly = monthly.reindex(index)
        # A speech score decays rather than remaining permanently active.
        signal = monthly.fillna(0.0).ewm(span=4, adjust=False).mean()
        return signal.clip(-1, 1)


def _v19_hawk_history(pack: Dict[str, pd.DataFrame], tape: pd.DataFrame, mode: str) -> Tuple[pd.DataFrame, Dict[str, str]]:
        common = pd.date_range("2016-01-31", pd.Timestamp.today().normalize() + pd.offsets.MonthEnd(0), freq="ME")
        frames: List[pd.DataFrame] = []
        source_map: Dict[str, str] = {}
        for code in V16_BANK_ORDER:
                rate_df, source, _ = _v19_rate_series(pack, code)
                rate = rate_df.set_index("date")["value"].reindex(common).ffill().bfill()
                d1 = rate.diff().fillna(0.0)
                d3 = rate.diff(3).fillna(0.0)
                d12 = rate.diff(12).fillna(0.0)
                accel = d1.diff().fillna(0.0)
                target = float(G10_BANKS_V6[code].get("target", 2.0))
                speech = _v19_speech_monthly(tape, code, common)
                score = (
                        .38 * np.tanh(d1 / .18)
                        + .23 * np.tanh(d3 / .70)
                        + .15 * np.tanh(d12 / 1.45)
                        + .10 * np.tanh(accel / .16)
                        + .08 * np.tanh((rate - target) / 2.0)
                        + .22 * speech
                )
                # Keep an event-like profile: modest EWM smoothing, not a decorative sine.
                score = pd.Series(score, index=common).ewm(span=3, adjust=False).mean().clip(-1, 1)
                if mode == "3m/3m Change":
                        recent = score.rolling(3, min_periods=1).mean()
                        score = (recent - recent.shift(3)).fillna(0.0).clip(-1, 1)
                frames.append(pd.DataFrame({"date": common, "score": score.values, "code": code}))
                source_map[code] = source
        return pd.concat(frames, ignore_index=True), source_map


def _v19_plot_hawk_dove(pack: Dict[str, pd.DataFrame], bank_df: pd.DataFrame, focus: str, mode: str, tape: pd.DataFrame) -> go.Figure:
        history, _ = _v19_hawk_history(pack, tape, mode)
        fig = go.Figure()
        for idx, code in enumerate(V16_BANK_ORDER):
                sub = history[history["code"].eq(code)]
                spec = G10_BANKS_V6[code]
                is_focus = code == focus
                fig.add_trace(go.Scatter(
                        x=sub["date"], y=sub["score"], mode="lines",
                        name=f"{spec.get('flag','')} {code}",
                        line=dict(color=spec.get("colour", V16_PALETTE[idx % len(V16_PALETTE)]), width=3.4 if is_focus else 2.0),
                        opacity=1.0 if is_focus else .78,
                        hovertemplate="%{fullData.name}<br>%{x|%b %Y}<br>Public-data stance proxy %{y:+.3f}<extra></extra>",
                ))
        # Speech-event markers for the focus bank, matching the event-driven nature
        # of the original composite without claiming proprietary NLP parity.
        focus_events = tape[tape["Bank"].astype(str).eq(focus)].copy() if isinstance(tape, pd.DataFrame) else pd.DataFrame()
        if not focus_events.empty:
                focus_line = history[history["code"].eq(focus)].set_index("date")["score"]
                event_dates = pd.to_datetime(focus_events["Date"], errors="coerce") + pd.offsets.MonthEnd(0)
                event_y = focus_line.reindex(event_dates).ffill().bfill().values
                fig.add_trace(go.Scatter(
                        x=event_dates, y=event_y, mode="markers", name=f"{focus} speeches",
                        marker=dict(size=7, color="#f4f1e7", line=dict(color=G10_BANKS_V6[focus].get("colour", V16_BLUE), width=2)),
                        customdata=np.stack([focus_events["Speaker"].astype(str), focus_events["Title"].astype(str), focus_events["Score"].astype(float)], axis=-1),
                        hovertemplate="%{customdata[0]}<br>%{customdata[1]}<br>Speech proxy %{customdata[2]:+.2f}<extra></extra>",
                        showlegend=False,
                ))
        fig.add_hline(y=0, line_dash="dot", line_color="#d6bd65", annotation_text="Neutral", annotation_font_color="#d6bd65")
        _v18_fig(fig, "Hawk/Dove Composite", height=570, x_is_date=True)
        fig.update_yaxes(title="Dovish    ←    score    →    Hawkish", range=[-1, 1])
        fig.update_layout(legend=dict(orientation="h", y=-.19, x=0, itemclick="toggle", itemdoubleclick="toggleothers"))
        return fig


def _v19_render_speeches(tape: pd.DataFrame) -> None:
        _v16_html("<div class='m19-speech-head'><div><div class='t'>Recent Speeches</div><div class='s'>Official/BIS RSS where available; hourly cache; lexicon score is a transparent proxy, not proprietary NLP.</div></div></div>")
        c1, c2, c3 = st.columns([.65, .35, 1.2], gap="large")
        with c1:
                bank = st.selectbox("Speech bank", ["ALL"] + V16_BANK_ORDER, key="m19_speech_bank")
        with c2:
                rows = st.selectbox("Rows", [10, 20, 30], index=1, key="m19_speech_rows")
        with c3:
                if st.button("Refresh live speeches", key="m19_refresh_speeches", use_container_width=False):
                        try:
                                _v19_live_speeches.clear()
                        except Exception:
                                pass
                        _v16_button_rerun()
        use = tape.copy()
        if bank != "ALL":
                use = use[use["Bank"].astype(str).eq(bank)]
        use = use.sort_values("Date", ascending=False).head(int(rows))
        html_rows = []
        for _, row in use.iterrows():
                score = float(pd.to_numeric(row.get("Score"), errors="coerce") or 0.0)
                cls = "hawk" if score > .08 else "dove" if score < -.08 else "neutral"
                status = str(row.get("Status", "Fallback"))
                status_cls = "m19-source-live" if status == "Live RSS" else "m19-source-fallback"
                title = _v16_esc(str(row.get("Title", "")))
                url = str(row.get("URL", "") or "").strip()
                title_html = f"<a href='{_v16_esc(url)}' target='_blank' rel='noopener'>{title}</a>" if url.startswith("http") else title
                date = pd.to_datetime(row.get("Date"), errors="coerce")
                date_txt = date.strftime("%Y-%m-%d") if pd.notna(date) else "N/A"
                html_rows.append(
                        f"<tr><td>{date_txt}</td><td><span class='m16-badge gold'>{_v16_esc(str(row.get('Bank','')))}</span></td>"
                        f"<td>{_v16_esc(str(row.get('Speaker','')))}</td><td>{title_html}</td>"
                        f"<td><span class='m19-score {cls}'>{score:+.2f}</span></td><td class='{status_cls}'>{_v16_esc(status)}</td></tr>"
                )
        _v16_html(
                "<table class='m19-speech-table'><thead><tr><th>Date</th><th>CB</th><th>Speaker</th><th>Title</th><th>Score</th><th>Source</th></tr></thead><tbody>"
                + "".join(html_rows) + "</tbody></table>"
        )


def _v19_render_central_banks(bank_df: pd.DataFrame, selected_code: str, pack: Dict[str, pd.DataFrame]) -> None:
        policy_pack = _v19_merge_pack(pack, _v19_load_policy_pack("1990-01-01"))
        current_df = _v19_bank_df(policy_pack)
        tape = _v19_speech_tape()
        _v16_hero(
                "Global Monetary Policy Observatory", "Hawk/Dove Monitor — G10 Central Banks",
                "G10 policy cards, public policy-rate histories, an event/policy-backed Hawk/Dove proxy, QE/QT impulse and a live RSS speech tape. Bank cards retain zero-URL routing.",
        )
        _v16_render_bank_cards(current_df, selected_code)
        _v16_section("Policy stance dashboard", "Display and focus are the only controls. Bank visibility is managed directly from the Plotly legend below the composite.")
        c1, c2, c3 = st.columns([.60, .60, 1.35], gap="large")
        with c1:
                mode = st.selectbox("Hawk/Dove display", V18_BANK_DISPLAY_MODES, index=0, key="m19_hd_mode")
        with c2:
                focus = st.selectbox("Focus bank", V16_BANK_ORDER, index=V16_BANK_ORDER.index(selected_code) if selected_code in V16_BANK_ORDER else 0, key="m19_focus_bank")
        with c3:
                _v16_html("<div class='m19-controls-note'>Click a legend item to hide/show a bank; double-click to isolate it. The focus bank is emphasized and its speech events are marked. No duplicate bank selector or Solo Focus control.</div>")
        fig = _v19_plot_hawk_dove(policy_pack, current_df, focus, mode, tape)
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("hawk_dove_composite_v19"))
        fig = _v18_plot_rates_ranked(current_df)
        fig.update_layout(title=None, margin=dict(l=115, r=105, t=25, b=60), height=500)
        _v16_section("Policy Rates — Ranked", "Current public snapshots with full G10 coverage. Hover exposes the bank, stance and Hawk/Dove anchor.")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("policy_rates_ranked_v19"))
        with st.expander("Policy-rate data coverage and sources", expanded=False):
                status = current_df[["Code", "Central Bank", "Policy Rate", "Stance", "Policy Source", "Last Public Observation"]].copy()
                status["Current Snapshot"] = V19_POLICY_SNAPSHOT_DATE
                status["Last Public Observation"] = pd.to_datetime(status["Last Public Observation"], errors="coerce").dt.strftime("%Y-%m-%d").fillna("Snapshot only")
                st.dataframe(status, use_container_width=True, hide_index=True)
        history_fig, history_source = _v18_policy_history_chart(policy_pack, current_df, focus)
        history_fig.update_layout(title=None, height=575, margin=dict(l=70, r=70, t=25, b=82))
        _v16_section(f"{G10_BANKS_V6[focus].get('name', focus)} — Policy Rates & Balance Sheet", history_source)
        st.plotly_chart(history_fig, use_container_width=True, config=_v18_plot_config(f"{focus.lower()}_policy_balance_v19"))
        _v19_render_speeches(tape)


