def _v19_apply_transform(df: pd.DataFrame, transform: str, global_view: str, smoothing: str) -> pd.DataFrame:
        out = df.copy()
        s = pd.to_numeric(out["value"], errors="coerce")
        transform = str(transform or "level")
        if transform == "diff": s = s.diff()
        elif transform == "diff3_ann": s = s.diff(3) / 3.0 * 12.0
        elif transform == "diff6_ann": s = s.diff(6) / 6.0 * 12.0
        elif transform == "diff12": s = s.diff(12)
        elif transform == "diff_ma3": s = s.diff().rolling(3, min_periods=1).mean()
        elif transform == "yoy": s = s.pct_change(12) * 100.0
        elif transform == "yoy4": s = s.pct_change(4) * 100.0
        elif transform == "yoy52": s = s.pct_change(52) * 100.0
        elif transform == "pct3_ann": s = ((s / s.shift(3)) ** 4 - 1.0) * 100.0
        elif transform == "ma3": s = s.rolling(3, min_periods=1).mean()
        elif transform == "ma4": s = s.rolling(4, min_periods=1).mean()
        elif transform == "rebase":
                target = pd.Timestamp("2020-02-01")
                idx = (out["date"] - target).abs().idxmin() if not out.empty else None
                base = s.loc[idx] if idx is not None and idx in s.index else np.nan
                if pd.notna(base) and base != 0: s = s / base * 100.0
        elif transform == "zscore": s = _v18_rolling_zscore(s, 60)
        elif transform == "inv_zscore": s = -_v18_rolling_zscore(s, 60)
        elif global_view == "YoY %": s = s.pct_change(12) * 100.0
        out["value"] = s
        out = out.dropna(subset=["value"])
        if smoothing != "Raw" and not out.empty:
                try:
                        window = "7D" if smoothing == "7D" else "28D"
                        out = out.set_index("date")["value"].rolling(window, min_periods=1).mean().reset_index()
                except Exception:
                        pass
        return out


def _v19_build_payroll_chart(pack: Dict[str, pd.DataFrame], spec: Dict[str, Any], global_view: str, smoothing: str) -> Tuple[go.Figure, int, int, Optional[pd.Timestamp]]:
        fig = go.Figure()
        live_count = 0; total_count = 0; latest_dates: List[pd.Timestamp] = []
        colors = ["#79c8ff", "#e0644a", "#d6bd65", "#67c58c", "#a78bfa"]
        prepared: List[Tuple[Dict[str, Any], pd.DataFrame, bool]] = []
        for item in spec.get("series", []):
                df, live = _v18_get_series(pack, item["sid"], item["label"], item["base"], item["slope"], item["amp"])
                view = global_view if spec.get("views", True) else "Levels"
                df = _v19_apply_transform(df, item.get("transform", "level"), view, smoothing)
                prepared.append((item, df, live)); total_count += 1; live_count += int(live)
                if not df.empty: latest_dates.append(pd.to_datetime(df["date"].iloc[-1]))
        derived = spec.get("derived")
        if derived and len(prepared) >= 2:
                joined = pd.concat([p[1].set_index("date")["value"].rename(str(i)) for i, p in enumerate(prepared)], axis=1).dropna()
                if not joined.empty:
                        a, b = joined.iloc[:,0], joined.iloc[:,1]
                        if derived == "ratio": y = a.div(b.replace(0, np.nan)) * float(spec.get("derived_scale", 1.0))
                        elif derived == "spread": y = a - b
                        elif derived == "product": y = a * b / float(spec.get("derived_scale", 1.0) or 1.0)
                        else: y = a
                        y = y.replace([np.inf, -np.inf], np.nan).dropna()
                        fig.add_trace(go.Scatter(x=y.index, y=y.values, mode="lines", name=spec.get("derived_label", derived), line=dict(color=colors[0], width=2.6)))
        elif spec.get("derived") == "openings_unemployed" and len(prepared) >= 2:
                pass
        else:
                for idx, (item, df, _) in enumerate(prepared):
                        if df.empty: continue
                        color = colors[idx % len(colors)]; axis = item.get("axis", "y")
                        hover = f"{item['label']}<br>%{{x|%b %Y}}<br>%{{y:,.2f}}<extra></extra>"
                        if item.get("chart", "line") == "bar":
                                marker = np.where(df["value"] >= 0, "#d6bd65", "#bd6048") if item.get("transform") in {"diff", "diff3_ann", "diff6_ann", "diff12", "diff_ma3"} else color
                                fig.add_trace(go.Bar(x=df["date"], y=df["value"], name=item["label"], yaxis=axis, marker_color=marker, opacity=.88, hovertemplate=hover))
                        else:
                                fig.add_trace(go.Scatter(x=df["date"], y=df["value"], mode="lines", name=item["label"], yaxis=axis, line=dict(color=color, width=2.35), hovertemplate=hover))
        if spec.get("hline") is not None: fig.add_hline(y=float(spec["hline"]), line_dash="dot", line_color="#d6bd65", annotation_text=f"{spec['hline']:g}")
        if spec.get("zero"): fig.add_hline(y=0, line_color="rgba(220,230,240,.35)")
        _v18_fig(fig, "", height=315, x_is_date=True, legend_bottom=True)
        fig.update_layout(title=None, margin=dict(l=48, r=50, t=22, b=78))
        if spec.get("dual"):
                fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False, zeroline=False, tickfont=dict(color="#d0dae3")))
        return fig, live_count, total_count, max(latest_dates) if latest_dates else None


