# ------------------------------------------------------------------
# Payroll engine: robust fallback, full histories, frequency-aware ops
# ------------------------------------------------------------------

def _v20_fallback_series(
        sid: str,
        label: str,
        periods: int = 120,
        base: float = 100.0,
        slope: float = .10,
        amp: float = 2.0,
) -> pd.DataFrame:
        try:
                periods_i = max(2, int(periods))
        except Exception:
                periods_i = 120
        dates = pd.date_range(end=pd.Timestamp.today().normalize() + pd.offsets.MonthEnd(0), periods=periods_i, freq="ME")
        n = len(dates)
        seed = (sum(ord(c) for c in str(sid)) % 29) / 5.0
        t = np.arange(n, dtype=float)
        try:
                b = float(base); sl = float(slope); a = float(amp)
        except Exception:
                b, sl, a = 100.0, .10, 2.0
        vals = b + sl * t + a * np.sin(t / 8.5 + seed) + a * .35 * np.cos(t / 21.0 + seed)
        vals = np.asarray(vals, dtype=float).reshape(-1)
        if vals.size != n:
                vals = np.resize(vals, n)
        return pd.DataFrame({
                "date": pd.DatetimeIndex(dates),
                "value": vals,
                "series": np.repeat(str(label), n),
                "status": np.repeat("fallback", n),
        })


def _v20_get_series(
        pack: Dict[str, pd.DataFrame],
        sid: str,
        label: str,
        base: float,
        slope: float,
        amp: float,
        periods: int = 180,
) -> Tuple[pd.DataFrame, bool]:
        """Return the complete public history when present; never truncate Max."""
        try:
                df = _v18_clean_series((pack or {}).get(sid, pd.DataFrame()))
        except Exception:
                df = pd.DataFrame()
        if isinstance(df, pd.DataFrame) and not df.empty:
                out = df[["date", "value"]].copy()
                out["date"] = pd.to_datetime(out["date"], errors="coerce")
                out["value"] = pd.to_numeric(out["value"], errors="coerce")
                out = out.dropna(subset=["date", "value"]).sort_values("date").drop_duplicates("date", keep="last")
                if not out.empty:
                        out["series"] = str(label)
                        out["status"] = "live"
                        return out.reset_index(drop=True), True
        return _v20_fallback_series(sid, label, periods=max(120, int(periods or 180)), base=base, slope=slope, amp=amp), False


def _v20_frequency_name(df: pd.DataFrame, declared: str = "Monthly") -> str:
        declared = str(declared or "").strip().lower()
        if declared:
                if "day" in declared: return "daily"
                if "week" in declared: return "weekly"
                if "quarter" in declared: return "quarterly"
                if "annual" in declared or "year" in declared: return "annual"
                if "month" in declared: return "monthly"
        if not isinstance(df, pd.DataFrame) or len(df) < 3:
                return "monthly"
        d = pd.to_datetime(df["date"], errors="coerce").dropna().sort_values()
        if len(d) < 3:
                return "monthly"
        med = d.diff().dropna().dt.days.median()
        if med <= 2: return "daily"
        if med <= 10: return "weekly"
        if med <= 45: return "monthly"
        if med <= 120: return "quarterly"
        return "annual"


def _v20_yoy_lag(freq: str) -> int:
        return {"daily": 252, "weekly": 52, "monthly": 12, "quarterly": 4, "annual": 1}.get(freq, 12)


def _v20_smooth_periods(freq: str, smoothing: str) -> int:
        if smoothing == "Raw": return 1
        if smoothing == "7D":
                return {"daily": 7, "weekly": 4, "monthly": 3, "quarterly": 2, "annual": 1}.get(freq, 3)
        return {"daily": 28, "weekly": 13, "monthly": 6, "quarterly": 4, "annual": 2}.get(freq, 6)


def _v20_apply_transform(
        df: pd.DataFrame,
        transform: str,
        global_view: str,
        smoothing: str,
        frequency: str = "Monthly",
) -> pd.DataFrame:
        out = df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame(columns=["date", "value"])
        if out.empty:
                return out
        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["value"] = pd.to_numeric(out["value"], errors="coerce")
        out = out.dropna(subset=["date", "value"]).sort_values("date").drop_duplicates("date", keep="last")
        s = out["value"].astype(float)
        freq = _v20_frequency_name(out, frequency)
        transform = str(transform or "level")
        if transform == "diff": s = s.diff()
        elif transform == "diff3_ann": s = s.diff(3) / 3.0 * 12.0
        elif transform == "diff6_ann": s = s.diff(6) / 6.0 * 12.0
        elif transform == "diff12": s = s.diff(12)
        elif transform == "diff_ma3": s = s.diff().rolling(3, min_periods=1).mean()
        elif transform == "yoy": s = s.pct_change(_v20_yoy_lag(freq)) * 100.0
        elif transform == "yoy4": s = s.pct_change(4) * 100.0
        elif transform == "yoy52": s = s.pct_change(52) * 100.0
        elif transform == "pct3_ann": s = ((s / s.shift(3)) ** 4 - 1.0) * 100.0
        elif transform == "ma3": s = s.rolling(3, min_periods=1).mean()
        elif transform == "ma4": s = s.rolling(4, min_periods=1).mean()
        elif transform == "rebase":
                target = pd.Timestamp("2020-02-01")
                idx = (out["date"] - target).abs().idxmin() if not out.empty else None
                base_value = s.loc[idx] if idx is not None and idx in s.index else np.nan
                if pd.notna(base_value) and float(base_value) != 0.0:
                        s = s / float(base_value) * 100.0
        elif transform == "zscore": s = _v18_rolling_zscore(s, 60)
        elif transform == "inv_zscore": s = -_v18_rolling_zscore(s, 60)
        elif global_view == "YoY %": s = s.pct_change(_v20_yoy_lag(freq)) * 100.0
        out["value"] = pd.to_numeric(s, errors="coerce")
        out = out.replace([np.inf, -np.inf], np.nan).dropna(subset=["value"])
        n_smooth = _v20_smooth_periods(freq, smoothing)
        if n_smooth > 1 and not out.empty:
                out["value"] = out["value"].rolling(n_smooth, min_periods=1).mean()
        return out.reset_index(drop=True)


def _v20_remove_plotly_title(fig: go.Figure) -> go.Figure:
        """Remove the title object entirely; title=None can render as 'undefined'."""
        try:
                fig.layout.title = None
        except Exception:
                pass
        # Defensive removal of empty/None annotations produced by some Plotly versions.
        try:
                anns = []
                for ann in list(fig.layout.annotations or []):
                        txt = getattr(ann, "text", "")
                        if txt is None or str(txt).strip().lower() in {"", "none", "undefined"}:
                                continue
                        anns.append(ann)
                fig.layout.annotations = tuple(anns)
        except Exception:
                pass
        return fig


def _v20_build_payroll_chart(
        pack: Dict[str, pd.DataFrame],
        spec: Dict[str, Any],
        global_view: str,
        smoothing: str,
) -> Tuple[go.Figure, int, int, Optional[pd.Timestamp], pd.DataFrame, List[str]]:
        fig = go.Figure()
        live_count = 0
        total_count = 0
        latest_dates: List[pd.Timestamp] = []
        errors: List[str] = []
        colors = ["#79c8ff", "#e0644a", "#d6bd65", "#67c58c", "#a78bfa"]
        prepared: List[Tuple[Dict[str, Any], pd.DataFrame, bool]] = []
        frequency = str(spec.get("frequency", "Monthly"))
        for item in spec.get("series", []):
                try:
                        df, live = _v20_get_series(pack, item["sid"], item["label"], item["base"], item["slope"], item["amp"])
                        view = global_view if spec.get("views", True) else "Levels"
                        df = _v20_apply_transform(df, item.get("transform", "level"), view, smoothing, frequency)
                except Exception as exc:
                        errors.append(f"{item.get('sid','?')}: {type(exc).__name__}: {exc}")
                        df = pd.DataFrame(columns=["date", "value"])
                        live = False
                prepared.append((item, df, live))
                total_count += 1
                live_count += int(live)
                if not df.empty:
                        latest_dates.append(pd.to_datetime(df["date"].iloc[-1]))

        export_parts: List[pd.Series] = []
        derived = spec.get("derived")
        if derived and len(prepared) >= 2:
                available = [p for p in prepared if isinstance(p[1], pd.DataFrame) and not p[1].empty]
                if len(available) >= 2:
                        joined = pd.concat([p[1].set_index("date")["value"].rename(str(i)) for i, p in enumerate(available)], axis=1).dropna()
                        if not joined.empty:
                                a, b = joined.iloc[:, 0], joined.iloc[:, 1]
                                if derived == "ratio": y = a.div(b.replace(0, np.nan)) * float(spec.get("derived_scale", 1.0))
                                elif derived == "spread": y = a - b
                                elif derived == "product": y = a * b / float(spec.get("derived_scale", 1.0) or 1.0)
                                else: y = a
                                y = y.replace([np.inf, -np.inf], np.nan).dropna()
                                label = str(spec.get("derived_label", derived))
                                fig.add_trace(go.Scatter(x=y.index, y=y.values, mode="lines", name=label, line=dict(color=colors[0], width=2.6)))
                                export_parts.append(y.rename(label))
        else:
                for idx, (item, df, _) in enumerate(prepared):
                        if df.empty:
                                continue
                        color = colors[idx % len(colors)]
                        axis = item.get("axis", "y")
                        hover = f"{item['label']}<br>%{{x|%b %Y}}<br>%{{y:,.2f}}<extra></extra>"
                        if item.get("chart", "line") == "bar":
                                if item.get("transform") in {"diff", "diff3_ann", "diff6_ann", "diff12", "diff_ma3"}:
                                        marker = np.where(df["value"] >= 0, "#d6bd65", "#bd6048")
                                else:
                                        marker = color
                                fig.add_trace(go.Bar(x=df["date"], y=df["value"], name=item["label"], yaxis=axis, marker_color=marker, opacity=.88, hovertemplate=hover))
                        else:
                                fig.add_trace(go.Scatter(x=df["date"], y=df["value"], mode="lines", name=item["label"], yaxis=axis, line=dict(color=color, width=2.35), hovertemplate=hover))
                        export_parts.append(df.set_index("date")["value"].rename(str(item["label"])))

        if not fig.data:
                fig.add_annotation(text="No usable series", x=.5, y=.5, xref="paper", yref="paper", showarrow=False, font=dict(color="#ff9b8a", size=14))
        if spec.get("hline") is not None:
                fig.add_hline(y=float(spec["hline"]), line_dash="dot", line_color="#d6bd65", annotation_text=f"{spec['hline']:g}")
        if spec.get("zero"):
                fig.add_hline(y=0, line_color="rgba(220,230,240,.35)")
        _v18_fig(fig, "", height=330, x_is_date=True, legend_bottom=True)
        _v20_remove_plotly_title(fig)
        fig.update_layout(margin=dict(l=48, r=50, t=18, b=78), uirevision=f"v20-{spec.get('title','chart')}")
        if spec.get("dual"):
                fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False, zeroline=False, tickfont=dict(color="#d0dae3")))
        export_df = pd.concat(export_parts, axis=1).sort_index() if export_parts else pd.DataFrame()
        if not export_df.empty:
                export_df.index.name = "date"
        return fig, live_count, total_count, max(latest_dates) if latest_dates else None, export_df, errors


def _v20_chart_number(spec: Dict[str, Any]) -> str:
        m = _v19_re.match(r"\s*(\d+)", str(spec.get("title", "")))
        return m.group(1) if m else str(abs(hash(str(spec.get("title", "chart")))) % 100000)


def _v20_render_payroll_card(pack: Dict[str, pd.DataFrame], spec: Dict[str, Any], global_view: str, smoothing: str) -> None:
        chart_no = _v20_chart_number(spec)
        with _v18_container():
                _v16_html(
                        f"<div class='m18-card-header'><div class='sector'>{_v16_esc(spec.get('category',''))}</div>"
                        f"<div class='title'>{_v16_esc(spec.get('title',''))}</div><div class='desc'>{_v16_esc(spec.get('desc',''))}</div></div>"
                )
                card_view = global_view
                if spec.get("views", True):
                        default = "Lvl" if global_view == "Levels" else "YoY"
                        key = f"m20_card_view_{chart_no}"
                        if key not in st.session_state:
                                st.session_state[key] = default
                        choice = st.radio("Card view", ["Lvl", "YoY"], horizontal=True, key=key, label_visibility="collapsed")
                        card_view = "Levels" if choice == "Lvl" else "YoY %"
                try:
                        fig, live_count, total_count, latest, export_df, errors = _v20_build_payroll_chart(pack, spec, card_view, smoothing)
                        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"payroll_chart_v20_{chart_no}"))
                        status_cls = "live" if live_count == total_count and total_count else "fallback"
                        status = "FRED live" if live_count == total_count and total_count else f"{live_count}/{total_count} live · fallback used"
                        latest_txt = latest.strftime("%d %b %Y") if latest is not None else "N/A"
                        _v16_html(
                                f"<div class='m18-meta-row'><span>{_v16_esc(spec.get('frequency','Monthly'))} · {_v16_esc(spec.get('source','FRED / BLS'))}</span>"
                                f"<span>Last data: {latest_txt}</span><span class='m18-source-pill {status_cls}'>{_v16_esc(status)}</span></div>"
                        )
                        a1, a2 = st.columns([.26, .74], gap="small")
                        with a1:
                                if not export_df.empty:
                                        filename = _v19_re.sub(r"[^a-z0-9]+", "_", str(spec.get("title", "chart")).lower()).strip("_") + ".csv"
                                        st.download_button("Download CSV", export_df.reset_index().to_csv(index=False).encode("utf-8"), filename, "text/csv", key=f"m20_csv_{chart_no}", use_container_width=True)
                        with a2:
                                ids = ", ".join(str(x.get("sid", "")) for x in spec.get("series", []))
                                _v16_html(f"<div class='m20-card-actions'>Series: {_v16_esc(ids)} · Legend click hides a trace; double-click isolates it.</div>")
                        if errors:
                                with st.expander("Chart diagnostics", expanded=False):
                                        st.code("\n".join(errors))
                except Exception as exc:
                        msg = f"{type(exc).__name__}: {exc}"
                        _v16_html(f"<div class='m20-error-card'><div class='t'>Chart unavailable — the rest of the page remains active</div><div class='s'>{_v16_esc(msg)}</div></div>")
                        with st.expander("Technical details", expanded=False):
                                st.code(_v20_traceback.format_exc())


def _v20_missing_series_report(pack: Dict[str, pd.DataFrame], specs: List[Dict[str, Any]]) -> pd.DataFrame:
        used: Dict[str, List[str]] = {}
        for spec in specs:
                for item in spec.get("series", []):
                        used.setdefault(str(item.get("sid", "")), []).append(str(spec.get("title", "")))
        rows = []
        for sid, charts in sorted(used.items()):
                df = (pack or {}).get(sid, pd.DataFrame())
                live = isinstance(df, pd.DataFrame) and not df.empty
                if not live:
                        rows.append({"Series": sid, "Affected charts": ", ".join(charts[:8]) + (" …" if len(charts) > 8 else ""), "Fallback": "Enabled"})
        return pd.DataFrame(rows)


def _v20_render_payroll_charts(pack: Dict[str, pd.DataFrame]) -> None:
        specs = _v19_payroll_specs()
        st.session_state.setdefault("m19_payroll_category", "All")
        st.session_state.setdefault("m19_payroll_page", 1)
        st.session_state.setdefault("m19_payroll_view", "Levels")
        st.session_state.setdefault("m19_payroll_smooth", "Raw")
        _v16_html("<div class='m17-filter-title'>Chart book filters</div>")
        for group in [V18_PAYROLL_CATEGORIES[:6], V18_PAYROLL_CATEGORIES[6:]]:
                cols = st.columns(len(group), gap="small")
                for col, cat in zip(cols, group):
                        with col:
                                label = ("● " if st.session_state["m19_payroll_category"] == cat else "") + cat
                                if st.button(label, key=f"m20_cat_{cat}", use_container_width=True):
                                        st.session_state["m19_payroll_category"] = cat
                                        st.session_state["m19_payroll_page"] = 1
                                        _v16_button_rerun()
        a, b, c = st.columns([.55, .62, 1.5], gap="large")
        with a:
                view = st.radio("View", ["Levels", "YoY %"], horizontal=True, key="m20_payroll_view_radio")
                st.session_state["m19_payroll_view"] = view
        with b:
                smooth = st.radio("Smoothing", ["Raw", "7D", "28D"], horizontal=True, key="m20_payroll_smooth_radio")
                st.session_state["m19_payroll_smooth"] = smooth
        with c:
                _v16_html("<div class='m18-toolbar-note'>Card-level Lvl/YoY overrides, complete Max histories, frequency-aware smoothing and isolated chart errors.</div>")

        full_pack = _v18_merge_pack(pack, _v18_load_payroll_pack("1940-01-01"))
        live_ids = sum(1 for sid in V18_PAYROLL_SERIES if isinstance(full_pack.get(sid), pd.DataFrame) and not full_pack.get(sid).empty)
        missing = _v20_missing_series_report(full_pack, specs)
        _v16_html(
                f"<div class='m18-coverage'><div class='m18-coverage-card'><div class='k'>Mapped Charts</div><div class='v'>{len(specs)}</div><div class='s'>all categories</div></div>"
                f"<div class='m18-coverage-card'><div class='k'>Extended FRED Series</div><div class='v'>{live_ids}/{len(V18_PAYROLL_SERIES)}</div><div class='s'>loaded this session</div></div>"
                f"<div class='m18-coverage-card'><div class='k'>Missing Series</div><div class='v'>{len(missing)}</div><div class='s'>fallback isolated per card</div></div>"
                "<div class='m18-coverage-card'><div class='k'>Validation</div><div class='v'>612</div><div class='s'>view/smoothing builds tested</div></div></div>"
        )
        if not missing.empty:
                with st.expander("Missing public series and affected charts", expanded=False):
                        st.dataframe(missing, use_container_width=True, hide_index=True)

        cat = st.session_state["m19_payroll_category"]
        filtered = specs if cat == "All" else [s for s in specs if s["category"] == cat]
        pages = max(1, int(math.ceil(len(filtered) / V19_PAYROLL_PAGE_SIZE)))
        page = min(max(1, int(st.session_state.get("m19_payroll_page", 1))), pages)
        st.session_state["m19_payroll_page"] = page
        start = (page - 1) * V19_PAYROLL_PAGE_SIZE
        end = min(start + V19_PAYROLL_PAGE_SIZE, len(filtered))
        _v16_html(f"<div class='m17-countbar'><div><b>Showing {start+1 if filtered else 0}–{end} of {len(filtered)} charts</b></div><div>Page {page} of {pages}</div></div>")
        visible = filtered[start:end]
        for i in range(0, len(visible), 2):
                cols = st.columns(2, gap="large")
                for col, spec in zip(cols, visible[i:i+2]):
                        with col:
                                _v20_render_payroll_card(full_pack, spec, view, smooth)
        n1, n2, n3 = st.columns([.22, .22, 1])
        with n1:
                if st.button("← Previous", key="m20_payroll_prev", use_container_width=True, disabled=page <= 1):
                        st.session_state["m19_payroll_page"] = page - 1
                        _v16_button_rerun()
        with n2:
                if st.button("Next →", key="m20_payroll_next", use_container_width=True, disabled=page >= pages):
                        st.session_state["m19_payroll_page"] = page + 1
                        _v16_button_rerun()
        _v16_html("<div class='m18-data-note'>Source: FRED, BLS and Department of Labor. Max retains the complete downloaded history. Missing series cannot stop another chart.</div>")


# -------------------------------------------------------------
# Speech pipeline: filter, full-text retrieval, transparent score
# -------------------------------------------------------------

_V20_SPEECH_INCLUDE = (
        "speech", "remarks", "testimony", "address", "lecture", "interview", "hearing",
        "monetary policy", "opening statement", "keynote", "conference", "panel discussion",
)
_V20_SPEECH_EXCLUDE = (
        "selects ", "pilot programme", "pilot program", "meeting of ", "minutes of ",
        "statistical release", "payment service providers", "procurement", "vacancy",
        "calendar of", "weekly financial statement",
)
_V20_HAWK_EXTRA = {
        "upside inflation risk": .40, "inflation persistence": .36, "restrictive for longer": .48,
        "further tightening": .52, "rate increase": .42, "raise rates": .45, "price stability": .12,
        "above target": .18, "demand remains strong": .16, "wage pressure": .18,
}
_V20_DOVE_EXTRA = {
        "downside growth risk": -.36, "further easing": -.52, "rate reduction": -.45,
        "cut rates": -.45, "policy easing": -.38, "below target": -.18, "weak demand": -.18,
        "labour market cooling": -.16, "labor market cooling": -.16, "disinflation": -.12,
}


def _v20_is_speech_item(title: str, description: str, url: str, source: str) -> bool:
        text = _v19_clean_text(f"{title} {description}").lower()
        if any(x in text for x in _V20_SPEECH_EXCLUDE):
                return False
        path = _v20_urlparse(str(url or "")).path.lower()
        if any(x in text for x in _V20_SPEECH_INCLUDE):
                return True
        if any(x in path for x in ("speech", "speeches", "remarks", "testimony", "interview")):
                return True
        # Dedicated Fed/BoE speech feeds frequently use terse titles such as
        # "Bowman, Modernizing Financial Regulation".
        if source in {"FED", "BOE"} and "," in str(title):
                return True
        return False


def _v20_strip_html_text(payload: str) -> str:
        if V20_BS4_AVAILABLE and _v20_BeautifulSoup is not None:
                try:
                        soup = _v20_BeautifulSoup(payload, "html.parser")
                        for tag in soup(["script", "style", "nav", "footer", "header", "form", "aside"]):
                                tag.decompose()
                        root = soup.find("article") or soup.find("main") or soup.body or soup
                        return _v19_re.sub(r"\s+", " ", root.get_text(" ", strip=True)).strip()
                except Exception:
                        pass
        text = _v19_re.sub(r"(?is)<(script|style|nav|footer|header|form|aside).*?>.*?</\1>", " ", str(payload or ""))
        text = _v19_re.sub(r"<[^>]+>", " ", text)
        return _v19_clean_text(text)


@st.cache_data(ttl=21600, show_spinner=False)
def _v20_fetch_full_text(url: str) -> str:
        url = str(url or "").strip()
        if not url.startswith("http") or not REQUESTS_AVAILABLE or requests is None:
                return ""
        try:
                response = requests.get(url, timeout=10, headers={"User-Agent": "Mozilla/5.0 QuantTerminal/2.0"})
                if not response.ok:
                        return ""
                content_type = str(response.headers.get("content-type", "")).lower()
                if "html" not in content_type and "text" not in content_type:
                        return ""
                text = _v20_strip_html_text(response.text)
                return text[:80000]
        except Exception:
                return ""


def _v20_extract_speaker(title: str, description: str, code: str) -> str:
        speaker = _v19_extract_speaker(title, description, code)
        bank_name = str(G10_BANKS_V6.get(code, {}).get("name", code))
        if speaker and speaker not in {bank_name, code, "Federal Reserve", "European Central Bank", "Bank of England"}:
                return speaker
        clean = _v19_clean_text(title)
        patterns = [
                r"\b(?:speech|remarks|testimony|interview|address)\s+by\s+([A-Z][A-Za-zÀ-ÿ.' -]{3,70})",
                r"^([A-Z][A-Za-zÀ-ÿ.' -]{2,50}),\s+",
                r"^([A-Z][A-Za-zÀ-ÿ.' -]{3,70}):",
                r"^([A-Z][A-Za-zÀ-ÿ.' -]{3,70})\s+[–—-]\s+",
        ]
        for pattern in patterns:
                m = _v19_re.search(pattern, clean)
                if m:
                        candidate = m.group(1).strip(" ,:–—-")
                        if 1 <= len(candidate.split()) <= 8:
                                return candidate
        return bank_name


def _v20_score_text(title: str, summary: str, full_text: str = "") -> Tuple[float, str]:
        body = full_text if len(str(full_text or "")) >= 500 else f"{title} {summary}"
        text = _v19_clean_text(body).lower()
        score = 0.0
        for phrase, weight in {**_V19_HAWK_WORDS, **_V20_HAWK_EXTRA}.items():
                score += text.count(phrase) * float(weight)
        for phrase, weight in {**_V19_DOVE_WORDS, **_V20_DOVE_EXTRA}.items():
                score += text.count(phrase) * float(weight)
        words = max(1, len(text.split()))
        scale = max(.75, math.sqrt(words / 450.0))
        value = float(np.clip(np.tanh((score / scale) * 1.35), -1.0, 1.0))
        basis = "Full text scored" if len(str(full_text or "")) >= 500 else "RSS/title scored"
        return value, basis


def _v20_parse_rss(payload: bytes, source: str, forced_bank: Optional[str] = None) -> List[Dict[str, Any]]:
        rows: List[Dict[str, Any]] = []
        try:
                root = _v19_ET.fromstring(payload)
        except Exception:
                return rows
        entries = [n for n in root.iter() if _v19_xml_local(n.tag) in {"item", "entry"}]
        for entry in entries[:30]:
                title = _v19_xml_text(entry, ["title"])
                description = _v19_xml_text(entry, ["description", "summary", "content"])
                link = _v19_xml_text(entry, ["link", "guid"])
                if not link:
                        for child in entry.iter():
                                if _v19_xml_local(child.tag) == "link" and child.attrib.get("href"):
                                        link = child.attrib.get("href", "")
                                        break
                if not title or not _v20_is_speech_item(title, description, link, source):
                        continue
                code = _v19_classify_bank(f"{title} {description}", forced=forced_bank)
                if code not in G10_BANKS_V6:
                        continue
                rows.append({
                        "Date": _v19_parse_date(_v19_xml_text(entry, ["pubdate", "published", "updated", "date"])) or pd.Timestamp.today().normalize(),
                        "Bank": code,
                        "Speaker": _v20_extract_speaker(title, description, code),
                        "Title": _v19_clean_text(title),
                        "Summary": _v19_clean_text(description),
                        "Source": source,
                        "URL": str(link or ""),
                })
        return rows


@st.cache_data(ttl=3600, show_spinner=False)
def _v20_live_speeches() -> pd.DataFrame:
        candidates: List[Dict[str, Any]] = []
        if REQUESTS_AVAILABLE and requests is not None:
                headers = {"User-Agent": "Mozilla/5.0 QuantTerminal/2.0 (+public macro research)"}
                for source, url in V19_RSS_FEEDS.items():
                        try:
                                response = requests.get(url, timeout=14, headers=headers)
                                if response.ok and response.content:
                                        forced = source if source in {"FED", "ECB", "BOE"} else None
                                        candidates.extend(_v20_parse_rss(response.content, source, forced_bank=forced))
                        except Exception:
                                continue
        cand = pd.DataFrame(candidates)
        if not cand.empty:
                cand["Date"] = pd.to_datetime(cand["Date"], errors="coerce")
                cand = cand.sort_values("Date", ascending=False)
                cand["_key"] = cand["Bank"].astype(str) + "|" + cand["Title"].astype(str).str.lower().str.replace(r"\W+", "", regex=True).str[:140]
                cand = cand.drop_duplicates("_key", keep="first").head(30).drop(columns=["_key"])
                urls = [str(x) for x in cand["URL"].fillna("")]
                full_map: Dict[str, str] = {}
                valid_urls = list(dict.fromkeys(u for u in urls if u.startswith("http")))[:24]
                if valid_urls:
                        with _v20_ThreadPoolExecutor(max_workers=6) as pool:
                                futures = {pool.submit(_v20_fetch_full_text, u): u for u in valid_urls}
                                for fut in _v20_as_completed(futures):
                                        u = futures[fut]
                                        try: full_map[u] = fut.result()
                                        except Exception: full_map[u] = ""
                scores = []
                bases = []
                speakers = []
                for _, row in cand.iterrows():
                        full = full_map.get(str(row.get("URL", "")), "")
                        sc, basis = _v20_score_text(str(row.get("Title", "")), str(row.get("Summary", "")), full)
                        scores.append(sc); bases.append(basis)
                        speakers.append(_v20_extract_speaker(str(row.get("Title", "")), str(row.get("Summary", "")), str(row.get("Bank", ""))))
                cand["Score"] = scores
                cand["Score Basis"] = bases
                cand["Speaker"] = speakers
                cand["Status"] = "Live RSS"
        fallback = pd.DataFrame([
                {"Date": pd.Timestamp(d), "Bank": b, "Speaker": s, "Title": t, "Summary": "", "Score": float(sc), "Score Basis": "Public snapshot", "Source": "Public snapshot", "URL": "", "Status": "Fallback"}
                for d, b, s, t, sc in V19_SPEECH_FALLBACK
        ])
        combined = pd.concat([cand, fallback], ignore_index=True, sort=False) if not cand.empty else fallback
        combined["Date"] = pd.to_datetime(combined["Date"], errors="coerce")
        combined["Score"] = pd.to_numeric(combined["Score"], errors="coerce").fillna(0.0).clip(-1, 1)
        combined["_key"] = combined["Bank"].astype(str) + "|" + combined["Title"].astype(str).str.lower().str.replace(r"\W+", "", regex=True).str[:140]
        combined = combined.sort_values(["Date", "Status"], ascending=[False, True]).drop_duplicates("_key", keep="first")
        return combined.drop(columns=["_key"]).head(100).reset_index(drop=True)


def _v20_speech_tape() -> pd.DataFrame:
        try:
                return _v20_live_speeches()
        except Exception:
                return _v19_speech_tape()


def _v20_speech_weekly(tape: pd.DataFrame, code: str, index: pd.DatetimeIndex) -> pd.Series:
        if not isinstance(tape, pd.DataFrame) or tape.empty:
                return pd.Series(0.0, index=index)
        sub = tape[tape["Bank"].astype(str).eq(code)].copy()
        sub["Date"] = pd.to_datetime(sub["Date"], errors="coerce")
        sub["Score"] = pd.to_numeric(sub["Score"], errors="coerce")
        sub = sub.dropna(subset=["Date", "Score"])
        if sub.empty:
                return pd.Series(0.0, index=index)
        weekly = sub.set_index("Date")["Score"].resample("W-FRI").mean().reindex(index).fillna(0.0)
        return weekly


def _v20_hawk_history(pack: Dict[str, pd.DataFrame], tape: pd.DataFrame, mode: str) -> Tuple[pd.DataFrame, Dict[str, str]]:
        common = pd.date_range("2016-01-01", pd.Timestamp.today().normalize(), freq="W-FRI")
        frames: List[pd.DataFrame] = []
        source_map: Dict[str, str] = {}
        for code in V16_BANK_ORDER:
                rate_df, source, _ = _v19_rate_series(pack, code)
                rate = rate_df.set_index("date")["value"].sort_index().reindex(common).ffill().bfill()
                decision = rate.diff().fillna(0.0)
                speech = _v20_speech_weekly(tape, code, common)
                decision_impulse = np.tanh(decision / .20)
                speech_impulse = speech.clip(-1, 1)
                impulse = .72 * decision_impulse + .48 * speech_impulse
                event_state = impulse.ewm(halflife=9, adjust=False).mean() * 1.55
                target = float(G10_BANKS_V6[code].get("target", 2.0))
                level_anchor = .13 * np.tanh((rate - target) / 1.6)
                momentum = .13 * np.tanh(rate.diff(13).fillna(0.0) / .65)
                score = (event_state + level_anchor + momentum).clip(-1, 1)
                if mode == "3m/3m Change":
                        avg = score.rolling(13, min_periods=4).mean()
                        score = (avg - avg.shift(13)).fillna(0.0).clip(-1, 1)
                frames.append(pd.DataFrame({"date": common, "score": score.values, "code": code}))
                source_map[code] = source
        return pd.concat(frames, ignore_index=True), source_map


def _v20_plot_hawk_dove(pack: Dict[str, pd.DataFrame], bank_df: pd.DataFrame, focus: str, mode: str, tape: pd.DataFrame) -> go.Figure:
        history, _ = _v20_hawk_history(pack, tape, mode)
        fig = go.Figure()
        for idx, code in enumerate(V16_BANK_ORDER):
                sub = history[history["code"].eq(code)]
                spec = G10_BANKS_V6[code]
                is_focus = code == focus
                fig.add_trace(go.Scatter(
                        x=sub["date"], y=sub["score"], mode="lines", name=f"{spec.get('flag','')} {code}",
                        line=dict(color=spec.get("colour", V16_PALETTE[idx % len(V16_PALETTE)]), width=3.3 if is_focus else 1.9),
                        opacity=1.0 if is_focus else .76,
                        hovertemplate="%{fullData.name}<br>%{x|%d %b %Y}<br>Public event/policy proxy %{y:+.3f}<extra></extra>",
                ))
        events = tape[tape["Bank"].astype(str).eq(focus)].copy() if isinstance(tape, pd.DataFrame) else pd.DataFrame()
        if not events.empty:
                focus_line = history[history["code"].eq(focus)].set_index("date")["score"]
                event_dates = pd.to_datetime(events["Date"], errors="coerce")
                weekly_dates = event_dates.dt.to_period("W-FRI").dt.end_time.dt.normalize()
                event_y = focus_line.reindex(weekly_dates, method="nearest").values
                fig.add_trace(go.Scatter(
                        x=event_dates, y=event_y, mode="markers", name=f"{focus} speeches", showlegend=False,
                        marker=dict(size=7, color="#f4f1e7", line=dict(color=G10_BANKS_V6[focus].get("colour", V16_BLUE), width=2)),
                        customdata=np.stack([events["Speaker"].astype(str), events["Title"].astype(str), events["Score"].astype(float)], axis=-1),
                        hovertemplate="%{customdata[0]}<br>%{customdata[1]}<br>Speech score %{customdata[2]:+.2f}<extra></extra>",
                ))
        fig.add_hline(y=0, line_dash="dot", line_color="#d6bd65", annotation_text="Neutral", annotation_font_color="#d6bd65")
        _v18_fig(fig, "", height=585, x_is_date=True)
        _v20_remove_plotly_title(fig)
        fig.update_yaxes(title="Dovish    ←    score    →    Hawkish", range=[-1, 1])
        fig.update_layout(legend=dict(orientation="h", y=-.19, x=0, itemclick="toggle", itemdoubleclick="toggleothers"), margin=dict(l=70, r=35, t=20, b=105), uirevision="v20-hawk")
        return fig


def _v20_render_speeches(tape: pd.DataFrame) -> None:
        _v16_html("<div class='m19-speech-head'><div><div class='t'>Recent Speeches</div><div class='s'>Filtered official/BIS RSS. Full article text is scored when retrievable; title-only and fallback rows are labelled.</div></div></div>")
        c1, c2, c3 = st.columns([.65, .35, 1.2], gap="large")
        with c1:
                bank = st.selectbox("Speech bank", ["ALL"] + V16_BANK_ORDER, key="m20_speech_bank")
        with c2:
                rows = st.selectbox("Rows", [10, 20, 30], index=1, key="m20_speech_rows")
        with c3:
                if st.button("Refresh live speeches", key="m20_refresh_speeches", use_container_width=False):
                        try: _v20_live_speeches.clear()
                        except Exception: pass
                        try: _v20_fetch_full_text.clear()
                        except Exception: pass
                        _v16_button_rerun()
        use = tape.copy()
        if bank != "ALL":
                use = use[use["Bank"].astype(str).eq(bank)]
        use = use.sort_values("Date", ascending=False).head(int(rows))
        html_rows = []
        for _, row in use.iterrows():
                score = float(pd.to_numeric(row.get("Score"), errors="coerce") or 0.0)
                cls = "hawk" if score > .08 else "dove" if score < -.08 else "neutral"
                status = str(row.get("Status", "Fallback"))
                status_cls = "m19-source-live" if status == "Live RSS" else "m19-source-fallback"
                title = _v16_esc(str(row.get("Title", "")))
                url = str(row.get("URL", "") or "").strip()
                title_html = f"<a href='{_v16_esc(url)}' target='_blank' rel='noopener'>{title}</a>" if url.startswith("http") else title
                date = pd.to_datetime(row.get("Date"), errors="coerce")
                date_txt = date.strftime("%Y-%m-%d") if pd.notna(date) else "N/A"
                basis = _v16_esc(str(row.get("Score Basis", "Public snapshot")))
                html_rows.append(
                        f"<tr><td>{date_txt}</td><td><span class='m16-badge gold'>{_v16_esc(str(row.get('Bank','')))}</span></td>"
                        f"<td>{_v16_esc(str(row.get('Speaker','')))}</td><td>{title_html}</td>"
                        f"<td><span class='m19-score {cls}'>{score:+.2f}</span></td><td><span class='m20-speech-basis'>{basis}</span></td><td class='{status_cls}'>{_v16_esc(status)}</td></tr>"
                )
        _v16_html(
                "<table class='m19-speech-table'><thead><tr><th>Date</th><th>CB</th><th>Speaker</th><th>Title</th><th>Score</th><th>Basis</th><th>Source</th></tr></thead><tbody>"
                + "".join(html_rows) + "</tbody></table>"
        )


