@st.cache_data(ttl=3600, show_spinner=False)
def _v20_load_balance_pack(start_date: str = "1990-01-01") -> Dict[str, pd.DataFrame]:
        out: Dict[str, pd.DataFrame] = {}
        for _, (sid, _, _, _) in V20_BALANCE_SERIES.items():
                try:
                        df = fetch_fred_csv_series(sid, start_date=start_date)
                        if isinstance(df, pd.DataFrame) and not df.empty:
                                out[sid] = df
                except Exception:
                        continue
        return out


def _v20_policy_history_chart(pack: Dict[str, pd.DataFrame], bank_df: pd.DataFrame, code: str) -> Tuple[go.Figure, str]:
        code = code if code in G10_BANKS_V6 else "FED"
        spec = G10_BANKS_V6[code]
        rate_df, rate_source, _ = _v19_rate_series(pack, code)
        balance_pack = _v20_load_balance_pack("1990-01-01")
        balance = pd.DataFrame()
        balance_source = "Balance-sheet series unavailable"
        if code in V20_BALANCE_SERIES:
                sid, scale, unit, source = V20_BALANCE_SERIES[code]
                raw = _v18_clean_series(balance_pack.get(sid, pd.DataFrame()))
                if not raw.empty:
                        balance = raw.set_index("date")["value"].resample("ME").last().diff().div(float(scale)).dropna().reset_index(name="value")
                        balance_source = f"{source} {sid} · monthly change in {unit}"
        fig = go.Figure()
        if not balance.empty:
                colors = np.where(balance["value"] >= 0, "#5e96b8", "#bd6048")
                fig.add_trace(go.Bar(x=balance["date"], y=balance["value"], yaxis="y2", name="Balance sheet monthly change", marker=dict(color=colors, opacity=.88), hovertemplate="%{x|%b %Y}<br>Balance-sheet change %{y:+,.1f}<extra></extra>"))
        fig.add_trace(go.Scatter(x=rate_df["date"], y=rate_df["value"], mode="lines", line_shape="hv", name="Policy rate", line=dict(color="#d6bd65", width=3), hovertemplate="%{x|%b %Y}<br>Policy rate %{y:.2f}%<extra></extra>"))
        if balance.empty:
                fig.add_annotation(text="Official balance-sheet series not connected for this bank", x=.5, y=.92, xref="paper", yref="paper", showarrow=False, font=dict(color="#d0a95c", size=12), bgcolor="rgba(214,189,101,.08)")
        _v18_fig(fig, "", height=585, x_is_date=True)
        _v20_remove_plotly_title(fig)
        fig.update_layout(
                yaxis=dict(title="Policy rate %"),
                yaxis2=dict(title="Balance-sheet change", overlaying="y", side="right", showgrid=False, zeroline=True, zerolinecolor="rgba(200,210,220,.25)", tickfont=dict(color="#c8d2dd")),
                margin=dict(l=70, r=70, t=20, b=82),
                uirevision=f"v20-balance-{code}",
        )
        rate = rate_df.set_index("date")["value"].sort_index()
        changes = rate[rate.diff().abs() > 1e-9]
        hold_since = changes.index[-1].strftime("%Y-%m-%d") if not changes.empty else "N/A"
        return fig, f"Rate: {rate_source} · on hold since {hold_since} · {balance_source}"


