        with c3:
                _v16_html("<div class='m19-controls-note'>The focused line is emphasised and its speech events are marked. Visibility is controlled only from the chart legend.</div>")
        fig = _v20_plot_hawk_dove(policy_pack, current_df, focus, mode, tape)
