def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
        """V20 renderer — stabilised chart engine, event-based stance and public-data provenance."""
        _v12_css(); _v13_css(); _v14_css(); _v15_css(); _v16_css(); _v17_css(); _v18_css(); _v19_css(); _v20_css(); _v12_init_state()
        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
        selected_code = str(st.session_state.get("macro_v12_bank", "FED")).upper().strip()
        if selected_code not in G10_BANKS_V6:
                selected_code = "FED"; st.session_state["macro_v12_bank"] = selected_code
        if page != "central-banks":
                st.session_state["macro_v12_route"] = "overview"
        with st.spinner("Loading macro desk data…"):
                try: pack = build_macro_pack_cached("2000-01-01", True)
                except Exception: pack = {}
                try: proxy_pack = fetch_market_proxy_pack("2y")
                except Exception: proxy_pack = {}
                try: indicator_df = compute_indicator_table(pack)
                except Exception: indicator_df = pd.DataFrame()
                policy_pack = _v19_merge_pack(pack, _v19_load_policy_pack("1990-01-01"))
                bank_df = _v19_bank_df(policy_pack)
        _v16_html('<div class="m16-shell">')
