def _v21_series_frame(raw: pd.DataFrame, mode: str) -> pd.DataFrame:
        if not isinstance(raw, pd.DataFrame) or raw.empty or "date" not in raw.columns or "value" not in raw.columns:
                return pd.DataFrame(columns=["date", "value"])
        out = raw[["date", "value"]].copy()
        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["value"] = pd.to_numeric(out["value"], errors="coerce")
        out = out.dropna().sort_values("date").drop_duplicates("date", keep="last")
        if out.empty:
                return out
        if mode == "index":
                out["value"] = out["value"].pct_change(12) * 100.0
                out = out.dropna(subset=["value"])
        out = out[np.isfinite(out["value"]) & out["value"].between(-15.0, 35.0)]
        return out.reset_index(drop=True)


def _v21_public_series(pack: Dict[str, pd.DataFrame], code: str, kind: str) -> Tuple[pd.DataFrame, str]:
        candidates = V21_INFLATION_SERIES_CANDIDATES.get(code, {}).get(kind, [])
        best = pd.DataFrame(columns=["date", "value"])
        best_sid = "Public snapshot"
        for sid, mode in candidates:
                raw = pack.get(sid, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
                if not isinstance(raw, pd.DataFrame) or raw.empty:
                        try:
                                raw = fetch_fred_csv_series(sid, start_date="1990-01-01")
                        except Exception:
                                raw = pd.DataFrame()
                use = _v21_series_frame(raw, mode)
                if use.empty:
                        continue
                if best.empty or pd.to_datetime(use["date"].iloc[-1]) > pd.to_datetime(best["date"].iloc[-1]):
                        best = use
                        best_sid = sid
        return best, best_sid


def _v21_recent_snapshot_series(code: str, kind: str = "headline") -> pd.DataFrame:
        if kind == "headline":
                vals = V21_HEADLINE_HEATMAP.get(code, [None] * 12)
        else:
                head = np.asarray([np.nan if v is None else float(v) for v in V21_HEADLINE_HEATMAP.get(code, [None] * 12)], dtype=float)
                snap = V21_INFLATION_SNAPSHOT.get(code, {})
                h_now = safe_float(snap.get("headline"), 2.0) or 2.0
                c_now = safe_float(snap.get("core"), h_now) or h_now
                vals_arr = c_now + 0.35 * (head - h_now)
                vals = [None if not np.isfinite(v) else float(np.clip(v, -3.0, 15.0)) for v in vals_arr]
                # Anchor the latest available observation to the disclosed current core reading.
                for i in range(len(vals) - 1, -1, -1):
                        if vals[i] is not None:
                                vals[i] = c_now
                                break
        return pd.DataFrame({"date": V21_HEATMAP_MONTHS, "value": vals}).dropna(subset=["value"])


def _v21_merged_series(pack: Dict[str, pd.DataFrame], code: str, kind: str) -> Tuple[pd.DataFrame, str, bool]:
        public, sid = _v21_public_series(pack, code, kind)
        recent = _v21_recent_snapshot_series(code, kind)
        used_proxy = False
        if public.empty:
                return recent.reset_index(drop=True), "Public snapshot", True
        latest = pd.to_datetime(public["date"].iloc[-1])
        if latest < pd.Timestamp("2026-05-01"):
                use = pd.concat([public, recent], ignore_index=True)
                use["month"] = pd.to_datetime(use["date"]).dt.to_period("M")
                use = use.sort_values("date").drop_duplicates("month", keep="last").drop(columns="month")
                used_proxy = True
                return use.reset_index(drop=True), f"{sid} + current public snapshot", used_proxy
        return public.reset_index(drop=True), sid, used_proxy


def _v21_snapshot_frame(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows: List[Dict[str, Any]] = []
        for code in V21_INFLATION_ORDER:
                spec = G10_BANKS_V6.get(code, {})
                snap = V21_INFLATION_SNAPSHOT.get(code, {})
                headline_series, headline_source, headline_proxy = _v21_merged_series(pack, code, "headline")
                core_series, core_source, core_proxy = _v21_merged_series(pack, code, "core")
                headline = safe_float(snap.get("headline"), np.nan)
                core = safe_float(snap.get("core"), np.nan)
                change = safe_float(snap.get("change"), np.nan)
                # Prefer a fresh public observation if it is contemporaneous and plausible.
                if not headline_series.empty and pd.to_datetime(headline_series["date"].iloc[-1]) >= pd.Timestamp("2026-05-01"):
                        live_val = safe_float(headline_series["value"].iloc[-1])
                        if live_val is not None and -5.0 <= live_val <= 20.0:
                                headline = live_val
                                if len(headline_series) >= 2:
                                        change = live_val - float(headline_series["value"].iloc[-2])
                if not core_series.empty and pd.to_datetime(core_series["date"].iloc[-1]) >= pd.Timestamp("2026-05-01"):
                        live_core = safe_float(core_series["value"].iloc[-1])
                        if live_core is not None and -5.0 <= live_core <= 20.0:
                                core = live_core
                target = safe_float(spec.get("target"), 2.0) or 2.0
                next_date = pd.to_datetime(snap.get("next_date"), errors="coerce")
                rows.append({
                        "Code": code,
                        "Rank": 0,
                        "Country": spec.get("country", code),
                        "Flag": spec.get("flag", ""),
                        "Bank": spec.get("name", code),
                        "Target": target,
                        "Headline": float(headline if headline is not None else np.nan),
                        "Core": float(core if core is not None else np.nan),
                        "Change": float(change if change is not None else np.nan),
                        "Deviation": float((headline if headline is not None else np.nan) - target),
                        "Trend": headline_series.tail(12)["value"].astype(float).tolist() if not headline_series.empty else [],
                        "Headline Source": headline_source,
                        "Core Source": core_source,
                        "Fallback": bool(headline_proxy or core_proxy),
                        "Next Date": next_date,
                        "Next Label": str(snap.get("next_label", "Next CPI release")),
                        "Colour": spec.get("colour", "#6baed6"),
                })
        out = pd.DataFrame(rows)
        out = out.sort_values(["Deviation", "Headline"], ascending=[False, False]).reset_index(drop=True)
        out["Rank"] = np.arange(1, len(out) + 1)
        return out


def _v21_dev_class(dev: float) -> Tuple[str, str]:
        if dev > 1.5:
                return "hot", "#ce5d3e"
        if dev > .75:
                return "warm", "#ca8b58"
        if dev >= -.25:
                return "target", "#86aa87"
        if dev >= -1.5:
                return "cool", "#a28d26"
        return "cold", "#7c6a17"


def _v21_spark_svg(values: List[float], colour: str, target: float) -> str:
        vals = np.asarray([float(v) for v in values if v is not None and np.isfinite(v)], dtype=float)
        if len(vals) < 2:
                return '<span style="color:#718095">—</span>'
        lo = float(min(np.nanmin(vals), target) - .25)
        hi = float(max(np.nanmax(vals), target) + .25)
        if hi <= lo:
                hi = lo + 1.0
        w, h, pad = 130.0, 34.0, 3.0
        xs = np.linspace(pad, w - pad, len(vals))
        ys = h - pad - (vals - lo) / (hi - lo) * (h - 2 * pad)
        pts = " ".join(f"{x:.1f},{y:.1f}" for x, y in zip(xs, ys))
        ty = h - pad - (target - lo) / (hi - lo) * (h - 2 * pad)
        return f'<svg viewBox="0 0 {w:.0f} {h:.0f}" width="130" height="34" role="img"><line x1="2" y1="{ty:.1f}" x2="128" y2="{ty:.1f}" stroke="#6f7d8b" stroke-width="1" stroke-dasharray="3 3" opacity=".65"/><polyline fill="none" stroke="{_v16_esc(colour)}" stroke-width="2.2" points="{pts}"/><circle cx="{xs[-1]:.1f}" cy="{ys[-1]:.1f}" r="2.4" fill="{_v16_esc(colour)}"/></svg>'


def _v21_next_release_text(dt: pd.Timestamp, label: str) -> str:
        if pd.isna(dt):
                return label
        now = pd.Timestamp(datetime.now().date())
        day = dt.normalize()
        if day == now:
                return "Today · " + label
        if day == now + pd.Timedelta(days=1):
                return "Tomorrow · " + label
        return f"{day.strftime('%d %b')} · {label}"


def _v21_render_snapshot_table(df: pd.DataFrame) -> None:
        if df.empty:
                _v16_html('<div class="m16-warning">Inflation snapshot unavailable.</div>')
                return
        st.session_state.setdefault("m21_infl_sort", "Deviation")
        st.session_state.setdefault("m21_infl_desc", True)
        c1, c2, c3 = st.columns([1.1, .65, 2.0], gap="small")
        with c1:
                sort_label = st.selectbox("Sort snapshot", ["Deviation", "CPI", "Monthly change", "Core", "Country"], key="m21_infl_sort")
        with c2:
                direction = st.radio("Direction", ["High → Low", "Low → High"], horizontal=True, label_visibility="collapsed", key="m21_infl_direction")
        with c3:
                _v16_html('<div class="m19-controls-note">Snapshot values, 12-month trend, deviation from the official target and the next scheduled release in one view.</div>')
        sort_map = {"Deviation": "Deviation", "CPI": "Headline", "Monthly change": "Change", "Core": "Core", "Country": "Country"}
        use = df.sort_values(sort_map.get(sort_label, "Deviation"), ascending=(direction == "Low → High")).reset_index(drop=True)
        use["Rank"] = np.arange(1, len(use) + 1)
        html = ['<div class="m21-snapshot-wrap"><table class="m21-snapshot"><thead><tr><th>#</th><th>Country</th><th>12m trend</th><th>vs target</th><th>CPI</th><th>Chg</th><th>Core</th><th>Dev</th><th>Next</th></tr></thead><tbody>']
        for _, r in use.iterrows():
                dev = float(r["Deviation"])
                cls, badge = _v21_dev_class(dev)
                arrow = "↑" if r["Change"] > .02 else "↓" if r["Change"] < -.02 else "→"
                max_scale = max(6.0, float(r["Headline"]) + .5, float(r["Target"]) + .5)
                fill = max(0.0, min(100.0, float(r["Headline"]) / max_scale * 100.0))
                mark = max(0.0, min(100.0, float(r["Target"]) / max_scale * 100.0))
                source_tip = f"Headline: {r['Headline Source']} · Core: {r['Core Source']}"
                html.append(
                        '<tr>'
                        f'<td class="m21-rank">{int(r["Rank"])}</td>'
                        f'<td><span class="m21-country">{_v16_esc(r["Flag"])} {_v16_esc(r["Country"])}</span><span class="m21-bank-sub">{_v16_esc(r["Bank"])} · {float(r["Target"]):.1f}% target</span></td>'
                        f'<td title="{_v16_esc(source_tip)}">{_v21_spark_svg(r["Trend"], r["Colour"], float(r["Target"]))}</td>'
                        f'<td><div class="m21-targetbar" title="CPI {float(r["Headline"]):.2f}% · target {float(r["Target"]):.2f}%"><span class="fill" style="width:{fill:.1f}%"></span><span class="mark" style="left:{mark:.1f}%"></span></div></td>'
                        f'<td><span class="m21-cpi-badge" style="background:{badge}"><span class="m21-num">{float(r["Headline"]):.1f}%</span><span class="m21-arrow">{arrow}</span></span></td>'
                        f'<td class="m21-num m21-dev {cls}">{float(r["Change"]):+.2f}pp</td>'
                        f'<td class="m21-num">{float(r["Core"]):.1f}%</td>'
                        f'<td class="m21-num m21-dev {cls}">{dev:+.1f}pp</td>'
                        f'<td class="m21-next">{_v16_esc(_v21_next_release_text(r["Next Date"], r["Next Label"]))}</td>'
                        '</tr>'
                )
        html.append('</tbody></table></div>')
        _v16_html(''.join(html))
        _v16_html('<div class="m21-scale"><span><i style="background:#7c6a17"></i>&lt; −1.5pp</span><span><i style="background:#a28d26"></i>−1.5 to −0.5pp</span><span><i style="background:#86aa87"></i>±0.25pp</span><span><i style="background:#d2b35b"></i>+0.25 to +0.75pp</span><span><i style="background:#ca8b58"></i>+0.75 to +1.5pp</span><span><i style="background:#ce5d3e"></i>&gt; +1.5pp</span></div>')


def _v21_heatmap_matrix(pack: Dict[str, pd.DataFrame], kind: str) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, str]]:
        actual_rows, deviation_rows, source_map = [], [], {}
        labels = [d.strftime("%b\n%y") for d in V21_HEATMAP_MONTHS]
        for code in V21_HEATMAP_ORDER:
                spec = G10_BANKS_V6.get(code, {})
                series, source, proxy = _v21_merged_series(pack, code, kind)
                use = series.copy()
                use["month"] = pd.to_datetime(use["date"]).dt.to_period("M")
                lookup = use.drop_duplicates("month", keep="last").set_index("month")["value"]
                vals = []
                for dt in V21_HEATMAP_MONTHS:
                        key = dt.to_period("M")
                        vals.append(float(lookup[key]) if key in lookup.index and np.isfinite(lookup[key]) else np.nan)
                target = float(spec.get("target", 2.0))
                actual_rows.append(vals)
                deviation_rows.append([v - target if np.isfinite(v) else np.nan for v in vals])
                source_map[code] = source + (" · proxy anchored" if proxy else "")
        y = [f"{G10_BANKS_V6[c].get('flag','')} {c}" for c in V21_HEATMAP_ORDER]
        actual = pd.DataFrame(actual_rows, index=y, columns=labels)
        deviation = pd.DataFrame(deviation_rows, index=y, columns=labels)
        return actual, deviation, source_map


def _v21_render_heatmap(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("12-Month CPI Heatmap", "Colour encodes deviation from each central-bank target; cell labels show the actual YoY inflation rate.")
        mode = st.radio("Heatmap series", ["Headline CPI", "Core CPI"], horizontal=True, key="m21_heatmap_mode")
        kind = "headline" if mode == "Headline CPI" else "core"
        actual, dev, sources = _v21_heatmap_matrix(pack, kind)
        text = np.empty(actual.shape, dtype=object)
        for i in range(actual.shape[0]):
                for j in range(actual.shape[1]):
                        v = actual.iloc[i, j]
                        text[i, j] = "—" if not np.isfinite(v) else f"{v:.1f}"
        fig = go.Figure(go.Heatmap(
                z=dev.values,
                x=actual.columns,
                y=actual.index,
                zmin=-2.0,
                zmax=2.0,
                zmid=0.0,
                colorscale=[[0.0, "#6f6117"], [.22, "#9d8723"], [.43, "#83aa86"], [.50, "#6d9077"], [.64, "#c5a34e"], [.82, "#ca895a"], [1.0, "#cf593b"]],
                text=text,
                texttemplate="%{text}",
                textfont=dict(size=12, color="#08101a"),
                hovertemplate="%{y}<br>%{x}<br>Actual: %{text}%<br>Deviation: %{z:+.2f}pp<extra></extra>",
                colorbar=dict(title="vs target", ticksuffix="pp", thickness=12),
                hoverongaps=False,
        ))
        _v18_fig(fig, "", height=520, legend_bottom=False)
        _v20_remove_plotly_title(fig)
        fig.update_layout(margin=dict(l=95, r=35, t=18, b=50), uirevision=f"v21-heatmap-{kind}")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"g10_{kind}_heatmap_v21"))
        proxy_count = sum("proxy anchored" in v for v in sources.values())
        _v16_html(f'<div class="m21-source-note"><b>Heatmap basis:</b> public FRED/OECD/Eurostat histories where current; current public snapshots bridge stale or unavailable series. Core history uses an explicitly labelled proxy only where no public core series loads. Proxy-anchored rows: {proxy_count}/10.</div>')


def _v21_quarterly_frame(pack: Dict[str, pd.DataFrame]) -> Tuple[pd.DataFrame, Dict[str, str]]:
        frames, source_map = [], {}
        for code in V21_HEATMAP_ORDER:
                series, source, proxy = _v21_merged_series(pack, code, "headline")
                if series.empty:
                        continue
                use = series.copy()
                use["date"] = pd.to_datetime(use["date"], errors="coerce")
                use = use.dropna(subset=["date", "value"])
                use = use[use["date"] >= pd.Timestamp("2024-04-01")]
                if use.empty:
                        continue
                q = use.set_index("date")["value"].resample("QE").mean().dropna().reset_index()
                q["Quarter"] = q["date"].dt.to_period("Q").astype(str)
                q["Code"] = code
                q["Label"] = f"{G10_BANKS_V6[code].get('flag','')} {code}"
                frames.append(q[["date", "Quarter", "Code", "Label", "value"]])
                source_map[code] = source + (" · snapshot bridge" if proxy else "")
        return (pd.concat(frames, ignore_index=True) if frames else pd.DataFrame(columns=["date", "Quarter", "Code", "Label", "value"])), source_map


def _v21_render_quarterly(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("G10 Inflation — Quarterly Overview", "Quarterly averages of monthly headline CPI YoY readings. Use the selector or click the legend to compare economies.")
        qdf, sources = _v21_quarterly_frame(pack)
        if qdf.empty:
                _v16_html('<div class="m16-warning">Quarterly inflation history unavailable.</div>')
                return
        options = V21_HEATMAP_ORDER
        selected = st.multiselect("Countries", options, default=options, key="m21_quarterly_countries")
        selected = selected or options
        fig = go.Figure()
        for code in selected:
                use = qdf[qdf["Code"] == code]
                if use.empty:
                        continue
                spec = G10_BANKS_V6.get(code, {})
                fig.add_trace(go.Scatter(
                        x=use["date"], y=use["value"], mode="lines+markers", name=f"{spec.get('flag','')} {code}",
                        line=dict(color=spec.get("colour", "#6baed6"), width=2.2), marker=dict(size=6),
                        customdata=use[["Quarter"]].values,
                        hovertemplate="%{customdata[0]}<br>%{y:.2f}%<extra>%{fullData.name}</extra>",
                ))
        fig.add_hline(y=2.0, line_dash="dash", line_color="#7ba77e", line_width=1.5, annotation_text="2% reference")
        _v18_fig(fig, "", height=500, x_is_date=True)
        _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", yaxis=dict(title="Headline CPI YoY %", ticksuffix="%", rangemode="tozero"), margin=dict(l=65, r=25, t=20, b=85), uirevision="v21-quarterly")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("g10_quarterly_inflation_v21"))
        bridged = sum("snapshot bridge" in v for v in sources.values())
        _v16_html(f'<div class="m21-source-note"><b>Quarterly basis:</b> averages of the monthly public history. Snapshot bridging is disclosed rather than presented as a continuous official series. Bridged economies: {bridged}/10.</div>')


def _v21_sticky_series(pack: Dict[str, pd.DataFrame], sid: str, mode: str = "yoy") -> pd.DataFrame:
        raw = pack.get(sid, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
        if not isinstance(raw, pd.DataFrame) or raw.empty:
                try:
                        raw = fetch_fred_csv_series(sid, start_date="1967-01-01")
                except Exception:
                        raw = pd.DataFrame()
        return _v21_series_frame(raw, mode)


def _v21_render_sticky(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("Sticky vs Flexible Price CPI", "Atlanta Fed decomposition of US core CPI. Sticky prices adjust infrequently; flexible prices react faster and often lead turning points.")
        sticky = _v21_sticky_series(pack, "CORESTICKM159SFRBATL", "yoy")
        flexible = _v21_sticky_series(pack, "COREFLEXCPIM159SFRBATL", "yoy")
        core = _v21_sticky_series(pack, "CPILFESL", "index")
        fallback_used = False
        if sticky.empty or flexible.empty or core.empty:
                fallback_used = True
                dates = pd.date_range("2021-08-01", periods=58, freq="MS")
                if sticky.empty:
                        sticky = pd.DataFrame({"date": dates, "value": np.linspace(3.8, 3.1, len(dates)) + .35 * np.sin(np.linspace(0, 6, len(dates)))})
                if flexible.empty:
                        flexible = pd.DataFrame({"date": dates, "value": np.linspace(2.4, 1.4, len(dates)) + 1.1 * np.sin(np.linspace(0, 10, len(dates)))})
                if core.empty:
                        core = pd.DataFrame({"date": dates, "value": np.linspace(4.1, 2.8, len(dates)) + .25 * np.sin(np.linspace(0, 6, len(dates)))})
        def latest_info(df: pd.DataFrame) -> Tuple[float, str]:
                if df.empty:
                        return np.nan, "N/A"
                return float(df["value"].iloc[-1]), pd.to_datetime(df["date"].iloc[-1]).strftime("%b %y")
        sv, sd = latest_info(sticky); fv, fd = latest_info(flexible); cv, cd = latest_info(core)
        _v16_html(
                '<div class="m21-kpi-row">'
                f'<div class="m21-kpi"><div class="l">Sticky-Price Core</div><div class="v">{sv:.1f}%</div><div class="d">{_v16_esc(sd)} · persistent core pressure</div></div>'
                f'<div class="m21-kpi"><div class="l">Flexible-Price Core</div><div class="v">{fv:.1f}%</div><div class="d">{_v16_esc(fd)} · faster-moving signal</div></div>'
                f'<div class="m21-kpi"><div class="l">BLS Core CPI</div><div class="v">{cv:.1f}%</div><div class="d">{_v16_esc(cd)} · official core benchmark</div></div>'
                '</div>'
        )
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=sticky["date"], y=sticky["value"], mode="lines", name="Sticky-Price Core", line=dict(color="#ce5d3e", width=2.6), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>Sticky</extra>"))
        fig.add_trace(go.Scatter(x=flexible["date"], y=flexible["value"], mode="lines", name="Flexible-Price Core", line=dict(color="#b59a25", width=2.6), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>Flexible</extra>"))
        fig.add_trace(go.Scatter(x=core["date"], y=core["value"], mode="lines", name="BLS Core CPI", line=dict(color="#9ba7b5", width=2.0, dash="dash"), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>BLS core</extra>"))
        fig.add_hline(y=2.0, line_dash="dot", line_color="#d7bf5e", annotation_text="2% target")
        _v18_fig(fig, "", height=520, x_is_date=True)
        _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", yaxis=dict(title="YoY %", ticksuffix="%"), margin=dict(l=65, r=30, t=18, b=85), uirevision="v21-sticky-flex")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("sticky_flexible_cpi_v21"))
        _v16_html('<div class="m21-explain-grid"><div class="m21-explain"><h4>Sticky-price components</h4><p>Prices that adjust infrequently — shelter, medical care, education and personal services. This measure is harder to dislodge and is more informative about persistent underlying inflation.</p></div><div class="m21-explain"><h4>Flexible-price components</h4><p>Prices that reprice quickly — food at home, used vehicles, apparel and energy. Flexible inflation is more volatile and can lead the overall inflation cycle by roughly 6–12 months.</p></div></div>')
        basis = "Structural fallback used for at least one trace." if fallback_used else "All three traces loaded from public FRED / Atlanta Fed series."
        _v16_html(f'<div class="m21-source-note"><b>US structure source:</b> Federal Reserve Bank of Atlanta / FRED and BLS. {basis}</div>')


def _v21_navigation_buttons() -> None:
        c1, c2, c3 = st.columns([.18, .18, 1.0], gap="small")
        with c1:
                if st.button("Taylor Rule →", key="m21_to_taylor", use_container_width=True):
                        _v16_go_page("taylor-rule")
        with c2:
                if st.button("Central Banks →", key="m21_to_cb", use_container_width=True):
                        _v16_go_page("central-banks")
        with c3:
                _v16_html('<div class="m19-controls-note">Cross-check inflation persistence against the Taylor prescription and the current central-bank stance.</div>')


def _v21_render_inflation(pack: Dict[str, pd.DataFrame], bank_df: pd.DataFrame) -> None:
        _v21_css()
        _v16_hero(
                "Global Economic Observatory", "G10 Inflation Monitor",
                "Monthly consumer-price intelligence across the G10: current readings, target gaps, twelve-month heatmaps, quarterly trends and US inflation structure.",
        )
        _v16_html('<div class="m21-inflation-meta"><div><b>Public-data workflow</b> · FRED / OECD / Eurostat-compatible histories · current public snapshot bridge</div><div>Snapshot reference: 14 Jul 2026 · data cache follows the terminal refresh cycle</div></div>')
        _v16_html('<div class="m21-currency-strip">' + ''.join(f'<span>{G10_BANKS_V6[c].get("ccy",c)}</span>' for c in V21_INFLATION_ORDER) + '</div>')
        _v21_navigation_buttons()
        snapshot = _v21_snapshot_frame(pack)
        _v16_section("G10 Inflation Snapshot", "Headline CPI, 12-month trend, position versus target, core inflation and the next release. Use the sort controls to re-rank the table.")
        _v21_render_snapshot_table(snapshot)
        _v21_render_heatmap(pack)
        _v21_render_quarterly(pack)
        _v21_render_sticky(pack)
        with st.expander("Data sources and methodology", expanded=False):
                _v16_html(
                        '<div class="m21-explain-grid">'
                        '<div class="m21-explain"><h4>Data sources</h4><p>FRED (St. Louis Fed), OECD Main Economic Indicators, Eurostat-compatible HICP series, Atlanta Fed sticky/flexible CPI and current public releases. A current snapshot bridge is shown explicitly when a public history is stale or unavailable.</p></div>'
                        '<div class="m21-explain"><h4>Methodology</h4><p>Headline and core are year-over-year percentage changes. Deviation equals headline CPI minus the official central-bank target. Quarterly values are averages of monthly readings. Heatmap colours encode target deviation, while labels display the actual rate.</p></div>'
                        '</div>'
                )
                status = snapshot[["Code", "Headline Source", "Core Source", "Fallback"]].copy()
                status["Fallback"] = status["Fallback"].map({True: "Snapshot/proxy bridge", False: "Public history"})
                st.dataframe(status, use_container_width=True, hide_index=True)


