def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
        """V21 renderer — V20 stability plus a content-complete G10 Inflation Monitor."""
        _v12_css(); _v13_css(); _v14_css(); _v15_css(); _v16_css(); _v17_css(); _v18_css(); _v19_css(); _v20_css(); _v21_css(); _v12_init_state()
        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
