def _v22_colour_for_deviation(dev: float) -> Tuple[str, str]:
        if not np.isfinite(dev):
                return "#121b26", "#667587"
        if dev < -1.5:
                return "#7d6b18", "#f7f3db"
        if dev < -0.5:
                return "#9c8625", "#fff8d5"
        if dev <= 0.25:
                return "#7ea07e", "#07120c"
        if dev <= 0.75:
                return "#b6a34f", "#111008"
        if dev <= 1.5:
                return "#ca8b59", "#160d08"
        return "#ce5d3e", "#180805"


def _v22_interpolated_trend(values: List[Optional[float]], final_value: float) -> List[float]:
        arr = pd.Series([np.nan if v is None else float(v) for v in values], dtype="float64")
        if arr.notna().sum() == 0:
                return [float(final_value)] * 12
        arr = arr.interpolate(limit_direction="both")
        arr.iloc[-1] = float(final_value)
        return arr.astype(float).tolist()


def _v22_snapshot_frame(pack: Dict[str, pd.DataFrame]) -> pd.DataFrame:
        rows: List[Dict[str, Any]] = []
        for code in V22_SNAPSHOT_ORDER:
                spec = G10_BANKS_V6.get(code, {})
                snap = V22_INFLATION_SNAPSHOT[code]
                headline = float(snap["headline"])
                core = float(snap["core"])
                target = float(spec.get("target", 2.0))
                trend = _v22_interpolated_trend(V22_HEADLINE_HEATMAP.get(code, []), headline)
                _, head_sid = _v21_public_series(pack, code, "headline")
                _, core_sid = _v21_public_series(pack, code, "core")
                rows.append({
                        "Code": code,
                        "Rank": 0,
                        "Country": spec.get("country", code),
                        "Flag": spec.get("flag", ""),
                        "Bank": spec.get("name", code),
                        "Target": target,
                        "Headline": headline,
                        "Core": core,
                        "Change": float(snap["change"]),
                        "Deviation": headline - target,
                        "Trend": trend,
                        "Headline Source": f"Current public snapshot · history {head_sid}",
                        "Core Source": f"Current public snapshot · history {core_sid}",
                        "Fallback": True,
                        "Next Date": pd.to_datetime(snap["next_date"]),
                        "Next Label": snap["next_label"],
                        "Colour": spec.get("colour", "#6baed6"),
                })
        out = pd.DataFrame(rows).sort_values(["Deviation", "Headline"], ascending=[False, False]).reset_index(drop=True)
        out["Rank"] = np.arange(1, len(out) + 1)
        return out


def _v22_core_months(pack: Dict[str, pd.DataFrame], code: str) -> Tuple[List[Optional[float]], str, bool]:
        public, sid = _v21_public_series(pack, code, "core")
        lookup: Dict[pd.Period, float] = {}
        if isinstance(public, pd.DataFrame) and not public.empty:
                use = public.copy()
                use["month"] = pd.to_datetime(use["date"], errors="coerce").dt.to_period("M")
                use = use.dropna(subset=["month", "value"]).drop_duplicates("month", keep="last")
                lookup = {r["month"]: float(r["value"]) for _, r in use.iterrows() if np.isfinite(r["value"])}
        snap = V22_INFLATION_SNAPSHOT[code]
        headline = np.asarray([np.nan if v is None else float(v) for v in V22_HEADLINE_HEATMAP[code]], dtype=float)
        headline_latest = float(snap["headline"])
        core_latest = float(snap["core"])
        proxy = core_latest + 0.30 * (headline - headline_latest)
        values: List[Optional[float]] = []
        proxy_used = False
        for i, dt in enumerate(V22_HEATMAP_MONTHS):
                key = dt.to_period("M")
                if key in lookup and np.isfinite(lookup[key]):
                        values.append(float(lookup[key]))
                elif np.isfinite(proxy[i]):
                        values.append(float(np.clip(proxy[i], -3.0, 15.0)))
                        proxy_used = True
                else:
                        values.append(None)
                        proxy_used = True
        # The current public reading is the authoritative Latest value, not a synthetic interpolation.
        for i in range(len(values) - 1, -1, -1):
                if values[i] is not None:
                        values[i] = core_latest
                        break
        return values, sid if sid else "Public core history", proxy_used


def _v22_heatmap_payload(pack: Dict[str, pd.DataFrame], kind: str) -> Tuple[Dict[str, List[Optional[float]]], Dict[str, str], Dict[str, bool]]:
        values: Dict[str, List[Optional[float]]] = {}
        sources: Dict[str, str] = {}
        proxies: Dict[str, bool] = {}
        for code in V22_HEATMAP_ORDER:
                if kind == "headline":
                        values[code] = list(V22_HEADLINE_HEATMAP[code])
                        sources[code] = "Current public monthly panel"
                        proxies[code] = False
                else:
                        vals, source, proxy = _v22_core_months(pack, code)
                        values[code] = vals
                        sources[code] = source
                        proxies[code] = proxy
        return values, sources, proxies


def _v22_render_heatmap(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("12-Month CPI Heatmap", "Colour intensity encodes deviation from each country's central-bank target. Numbers show the actual YoY reading.")
        mode = st.radio("Heatmap series", ["Headline CPI", "Core CPI"], horizontal=True, key="m22_heatmap_mode")
        kind = "headline" if mode == "Headline CPI" else "core"
        values, sources, proxies = _v22_heatmap_payload(pack, kind)
        headers = [d.strftime("%b<br><span>%y</span>") for d in V22_HEATMAP_MONTHS]
        html: List[str] = ['<div class="m22-heat-wrap"><div class="m22-heat-grid">']
        html.append('<div class="m22-hcell">Country</div>')
        for label in headers:
                html.append(f'<div class="m22-hcell">{label}</div>')
        html.append('<div class="m22-hcell">Latest</div>')
        csv_rows: List[Dict[str, Any]] = []
        for code in V22_HEATMAP_ORDER:
                spec = G10_BANKS_V6[code]
                row_vals = values[code]
                target = float(spec.get("target", 2.0))
                proxy_badge = '<span class="m22-source-badge">proxy</span>' if proxies.get(code, False) else ''
                html.append(f'<div class="m22-label" title="{_v16_esc(sources.get(code, ""))}"><span>{_v16_esc(spec.get("flag", ""))}</span><div>{_v16_esc(code)}{proxy_badge}<small>{_v16_esc(spec.get("country", code))}</small></div></div>')
                csv_row: Dict[str, Any] = {"Country": spec.get("country", code), "Code": code}
                for dt, val in zip(V22_HEATMAP_MONTHS, row_vals):
                        label = dt.strftime("%b %Y")
                        csv_row[label] = val
                        if val is None or not np.isfinite(val):
                                html.append(f'<div class="m22-cell missing" title="{_v16_esc(code)} · {label} · unavailable">—</div>')
                        else:
                                dev = float(val) - target
                                bg, fg = _v22_colour_for_deviation(dev)
                                tip = f"{code} · {label} · {kind.title()} {float(val):.1f}% · target {target:.1f}% · deviation {dev:+.1f}pp"
                                html.append(f'<div class="m22-cell" style="background:{bg};color:{fg}" title="{_v16_esc(tip)}">{float(val):.1f}</div>')
                latest = float(V22_INFLATION_SNAPSHOT[code]["headline" if kind == "headline" else "core"])
                csv_row["Latest"] = latest
                html.append(f'<div class="m22-latest">{latest:.1f}%</div>')
                csv_rows.append(csv_row)
        html.append('</div></div>')
        _v16_html(''.join(html))
        _v16_html('<div class="m21-scale"><span><i style="background:#7d6b18"></i>&lt; −1.5pp</span><span><i style="background:#9c8625"></i>−1.5 to −0.5pp</span><span><i style="background:#7ea07e"></i>±0.25pp</span><span><i style="background:#b6a34f"></i>+0.25 to +0.75pp</span><span><i style="background:#ca8b59"></i>+0.75 to +1.5pp</span><span><i style="background:#ce5d3e"></i>&gt; +1.5pp</span></div>')
        proxy_count = sum(1 for v in proxies.values() if v)
        note = "No proxy rows." if proxy_count == 0 else f"Rows marked proxy use a transparent public-history bridge for missing core months: {proxy_count}/10."
        _v16_html(f'<div class="m21-source-note"><b>Heatmap basis:</b> monthly values run from Jul 2025 to Jun 2026, with an explicit Latest column. {note}</div>')
        try:
                csv_data = pd.DataFrame(csv_rows).to_csv(index=False).encode("utf-8")
                st.download_button("Download heatmap CSV", csv_data, file_name=f"g10_{kind}_inflation_heatmap.csv", mime="text/csv", key=f"m22_heatmap_csv_{kind}")
        except Exception:
                pass


def _v22_monthly_history(pack: Dict[str, pd.DataFrame], code: str) -> Tuple[pd.DataFrame, str, bool]:
        public, sid = _v21_public_series(pack, code, "headline")
        recent = pd.DataFrame({"date": V22_HEATMAP_MONTHS, "value": V22_HEADLINE_HEATMAP[code]}).dropna(subset=["value"])
        if public.empty:
                return recent.reset_index(drop=True), "Current public monthly panel", True
        use = pd.concat([public[["date", "value"]], recent], ignore_index=True)
        use["date"] = pd.to_datetime(use["date"], errors="coerce")
        use["month"] = use["date"].dt.to_period("M")
        use = use.dropna(subset=["date", "value", "month"]).sort_values("date").drop_duplicates("month", keep="last").drop(columns="month")
        return use.reset_index(drop=True), f"{sid} + current monthly panel", True


def _v22_quarterly_frame(pack: Dict[str, pd.DataFrame]) -> Tuple[pd.DataFrame, Dict[str, str]]:
        frames: List[pd.DataFrame] = []
        sources: Dict[str, str] = {}
        for code in V22_HEATMAP_ORDER:
                series, source, bridged = _v22_monthly_history(pack, code)
                if series.empty:
                        continue
                use = series.copy()
                use["date"] = pd.to_datetime(use["date"], errors="coerce")
                use = use.dropna(subset=["date", "value"])
                use = use[(use["date"] >= pd.Timestamp("2024-04-01")) & (use["date"] <= pd.Timestamp("2026-06-30"))]
                if use.empty:
                        continue
                use["Quarter"] = use["date"].dt.to_period("Q")
                q = use.groupby("Quarter", as_index=False)["value"].mean()
                q = q[(q["Quarter"] >= pd.Period("2024Q2")) & (q["Quarter"] <= pd.Period("2026Q2"))]
                q["Quarter Label"] = q["Quarter"].astype(str).str.replace("Q", " Q", regex=False)
                q["Code"] = code
                frames.append(q[["Quarter", "Quarter Label", "Code", "value"]])
                sources[code] = source + (" · bridged" if bridged else "")
        empty = pd.DataFrame(columns=["Quarter", "Quarter Label", "Code", "value"])
        return (pd.concat(frames, ignore_index=True) if frames else empty), sources


def _v22_render_quarterly(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("G10 Inflation — Quarterly Overview", "Quarterly averages of monthly headline CPI YoY readings. Toggle economies with the selector or directly from the chart legend.")
        qdf, sources = _v22_quarterly_frame(pack)
        if qdf.empty:
                _v16_html('<div class="m16-warning">Quarterly inflation history unavailable.</div>')
                return
        options = V22_HEATMAP_ORDER
        c1, c2, c3 = st.columns([5.5, .8, .8], gap="small")
        with c1:
                selected = st.multiselect("Countries", options, default=options, key="m22_quarterly_countries")
        with c2:
                if st.button("All", key="m22_q_all", use_container_width=True):
                        st.session_state["m22_quarterly_countries"] = options
                        st.rerun()
        with c3:
                if st.button("US only", key="m22_q_us", use_container_width=True):
                        st.session_state["m22_quarterly_countries"] = ["FED"]
                        st.rerun()
        selected = selected or options
        quarter_order = [str(pd.Period(f"{year}Q{q}")) for year, q in [(2024,2),(2024,3),(2024,4),(2025,1),(2025,2),(2025,3),(2025,4),(2026,1),(2026,2)]]
        quarter_labels = [x.replace("Q", " Q") for x in quarter_order]
        fig = go.Figure()
        for code in selected:
                use = qdf[qdf["Code"] == code].copy()
                if use.empty:
                        continue
                spec = G10_BANKS_V6[code]
                mapping = dict(zip(use["Quarter"].astype(str), use["value"]))
                ys = [mapping.get(q, np.nan) for q in quarter_order]
                fig.add_trace(go.Scatter(
                        x=quarter_labels, y=ys, mode="lines+markers", name=f"{spec.get('flag','')} {code}",
                        line=dict(color=spec.get("colour", "#6baed6"), width=2.25), marker=dict(size=6),
                        hovertemplate="%{x}<br>%{y:.2f}%<extra>%{fullData.name}</extra>",
                ))
        fig.add_hline(y=2.0, line_dash="dash", line_color="#7ba77e", line_width=1.5, annotation_text="2% reference")
        _v18_fig(fig, "", height=510, x_is_date=False)
        _v20_remove_plotly_title(fig)
        fig.update_layout(
                hovermode="x unified", yaxis=dict(title="Headline CPI YoY %", ticksuffix="%", range=[0, 8]),
                xaxis=dict(categoryorder="array", categoryarray=quarter_labels), margin=dict(l=65, r=25, t=15, b=80),
                uirevision="v22-quarterly",
        )
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("g10_quarterly_inflation_v22"))
        bridged = sum("bridged" in s for s in sources.values())
        _v16_html(f'<div class="m21-source-note"><b>Quarterly basis:</b> 2024 Q2 to 2026 Q2 only; the incomplete 2026 Q3 quarter is excluded. Monthly public histories are averaged by quarter. Bridged economies: {bridged}/10.</div>')


def _v22_render_sticky(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_section("Sticky vs Flexible Price CPI", "Atlanta Fed decomposition of US core CPI. Sticky prices adjust infrequently; flexible prices react faster and often lead turning points by 6–12 months.")
        sticky = _v21_sticky_series(pack, "CORESTICKM159SFRBATL", "yoy")
        flexible = _v21_sticky_series(pack, "COREFLEXCPIM159SFRBATL", "yoy")
        core = _v21_sticky_series(pack, "CPILFESL", "index")
        fallback_used = False
        if sticky.empty or flexible.empty or core.empty:
                fallback_used = True
                dates = pd.date_range("2021-08-01", periods=59, freq="MS")
                if sticky.empty:
                        sticky = pd.DataFrame({"date": dates, "value": np.linspace(3.8, 3.1, len(dates)) + .35 * np.sin(np.linspace(0, 6, len(dates)))})
                if flexible.empty:
                        flexible = pd.DataFrame({"date": dates, "value": np.linspace(2.4, 1.4, len(dates)) + 1.1 * np.sin(np.linspace(0, 10, len(dates)))})
                if core.empty:
                        core = pd.DataFrame({"date": dates, "value": np.linspace(4.1, 2.8, len(dates)) + .25 * np.sin(np.linspace(0, 6, len(dates)))})
        def latest_info(df: pd.DataFrame) -> Tuple[float, str]:
                if df.empty:
                        return np.nan, "N/A"
                return float(df["value"].iloc[-1]), pd.to_datetime(df["date"].iloc[-1]).strftime("%b %y")
        sv, sd = latest_info(sticky); fv, fd = latest_info(flexible); cv, cd = latest_info(core)
        _v16_html(
                '<div class="m21-kpi-row">'
                f'<div class="m21-kpi"><div class="l">Sticky-Price Core</div><div class="v">{sv:.1f}%</div><div class="d">{_v16_esc(sd)} · persistent signal</div></div>'
                f'<div class="m21-kpi"><div class="l">Flexible-Price Core</div><div class="v">{fv:.1f}%</div><div class="d">{_v16_esc(fd)} · faster-moving signal</div></div>'
                f'<div class="m21-kpi"><div class="l">BLS Core CPI</div><div class="v">{cv:.1f}%</div><div class="d">{_v16_esc(cd)} · official benchmark</div></div>'
                '</div>'
        )
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=sticky["date"], y=sticky["value"], mode="lines", name="Sticky-Price Core", line=dict(color="#ce5d3e", width=2.6), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>Sticky</extra>"))
        fig.add_trace(go.Scatter(x=flexible["date"], y=flexible["value"], mode="lines", name="Flexible-Price Core", line=dict(color="#b59a25", width=2.6), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>Flexible</extra>"))
        fig.add_trace(go.Scatter(x=core["date"], y=core["value"], mode="lines", name="BLS Core CPI", line=dict(color="#9ba7b5", width=2.0, dash="dash"), hovertemplate="%{x|%b %Y}<br>%{y:.2f}%<extra>BLS core</extra>"))
        fig.add_hline(y=2.0, line_dash="dot", line_color="#d7bf5e", annotation_text="2% target")
        _v18_fig(fig, "", height=520, x_is_date=True)
        _v20_remove_plotly_title(fig)
        latest_date = max(pd.to_datetime(x["date"].max()) for x in (sticky, flexible, core) if not x.empty)
        start_date = latest_date - pd.DateOffset(years=5)
        fig.update_layout(hovermode="x unified", yaxis=dict(title="YoY %", ticksuffix="%"), margin=dict(l=65, r=30, t=15, b=85), uirevision="v22-sticky-flex")
        fig.update_xaxes(range=[start_date, latest_date])
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("sticky_flexible_cpi_v22"))
        _v16_html('<div class="m21-explain-grid"><div class="m21-explain"><h4>Sticky-price components</h4><p>Prices that adjust infrequently — shelter, medical care, education and personal services. Sticky inflation is harder to dislodge and is more informative about persistent underlying pressure.</p></div><div class="m21-explain"><h4>Flexible-price components</h4><p>Prices that reprice quickly — food at home, used vehicles, apparel and energy. Flexible inflation is volatile and can lead the broader cycle by roughly 6–12 months.</p></div></div>')
        basis = "Structural fallback used for at least one trace." if fallback_used else "All three traces loaded from public FRED / Atlanta Fed series."
        _v16_html(f'<div class="m21-source-note"><b>US structure source:</b> Federal Reserve Bank of Atlanta / FRED and BLS. The default window is the latest five years; Max retains the complete history. {basis}</div>')


def _v22_about_cards() -> None:
        _v16_html(
                '<div class="m22-about-grid">'
                '<div class="m22-about-card"><h4>About</h4><p>G10 Inflation Monitor is a monthly consumer-price workspace covering current readings, target gaps, monthly heatmaps, quarterly trends and the US sticky/flexible inflation structure.</p></div>'
                '<div class="m22-about-card"><h4>Data sources</h4><p>FRED, OECD Main Economic Indicators, Eurostat-compatible HICP series, national statistics releases and the Federal Reserve Bank of Atlanta. Snapshot bridges are disclosed rather than hidden.</p></div>'
                '<div class="m22-about-card"><h4>Methodology</h4><p>Headline and core CPI are year-over-year changes. Deviation equals headline CPI minus the official target. Quarterly figures are arithmetic averages of available monthly readings.</p></div>'
                '</div>'
        )


