        try:
                st.download_button("Download snapshot CSV", snapshot[["Country", "Code", "Headline", "Change", "Core", "Target", "Deviation", "Next Date", "Next Label"]].to_csv(index=False).encode("utf-8"), file_name="g10_inflation_snapshot.csv", mime="text/csv", key="m22_snapshot_csv")
        except Exception:
                pass
        _v22_render_heatmap(pack)
        _v22_render_quarterly(pack)
        _v22_render_sticky(pack)
        _v22_about_cards()
        with st.expander("Data sources and methodology — detailed coverage", expanded=False):
                status_rows = []
                for code in V22_SNAPSHOT_ORDER:
                        _, hs = _v21_public_series(pack, code, "headline")
                        _, cs = _v21_public_series(pack, code, "core")
                        _, _, cp = _v22_core_months(pack, code)
                        status_rows.append({"Code": code, "Headline history": hs, "Core history": cs, "Core bridge": "Yes" if cp else "No", "Snapshot date": V22_INFLATION_SNAPSHOT_DATE.date().isoformat()})
                st.dataframe(pd.DataFrame(status_rows), use_container_width=True, hide_index=True)


