def _v23_queue_quarterly(values: List[str]) -> None:
        """Queue a multiselect update without touching its instantiated widget key."""
        st.session_state["_m23_quarterly_pending"] = list(values)


def _v23_apply_quarterly_pending() -> None:
        pending = st.session_state.pop("_m23_quarterly_pending", None)
        if pending is not None:
                st.session_state["m22_quarterly_countries"] = list(pending)


def _v23_render_quarterly(pack: Dict[str, pd.DataFrame]) -> None:
        """V22 quarterly view with callback-safe All / US-only controls."""
        _v16_section("G10 Inflation — Quarterly Overview", "Quarterly averages of monthly headline CPI YoY readings. Toggle economies with the selector or directly from the chart legend.")
        qdf, sources = _v22_quarterly_frame(pack)
        if qdf.empty:
                _v16_html('<div class="m16-warning">Quarterly inflation history unavailable.</div>')
                return
        options = list(V22_HEATMAP_ORDER)
        _v23_apply_quarterly_pending()
        if "m22_quarterly_countries" not in st.session_state:
                st.session_state["m22_quarterly_countries"] = options
        c1, c2, c3 = st.columns([5.5, .8, .8], gap="small")
        with c1:
                selected = st.multiselect("Countries", options, default=options, key="m22_quarterly_countries")
        with c2:
                st.button("All", key="m23_q_all", use_container_width=True, on_click=_v23_queue_quarterly, args=(options,))
        with c3:
                st.button("US only", key="m23_q_us", use_container_width=True, on_click=_v23_queue_quarterly, args=(["FED"],))
        selected = list(selected or [])
        if not selected:
                _v16_html('<div class="m16-warning">Select at least one economy or use <b>All</b>.</div>')
                return
        quarter_order = [str(pd.Period(f"{year}Q{q}")) for year, q in [(2024,2),(2024,3),(2024,4),(2025,1),(2025,2),(2025,3),(2025,4),(2026,1),(2026,2)]]
        quarter_labels = [x.replace("Q", " Q") for x in quarter_order]
        fig = go.Figure()
        for code in selected:
                use = qdf[qdf["Code"] == code].copy()
                if use.empty:
                        continue
                spec = G10_BANKS_V6[code]
                mapping = dict(zip(use["Quarter"].astype(str), use["value"]))
                ys = [mapping.get(q, np.nan) for q in quarter_order]
                fig.add_trace(go.Scatter(
                        x=quarter_labels, y=ys, mode="lines+markers", name=f"{spec.get('flag','')} {code}",
                        line=dict(color=spec.get("colour", "#6baed6"), width=2.25), marker=dict(size=6),
                        hovertemplate="%{x}<br>%{y:.2f}%<extra>%{fullData.name}</extra>",
                ))
        fig.add_hline(y=2.0, line_dash="dash", line_color="#7ba77e", line_width=1.5, annotation_text="2% reference")
        _v18_fig(fig, "", height=510, x_is_date=False); _v20_remove_plotly_title(fig)
        fig.update_layout(
                hovermode="x unified", yaxis=dict(title="Headline CPI YoY %", ticksuffix="%", range=[0, 8]),
                xaxis=dict(categoryorder="array", categoryarray=quarter_labels), margin=dict(l=65, r=25, t=15, b=80),
                uirevision="v23-quarterly",
        )
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config("g10_quarterly_inflation_v23"))
        bridged = sum("bridged" in s for s in sources.values())
        _v16_html(f'<div class="m21-source-note"><b>Quarterly basis:</b> 2024 Q2 to 2026 Q2 only; the incomplete 2026 Q3 quarter is excluded. Monthly public histories are averaged by quarter. Bridged economies: {bridged}/10.</div>')


def _v23_queue_page(page: str) -> None:
        """Callback-safe internal page navigation; no URL/query-parameter routing."""
        st.session_state["macro_v12_page"] = _v12_normalize_page(page)
        st.session_state["macro_v12_route"] = "overview"
        st.session_state["macro_v12_bank_view"] = "overview"


def _v23_long_frame(metric: str = "GDP", current: bool = True) -> pd.DataFrame:
        data = (V23_GDP_FORECASTS if metric == "GDP" else V23_INFLATION_FORECASTS) if current else (V23_GDP_PRIOR if metric == "GDP" else V23_INFLATION_PRIOR)
        rows: List[Dict[str, Any]] = []
        for horizon, values in data.items():
                for code, value in values.items():
                        meta = V23_COUNTRY_META[code]
                        rows.append({"Metric": metric, "Horizon": horizon, "Code": code, "Country": meta["country"], "Value": float(value), "Target": float(meta["target"])})
        return pd.DataFrame(rows)


def _v23_revision(metric: str, horizon: str, code: str) -> Optional[float]:
        if horizon not in V23_ANNUAL_HORIZONS:
                return None
        current = V23_GDP_FORECASTS if metric == "GDP" else V23_INFLATION_FORECASTS
        prior = V23_GDP_PRIOR if metric == "GDP" else V23_INFLATION_PRIOR
        try:
                return round(float(current[horizon][code]) - float(prior[horizon][code]), 2)
        except Exception:
                return None


def _v23_revision_html(value: Optional[float]) -> str:
        if value is None:
                return ""
        if abs(value) < 0.005:
                return '<span class="rev flat">↔ 0.0pp</span>'
        cls = "up" if value > 0 else "down"
        arrow = "▲" if value > 0 else "▼"
        return f'<span class="rev {cls}">{arrow} {value:+.1f}pp</span>'


def _v23_forecast_table(metric: str) -> None:
        forecasts = V23_GDP_FORECASTS if metric == "GDP" else V23_INFLATION_FORECASTS
        title = "Real GDP Growth" if metric == "GDP" else "Inflation"
        subtitle = "Q4 2026 is a near-term sequential reading; full-year rows are annual averages." if metric == "GDP" else "Annual average, % — Eurozone uses HICP; AU/NZ quarterly CPI is synthesised to annual averages."
        _v16_section(title, subtitle)
        head = ['<div class="m23-table-wrap"><table class="m23-table"><thead><tr><th>Time period</th>']
        for code in V23_FORECAST_CODES:
                meta = V23_COUNTRY_META[code]
                head.append(f'<th><div class="country"><b>{meta["flag"]}</b><b>{_v16_esc(meta["country"])}</b><span>{code}</span></div></th>')
        head.append('</tr></thead><tbody>')
        body: List[str] = []
        for horizon in V23_FORECAST_HORIZONS:
                descriptor = "near-term" if horizon == "Q4 2026" else "annual average"
                body.append(f'<tr><td><b>{_v16_esc(horizon)}</b><span style="display:block;color:#718395;font-size:.61rem;margin-top:3px">{descriptor}</span></td>')
                for code in V23_FORECAST_CODES:
                        value = forecasts[horizon][code]
                        body.append(f'<td>{value:.1f}%{_v23_revision_html(_v23_revision(metric,horizon,code))}</td>')
                body.append('</tr>')
        _v16_html(''.join(head + body + ['</tbody></table></div>']))


def _v23_regime(code: str, horizon: str = "Full Year 2026") -> str:
        growth = V23_GDP_FORECASTS[horizon][code]
        gap = V23_INFLATION_FORECASTS[horizon][code] - V23_COUNTRY_META[code]["target"]
        if growth >= 1.8 and abs(gap) <= 0.35:
                return "Resilient / near target"
        if growth >= 1.8 and gap > 0.35:
                return "Reflation pressure"
        if growth < 1.2 and gap > 0.35:
                return "Stagflation watch"
        if growth < 1.2 and gap <= 0:
                return "Low-growth disinflation"
        if gap < -0.35:
                return "Below-target inflation"
        return "Moderate expansion"


def _v23_key_observations() -> List[str]:
        h = "Full Year 2026"
        top_growth = max(V23_FORECAST_CODES, key=lambda c: V23_GDP_FORECASTS[h][c])
        hot_infl = max(V23_FORECAST_CODES, key=lambda c: V23_INFLATION_FORECASTS[h][c] - V23_COUNTRY_META[c]["target"])
        largest_cut = min(V23_FORECAST_CODES, key=lambda c: _v23_revision("GDP", h, c) or 0.0)
        converged = sum(abs(V23_INFLATION_FORECASTS["Full Year 2028"][c] - V23_COUNTRY_META[c]["target"]) <= 0.30 for c in V23_FORECAST_CODES)
        return [
                f'{V23_COUNTRY_META[top_growth]["country"]} and the United States sit at the top of the 2026 G10 growth distribution at {V23_GDP_FORECASTS[h][top_growth]:.1f}%.',
                f'{V23_COUNTRY_META[hot_infl]["country"]} has the largest 2026 inflation overshoot versus its policy target ({V23_INFLATION_FORECASTS[h][hot_infl]-V23_COUNTRY_META[hot_infl]["target"]:+.1f}pp).',
                f'{V23_COUNTRY_META[largest_cut]["country"]} has the largest GDP downgrade versus the 24 May public synthesis ({_v23_revision("GDP",h,largest_cut):+.1f}pp).',
                f'{converged} of 10 economies are projected to be within ±0.3pp of their inflation target by 2028.',
        ]


def _v23_summary_kpis() -> None:
        h = "Full Year 2026"
        growth_vals = [V23_GDP_FORECASTS[h][c] for c in V23_FORECAST_CODES]
        inflation_vals = [V23_INFLATION_FORECASTS[h][c] for c in V23_FORECAST_CODES]
        revisions = [_v23_revision("GDP", h, c) or 0.0 for c in V23_FORECAST_CODES]
        converged = sum(abs(V23_INFLATION_FORECASTS["Full Year 2028"][c] - V23_COUNTRY_META[c]["target"]) <= .30 for c in V23_FORECAST_CODES)
        _v16_html(
                '<div class="m23-kpis">'
                f'<div class="m23-kpi"><div class="l">G10 median growth</div><div class="v">{np.median(growth_vals):.1f}%</div><div class="d">Full-year 2026 annual average</div></div>'
                f'<div class="m23-kpi"><div class="l">G10 median inflation</div><div class="v">{np.median(inflation_vals):.1f}%</div><div class="d">Full-year 2026 annual average</div></div>'
                f'<div class="m23-kpi"><div class="l">GDP revision breadth</div><div class="v">{sum(x>0 for x in revisions)}↑ / {sum(x<0 for x in revisions)}↓</div><div class="d">Current snapshot versus 24 May vintage</div></div>'
                f'<div class="m23-kpi"><div class="l">Target convergence</div><div class="v">{converged}/10</div><div class="d">Within ±0.3pp of target by 2028</div></div>'
                '</div>'
        )


def _v23_quadrant(horizon: str) -> None:
        rows = []
        for code in V23_FORECAST_CODES:
                meta = V23_COUNTRY_META[code]
                rows.append({"Code": code, "Country": meta["country"], "Growth": V23_GDP_FORECASTS[horizon][code], "Inflation Gap": V23_INFLATION_FORECASTS[horizon][code] - meta["target"], "Inflation": V23_INFLATION_FORECASTS[horizon][code], "Regime": _v23_regime(code, horizon)})
        df = pd.DataFrame(rows)
        median_growth = float(df["Growth"].median())
        fig = go.Figure()
        for _, row in df.iterrows():
                spec = G10_BANKS_V6.get(row["Code"], {})
                fig.add_trace(go.Scatter(
                        x=[row["Growth"]], y=[row["Inflation Gap"]], mode="markers+text", name=f'{spec.get("flag","")} {row["Code"]}',
                        text=[row["Code"]], textposition="top center", marker=dict(size=14, color=spec.get("colour", "#6baed6"), line=dict(width=1, color="#dfe6ec")),
                        customdata=[[row["Country"], row["Inflation"], row["Regime"]]],
                        hovertemplate="%{customdata[0]}<br>Growth %{x:.1f}%<br>Inflation %{customdata[1]:.1f}%<br>Gap %{y:+.1f}pp<br>%{customdata[2]}<extra></extra>",
                ))
        fig.add_vline(x=median_growth, line_dash="dot", line_color="#708394", annotation_text="G10 median growth")
        fig.add_hline(y=0, line_dash="dash", line_color="#d0b44f", annotation_text="At target")
        _v18_fig(fig, "", height=520, x_is_date=False); _v20_remove_plotly_title(fig)
        fig.update_layout(xaxis=dict(title="Real GDP growth %"), yaxis=dict(title="Inflation gap vs target (pp)"), hovermode="closest", margin=dict(l=70,r=30,t=15,b=70), uirevision=f"v23-quadrant-{horizon}")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"growth_inflation_quadrant_{horizon}"))


def _v23_country_detail(code: str) -> None:
        meta = V23_COUNTRY_META[code]
        horizons = V23_ANNUAL_HORIZONS
        g = [V23_GDP_FORECASTS[h][code] for h in horizons]
        inf = [V23_INFLATION_FORECASTS[h][code] for h in horizons]
        rev_g = [_v23_revision("GDP", h, code) or 0.0 for h in horizons]
        rev_i = [_v23_revision("Inflation", h, code) or 0.0 for h in horizons]
        _v16_html(f'<div class="m23-detail"><h3>{meta["flag"]} {_v16_esc(meta["country"])} Outlook</h3><p>{_v16_esc(meta["sources"])} · target {meta["target"]:.1f}%</p><span class="m23-regime">{_v16_esc(_v23_regime(code))}</span></div>')
        _v16_html(
                '<div class="m23-kpis">'
                f'<div class="m23-kpi"><div class="l">2026 GDP</div><div class="v">{g[0]:.1f}%</div><div class="d">Revision {rev_g[0]:+.1f}pp vs 24 May</div></div>'
                f'<div class="m23-kpi"><div class="l">2026 Inflation</div><div class="v">{inf[0]:.1f}%</div><div class="d">{inf[0]-meta["target"]:+.1f}pp versus target</div></div>'
                f'<div class="m23-kpi"><div class="l">2028 Growth</div><div class="v">{g[-1]:.1f}%</div><div class="d">Medium-term annual average</div></div>'
                f'<div class="m23-kpi"><div class="l">2028 Inflation gap</div><div class="v">{inf[-1]-meta["target"]:+.1f}pp</div><div class="d">Convergence to official target</div></div>'
                '</div>'
        )
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=horizons, y=g, mode="lines+markers", name="Real GDP", line=dict(color="#73bdf2", width=3), marker=dict(size=8), hovertemplate="%{x}<br>%{y:.1f}%<extra>GDP</extra>"))
        fig.add_trace(go.Scatter(x=horizons, y=inf, mode="lines+markers", name="Inflation", line=dict(color="#d2b54a", width=3), marker=dict(size=8), hovertemplate="%{x}<br>%{y:.1f}%<extra>Inflation</extra>"))
        fig.add_hline(y=meta["target"], line_dash="dot", line_color="#7ba77e", annotation_text=f'Target {meta["target"]:.1f}%')
        _v18_fig(fig, "", height=450, x_is_date=False); _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", yaxis=dict(title="Annual average %", ticksuffix="%"), margin=dict(l=65,r=25,t=15,b=70), uirevision=f"v23-country-{code}")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"country_outlook_{code}"))
        rev_df = pd.DataFrame({"Horizon": horizons, "GDP Revision pp": rev_g, "Inflation Revision pp": rev_i})
        st.dataframe(rev_df, use_container_width=True, hide_index=True)


def _v23_revision_workspace() -> None:
        c1, c2 = st.columns(2, gap="small")
        with c1:
                metric = st.radio("Revision metric", ["GDP", "Inflation"], horizontal=True, key="m23_revision_metric")
        with c2:
                horizon = st.selectbox("Revision horizon", V23_ANNUAL_HORIZONS, key="m23_revision_horizon")
        current = V23_GDP_FORECASTS if metric == "GDP" else V23_INFLATION_FORECASTS
        prior = V23_GDP_PRIOR if metric == "GDP" else V23_INFLATION_PRIOR
        rows = []
        for code in V23_FORECAST_CODES:
                rows.append({"Code": code, "Country": V23_COUNTRY_META[code]["country"], "Prior": prior[horizon][code], "Current": current[horizon][code], "Revision": round(current[horizon][code]-prior[horizon][code],2)})
        df = pd.DataFrame(rows).sort_values("Revision")
        colors = ["#5dbb87" if x >= 0 else "#d8665b" for x in df["Revision"]]
        fig = go.Figure(go.Bar(x=df["Revision"], y=[f'{V23_COUNTRY_META[c]["flag"]} {c}' for c in df["Code"]], orientation="h", marker_color=colors, text=[f'{x:+.1f}pp' for x in df["Revision"]], textposition="outside", customdata=df[["Country","Prior","Current"]].to_numpy(), hovertemplate="%{customdata[0]}<br>Prior %{customdata[1]:.1f}%<br>Current %{customdata[2]:.1f}%<br>Revision %{x:+.1f}pp<extra></extra>"))
        fig.add_vline(x=0, line_color="#798a9a", line_width=1)
        _v18_fig(fig, "", height=500, x_is_date=False); _v20_remove_plotly_title(fig)
        fig.update_layout(xaxis=dict(title="Revision (percentage points)"), yaxis=dict(title=""), margin=dict(l=110,r=45,t=15,b=65), uirevision=f"v23-revisions-{metric}-{horizon}")
        st.plotly_chart(fig, use_container_width=True, config=_v18_plot_config(f"forecast_revisions_{metric}_{horizon}"))
        st.dataframe(df, use_container_width=True, hide_index=True)
        _v16_html(f'<div class="m23-note"><b>Revision basis:</b> current public synthesis versus the {V23_PRIOR_VINTAGE.strftime("%d %b %Y")} public institutional vintage. Revisions measure forecast changes, not statistical uncertainty.</div>')


def _v23_sources_workspace() -> None:
        _v16_html(
                '<div class="m23-source-grid">'
                '<div class="m23-source"><h4>Global institutions</h4><p>Cross-country baseline and consistency checks.</p><span class="tag">IMF WEO</span><span class="tag">OECD Economic Outlook</span><span class="tag">World Bank GEP</span></div>'
                '<div class="m23-source"><h4>United States</h4><p>Growth, inflation and policy projections.</p><span class="tag">FOMC SEP</span><span class="tag">CBO</span><span class="tag">IMF</span><span class="tag">OECD</span></div>'
                '<div class="m23-source"><h4>Eurozone & United Kingdom</h4><p>Official staff and fiscal projections.</p><span class="tag">ECB Staff</span><span class="tag">ECB SPF</span><span class="tag">OBR</span></div>'
                '<div class="m23-source"><h4>Other G10 central banks</h4><p>National monetary-policy reports and outlook publications.</p><span class="tag">BoC MPR</span><span class="tag">RBA SoMP</span><span class="tag">RBNZ MPS</span><span class="tag">BoJ Outlook</span><span class="tag">Riksbank</span><span class="tag">SNB</span><span class="tag">Norges</span></div>'
                '</div>'
        )
        rows = []
        for code in V23_FORECAST_CODES:
                meta = V23_COUNTRY_META[code]
                rows.append({"Code": code, "Economy": meta["country"], "Primary source mix": meta["sources"], "Current vintage": V23_OUTLOOK_ASOF.date().isoformat(), "Prior vintage": V23_PRIOR_VINTAGE.date().isoformat(), "Update cycle": "Quarterly / release-driven"})
        st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)
        _v16_html('<div class="m23-note"><b>Methodology:</b> single-point public institutional projections are combined using a median when sources differ. Q4 2026 is kept separate from annual averages. Forecasts are not real-time market consensus and can lag current conditions between official projection rounds.</div>')


def _v23_downloads() -> None:
        current = pd.concat([_v23_long_frame("GDP", True), _v23_long_frame("Inflation", True)], ignore_index=True)
        prior = pd.concat([_v23_long_frame("GDP", False), _v23_long_frame("Inflation", False)], ignore_index=True)
        try:
                c1, c2 = st.columns(2, gap="small")
                with c1:
                        st.download_button("Download current forecast CSV", current.to_csv(index=False).encode("utf-8"), file_name="g10_consensus_forecasts_current.csv", mime="text/csv", key="m23_current_csv", use_container_width=True)
                with c2:
                        st.download_button("Download revision vintage CSV", prior.to_csv(index=False).encode("utf-8"), file_name="g10_consensus_forecasts_prior_vintage.csv", mime="text/csv", key="m23_prior_csv", use_container_width=True)
        except Exception:
                pass


def _v23_render_outlook() -> None:
        _v23_css()
        _v16_hero("Economic Outlook", "Consensus Forecasts — GDP & Inflation", "Median public-institution forecasts across the G10, with transparent vintages, revision diagnostics and policy read-through.")
        _v16_html(
                '<div class="m23-meta">'
                f'<div><strong>Updated {V23_OUTLOOK_ASOF.strftime("%d %b %Y, %H:%M")}</strong> · IMF / OECD / central-bank projection synthesis</div>'
                '<div>Quarterly update cycle · figures may lag current conditions between official releases</div>'
                '</div>'
        )
        _v16_html('<div class="m23-callout"><b>Forecast convention:</b> Full-year rows are annual averages. Q4 2026 is a near-term sequential reading and should not be compared mechanically with the annual rows. Revisions compare the current reference snapshot with the 24 May 2026 public synthesis.</div>')
        cnav1, cnav2, cnav3 = st.columns([1,1,4], gap="small")
        with cnav1:
                st.button("Inflation →", key="m23_to_inflation", use_container_width=True, on_click=_v23_queue_page, args=("inflation",))
        with cnav2:
                st.button("Taylor Rule →", key="m23_to_taylor", use_container_width=True, on_click=_v23_queue_page, args=("taylor-rule",))
        with cnav3:
                _v16_html('<div class="m23-note" style="margin:0">Use Inflation for the live price snapshot and Taylor Rule for the implied-rate read-through.</div>')
        view = st.radio("Outlook workspace", ["Overview", "Country Detail", "Revisions", "Sources"], horizontal=True, key="m23_outlook_view")
        if view == "Overview":
                _v23_summary_kpis()
                _v23_forecast_table("GDP")
                _v23_forecast_table("Inflation")
                obs = ''.join(f'<li>{_v16_esc(x)}</li>' for x in _v23_key_observations())
                _v16_html(f'<div class="m23-obs"><h4>Key observations</h4><ol>{obs}</ol></div>')
                horizon = st.selectbox("Growth–inflation map horizon", V23_ANNUAL_HORIZONS, key="m23_quadrant_horizon")
                _v16_section("Growth–Inflation Regime Map", "A policy-oriented extension: growth on the horizontal axis and inflation deviation from target on the vertical axis.")
                _v23_quadrant(horizon)
                _v23_downloads()
        elif view == "Country Detail":
                labels = [f'{V23_COUNTRY_META[c]["flag"]} {V23_COUNTRY_META[c]["country"]}' for c in V23_FORECAST_CODES]
                selected_label = st.selectbox("Economy", labels, key="m23_country_detail")
                code = V23_FORECAST_CODES[labels.index(selected_label)]
                _v23_country_detail(code)
        elif view == "Revisions":
                _v16_section("Forecast Revisions", "Current public-institution synthesis versus the prior May vintage. Positive values are upgrades; negative values are downgrades.")
                _v23_revision_workspace()
        else:
                _v16_section("Primary Sources & Methodology", "Public institutional projections, source mix, vintage discipline and update cadence.")
                _v23_sources_workspace()


# Activate V23 fixes and the new consensus workspace without altering other V22 pages.
_v22_render_quarterly = _v23_render_quarterly
_v16_render_outlook = _v23_render_outlook


def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
        """V23 renderer — V22 inflation parity, callback-safe quarterly controls and a full consensus outlook workspace."""
        _v12_css(); _v13_css(); _v14_css(); _v15_css(); _v16_css(); _v17_css(); _v18_css(); _v19_css(); _v20_css(); _v21_css(); _v22_css(); _v23_css(); _v12_init_state()
        page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
        selected_code = str(st.session_state.get("macro_v12_bank", "FED")).upper().strip()
        if selected_code not in G10_BANKS_V6:
                selected_code = "FED"; st.session_state["macro_v12_bank"] = selected_code
        if page != "central-banks":
                st.session_state["macro_v12_route"] = "overview"
        with st.spinner("Loading macro desk data…"):
                try: pack = build_macro_pack_cached("2000-01-01", True)
                except Exception: pack = {}
                try: proxy_pack = fetch_market_proxy_pack("2y")
                except Exception: proxy_pack = {}
                try: indicator_df = compute_indicator_table(pack)
                except Exception: indicator_df = pd.DataFrame()
                policy_pack = _v19_merge_pack(pack, _v19_load_policy_pack("1990-01-01"))
                bank_df = _v19_bank_df(policy_pack)
        _v16_html('<div class="m16-shell">')
        try:
                _v16_topbar(page)
                _v16_render_page(page, selected_code, policy_pack, proxy_pack, indicator_df, bank_df)
                _v16_html('<div class="m16-footer">Macro V23 · callback-safe inflation quarterly controls + institutional consensus forecasts. V20 routing, Policy Stance, Payrolls and Central Banks remain unchanged.</div>')
        finally:
                _v16_html('</div>')

