def _v25_series(name: str, frequency: str, unit: str = "Index", source: str = "Public snapshot", sid: Optional[str] = None,
                                transform: str = "level", latest: Optional[float] = None, min_value: Optional[float] = None,
                                max_value: Optional[float] = None, colour: Optional[str] = None, invert: bool = False,
                                side: str = "left", description: str = "") -> Dict[str, Any]:
        return {"name": name, "frequency": frequency, "unit": unit, "source": source, "sid": sid,
                        "transform": transform, "latest": latest, "min": min_value, "max": max_value,
                        "colour": colour, "invert": invert, "side": side, "description": description}


def _v25_pair(title: str, subtitle: str, left: List[Dict[str, Any]], right: List[Dict[str, Any]], note: str) -> Dict[str, Any]:
        return {"title": title, "subtitle": subtitle, "left": left, "right": right, "note": note}


