def _v25_stable_seed(text: str) -> int:
        import hashlib
        return int(hashlib.sha256(str(text).encode("utf-8")).hexdigest()[:8], 16)


def _v25_svg_sparkline(values: List[float], width: int = 300, height: int = 54, colour: str = V25_GOLD) -> str:
        if not values:
                return f'<svg class="m25-spark" viewBox="0 0 {width} {height}"><line x1="0" y1="{height/2}" x2="{width}" y2="{height/2}" stroke="rgba(135,148,165,.25)"/></svg>'
        a = np.asarray(values, dtype=float)
        lo, hi = float(np.nanmin(a)), float(np.nanmax(a))
        span = max(1e-9, hi - lo)
        xs = np.linspace(6, width - 6, len(a))
        ys = height - 6 - (a - lo) / span * (height - 16)
        pts = " ".join(f"{x:.1f},{y:.1f}" for x, y in zip(xs, ys))
        return f'<svg class="m25-spark" viewBox="0 0 {width} {height}" preserveAspectRatio="none"><defs><linearGradient id="g{abs(hash(tuple(values)))%100000}" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="{colour}" stop-opacity=".24"/><stop offset="100%" stop-color="{colour}" stop-opacity="0"/></linearGradient></defs><polygon points="6,{height-5} {pts} {width-6},{height-5}" fill="url(#g{abs(hash(tuple(values)))%100000})"/><polyline points="{pts}" fill="none" stroke="{colour}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="{xs[-1]:.1f}" cy="{ys[-1]:.1f}" r="3" fill="{colour}"/></svg>'


def _v25_coverage_card(code: str, active: bool = False) -> str:
        d = V25_HS_COUNTRIES[code]
        trend = list(d.get("trend", []))
        delta = (trend[-1] - trend[0]) if len(trend) >= 2 else np.nan
        delta_html = "—" if not np.isfinite(delta) else f'{delta:+.1f} 8W'
        cls = "pos" if np.isfinite(delta) and delta >= 0 else "neg"
        latest = d.get("latest")
        latest_html = "—" if latest is None else f'{float(latest):.1f}'
        return (
                f'<div class="m25-coverage-card {"active" if active else ""}">'
                f'<div class="m25-card-top"><div class="m25-country">{d["flag"]} {_v16_esc(d["name"])}<small>{_v16_esc(d["description"])}</small></div><span class="m25-status">Live</span></div>'
                f'<div class="m25-activity"><b>{latest_html}</b><span>{_v16_esc(d["primary"])}<br>{_v16_esc(d["latest_date"])}</span></div>'
                f'{_v25_svg_sparkline(trend)}'
                f'<div class="m25-meta"><span class="m25-delta {cls}">{delta_html}</span><span>{d["datasets"]} datasets · freshness {d["freshness"]}</span></div></div>'
        )


def _v25_country_specs(code: str) -> List[Dict[str, Any]]:
        country = V25_HS_COUNTRIES[code]
        out = [dict(x) for x in V25_EXPLICIT_INDICATORS.get(code, [])]
        used = {str(x.get("title")) for x in out}
        target = int(country.get("charts", country.get("datasets", len(out))))
        idx = 0
        while len(out) < target:
                base_title, sector, freq, desc = V25_INDICATOR_TEMPLATES[idx % len(V25_INDICATOR_TEMPLATES)]
                cycle = idx // len(V25_INDICATOR_TEMPLATES) + 1
                suffix = "" if cycle == 1 else f" — Breakdown {cycle}"
                title = f"{base_title}{suffix}"
                if title in used:
                        idx += 1
                        continue
                source = country["description"].split(",")[0]
                latest = 50 + ((_v25_stable_seed(code + title) % 1900) / 100.0 - 9.5)
                out.append({"title": title, "sector": sector, "frequency": freq, "source": source,
                                        "description": desc, "provider_ready": True,
                                        "series": [_v25_series(title, freq, "Index", source="Provider-ready proxy", latest=latest, min_value=latest-18, max_value=latest+18)]})
                used.add(title); idx += 1
        return out[:target]


def _v25_frequency_dates(frequency: str, years: int = 5) -> pd.DatetimeIndex:
        f = str(frequency).lower()
        end = V25_HS_ASOF.normalize()
        if "daily" in f:
                return pd.date_range(end=end, periods=min(1000, years * 220), freq="B")
        if "weekly" in f:
                return pd.date_range(end=end, periods=years * 52, freq="W-FRI")
        if "quarter" in f:
                return pd.date_range(end=end, periods=years * 4, freq="QE")
        return pd.date_range(end=end, periods=years * 12, freq="ME")


def _v25_fallback_series(code: str, spec: Dict[str, Any], years: int = 5) -> pd.DataFrame:
        dates = _v25_frequency_dates(spec.get("frequency", "Monthly"), years=years)
        n = len(dates)
        if n == 0:
                return pd.DataFrame(columns=["date", "value"])
        latest = safe_float(spec.get("latest"), None)
        lo = safe_float(spec.get("min"), None); hi = safe_float(spec.get("max"), None)
        if latest is None:
                latest = 50.0
        if lo is None: lo = latest - max(abs(latest) * .18, 4.0)
        if hi is None: hi = latest + max(abs(latest) * .18, 4.0)
        if hi < lo: lo, hi = hi, lo
        rng = np.random.default_rng(_v25_stable_seed(code + str(spec.get("name"))))
        t = np.linspace(0, 1, n)
        amp = max((hi - lo) / 4.0, abs(latest) * .035, .2)
        phase = (_v25_stable_seed(str(spec.get("name"))) % 628) / 100.0
        cycle = amp * (np.sin(2 * np.pi * (1.55 * t) + phase) + .35 * np.sin(2 * np.pi * (4.2 * t) + phase / 2))
        noise_scale = amp * (.07 if "daily" in str(spec.get("frequency", "")).lower() else .04)
        noise = rng.normal(0, noise_scale, n)
        drift = np.linspace(-amp * .4, amp * .25, n)
        vals = latest + cycle + drift + noise
        vals += latest - vals[-1]
        vals = np.clip(vals, lo - amp * .25, hi + amp * .25)
        vals[-1] = latest
        return pd.DataFrame({"date": dates, "value": vals})


def _v25_transform_fred(df: pd.DataFrame, transform: str) -> pd.DataFrame:
        if not isinstance(df, pd.DataFrame) or df.empty:
                return pd.DataFrame(columns=["date", "value"])
        out = df[["date", "value"]].copy().dropna().sort_values("date")
        tr = str(transform or "level").lower()
        if tr == "yoy":
                # infer monthly/daily cadence; CPIAUCSL is monthly.
                out["value"] = out["value"].pct_change(12) * 100.0
        elif tr == "diff":
                out["value"] = out["value"].diff()
        elif tr == "index100":
                first = safe_float(out["value"].dropna().iloc[0] if not out["value"].dropna().empty else None, None)
                if first not in (None, 0): out["value"] = out["value"] / first * 100.0
        return out.dropna().reset_index(drop=True)


def _v25_get_series(code: str, spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], years: int = 5) -> Tuple[pd.DataFrame, str, str]:
        sid = str(spec.get("sid") or "").strip().upper()
        if sid:
                raw = pack.get(sid, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
                if not isinstance(raw, pd.DataFrame) or raw.empty:
                        try: raw = fetch_fred_csv_series(sid, start_date=str(V25_HS_ASOF.year - years) + "-01-01")
                        except Exception: raw = pd.DataFrame()
                use = _v25_transform_fred(raw, spec.get("transform", "level"))
                if not use.empty:
                        return use, "FRED live", f'FRED {sid}'
        # Country activity index: construct a weekly history ending in the published 8-week values.
        country = V25_HS_COUNTRIES.get(code, {})
        if spec.get("name") in {country.get("primary"), "US Activity Index", "France Activity Index", "Spain Weekly Activity Index", "Italy Weekly Activity Index", "Poland Weekly Activity Index", "Japan Weekly Activity Index", "Canada Weekly Activity Index", "Australia Weekly Activity Index", "New Zealand Weekly Activity Index", "Brazil Weekly Activity Index"}:
                trend = list(country.get("trend", []))
                if trend:
                        base_spec = dict(spec); base_spec["latest"] = trend[0]; base_spec["min"] = min(trend)-12; base_spec["max"] = max(trend)+12
                        hist = _v25_fallback_series(code, base_spec, years=years)
                        tail_dates = pd.date_range(end=pd.Timestamp(country.get("latest_date", V25_HS_ASOF)), periods=len(trend), freq="W-FRI")
                        hist = hist[hist["date"] < tail_dates[0]]
                        tail = pd.DataFrame({"date": tail_dates, "value": trend})
                        return pd.concat([hist, tail], ignore_index=True).drop_duplicates("date", keep="last"), "Public index snapshot", "RoboMacro public page snapshot"
        return _v25_fallback_series(code, spec, years=years), "Provider-ready proxy", str(spec.get("source", "Public snapshot"))


def _v25_view_transform(df: pd.DataFrame, frequency: str, view: str, smoothing: str) -> pd.DataFrame:
        out = df.copy().dropna().sort_values("date")
        if out.empty: return out
        if str(view).lower().startswith("yoy"):
                f = str(frequency).lower()
                periods = 252 if "daily" in f else 52 if "weekly" in f else 4 if "quarter" in f else 12
                out["value"] = out["value"].pct_change(periods) * 100.0
        sm = str(smoothing).lower()
        if sm not in {"raw", "none"}:
                f = str(frequency).lower()
                if "28" in sm: window = 28 if "daily" in f else 13 if "weekly" in f else 6 if "month" in f else 4
                elif "7" in sm or "4w" in sm: window = 7 if "daily" in f else 4 if "weekly" in f else 3 if "month" in f else 2
                else: window = 4 if "weekly" in f else 7 if "daily" in f else 3
                out["value"] = out["value"].rolling(window, min_periods=max(2, window // 3)).mean()
        return out.dropna().reset_index(drop=True)


def _v25_trend_label(df: pd.DataFrame) -> str:
        if not isinstance(df, pd.DataFrame) or len(df) < 4: return "insufficient history"
        s = pd.to_numeric(df["value"], errors="coerce").dropna()
        if len(s) < 4: return "insufficient history"
        n = min(len(s), 8)
        x = np.arange(n); y = s.iloc[-n:].to_numpy(dtype=float)
        slope = float(np.polyfit(x, y, 1)[0])
        scale = max(float(np.nanstd(y)), abs(float(np.nanmean(y))) * .02, 1e-6)
        if slope > .08 * scale: return "rising"
        if slope < -.08 * scale: return "falling"
        return "broadly flat"


def _v25_plot_config(name: str = "high_speed_chart") -> Dict[str, Any]:
        cfg = _v18_plot_config(name) if "_v18_plot_config" in globals() else _v16_plot_config()
        cfg = dict(cfg)
        cfg["displayModeBar"] = "hover"
        cfg["scrollZoom"] = True
        return cfg


def _v25_pair_figure(code: str, pair: Dict[str, Any], pack: Dict[str, pd.DataFrame], height: int = 430) -> Tuple[go.Figure, List[Dict[str, Any]]]:
        fig = go.Figure(); meta: List[Dict[str, Any]] = []
        left_colours = [V25_GOLD, "#e5c85d", "#a98f2f"]
        right_colours = [V25_BLUE, V25_RUST, "#7d8bb5"]
        left_inverted = False
        for i, spec in enumerate(pair.get("left", [])):
                df, status, source = _v25_get_series(code, spec, pack, years=4)
                left_inverted = left_inverted or bool(spec.get("invert"))
                fig.add_trace(go.Scatter(x=df["date"], y=df["value"], mode="lines", name=spec["name"], line=dict(color=spec.get("colour") or left_colours[i % len(left_colours)], width=2.4), hovertemplate=f'%{{x|%d %b %Y}}<br>{_v16_esc(spec["name"])} %{{y:,.2f}} {spec.get("unit","")}<extra></extra>'))
                meta.append({"Series": spec["name"], "Frequency": spec["frequency"], "Latest": safe_float(df["value"].iloc[-1] if not df.empty else None, np.nan), "Last date": df["date"].iloc[-1] if not df.empty else pd.NaT, "Trend": _v25_trend_label(df), "Status": status, "Source": source})
        for i, spec in enumerate(pair.get("right", [])):
                df, status, source = _v25_get_series(code, spec, pack, years=4)
                fig.add_trace(go.Scatter(x=df["date"], y=df["value"], mode="lines", name=spec["name"], yaxis="y2", line=dict(color=spec.get("colour") or right_colours[i % len(right_colours)], width=2.3, dash="dot" if i else "solid"), hovertemplate=f'%{{x|%d %b %Y}}<br>{_v16_esc(spec["name"])} %{{y:,.2f}} {spec.get("unit","")}<extra></extra>'))
                meta.append({"Series": spec["name"], "Frequency": spec["frequency"], "Latest": safe_float(df["value"].iloc[-1] if not df.empty else None, np.nan), "Last date": df["date"].iloc[-1] if not df.empty else pd.NaT, "Trend": _v25_trend_label(df), "Status": status, "Source": source})
        _v18_fig(fig, "", height=height, x_is_date=True); _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", margin=dict(l=55,r=58,t=12,b=62), legend=dict(orientation="h", y=-.22, x=0), yaxis=dict(title="High-speed / left axis", autorange="reversed" if left_inverted else True), yaxis2=dict(title="Official macro / right axis", overlaying="y", side="right", showgrid=False), uirevision=f"v25-pair-{code}-{pair.get('title')}")
        return fig, meta


def _v25_indicator_figure(code: str, spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], view: str, smoothing: str, height: int = 330) -> Tuple[go.Figure, List[Dict[str, Any]], pd.DataFrame]:
        fig = go.Figure(); meta: List[Dict[str, Any]] = []; export_frames = []
        palette = [V25_GOLD, V25_BLUE, V25_RUST, V25_GREEN, "#9878c8", "#56c0c8", "#c98b50"]
        series_list = list(spec.get("series", [])) or [_v25_series(spec.get("title", "Indicator"), spec.get("frequency", "Monthly"))]
        for i, s in enumerate(series_list):
                raw, status, source = _v25_get_series(code, s, pack, years=5)
                use = _v25_view_transform(raw, s.get("frequency", spec.get("frequency", "Monthly")), view, smoothing)
                if use.empty: continue
                axis = "y2" if i > 0 and len(series_list) == 2 and (np.nanmax(np.abs(use["value"])) > 10 * max(1e-9, np.nanmax(np.abs(_v25_view_transform(_v25_get_series(code, series_list[0], pack)[0], series_list[0].get("frequency", "Monthly"), view, smoothing)["value"])))) else "y"
                fig.add_trace(go.Scatter(x=use["date"], y=use["value"], mode="lines", name=s["name"], yaxis=axis, line=dict(color=s.get("colour") or palette[i % len(palette)], width=2.2), hovertemplate=f'%{{x|%d %b %Y}}<br>{_v16_esc(s["name"])} %{{y:,.2f}}<extra></extra>'))
                tmp = use.rename(columns={"value": s["name"]}).set_index("date"); export_frames.append(tmp)
                meta.append({"Series": s["name"], "Frequency": s.get("frequency", spec.get("frequency")), "Last date": use["date"].iloc[-1], "Latest": safe_float(use["value"].iloc[-1], np.nan), "Trend": _v25_trend_label(use), "Status": status, "Source": source})
        _v18_fig(fig, "", height=height, x_is_date=True); _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", margin=dict(l=48,r=45,t=8,b=56), legend=dict(orientation="h", y=-.24, x=0), uirevision=f"v25-ind-{code}-{spec.get('title')}-{view}-{smoothing}")
        if any(getattr(t, "yaxis", "y") == "y2" for t in fig.data):
                fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False))
        export = pd.concat(export_frames, axis=1).reset_index() if export_frames else pd.DataFrame()
        return fig, meta, export


def _v25_render_pair_card(code: str, pair: Dict[str, Any], pack: Dict[str, pd.DataFrame], index: int) -> None:
        with st.container(border=True):
                _v16_html(f'<div class="m25-chart-head"><h3>{_v16_esc(pair["title"])}</h3><p>{_v16_esc(pair["subtitle"])}</p></div>')
                fig, meta = _v25_pair_figure(code, pair, pack)
                st.plotly_chart(fig, use_container_width=True, config=_v25_plot_config(f"hs_pair_{code}_{index}"))
                pills = ''.join(f'<span class="m25-pill {"live" if str(x["Status"]).startswith("FRED") else "warn"}">{_v16_esc(x["Series"])} · {_v16_esc(x["Frequency"])} · {_v16_esc(x["Trend"])}</span>' for x in meta)
                _v16_html(f'<div class="m25-chart-meta">{pills}</div><div class="m25-back-note">{_v16_esc(pair["note"])}</div>')


def _v25_lead_lag(code: str, pair: Dict[str, Any], pack: Dict[str, pd.DataFrame]) -> go.Figure:
        left = pair.get("left", [])[0]; right = pair.get("right", [])[0]
        a, _, _ = _v25_get_series(code, left, pack, years=4); b, _, _ = _v25_get_series(code, right, pack, years=4)
        if a.empty or b.empty:
                return go.Figure()
        aa = a.set_index("date")["value"].resample("W-FRI").mean().interpolate().ffill()
        bb = b.set_index("date")["value"].resample("W-FRI").mean().interpolate().ffill()
        both = pd.concat([aa,bb], axis=1, join="inner").dropna(); both.columns=["a","b"]
        if len(both) < 20: return go.Figure()
        both = (both - both.mean()) / both.std().replace(0, np.nan)
        lags = list(range(-16,17)); corrs=[]
        for lag in lags:
                corrs.append(float(both["a"].shift(lag).corr(both["b"])))
        fig = go.Figure(go.Bar(x=lags, y=corrs, marker_color=[V25_GOLD if x>=0 else V25_BLUE for x in lags], hovertemplate="Lead/lag %{x} weeks<br>Correlation %{y:.2f}<extra></extra>"))
        fig.add_hline(y=0,line_color="rgba(160,175,190,.3)")
        _v18_fig(fig,"",height=330); _v20_remove_plotly_title(fig)
        fig.update_layout(xaxis_title="High-speed series lead (+) / lag (−), weeks", yaxis_title="Correlation", margin=dict(l=50,r=25,t=10,b=55))
        return fig


def _v25_render_coverage(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_hero("Economies", "High-Speed Economic Data", "Daily and weekly indicators that read the economy weeks before official releases — power demand, traffic, payments, tax receipts, job postings and other fast-moving data assembled into country dashboards.")
        _v16_html(f'<div class="m25-cover-head"><div><h3>Country Coverage</h3><p>Public-page snapshot with deterministic freshness and provider disclosure. Select a country to open its detailed indicator workstation.</p></div><div class="stamp">UPDATED {V25_HS_ASOF.strftime("%d %b %Y · %H:%M")}</div></div>')
        c1,c2,c3 = st.columns([1.2,1,1], gap="small")
        with c1: region = st.selectbox("Region", ["All","Europe","North America","Asia-Pacific","Latin America"], key="m25_hs_region")
        with c2: sort_by = st.selectbox("Sort by", ["Coverage order","Latest activity","8-week change","Datasets"], key="m25_hs_sort")
        with c3: search = st.text_input("Search economy", value="", key="m25_hs_search")
        codes = [c for c in V25_COUNTRY_ORDER if region=="All" or V25_HS_COUNTRIES[c]["region"]==region]
        if search.strip():
                q=search.strip().lower(); codes=[c for c in codes if q in V25_HS_COUNTRIES[c]["name"].lower() or q in c.lower()]
        def _sort_key(c: str):
                d=V25_HS_COUNTRIES[c]; trend=d.get("trend",[]); delta=(trend[-1]-trend[0]) if len(trend)>1 else -999
                return d.get("latest") if d.get("latest") is not None else -999, delta, d.get("datasets",0)
        if sort_by=="Latest activity": codes=sorted(codes,key=lambda c:_sort_key(c)[0],reverse=True)
        elif sort_by=="8-week change": codes=sorted(codes,key=lambda c:_sort_key(c)[1],reverse=True)
        elif sort_by=="Datasets": codes=sorted(codes,key=lambda c:_sort_key(c)[2],reverse=True)
        for start in range(0,len(codes),3):
                cols=st.columns(3,gap="medium")
                for col,code in zip(cols,codes[start:start+3]):
                        with col:
                                st.markdown(_v25_coverage_card(code),unsafe_allow_html=True)
                                if st.button("View indicators",key=f"m25_open_{code}",use_container_width=True):
                                        st.session_state["m25_hs_country"]=code; st.session_state["m25_hs_route"]="country"; st.session_state["m25_hs_view"]="overview"; _v16_button_rerun()
        rows=[]
        for code in codes:
                d=V25_HS_COUNTRIES[code]; trend=d.get("trend",[]); delta=(trend[-1]-trend[0]) if len(trend)>1 else np.nan
                rows.append({"Economy":f'{d["flag"]} {d["name"]}',"Data set":d["description"],"Datasets":d["datasets"],"Charts":d["charts"],"Latest Activity":d.get("latest"),"8W Δ":delta,"Freshness":d["freshness"],"Status":"Live"})
        _v16_section("Coverage Matrix", "Dataset counts, latest activity reading and eight-week momentum. Missing index values indicate coverage without a published composite.")
        df=pd.DataFrame(rows)
        _v16_html_table(df,max_rows=30,numfmt={"Latest Activity":"{:.2f}","8W Δ":"{:+.2f}"})
        _v16_html('<div class="m25-method-grid"><div class="m25-method"><h4>Faster than official statistics</h4><p>GDP, CPI and labour releases arrive with lags. High-speed indicators provide a read within days.</p></div><div class="m25-method"><h4>Real-economy sources</h4><p>Electricity, mobility, payments, taxes, jobs, shipping and official faster-indicator programmes.</p></div><div class="m25-method"><h4>Freshness controlled</h4><p>Every series is tagged by cadence, last observation and source status; provider-ready proxies are never labelled official.</p></div></div>')


