def _v25_render_overview(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        pairs=V25_OVERVIEW_PAIRS.get(code,[])
        _v16_section("High Speed vs Official Macro", "Fast series use the left axis; the official release they lead uses the right axis. Last four years, unified hover, clickable legends and range controls.")
