def _v25_render_indicator_book(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        specs=_v25_country_specs(code); sectors=["All"]+sorted({str(x.get("sector","Other")) for x in specs})
        _v16_section(f'All {V25_HS_COUNTRIES[code]["name"]} High-Speed Indicators', f'{V25_HS_COUNTRIES[code]["datasets"]} datasets tracked · {V25_HS_COUNTRIES[code]["series"]} series with seasonal factors · last five years shown.')
        c1,c2,c3,c4=st.columns([1.2,.8,.9,.8],gap="small")
        with c1: sector=st.selectbox("Sector",sectors,key=f"m25_sector_{code}")
        with c2: global_view=st.selectbox("View",["Levels","YoY %"],key=f"m25_viewmode_{code}")
        with c3: global_smooth=st.selectbox("Smoothing",["Raw","7D / 4W / 3M","28D / 13W / 6M"],key=f"m25_smooth_{code}")
        with c4: per_page=int(st.selectbox("Charts/page",[5,7,10],index=1,key=f"m25_perpage_{code}"))
        use=specs if sector=="All" else [x for x in specs if x.get("sector")==sector]
        pages=max(1,int(math.ceil(len(use)/per_page)))
        page_key=f"m25_page_{code}_{sector}"; st.session_state.setdefault(page_key,1)
        page=max(1,min(int(st.session_state.get(page_key,1)),pages)); st.session_state[page_key]=page
        p1,p2,p3=st.columns([1,2,1],gap="small")
        with p1:
                if st.button("← Previous",key=f"m25_prev_{code}_{sector}",disabled=page<=1,use_container_width=True): st.session_state[page_key]=page-1; _v16_button_rerun()
        with p2: _v16_html(f'<div class="m19-controls-note" style="text-align:center">Showing {(page-1)*per_page+1}–{min(page*per_page,len(use))} of {len(use)} charts · Page {page} of {pages}</div>')
        with p3:
                if st.button("Next →",key=f"m25_next_{code}_{sector}",disabled=page>=pages,use_container_width=True): st.session_state[page_key]=page+1; _v16_button_rerun()
        subset=use[(page-1)*per_page:page*per_page]
        for local_idx,spec in enumerate(subset,start=(page-1)*per_page+1):
                with st.container(border=True):
                        _v16_html(f'<div class="m25-chart-head"><h3>{local_idx}. {_v16_esc(spec["title"])}</h3><p>{_v16_esc(spec.get("description",""))}</p><div class="m25-chart-meta"><span class="m25-pill">{_v16_esc(spec.get("sector","Other"))}</span><span class="m25-pill">{_v16_esc(spec.get("frequency",""))}</span><span class="m25-pill">{len(spec.get("series",[]))} series</span><span class="m25-pill {"warn" if spec.get("provider_ready") else "live"}">{"Provider-ready" if spec.get("provider_ready") else _v16_esc(spec.get("source","Public"))}</span></div></div>')
                        cview,csmooth,cspace=st.columns([.8,1.1,3.1],gap="small")
                        with cview: view=st.selectbox("Card view",[global_view,"Levels" if global_view!="Levels" else "YoY %"],key=f"m25_card_view_{code}_{local_idx}",label_visibility="collapsed")
                        with csmooth: smooth=st.selectbox("Card smoothing",[global_smooth,"Raw" if global_smooth!="Raw" else "28D / 13W / 6M"],key=f"m25_card_smooth_{code}_{local_idx}",label_visibility="collapsed")
                        fig,meta,export=_v25_indicator_figure(code,spec,pack,view,smooth)
                        st.plotly_chart(fig,use_container_width=True,config=_v25_plot_config(f"hs_{code}_{local_idx}"))
                        last=max([x["Last date"] for x in meta if pd.notna(x["Last date"])],default=pd.NaT)
                        statuses=sorted({str(x["Status"]) for x in meta})
                        _v16_html(f'<div class="m25-chart-meta"><span class="m25-pill">Last data {last.strftime("%d %b %Y") if pd.notna(last) else "N/A"}</span><span class="m25-pill">{_v16_esc(" / ".join(statuses))}</span><span class="m25-pill">Source: {_v16_esc(spec.get("source","Public snapshot"))}</span></div>')
                        if not export.empty:
                                st.download_button("Download CSV",export.to_csv(index=False).encode("utf-8"),file_name=f'{code}_{local_idx}_{str(spec["title"]).lower().replace(" ","_")}.csv',mime="text/csv",key=f"m25_dl_{code}_{local_idx}")
        q1,q2,q3=st.columns([1,2,1],gap="small")
        with q1:
                if st.button("← Previous page",key=f"m25_prev2_{code}_{sector}",disabled=page<=1,use_container_width=True): st.session_state[page_key]=page-1; _v16_button_rerun()
        with q2: _v16_html(f'<div class="m19-controls-note" style="text-align:center">Page {page} of {pages}</div>')
        with q3:
                if st.button("Next page →",key=f"m25_next2_{code}_{sector}",disabled=page>=pages,use_container_width=True): st.session_state[page_key]=page+1; _v16_button_rerun()


def _v25_render_quality(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        d=V25_HS_COUNTRIES[code]; specs=_v25_country_specs(code)
        explicit=len([x for x in specs if not x.get("provider_ready")]); provider=len(specs)-explicit
        overview=V25_OVERVIEW_PAIRS.get(code,[])
        _v16_section("Data Quality & Methodology", "Freshness, source coverage, transformation conventions and explicit provider-ready gaps.")
        _v16_html(f'<div class="m25-dq"><div><b>{explicit}</b><span>named public/snapshot cards</span></div><div><b>{provider}</b><span>provider-ready cards</span></div><div><b>{len(overview)}</b><span>lead-vs-official relationships</span></div><div><b>{d["freshness"]}</b><span>published freshness grade</span></div></div>')
        rows=[]
        for i,pair in enumerate(overview,1):
                for side in ["left","right"]:
                        for s in pair.get(side,[]):
                                df,status,source=_v25_get_series(code,s,pack,years=4)
                                rows.append({"Relationship":pair["title"],"Side":side.title(),"Series":s["name"],"Frequency":s["frequency"],"Last date":df["date"].iloc[-1].date().isoformat() if not df.empty else "N/A","Status":status,"Source":source})
        _v16_html_table(pd.DataFrame(rows),max_rows=50)
        _v16_html('<div class="m25-method-grid"><div class="m25-method"><h4>Levels and YoY</h4><p>Level displays the source unit. YoY applies cadence-aware percentage changes: 252 business days, 52 weeks, 12 months or 4 quarters.</p></div><div class="m25-method"><h4>Smoothing</h4><p>Daily series use 7/28 observations, weekly series 4/13 weeks, monthly series 3/6 months and quarterly series 2/4 quarters.</p></div><div class="m25-method"><h4>Provider discipline</h4><p>FRED series are labelled live. Public-page anchors are labelled snapshots. Unwired datasets are labelled provider-ready proxies and are not presented as official observations.</p></div></div>')


def _v25_render_country(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        if code not in V25_HS_COUNTRIES: code="UK"
        top1,top2,top3=st.columns([1,1.4,2.6],gap="small")
        with top1:
                if st.button("← Economies",key="m25_back_coverage",use_container_width=True): st.session_state["m25_hs_route"]="coverage"; _v16_button_rerun()
        with top2:
                names=[f'{V25_HS_COUNTRIES[c]["flag"]} {V25_HS_COUNTRIES[c]["name"]}' for c in V25_COUNTRY_ORDER]
                chosen=st.selectbox("Economy",names,index=V25_COUNTRY_ORDER.index(code),key="m25_country_switch")
                new_code=V25_COUNTRY_ORDER[names.index(chosen)]
                if new_code!=code: st.session_state["m25_hs_country"]=new_code; _v16_button_rerun()
        with top3: _v16_html('<div class="m25-back-note" style="margin:0">Country navigation is session-state only; switching economies cannot reset the MacroDesk route.</div>')
        code=str(st.session_state.get("m25_hs_country",code)); _v25_country_header(code)
        view=st.radio("High-speed workspace",["Overview","Indicator Book","Data Quality"],horizontal=True,key=f"m25_hs_view_{code}")
        if view=="Overview": _v25_render_overview(code,pack)
        elif view=="Indicator Book": _v25_render_indicator_book(code,pack)
        else: _v25_render_quality(code,pack)


def _v25_render_high_speed(pack: Dict[str, pd.DataFrame]) -> None:
        st.session_state.setdefault("m25_hs_route","coverage")
        st.session_state.setdefault("m25_hs_country","UK")
        if st.session_state.get("m25_hs_route")=="country": _v25_render_country(str(st.session_state.get("m25_hs_country","UK")),pack)
        else: _v25_render_coverage(pack)


