def _v26_demo_enabled(code: str) -> bool:
        try:
                return bool(st.session_state.get(f"{V26_DEMO_KEY_PREFIX}{code}", False))
        except Exception:
                return False


def _v26_snapshot_df(code: str, spec: Dict[str, Any]) -> Tuple[pd.DataFrame, str, str]:
        country = V25_HS_COUNTRIES.get(code, {})
        name = str(spec.get("name") or "")
        trend: List[float] = []
        end_date = None
        if name == str(country.get("primary")) or (code == "UK" and name == "Consumer Index") or name in {
                "US Activity Index", "Euro Area Weekly Activity Index", "Germany Activity Index",
                "France Activity Index", "Spain Weekly Activity Index", "Italy Weekly Activity Index",
                "Poland Weekly Activity Index", "Japan Weekly Activity Index", "Canada Weekly Activity Index",
                "Australia Weekly Activity Index", "New Zealand Weekly Activity Index", "Brazil Weekly Activity Index",
        }:
                trend = list(country.get("trend", []))
                end_date = country.get("latest_date")
        elif name == str(country.get("secondary_name")) or (code == "UK" and name == "Nowcast Index"):
                trend = list(country.get("secondary_trend", []))
                end_date = country.get("secondary_date") or country.get("latest_date")
        if trend and end_date:
                dates = pd.date_range(end=pd.Timestamp(end_date), periods=len(trend), freq="W-FRI")
                return pd.DataFrame({"date": dates, "value": pd.to_numeric(pd.Series(trend), errors="coerce")}).dropna(), "Public 8-week snapshot", "RoboMacro public page snapshot"
        latest = safe_float(spec.get("latest"), None)
        last_data = spec.get("last_data") or spec.get("date")
        if bool(spec.get("verified_value")) and latest is not None and last_data:
                return pd.DataFrame({"date": [pd.Timestamp(last_data)], "value": [float(latest)]}), "Public latest snapshot", str(spec.get("source", "Public page snapshot"))
        return pd.DataFrame(columns=["date", "value"]), "Provider required", str(spec.get("source", "Provider required"))


_v26_original_v25_get_series = _v25_get_series


def _v25_get_series(code: str, spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], years: int = 5) -> Tuple[pd.DataFrame, str, str]:
        """V26 integrity loader: live public series, observed page snapshots, or an empty state.

        Synthetic histories are available only when the user explicitly enables the demo toggle.
        """
        sid = str(spec.get("sid") or "").strip().upper()
        if sid:
                raw = pack.get(sid, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
                if not isinstance(raw, pd.DataFrame) or raw.empty:
                        try:
                                raw = fetch_fred_csv_series(sid, start_date=str(V26_HS_ASOF.year - years) + "-01-01")
                        except Exception:
                                raw = pd.DataFrame()
                use = _v25_transform_fred(raw, spec.get("transform", "level"))
                if isinstance(use, pd.DataFrame) and not use.empty:
                        return use, "FRED live", f"FRED {sid}"
        snap, status, source = _v26_snapshot_df(code, spec)
        if not snap.empty:
                return snap, status, source
        if _v26_demo_enabled(code):
                demo = _v25_fallback_series(code, spec, years=years)
                return demo, "Illustrative demo", "Synthetic demonstration — not an observed series"
        return pd.DataFrame(columns=["date", "value"]), "Provider required", source


def _v26_trace_mode(df: pd.DataFrame) -> str:
        return "lines" if isinstance(df, pd.DataFrame) and len(df) >= 2 else "markers+text"


def _v25_pair_figure(code: str, pair: Dict[str, Any], pack: Dict[str, pd.DataFrame], height: int = 430) -> Tuple[go.Figure, List[Dict[str, Any]]]:
        fig = go.Figure(); meta: List[Dict[str, Any]] = []
        left_colours = [V25_GOLD, "#e5c85d", "#a98f2f"]
        right_colours = [V25_BLUE, V25_RUST, "#7d8bb5"]
        left_inverted = False
        plotted = 0
        for side, specs, colours in (("left", pair.get("left", []), left_colours), ("right", pair.get("right", []), right_colours)):
                for i, spec in enumerate(specs):
                        df, status, source = _v25_get_series(code, spec, pack, years=4)
                        if side == "left":
                                left_inverted = left_inverted or bool(spec.get("invert"))
                        if not df.empty:
                                mode = _v26_trace_mode(df)
                                fig.add_trace(go.Scatter(
                                        x=df["date"], y=df["value"], mode=mode, name=spec["name"],
                                        yaxis="y2" if side == "right" else "y",
                                        line=dict(color=spec.get("colour") or colours[i % len(colours)], width=2.3, dash="dot" if side == "right" and i else "solid"),
                                        marker=dict(size=8, color=spec.get("colour") or colours[i % len(colours)]),
                                        text=["latest"] * len(df) if len(df) == 1 else None,
                                        textposition="top center",
                                        hovertemplate=f'%{{x|%d %b %Y}}<br>{_v16_esc(spec["name"])} %{{y:,.2f}} {spec.get("unit","")}<extra></extra>',
                                ))
                                plotted += 1
                        meta.append({
                                "Series": spec["name"], "Frequency": spec["frequency"],
                                "Latest": safe_float(df["value"].iloc[-1] if not df.empty else spec.get("latest"), np.nan),
                                "Last date": df["date"].iloc[-1] if not df.empty else pd.to_datetime(spec.get("last_data"), errors="coerce"),
                                "Trend": _v25_trend_label(df), "Status": status, "Source": source,
                        })
        _v18_fig(fig, "", height=height, x_is_date=True); _v20_remove_plotly_title(fig)
        fig.update_layout(
                hovermode="x unified", margin=dict(l=55,r=58,t=12,b=62), legend=dict(orientation="h", y=-.22, x=0),
                yaxis=dict(title="High-speed / left axis", autorange="reversed" if left_inverted else True),
                yaxis2=dict(title="Official macro / right axis", overlaying="y", side="right", showgrid=False),
                uirevision=f"v26-pair-{code}-{pair.get('title')}",
        )
        if plotted == 0:
                fig.add_annotation(text="No verified time series connected", x=.5, y=.55, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=16))
                fig.add_annotation(text="Enable illustrative demo histories only for interface testing.", x=.5, y=.45, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=11))
        return fig, meta


def _v25_indicator_figure(code: str, spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], view: str, smoothing: str, height: int = 330) -> Tuple[go.Figure, List[Dict[str, Any]], pd.DataFrame]:
        fig = go.Figure(); meta: List[Dict[str, Any]] = []; export_frames: List[pd.DataFrame] = []
        palette = [V25_GOLD, V25_BLUE, V25_RUST, V25_GREEN, "#9878c8", "#56c0c8", "#c98b50", "#d0a6e8", "#9fc65f", "#eaa35d"]
        series_list = list(spec.get("series", []))
        plotted_data: List[Tuple[Dict[str, Any], pd.DataFrame, str, str]] = []
        for s in series_list:
                raw, status, source = _v25_get_series(code, s, pack, years=5)
                use = _v25_view_transform(raw, s.get("frequency", spec.get("frequency", "Monthly")), view, smoothing)
                plotted_data.append((s, use, status, source))
        primary_scale = None
        for _, use, _, _ in plotted_data:
                if not use.empty:
                        primary_scale = float(np.nanmax(np.abs(pd.to_numeric(use["value"], errors="coerce"))))
                        break
        for i, (s, use, status, source) in enumerate(plotted_data):
                if use.empty:
                        meta.append({"Series": s.get("name"), "Frequency": s.get("frequency", spec.get("frequency")), "Last date": pd.to_datetime(s.get("last_data") or spec.get("last_data"), errors="coerce"), "Latest": safe_float(s.get("latest"), np.nan), "Trend": "not available", "Status": status, "Source": source})
                        continue
                this_scale = float(np.nanmax(np.abs(pd.to_numeric(use["value"], errors="coerce")))) if not use.empty else 0.0
                axis = "y2" if i > 0 and primary_scale not in (None, 0) and this_scale > 10 * max(1e-9, primary_scale) else "y"
                colour = s.get("colour") or palette[i % len(palette)]
                fig.add_trace(go.Scatter(
                        x=use["date"], y=use["value"], mode=_v26_trace_mode(use), name=s["name"], yaxis=axis,
                        line=dict(color=colour, width=2.2), marker=dict(color=colour, size=8),
                        text=["latest"] * len(use) if len(use) == 1 else None, textposition="top center",
                        hovertemplate=f'%{{x|%d %b %Y}}<br>{_v16_esc(s["name"])} %{{y:,.2f}}<extra></extra>',
                ))
                export_frames.append(use.rename(columns={"value": s["name"]}).set_index("date"))
                meta.append({"Series": s["name"], "Frequency": s.get("frequency", spec.get("frequency")), "Last date": use["date"].iloc[-1], "Latest": safe_float(use["value"].iloc[-1], np.nan), "Trend": _v25_trend_label(use), "Status": status, "Source": source})
        _v18_fig(fig, "", height=height, x_is_date=True); _v20_remove_plotly_title(fig)
        fig.update_layout(hovermode="x unified", margin=dict(l=48,r=45,t=8,b=56), legend=dict(orientation="h", y=-.24, x=0), uirevision=f"v26-ind-{code}-{spec.get('title')}-{view}-{smoothing}")
        if any(getattr(t, "yaxis", "y") == "y2" for t in fig.data):
                fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False))
        if len(fig.data) == 0:
                fig.add_annotation(text="Provider connection required", x=.5, y=.56, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=16))
                fig.add_annotation(text="No synthetic history is plotted in integrity mode.", x=.5, y=.45, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=11))
        export = pd.concat(export_frames, axis=1).reset_index() if export_frames else pd.DataFrame()
        return fig, meta, export


def _v25_lead_lag(code: str, pair: Dict[str, Any], pack: Dict[str, pd.DataFrame]) -> go.Figure:
        left = pair.get("left", [])[0]; right = pair.get("right", [])[0]
        a, sa, _ = _v25_get_series(code, left, pack, years=4); b, sb, _ = _v25_get_series(code, right, pack, years=4)
        allowed = {"FRED live", "Official live"}
        if sa not in allowed or sb not in allowed or a.empty or b.empty:
                fig = go.Figure(); _v18_fig(fig, "", height=300); _v20_remove_plotly_title(fig)
                fig.add_annotation(text="Lead–lag unavailable", x=.5, y=.58, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=17))
                fig.add_annotation(text="Both series must be connected observed histories; snapshots and demo proxies are excluded.", x=.5, y=.44, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=11))
                return fig
        aa = a.set_index("date")["value"].resample("W-FRI").mean().interpolate().ffill()
        bb = b.set_index("date")["value"].resample("W-FRI").mean().interpolate().ffill()
        both = pd.concat([aa, bb], axis=1, join="inner").dropna(); both.columns = ["a", "b"]
        if len(both) < 20:
                fig = go.Figure(); _v18_fig(fig, "", height=300); _v20_remove_plotly_title(fig)
                fig.add_annotation(text="Insufficient overlapping observed history", x=.5, y=.5, xref="paper", yref="paper", showarrow=False, font=dict(color=V25_MUTED, size=14))
                return fig
        both = (both - both.mean()) / both.std().replace(0, np.nan)
        lags = list(range(-16, 17)); corrs = [float(both["a"].shift(lag).corr(both["b"])) for lag in lags]
        fig = go.Figure(go.Bar(x=lags, y=corrs, marker_color=[V25_GOLD if x >= 0 else V25_BLUE for x in lags], hovertemplate="Lead/lag %{x} weeks<br>Correlation %{y:.2f}<extra></extra>"))
        fig.add_hline(y=0, line_color="rgba(160,175,190,.3)")
        _v18_fig(fig, "", height=330); _v20_remove_plotly_title(fig)
        fig.update_layout(xaxis_title="High-speed series lead (+) / lag (−), weeks", yaxis_title="Correlation", margin=dict(l=50,r=25,t=10,b=55))
        return fig


def _v26_expected_series(spec: Dict[str, Any]) -> int:
        return int(spec.get("expected_series", len(spec.get("series", []))))


def _v26_declared_series(spec: Dict[str, Any]) -> int:
        return int(len(spec.get("series", [])))


def _v26_verified_history_count(spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], code: str) -> int:
        count = 0
        for s in spec.get("series", []):
                df, status, _ = _v25_get_series(code, s, pack, years=5)
                if status in {"FRED live", "Official live"} and len(df) >= 2:
                        count += 1
        return count


def _v25_coverage_card(code: str, active: bool = False) -> str:
        d = V25_HS_COUNTRIES[code]
        trend = list(d.get("trend", [])); delta = (trend[-1] - trend[0]) if len(trend) >= 2 else np.nan
        delta_html = "No published composite" if not bool(d.get("composite_published", d.get("latest") is not None)) else ("—" if not np.isfinite(delta) else f"{delta:+.1f} 8W")
        cls = "pos" if np.isfinite(delta) and delta >= 0 else "neg"
        latest = d.get("latest"); latest_html = "—" if latest is None else f"{float(latest):.1f}"
        status = "Coverage live" if latest is None else "Snapshot"
        return (
                f'<div class="m25-coverage-card {"active" if active else ""}">'
                f'<div class="m25-card-top"><div class="m25-country">{d["flag"]} {_v16_esc(d["name"])}<small>{_v16_esc(d["description"])}</small></div><span class="m25-status">{status}</span></div>'
                f'<div class="m25-activity"><b>{latest_html}</b><span>{_v16_esc(d["primary"])}<br>{_v16_esc(d["latest_date"])}</span></div>'
                f'{_v25_svg_sparkline(trend)}'
                f'<div class="m25-meta"><span class="m25-delta {cls}">{delta_html}</span><span>{d["datasets"]} datasets · freshness {d["freshness"]}</span></div></div>'
        )


def _v25_render_coverage(pack: Dict[str, pd.DataFrame]) -> None:
        _v16_hero("Economies", "High-Speed Economic Data", "Daily and weekly indicators that read the economy weeks before official releases — power demand, traffic, payments, tax receipts, job postings and other fast-moving data assembled into country dashboards.")
        _v16_html(f'<div class="m25-cover-head"><div><h3>Country Coverage</h3><p>Public coverage-page snapshot. A country composite is not treated as an official statistic and missing composites remain blank.</p></div><div class="stamp">CHECKED {V26_HS_ASOF.strftime("%d %b %Y · %H:%M")}</div></div>')
        c1,c2,c3 = st.columns([1.2,1,1], gap="small")
        with c1: region = st.selectbox("Region", ["All","Europe","North America","Asia-Pacific","Latin America"], key="m25_hs_region")
        with c2: sort_by = st.selectbox("Sort by", ["Coverage order","Latest activity","8-week change","Datasets"], key="m25_hs_sort")
        with c3: search = st.text_input("Search economy", value="", key="m25_hs_search")
        codes = [c for c in V25_COUNTRY_ORDER if region == "All" or V25_HS_COUNTRIES[c]["region"] == region]
        if search.strip():
                q = search.strip().lower(); codes = [c for c in codes if q in V25_HS_COUNTRIES[c]["name"].lower() or q in c.lower()]
        def _sort_key(c: str):
                d=V25_HS_COUNTRIES[c]; trend=d.get("trend",[]); delta=(trend[-1]-trend[0]) if len(trend)>1 else -999
                return d.get("latest") if d.get("latest") is not None else -999, delta, d.get("datasets",0)
        if sort_by == "Latest activity": codes = sorted(codes, key=lambda c:_sort_key(c)[0], reverse=True)
        elif sort_by == "8-week change": codes = sorted(codes, key=lambda c:_sort_key(c)[1], reverse=True)
        elif sort_by == "Datasets": codes = sorted(codes, key=lambda c:_sort_key(c)[2], reverse=True)
        for start in range(0, len(codes), 3):
                cols = st.columns(3, gap="medium")
                for col, code in zip(cols, codes[start:start+3]):
                        with col:
                                st.markdown(_v25_coverage_card(code), unsafe_allow_html=True)
                                if st.button("View indicators", key=f"m25_open_{code}", use_container_width=True):
                                        st.session_state["m25_hs_country"] = code; st.session_state["m25_hs_route"] = "country"; st.session_state["m25_hs_view"] = "overview"; _v16_button_rerun()
        rows=[]
        for code in codes:
                d=V25_HS_COUNTRIES[code]; trend=d.get("trend",[]); delta=(trend[-1]-trend[0]) if len(trend)>1 else None
                rows.append({
                        "Economy":f'{d["flag"]} {d["name"]}', "Data set":d["description"], "Datasets":d["datasets"], "Charts":d["charts"],
                        "Latest Activity":"—" if d.get("latest") is None else f'{float(d.get("latest")):.2f}', "8W Δ":"—" if delta is None else f'{float(delta):+.2f}',
                        "Freshness":d["freshness"], "Composite":"Published snapshot" if d.get("composite_published") else "No published composite",
                })
        _v16_section("Coverage Matrix", "Dataset counts and the latest published coverage-page composite. Blank values are preserved as blank rather than converted to zero or NaN text.")
        _v16_html_table(pd.DataFrame(rows), max_rows=30)
        _v16_html('<div class="m25-method-grid"><div class="m25-method"><h4>Snapshot discipline</h4><p>Country cards reproduce the public coverage-page snapshot and its timestamp. They are not official national statistics.</p></div><div class="m25-method"><h4>Observed histories only</h4><p>Indicator charts default to connected public series or observed point snapshots. Missing providers produce an empty state.</p></div><div class="m25-method"><h4>Diagnostics gated</h4><p>Lead–lag analysis is disabled unless both histories are connected observations.</p></div></div>')


