def _v25_render_indicator_book(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        specs=_v25_country_specs(code); sectors=["All"]+sorted({str(x.get("sector","Other")) for x in specs})
        expected_total=sum(_v26_expected_series(x) for x in specs); declared_total=sum(_v26_declared_series(x) for x in specs)
        _v16_section(f'All {V25_HS_COUNTRIES[code]["name"]} High-Speed Indicators', f'{V25_HS_COUNTRIES[code]["datasets"]} datasets advertised · {V25_HS_COUNTRIES[code]["charts"]} chart cards · {declared_total}/{expected_total} series metadata currently declared.')
        demo = st.toggle("Show illustrative proxy histories", value=False, key=f"{V26_DEMO_KEY_PREFIX}{code}", help="Off by default. When enabled, missing provider histories are filled only for interface demonstration and are excluded from analytical diagnostics.")
        if demo:
                _v16_html('<div class="m16-warning">Illustrative mode is active. Synthetic histories are clearly labelled and must not be used for economic inference.</div>')
        else:
                _v16_html('<div class="m25-back-note">Integrity mode: only connected public histories and observed public snapshots are plotted. Missing providers remain empty.</div>')
        c1,c2,c3,c4=st.columns([1.2,.8,.9,.8],gap="small")
        with c1: sector=st.selectbox("Sector",sectors,key=f"m25_sector_{code}")
        with c2: global_view=st.selectbox("View",["Levels","YoY %"],key=f"m25_viewmode_{code}")
        with c3: global_smooth=st.selectbox("Smoothing",["Raw","7D / 4W / 3M","28D / 13W / 6M"],key=f"m25_smooth_{code}")
        with c4: per_page=int(st.selectbox("Charts/page",[5,7,10],index=1,key=f"m25_perpage_{code}"))
        use=specs if sector=="All" else [x for x in specs if x.get("sector")==sector]
        pages=max(1,int(math.ceil(len(use)/per_page))); page_key=f"m25_page_{code}_{sector}"; st.session_state.setdefault(page_key,1)
        page=max(1,min(int(st.session_state.get(page_key,1)),pages)); st.session_state[page_key]=page
        p1,p2,p3=st.columns([1,2,1],gap="small")
        with p1:
                if st.button("← Previous",key=f"m25_prev_{code}_{sector}",disabled=page<=1,use_container_width=True): st.session_state[page_key]=page-1; _v16_button_rerun()
        with p2: _v16_html(f'<div class="m19-controls-note" style="text-align:center">Showing {(page-1)*per_page+1}–{min(page*per_page,len(use))} of {len(use)} charts · Page {page} of {pages}</div>')
        with p3:
                if st.button("Next →",key=f"m25_next_{code}_{sector}",disabled=page>=pages,use_container_width=True): st.session_state[page_key]=page+1; _v16_button_rerun()
        subset=use[(page-1)*per_page:page*per_page]
        for local_idx,spec in enumerate(subset,start=(page-1)*per_page+1):
                expected=_v26_expected_series(spec); declared=_v26_declared_series(spec); gap=max(0,expected-declared)
                with st.container(border=True):
                        integrity_label=f"{declared}/{expected} series declared" if expected else f"{declared} series"
                        gap_label=f'<span class="m25-pill warn">{gap} provider series missing</span>' if gap else '<span class="m25-pill live">series metadata complete</span>'
                        _v16_html(f'<div class="m25-chart-head"><h3>{local_idx}. {_v16_esc(spec["title"])}</h3><p>{_v16_esc(spec.get("description",""))}</p><div class="m25-chart-meta"><span class="m25-pill">{_v16_esc(spec.get("sector","Other"))}</span><span class="m25-pill">{_v16_esc(spec.get("frequency",""))}</span><span class="m25-pill">{integrity_label}</span>{gap_label}<span class="m25-pill {"warn" if spec.get("provider_ready") or spec.get("snapshot_only") else "live"}">{_v16_esc(spec.get("published_status", spec.get("source","Public")))}</span></div></div>')
                        cview,csmooth,cspace=st.columns([.8,1.1,3.1],gap="small")
                        with cview: view=st.selectbox("Card view",[global_view,"Levels" if global_view!="Levels" else "YoY %"],key=f"m25_card_view_{code}_{local_idx}",label_visibility="collapsed")
                        with csmooth: smooth=st.selectbox("Card smoothing",[global_smooth,"Raw" if global_smooth!="Raw" else "28D / 13W / 6M"],key=f"m25_card_smooth_{code}_{local_idx}",label_visibility="collapsed")
                        fig,meta,export=_v25_indicator_figure(code,spec,pack,view,smooth)
                        st.plotly_chart(fig,use_container_width=True,config=_v25_plot_config(f"hs_{code}_{local_idx}"))
                        dates=[x["Last date"] for x in meta if pd.notna(x["Last date"])]
                        last=max(dates,default=pd.to_datetime(spec.get("last_data"),errors="coerce"))
                        statuses=sorted({str(x["Status"]) for x in meta}) or ["Provider required"]
                        _v16_html(f'<div class="m25-chart-meta"><span class="m25-pill">Last data {last.strftime("%d %b %Y") if pd.notna(last) else "N/A"}</span><span class="m25-pill">{_v16_esc(" / ".join(statuses))}</span><span class="m25-pill">Source: {_v16_esc(spec.get("source","Public snapshot"))}</span></div>')
                        if gap:
                                _v16_html(f'<div class="m25-back-note">Original/public specification reports {expected} series; {declared} are currently declared in this terminal. The {gap} missing provider series are not fabricated.</div>')
                        if not export.empty:
                                st.download_button("Download CSV",export.to_csv(index=False).encode("utf-8"),file_name=f'{code}_{local_idx}_{str(spec["title"]).lower().replace(" ","_")}.csv',mime="text/csv",key=f"m25_dl_{code}_{local_idx}")
        q1,q2,q3=st.columns([1,2,1],gap="small")
        with q1:
                if st.button("← Previous page",key=f"m25_prev2_{code}_{sector}",disabled=page<=1,use_container_width=True): st.session_state[page_key]=page-1; _v16_button_rerun()
        with q2: _v16_html(f'<div class="m19-controls-note" style="text-align:center">Page {page} of {pages}</div>')
        with q3:
                if st.button("Next page →",key=f"m25_next2_{code}_{sector}",disabled=page>=pages,use_container_width=True): st.session_state[page_key]=page+1; _v16_button_rerun()


def _v25_render_quality(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        d=V25_HS_COUNTRIES[code]; specs=_v25_country_specs(code); overview=V25_OVERVIEW_PAIRS.get(code,[])
        expected=sum(_v26_expected_series(x) for x in specs); declared=sum(_v26_declared_series(x) for x in specs)
        wired=sum(sum(1 for s in x.get("series",[]) if s.get("sid")) for x in specs)
        _v16_section("Data Quality & Methodology", "Observed coverage, declared series, provider gaps and analytical eligibility.")
        _v16_html(f'<div class="m25-dq"><div><b>{expected}</b><span>series expected by chart metadata</span></div><div><b>{declared}</b><span>series currently declared</span></div><div><b>{wired}</b><span>public API/FRED wires</span></div><div><b>{max(0,expected-declared)}</b><span>undeclared provider series</span></div></div>')
        rows=[]
        for i,spec in enumerate(specs,1):
                exp=_v26_expected_series(spec); dec=_v26_declared_series(spec)
                rows.append({"#":i,"Chart":spec.get("title"),"Expected":exp,"Declared":dec,"Gap":max(0,exp-dec),"Last public date":spec.get("last_data") or "N/A","Published status":spec.get("published_status"),"Default render":"Provider required" if spec.get("provider_ready") else "Snapshot / connected data only"})
        _v16_html_table(pd.DataFrame(rows),max_rows=200)
        _v16_html('<div class="m25-method-grid"><div class="m25-method"><h4>No silent synthesis</h4><p>Synthetic curves are disabled by default and require an explicit per-country demo toggle.</p></div><div class="m25-method"><h4>Snapshot vs history</h4><p>A latest public value or eight-week page snapshot is not promoted into a multi-year official history.</p></div><div class="m25-method"><h4>Lead–lag eligibility</h4><p>Cross-correlation is available only when both series are observed connected histories.</p></div></div>')


