        top1,top2,top3=st.columns([1,1.4,2.6],gap="small")
        with top1:
                if st.button("← Economies",key="m25_back_coverage",use_container_width=True): st.session_state["m25_hs_route"]="coverage"; _v16_button_rerun()
        with top2:
                names=[f'{V25_HS_COUNTRIES[c]["flag"]} {V25_HS_COUNTRIES[c]["name"]}' for c in V25_COUNTRY_ORDER]
                chosen=st.selectbox("Economy",names,index=V25_COUNTRY_ORDER.index(code),key="m25_country_switch")
                new_code=V25_COUNTRY_ORDER[names.index(chosen)]
                if new_code!=code: st.session_state["m25_hs_country"]=new_code; _v16_button_rerun()
        with top3: _v16_html('<div class="m25-back-note" style="margin:0">Session-state navigation remains unchanged. V26 modifies only High-Speed data integrity.</div>')
        code=str(st.session_state.get("m25_hs_country",code)); _v25_country_header(code)
        view=st.radio("High-speed workspace",["Overview","Indicator Book","Data Quality"],horizontal=True,key=f"m25_hs_view_{code}")
        if view=="Overview":
                # Ensure the same explicit demo choice governs Overview and the Indicator Book.
                st.toggle("Show illustrative proxy histories", value=False, key=f"{V26_DEMO_KEY_PREFIX}{code}", help="Off by default. Synthetic lines are interface demonstrations only and are excluded from lead–lag diagnostics.")
                _v25_render_overview(code,pack)
        elif view=="Indicator Book": _v25_render_indicator_book(code,pack)
        else: _v25_render_quality(code,pack)


