import re as _v27_re
import time as _v27_time

V27_PROVIDER_VERSION = "Macro V27 · public provider integration (ONS + FRED)"
V27_CACHE_MAX_AGE_HOURS = 12
V27_PROVIDER_RUNTIME: Dict[str, Dict[str, Any]] = {}
V27_WORKBOOK_MEMORY: Dict[str, List[Dict[str, Any]]] = {}


def _v27_cache_root() -> Path:
        candidates = []
        env_dir = os.getenv("QUANT_TERMINAL_CACHE_DIR", "").strip()
        if env_dir:
                candidates.append(Path(env_dir).expanduser() / "high_speed_v27")
        candidates.extend([
                Path.home() / ".quant_terminal_cache" / "high_speed_v27",
                Path("/tmp") / "quant_terminal_cache" / "high_speed_v27",
        ])
        for path in candidates:
                try:
                        path.mkdir(parents=True, exist_ok=True)
                        probe = path / ".write_probe"
                        probe.write_text("ok", encoding="utf-8")
                        probe.unlink(missing_ok=True)
                        return path
                except Exception:
                        continue
        return Path(".")


V27_CACHE_DIR = _v27_cache_root()


def _v27_slug(value: Any) -> str:
        text = str(value or "").lower().strip()
        text = _v27_re.sub(r"[^a-z0-9]+", "_", text).strip("_")
        digest = _v27_hashlib.sha256(str(value).encode("utf-8")).hexdigest()[:10]
        return (text[:70] or "cache") + "_" + digest


def _v27_cache_paths(key: str) -> Dict[str, Path]:
        base = V27_CACHE_DIR / _v27_slug(key)
        return {
                "parquet": base.with_suffix(".parquet"),
                "pickle": base.with_suffix(".pkl"),
                "binary": base.with_suffix(".bin"),
                "text": base.with_suffix(".txt"),
                "meta": base.with_suffix(".json"),
        }


def _v27_age_hours(path: Path) -> float:
        try:
                return max(0.0, (_v27_time.time() - path.stat().st_mtime) / 3600.0)
        except Exception:
                return float("inf")


def _v27_read_frame_cache(key: str, max_age_hours: float = V27_CACHE_MAX_AGE_HOURS, allow_stale: bool = False) -> pd.DataFrame:
        paths = _v27_cache_paths(key)
        for kind in ("parquet", "pickle"):
                path = paths[kind]
                if not path.exists() or (not allow_stale and _v27_age_hours(path) > max_age_hours):
                        continue
                try:
                        df = pd.read_parquet(path) if kind == "parquet" else pd.read_pickle(path)
                        if isinstance(df, pd.DataFrame):
                                return df
                except Exception:
                        continue
        return pd.DataFrame()


def _v27_write_frame_cache(key: str, frame: pd.DataFrame, meta: Optional[Dict[str, Any]] = None) -> None:
        if not isinstance(frame, pd.DataFrame):
                return
        paths = _v27_cache_paths(key)
        saved = False
        try:
                frame.to_parquet(paths["parquet"], index=False)
                saved = True
        except Exception:
                try:
                        frame.to_pickle(paths["pickle"])
                        saved = True
                except Exception:
                        saved = False
        if meta is not None:
                payload = dict(meta)
                payload["cached_at"] = pd.Timestamp.utcnow().isoformat()
                payload["saved"] = bool(saved)
                try:
                        paths["meta"].write_text(_v27_json.dumps(payload, default=str, indent=2), encoding="utf-8")
                except Exception:
                        pass


def _v27_read_blob_cache(key: str, max_age_hours: float = V27_CACHE_MAX_AGE_HOURS, allow_stale: bool = False, text: bool = False):
        path = _v27_cache_paths(key)["text" if text else "binary"]
        if not path.exists() or (not allow_stale and _v27_age_hours(path) > max_age_hours):
                return None
        try:
                return path.read_text(encoding="utf-8") if text else path.read_bytes()
        except Exception:
                return None


def _v27_write_blob_cache(key: str, data, text: bool = False) -> None:
        path = _v27_cache_paths(key)["text" if text else "binary"]
        try:
                if text:
                        path.write_text(str(data), encoding="utf-8")
                else:
                        path.write_bytes(bytes(data))
        except Exception:
                pass


def _v27_clear_provider_cache() -> int:
        removed = 0
        try:
                for path in V27_CACHE_DIR.glob("*"):
                        if path.is_file():
                                try:
                                        path.unlink()
                                        removed += 1
                                except Exception:
                                        pass
        except Exception:
                pass
        V27_WORKBOOK_MEMORY.clear()
        V27_PROVIDER_RUNTIME.clear()
        return removed


def _v27_http_get(url: str, *, binary: bool = False, cache_key: Optional[str] = None, max_age_hours: float = V27_CACHE_MAX_AGE_HOURS):
        key = cache_key or ("http_" + url)
        cached = _v27_read_blob_cache(key, max_age_hours=max_age_hours, text=not binary)
        if cached is not None:
                return cached, "cache"
        if not REQUESTS_AVAILABLE or requests is None:
                stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
                return stale, "stale cache" if stale is not None else "offline"
        headers = {
                "User-Agent": "QuantTerminal/27 (+public macro research; contact local operator)",
                "Accept": "application/octet-stream,*/*" if binary else "text/html,application/json,*/*",
        }
        last_error = None
        for wait in (0.0, 0.5, 1.25):
                if wait:
                        _v27_time.sleep(wait)
                try:
                        response = requests.get(url, timeout=(7, 30), headers=headers, allow_redirects=True)
                        response.raise_for_status()
                        payload = response.content if binary else response.text
                        _v27_write_blob_cache(key, payload, text=not binary)
                        return payload, "live"
                except Exception as exc:
                        last_error = exc
        stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
        if stale is not None:
                return stale, "stale cache"
        return None, f"error: {last_error}" if last_error else "error"


def _v27_parse_period(value: Any, frequency_hint: str = "") -> pd.Timestamp:
        if isinstance(value, pd.Timestamp):
                return value
        if isinstance(value, (datetime, np.datetime64)):
                try:
                        return pd.Timestamp(value)
                except Exception:
                        return pd.NaT
        if isinstance(value, (int, float, np.integer, np.floating)) and np.isfinite(value):
                # Excel serial dates are normally between 20,000 and 80,000.
                if 20000 <= float(value) <= 80000:
                        try:
                                return pd.Timestamp("1899-12-30") + pd.to_timedelta(float(value), unit="D")
                        except Exception:
                                return pd.NaT
                return pd.NaT
        text = str(value or "").strip()
        if not text or text.lower() in {"nan", "none", "nat", "latest"}:
                return pd.NaT
        cleaned = text.replace("Sept", "Sep").replace("sept", "Sep")
        quarter_match = _v27_re.search(r"(19|20)\d{2}\s*[- ]?Q([1-4])", cleaned, flags=_v27_re.I)
        if quarter_match:
                try:
                        year = int(quarter_match.group(0)[:4])
                        quarter = int(quarter_match.group(2))
                        return pd.Period(f"{year}Q{quarter}", freq="Q").end_time.normalize()
                except Exception:
                        pass
        month_match = _v27_re.search(r"((?:19|20)\d{2})\s*[- /]?([A-Za-z]{3,9}|0?[1-9]|1[0-2])", cleaned)
        if month_match:
                try:
                        parsed = pd.to_datetime(cleaned, errors="coerce", dayfirst=True)
                        if pd.notna(parsed):
                                return pd.Timestamp(parsed)
                except Exception:
                        pass
        try:
                parsed = pd.to_datetime(cleaned, errors="coerce", dayfirst=True)
                return pd.Timestamp(parsed) if pd.notna(parsed) else pd.NaT
        except Exception:
                return pd.NaT


def _v27_clean_series_frame(frame: pd.DataFrame, years: Optional[int] = None) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame) or frame.empty:
                return pd.DataFrame(columns=["date", "value"])
        if "date" not in frame or "value" not in frame:
                return pd.DataFrame(columns=["date", "value"])
        out = frame[["date", "value"]].copy()
        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["value"] = pd.to_numeric(out["value"], errors="coerce")
        out = out.dropna().sort_values("date").drop_duplicates("date", keep="last")
        if years and not out.empty:
                cutoff = out["date"].max() - pd.DateOffset(years=int(years))
                out = out[out["date"] >= cutoff]
        return out.reset_index(drop=True)


