def _v27_norm_name(value: Any) -> str:
        text = str(value or "").lower()
        text = text.replace("%", " ").replace("&", " and ")
        return " ".join(_v27_re.findall(r"[a-z0-9]+", text))


def _v27_ons_timeseries(cdid: str, dataset: str, transform: str = "level", years: int = 10) -> Tuple[pd.DataFrame, str]:
        cdid_u, dataset_u = str(cdid).upper(), str(dataset).upper()
        cache_key = f"ons_ts_{cdid_u}_{dataset_u}_{transform}"
        cached = _v27_read_frame_cache(cache_key, max_age_hours=6)
        if not cached.empty:
                return _v27_clean_series_frame(cached, years), "ONS cache"
        url = f"https://api.ons.gov.uk/timeseries/{cdid_u.lower()}/dataset/{dataset_u.lower()}/data"
        payload, mode = _v27_http_get(url, binary=False, cache_key=cache_key + "_json", max_age_hours=6)
        if payload is None:
                stale = _v27_read_frame_cache(cache_key, allow_stale=True)
                return _v27_clean_series_frame(stale, years), "ONS stale cache" if not stale.empty else mode
        try:
                obj = _v27_json.loads(payload) if isinstance(payload, str) else payload
        except Exception:
                obj = {}
        records: List[Tuple[pd.Timestamp, float]] = []
        buckets = []
        for name in ("months", "quarters", "years"):
                values = obj.get(name, []) if isinstance(obj, dict) else []
                if isinstance(values, list) and values:
                        buckets.append((name, values))
        # Prefer the highest available frequency.
        if buckets:
                priority = {"months": 0, "quarters": 1, "years": 2}
                bucket_name, values = sorted(buckets, key=lambda x: priority.get(x[0], 9))[0]
                for row in values:
                        if not isinstance(row, dict):
                                continue
                        raw_date = row.get("date") or row.get("label") or row.get("month") or row.get("quarter") or row.get("year")
                        if row.get("year") and row.get("month"):
                                raw_date = f'{row.get("year")} {row.get("month")}'
                        elif row.get("year") and row.get("quarter"):
                                raw_date = f'{row.get("year")} {row.get("quarter")}'
                        dt = _v27_parse_period(raw_date, bucket_name)
                        value = pd.to_numeric(row.get("value"), errors="coerce")
                        if pd.notna(dt) and pd.notna(value):
                                records.append((pd.Timestamp(dt), float(value)))
        frame = pd.DataFrame(records, columns=["date", "value"])
        frame = _v27_clean_series_frame(frame)
        tr = str(transform or "level").lower()
        if not frame.empty and tr == "yoy":
                diffs = frame["date"].diff().dt.days.dropna()
                median_days = float(diffs.median()) if not diffs.empty else 30.0
                lag = 12 if median_days < 45 else 4 if median_days < 130 else 1
                frame["value"] = frame["value"].pct_change(lag) * 100.0
                frame = frame.dropna().reset_index(drop=True)
        elif not frame.empty and tr == "diff":
                frame["value"] = frame["value"].diff()
                frame = frame.dropna().reset_index(drop=True)
        if not frame.empty:
                _v27_write_frame_cache(cache_key, frame, {"url": url, "mode": mode, "provider": "ONS"})
        return _v27_clean_series_frame(frame, years), "ONS live" if mode == "live" else "ONS cache"


