def _v27_resolve_xlsx_url(dataset_key: str) -> Tuple[Optional[str], str]:
        cfg = V27_ONS_XLSX_DATASETS.get(dataset_key, {})
        page = str(cfg.get("page") or "")
        if not page:
                return None, "no page"
        html_text, mode = _v27_http_get(page, binary=False, cache_key=f"ons_page_{dataset_key}", max_age_hours=6)
        if html_text:
                matches = _v27_re.findall(r'href=["\']([^"\']*(?:/file\?uri=|\.xlsx)[^"\']*)["\']', str(html_text), flags=_v27_re.I)
                if matches:
                        href = _v27_html_module.unescape(matches[0])
                        return urljoin("https://www.ons.gov.uk", href), mode
        fallback = cfg.get("fallback")
        if fallback and str(fallback).lower().endswith(".xlsx"):
                return str(fallback), "fallback URL"
        return None, mode


def _v27_header_name(raw: pd.DataFrame, row: int, col: int, sheet: str) -> str:
        parts: List[str] = []
        for r in range(max(0, row - 5), row):
                try:
                        value = raw.iat[r, col]
                except Exception:
                        continue
                if pd.notna(value):
                        text = str(value).strip()
                        if text and text.lower() not in {"nan", "date", "time", "period"}:
                                parts.append(text)
        # Include row labels from the left for horizontal layouts.
        for c in range(max(0, col - 4), col):
                try:
                        value = raw.iat[row, c]
                except Exception:
                        continue
                if pd.notna(value):
                        text = str(value).strip()
                        if text and text.lower() not in {"nan", "date", "time", "period"}:
                                parts.append(text)
        dedup: List[str] = []
        for part in parts:
                if part not in dedup:
                        dedup.append(part)
        label = " | ".join(dedup[-3:]).strip(" |")
        return label or f"{sheet} series {col + 1}"


def _v27_workbook_candidates(content: bytes, dataset_key: str) -> List[Dict[str, Any]]:
        if not content:
                return []
        content_hash = _v27_hashlib.sha256(content).hexdigest()[:16]
        memory_key = dataset_key + "_" + content_hash
        if memory_key in V27_WORKBOOK_MEMORY:
                return V27_WORKBOOK_MEMORY[memory_key]
        candidates: List[Dict[str, Any]] = []
        try:
                book = pd.ExcelFile(BytesIO(content))
        except Exception:
                return []
        for sheet in book.sheet_names:
                try:
                        raw = pd.read_excel(book, sheet_name=sheet, header=None)
                except Exception:
                        continue
                if not isinstance(raw, pd.DataFrame) or raw.empty:
                        continue
                raw = raw.iloc[:5000, :250]
                # Vertical layout: one date column, multiple value columns.
                best_col, best_dates, best_count = None, None, 0
                for col in range(raw.shape[1]):
                        parsed = raw.iloc[:, col].map(_v27_parse_period)
                        count = int(parsed.notna().sum())
                        if count > best_count:
                                best_col, best_dates, best_count = col, parsed, count
                if best_col is not None and best_dates is not None and best_count >= 4:
                        valid_rows = best_dates.notna()
                        first_row = int(np.flatnonzero(valid_rows.to_numpy())[0])
                        dates = pd.to_datetime(best_dates[valid_rows], errors="coerce")
                        for col in range(raw.shape[1]):
                                if col == best_col:
                                        continue
                                values = pd.to_numeric(raw.loc[valid_rows, col], errors="coerce")
                                if int(values.notna().sum()) < 4:
                                        continue
                                frame = _v27_clean_series_frame(pd.DataFrame({"date": dates.to_numpy(), "value": values.to_numpy()}))
                                if len(frame) < 4:
                                        continue
                                name = _v27_header_name(raw, first_row, col, sheet)
                                candidates.append({"name": name, "norm": _v27_norm_name(name), "sheet": sheet, "frame": frame})
                # Horizontal layout: one date row, multiple observation rows.
                best_row, best_dates_row, best_count = None, None, 0
                for row in range(raw.shape[0]):
                        parsed = raw.iloc[row, :].map(_v27_parse_period)
                        count = int(parsed.notna().sum())
                        if count > best_count:
                                best_row, best_dates_row, best_count = row, parsed, count
                if best_row is not None and best_dates_row is not None and best_count >= 4:
                        valid_cols = best_dates_row.notna()
                        first_col = int(np.flatnonzero(valid_cols.to_numpy())[0])
                        dates = pd.to_datetime(best_dates_row[valid_cols], errors="coerce")
                        for row in range(raw.shape[0]):
                                if row == best_row:
                                        continue
                                values = pd.to_numeric(raw.loc[row, valid_cols], errors="coerce")
                                if int(values.notna().sum()) < 4:
                                        continue
                                frame = _v27_clean_series_frame(pd.DataFrame({"date": dates.to_numpy(), "value": values.to_numpy()}))
                                if len(frame) < 4:
                                        continue
                                name_parts = []
                                for col in range(max(0, first_col - 5), first_col):
                                        value = raw.iat[row, col]
                                        if pd.notna(value) and str(value).strip().lower() not in {"nan", "date"}:
                                                name_parts.append(str(value).strip())
                                name = " | ".join(name_parts[-3:]) or f"{sheet} row {row + 1}"
                                candidates.append({"name": name, "norm": _v27_norm_name(name), "sheet": sheet, "frame": frame})
        # Deduplicate by normalized label and end date / length.
        dedup: Dict[str, Dict[str, Any]] = {}
        for item in candidates:
                key = item["norm"] or _v27_slug(item["name"])
                old = dedup.get(key)
                if old is None or len(item["frame"]) > len(old["frame"]):
                        dedup[key] = item
        result = list(dedup.values())
        V27_WORKBOOK_MEMORY[memory_key] = result
        return result


def _v27_match_candidate(candidates: List[Dict[str, Any]], rule: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        keyword_sets = [rule.get("keywords", [])]
        if rule.get("fallback_keywords"):
                keyword_sets.append(rule.get("fallback_keywords", []))
        excludes = [_v27_norm_name(x) for x in rule.get("exclude", [])]
        best = None
        best_score = -1e9
        for pass_index, keywords in enumerate(keyword_sets):
                wanted = [_v27_norm_name(x) for x in keywords if str(x).strip()]
                for item in candidates:
                        norm = item.get("norm", "")
                        if any(ex and ex in norm for ex in excludes):
                                continue
                        matches = sum(1 for token in wanted if token and token in norm)
                        if wanted and matches == 0:
                                continue
                        score = matches * 20.0 - pass_index * 5.0
                        if wanted and matches == len(wanted):
                                score += 25.0
                        score += min(10.0, len(item.get("frame", [])) / 100.0)
                        # Prefer descriptive labels over generic sheet/row names.
                        if "series" not in norm and "row" not in norm:
                                score += 3.0
                        if score > best_score:
                                best_score, best = score, item
                if best is not None:
                        break
        return best


def _v27_ons_xlsx_series(series_name: str, years: int = 10) -> Tuple[pd.DataFrame, str, str]:
        norm = _v27_norm_name(series_name)
        rule = V27_XLSX_SERIES.get(norm)
        if not rule:
                return pd.DataFrame(columns=["date", "value"]), "Provider required", "No public mapping"
        dataset_key = str(rule["dataset"])
        cfg = V27_ONS_XLSX_DATASETS.get(dataset_key, {})
        cache_key = f"ons_xlsx_series_{dataset_key}_{norm}"
        cached = _v27_read_frame_cache(cache_key, max_age_hours=6)
        if not cached.empty:
                return _v27_clean_series_frame(cached, years), "ONS cache", str(cfg.get("source", "ONS"))
        xlsx_url, url_mode = _v27_resolve_xlsx_url(dataset_key)
        if not xlsx_url:
                stale = _v27_read_frame_cache(cache_key, allow_stale=True)
                return _v27_clean_series_frame(stale, years), "ONS stale cache" if not stale.empty else "Provider required", str(cfg.get("source", "ONS"))
        content, download_mode = _v27_http_get(xlsx_url, binary=True, cache_key=f"ons_xlsx_file_{dataset_key}", max_age_hours=6)
        if not content:
                stale = _v27_read_frame_cache(cache_key, allow_stale=True)
                return _v27_clean_series_frame(stale, years), "ONS stale cache" if not stale.empty else "Provider required", str(cfg.get("source", "ONS"))
        candidates = _v27_workbook_candidates(content, dataset_key)
        match = _v27_match_candidate(candidates, rule)
        if not match:
                return pd.DataFrame(columns=["date", "value"]), "Provider required", str(cfg.get("source", "ONS"))
        frame = _v27_clean_series_frame(match["frame"], years)
        if not frame.empty:
                _v27_write_frame_cache(cache_key, frame, {
                        "provider": "ONS XLSX", "dataset": dataset_key, "series": series_name,
                        "matched_label": match.get("name"), "sheet": match.get("sheet"),
                        "url": xlsx_url, "url_mode": url_mode, "download_mode": download_mode,
                })
        return frame, "ONS live" if download_mode == "live" else "ONS cache", f'{cfg.get("source", "ONS")} · {match.get("name", series_name)}'


def _v27_public_provider_series(code: str, spec: Dict[str, Any], years: int = 5) -> Tuple[pd.DataFrame, str, str]:
        if str(code).upper() != "UK":
                return pd.DataFrame(columns=["date", "value"]), "Provider required", "No V27 country provider"
        name = str(spec.get("name") or "")
        norm = _v27_norm_name(name)
        ts_rule = V27_ONS_TIME_SERIES.get(norm)
        if ts_rule:
                frame, status = _v27_ons_timeseries(ts_rule["cdid"], ts_rule["dataset"], ts_rule.get("transform", "level"), years=max(years, 8))
                if not frame.empty:
                        return frame, status, ts_rule.get("source", "ONS")
        if norm in V27_XLSX_SERIES:
                return _v27_ons_xlsx_series(name, years=max(years, 8))
        return pd.DataFrame(columns=["date", "value"]), "Provider required", "No V27 provider mapping"


# Preserve V26.1 fallback hierarchy, but put official providers first.
_v27_v261_get_series = _v25_get_series


def _v25_get_series(code: str, spec: Dict[str, Any], pack: Dict[str, pd.DataFrame], years: int = 5) -> Tuple[pd.DataFrame, str, str]:
        name = str(spec.get("name") or "Series")
        try:
                frame, status, source = _v27_public_provider_series(code, spec, years=years)
        except Exception as exc:
                frame, status, source = pd.DataFrame(), "Provider error", str(exc)
        if isinstance(frame, pd.DataFrame) and not frame.empty:
                V27_PROVIDER_RUNTIME[f"{code}:{name}"] = {
                        "series": name, "country": code, "status": status, "source": source,
                        "observations": len(frame), "last_date": frame["date"].max(), "connected": True,
                }
                return _v27_clean_series_frame(frame, years), status, source
        try:
                fallback, fallback_status, fallback_source = _v27_v261_get_series(code, spec, pack, years=years)
        except Exception as exc:
                fallback, fallback_status, fallback_source = pd.DataFrame(columns=["date", "value"]), "Provider required", str(exc)
        V27_PROVIDER_RUNTIME[f"{code}:{name}"] = {
                "series": name, "country": code, "status": fallback_status, "source": fallback_source,
                "observations": len(fallback) if isinstance(fallback, pd.DataFrame) else 0,
                "last_date": fallback["date"].max() if isinstance(fallback, pd.DataFrame) and not fallback.empty and "date" in fallback else pd.NaT,
                "connected": str(fallback_status).startswith(("ONS", "FRED")),
        }
        return fallback, fallback_status, fallback_source


def _v27_spec_has_public_path(code: str, spec: Dict[str, Any]) -> bool:
        country = V25_HS_COUNTRIES.get(code, {})
        for series in spec.get("series", []):
                name_norm = _v27_norm_name(series.get("name"))
                if series.get("sid") or name_norm in V27_ONS_TIME_SERIES or name_norm in V27_XLSX_SERIES:
                        return True
                if np.isfinite(safe_float(series.get("latest"), np.nan)):
                        return True
                if series.get("name") == country.get("primary") and country.get("trend"):
                        return True
        return bool(spec.get("snapshot_only"))


def _v27_data_badge(statuses: Iterable[str]) -> str:
        values = {str(x) for x in statuses}
        if any(x.startswith("ONS") or x.startswith("FRED") for x in values):
                return "official/public history"
        if any("snapshot" in x.lower() for x in values):
                return "public snapshot"
        if any("illustrative" in x.lower() for x in values):
                return "illustrative demo"
        return "provider required"


def _v25_render_indicator_book(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        all_specs = _v25_country_specs(code)
        sectors = ["All"] + sorted({str(x.get("sector", "Other")) for x in all_specs})
        expected_total = sum(_v26_expected_series(x) for x in all_specs)
        declared_total = sum(_v26_declared_series(x) for x in all_specs)
        candidate_specs = [x for x in all_specs if _v27_spec_has_public_path(code, x)]
        _v16_section(
                f'All {V25_HS_COUNTRIES[code]["name"]} High-Speed Indicators',
                f'{len(candidate_specs)} cards have a public API/file path or verified snapshot · {len(all_specs) - len(candidate_specs)} provider-only cards · {declared_total}/{expected_total} declared series.',
        )
        demo = _v26_demo_enabled(code)
        if demo:
                _v16_html('<div class="m16-warning">Developer illustrative mode is enabled in Data Quality. Synthetic histories remain excluded from analytical diagnostics.</div>')
        else:
                _v16_html('<div class="m25-back-note">Production mode: official histories are charted, point observations become snapshot cards, and missing providers are compactly hidden by default.</div>')

        f1, f2 = st.columns([1, 1], gap="small")
        with f1:
                available_only = st.toggle("Available data only", value=(code in {"UK", "US"}), key=f"m27_available_only_{code}", help="Show cards with an official API/file path or a verified public snapshot.")
        with f2:
                show_missing = st.toggle("Show missing providers", value=False, key=f"m27_show_missing_{code}", help="Include provider-only cards that have no connected public path yet.")

        c1, c2, c3, c4 = st.columns([1.2, .8, .9, .8], gap="small")
        with c1:
                sector = st.selectbox("Sector", sectors, key=f"m27_sector_{code}")
        with c2:
                global_view = st.selectbox("View", ["Levels", "YoY %"], key=f"m27_viewmode_{code}")
        with c3:
                global_smooth = st.selectbox("Smoothing", ["Raw", "7D / 4W / 3M", "28D / 13W / 6M"], key=f"m27_smooth_{code}")
        with c4:
                per_page = int(st.selectbox("Charts/page", [5, 7, 10], index=1, key=f"m27_perpage_{code}"))

        if show_missing or not available_only:
                use = list(all_specs)
        else:
                use = list(candidate_specs)
        if sector != "All":
                use = [x for x in use if x.get("sector") == sector]
        if not use:
                _v16_html('<div class="m261-empty"><b>No cards match the active filters</b><span>Enable “Show missing providers” or select another sector.</span></div>')
                return

        pages = max(1, int(math.ceil(len(use) / per_page)))
        page_key = f"m27_page_{code}_{sector}_{int(show_missing)}_{int(available_only)}"
        st.session_state.setdefault(page_key, 1)
        page = max(1, min(int(st.session_state.get(page_key, 1)), pages))
        st.session_state[page_key] = page

        p1, p2, p3 = st.columns([1, 2, 1], gap="small")
        with p1:
                if st.button("← Previous", key=f"m27_prev_{code}_{sector}", disabled=page <= 1, use_container_width=True):
                        st.session_state[page_key] = page - 1
                        _v16_button_rerun()
        with p2:
                _v16_html(f'<div class="m19-controls-note" style="text-align:center">Showing {(page-1)*per_page+1}–{min(page*per_page,len(use))} of {len(use)} cards · Page {page} of {pages}</div>')
        with p3:
                if st.button("Next →", key=f"m27_next_{code}_{sector}", disabled=page >= pages, use_container_width=True):
                        st.session_state[page_key] = page + 1
                        _v16_button_rerun()

        subset = use[(page - 1) * per_page:page * per_page]
        start_index = all_specs.index(subset[0]) + 1 if subset and subset[0] in all_specs else (page - 1) * per_page + 1
        for offset, spec in enumerate(subset):
                local_idx = all_specs.index(spec) + 1 if spec in all_specs else start_index + offset
                expected = _v26_expected_series(spec)
                declared = _v26_declared_series(spec)
                gap = max(0, expected - declared)
                with st.container(border=True):
                        integrity_label = f"{declared}/{expected} series declared" if expected else f"{declared} series"
                        gap_label = f'<span class="m25-pill warn">{gap} provider series missing</span>' if gap else '<span class="m25-pill live">series metadata complete</span>'
                        _v16_html(
                                f'<div class="m25-chart-head"><h3>{local_idx}. {_v16_esc(spec["title"])}</h3><p>{_v16_esc(spec.get("description", ""))}</p>'
                                f'<div class="m25-chart-meta"><span class="m25-pill">{_v16_esc(spec.get("sector", "Other"))}</span>'
                                f'<span class="m25-pill">{_v16_esc(spec.get("frequency", ""))}</span><span class="m25-pill">{integrity_label}</span>{gap_label}</div></div>'
                        )
                        cview, csmooth, _ = st.columns([.8, 1.1, 3.1], gap="small")
                        with cview:
                                view = st.selectbox("Card view", [global_view, "Levels" if global_view != "Levels" else "YoY %"], key=f"m27_card_view_{code}_{local_idx}", label_visibility="collapsed")
                        with csmooth:
                                smooth = st.selectbox("Card smoothing", [global_smooth, "Raw" if global_smooth != "Raw" else "28D / 13W / 6M"], key=f"m27_card_smooth_{code}_{local_idx}", label_visibility="collapsed")

                        fig, meta, export = _v25_indicator_figure(code, spec, pack, view, smooth)
                        if len(fig.data):
                                st.plotly_chart(fig, use_container_width=True, config=_v25_plot_config(f"hs_v27_{code}_{local_idx}"))
                        else:
                                snapshots = [m for m in meta if np.isfinite(safe_float(m.get("Latest"), np.nan))]
                                if snapshots:
                                        _v16_html(_v261_snapshot_html(snapshots, "Latest public observations"))
                                        _v16_html('<div class="m261-history-note">Historical provider not connected. The verified point observation is not stretched into a time-series.</div>')
                                else:
                                        _v16_html(_v261_empty_html(spec.get("title", "")))

                        public_dates = [pd.to_datetime(s.get("last_data") or spec.get("last_data"), errors="coerce") for s in spec.get("series", [])]
                        public_dates = [d for d in public_dates if pd.notna(d)]
                        public_last = max(public_dates, default=pd.to_datetime(spec.get("last_data"), errors="coerce"))
                        observed_dates = [pd.to_datetime(m.get("Last date"), errors="coerce") for m in meta if pd.notna(m.get("Last date"))]
                        observed_last = max(observed_dates, default=pd.NaT) if observed_dates else pd.NaT
                        statuses = sorted({str(m.get("Status")) for m in meta}) or ["Provider required"]
                        source_values = sorted({str(m.get("Source")) for m in meta if m.get("Source")})
                        date_pills = f'<span class="m25-pill">Last public data {public_last.strftime("%d %b %Y") if pd.notna(public_last) else "N/A"}</span>'
                        if pd.notna(observed_last) and any(x.startswith(("ONS", "FRED")) for x in statuses):
                                date_pills = f'<span class="m25-pill live">Connected through {observed_last.strftime("%d %b %Y")}</span>'
                        elif demo and pd.notna(observed_last):
                                date_pills += f'<span class="m25-pill warn">Illustrative horizon {observed_last.strftime("%d %b %Y")}</span>'
                        _v16_html(
                                f'<div class="m25-chart-meta">{date_pills}<span class="m25-pill">{_v16_esc(_v27_data_badge(statuses))}</span>'
                                f'<span class="m25-pill">{_v16_esc(" / ".join(statuses))}</span><span class="m25-pill">Source: {_v16_esc("; ".join(source_values) or spec.get("source", "Public"))}</span></div>'
                        )
                        if gap:
                                _v16_html(f'<div class="m25-back-note">Public specification reports {expected} series; {declared} are declared. Missing provider series are not fabricated.</div>')
                        if not export.empty:
                                label = "Download illustrative CSV" if demo and any("Illustrative" in x for x in statuses) else "Download CSV"
                                st.download_button(
                                        label,
                                        export.to_csv(index=False).encode("utf-8"),
                                        file_name=f'{code}_{local_idx}_{str(spec["title"]).lower().replace(" ", "_")}.csv',
                                        mime="text/csv",
                                        key=f"m27_dl_{code}_{local_idx}",
                                )

        q1, q2, q3 = st.columns([1, 2, 1], gap="small")
        with q1:
                if st.button("← Previous page", key=f"m27_prev2_{code}_{sector}", disabled=page <= 1, use_container_width=True):
                        st.session_state[page_key] = page - 1
                        _v16_button_rerun()
        with q2:
                _v16_html(f'<div class="m19-controls-note" style="text-align:center">Page {page} of {pages}</div>')
        with q3:
                if st.button("Next page →", key=f"m27_next2_{code}_{sector}", disabled=page >= pages, use_container_width=True):
                        st.session_state[page_key] = page + 1
                        _v16_button_rerun()


def _v25_render_quality(code: str, pack: Dict[str, pd.DataFrame]) -> None:
        specs = _v25_country_specs(code)
        expected = sum(_v26_expected_series(x) for x in specs)
        declared = sum(_v26_declared_series(x) for x in specs)
        public_path_cards = sum(1 for x in specs if _v27_spec_has_public_path(code, x))
        mapped_series = 0
        for spec in specs:
                for series in spec.get("series", []):
                        norm = _v27_norm_name(series.get("name"))
                        if series.get("sid") or norm in V27_ONS_TIME_SERIES or norm in V27_XLSX_SERIES:
                                mapped_series += 1
        _v16_section("Data Quality & Provider Integration", "Official provider paths, cache state, declared metadata and developer-only illustration controls.")
        connected_runtime = sum(1 for x in V27_PROVIDER_RUNTIME.values() if x.get("country") == code and x.get("connected"))
        _v16_html(
                f'<div class="m25-dq"><div><b>{public_path_cards}</b><span>cards with public path or snapshot</span></div>'
                f'<div><b>{mapped_series}</b><span>series mapped to ONS/FRED</span></div>'
                f'<div><b>{connected_runtime}</b><span>histories connected this session</span></div>'
                f'<div><b>{max(0, expected-declared)}</b><span>undeclared provider series</span></div></div>'
        )

        with st.expander("Developer tools", expanded=False):
                demo = st.toggle(
                        "Show illustrative proxy histories",
                        value=bool(st.session_state.get(f"{V26_DEMO_KEY_PREFIX}{code}", False)),
                        key=f"{V26_DEMO_KEY_PREFIX}{code}",
                        help="Development only. Synthetic histories are never eligible for lead–lag or economic inference.",
                )
                _v16_html('<div class="m25-back-note">Illustrative mode is for layout testing only. Production pages automatically prefer ONS/FRED history, then verified snapshots, then compact provider-required states.</div>')
                if st.button("Refresh public providers and clear cache", key=f"m27_refresh_{code}", use_container_width=True):
                        removed = _v27_clear_provider_cache()
                        st.session_state[f"m27_cache_message_{code}"] = f"Cleared {removed} cached provider files."
                        _v16_button_rerun()
                message = st.session_state.pop(f"m27_cache_message_{code}", None)
                if message:
                        st.success(message)
                _v16_html(f'<div class="m19-controls-note">Cache directory: {_v16_esc(str(V27_CACHE_DIR))} · Parquet attempted first, pickle fallback when no Parquet engine is installed.</div>')

        provider_rows = []
        if code == "UK":
                for name, cfg in V27_ONS_TIME_SERIES.items():
                        provider_rows.append({"Series mapping": name, "Provider": "ONS time-series API", "Dataset": f'{cfg["cdid"]}/{cfg["dataset"]}', "Mode": cfg.get("transform", "level")})
                for name, cfg in V27_XLSX_SERIES.items():
                        dataset = V27_ONS_XLSX_DATASETS.get(cfg["dataset"], {})
                        provider_rows.append({"Series mapping": name, "Provider": "ONS XLSX", "Dataset": cfg["dataset"], "Mode": dataset.get("source", "ONS")})
        if provider_rows:
                _v16_section("Public provider registry", "V27 resolves current ONS files dynamically and caches normalized observations locally.")
                _v16_html_table(pd.DataFrame(provider_rows), max_rows=100)

        runtime_rows = [x for x in V27_PROVIDER_RUNTIME.values() if x.get("country") == code]
        if runtime_rows:
                runtime_df = pd.DataFrame(runtime_rows)
                _v16_section("Session provider results", "Only series requested during this Streamlit session are listed.")
                _v16_html_table(runtime_df, max_rows=100)

        rows = []
        for i, spec in enumerate(specs, 1):
                exp = _v26_expected_series(spec)
                dec = _v26_declared_series(spec)
                rows.append({
                        "#": i, "Chart": spec.get("title"), "Expected": exp, "Declared": dec,
                        "Gap": max(0, exp-dec), "Public path": "Yes" if _v27_spec_has_public_path(code, spec) else "No",
                        "Last public date": spec.get("last_data") or "N/A",
                        "Default render": "History / snapshot" if _v27_spec_has_public_path(code, spec) else "Hidden unless missing providers enabled",
                })
        _v16_section("Chart coverage", "The theoretical chart book is separated from the subset that has a public path or verified snapshot.")
        _v16_html_table(pd.DataFrame(rows), max_rows=200)
        _v16_html('<div class="m25-method-grid"><div class="m25-method"><h4>Official first</h4><p>ONS APIs and current ONS workbooks are attempted before any snapshot or demo fallback.</p></div><div class="m25-method"><h4>Persistent cache</h4><p>Normalized histories are cached locally, with stale-cache fallback during temporary network failures.</p></div><div class="m25-method"><h4>Automatic rendering</h4><p>History becomes a chart, a single point becomes a value card, and an absent provider becomes a compact state.</p></div></div>')


