# V27.0.1 — provider-path classification correction.
# Template cards carry illustrative numeric anchors; these are not verified snapshots.
def _v27_spec_has_public_path(code: str, spec: Dict[str, Any]) -> bool:
        country = V25_HS_COUNTRIES.get(code, {})
        for series in spec.get("series", []):
                name_norm = _v27_norm_name(series.get("name"))
                if series.get("sid") or name_norm in V27_ONS_TIME_SERIES or name_norm in V27_XLSX_SERIES:
                        return True
                if bool(series.get("verified_value")) and np.isfinite(safe_float(series.get("latest"), np.nan)):
                        return True
                if series.get("name") == country.get("primary") and country.get("trend"):
                        return True
        if bool(spec.get("provider_ready")):
                return False
        return bool(spec.get("snapshot_only")) and any(bool(s.get("verified_value")) for s in spec.get("series", []))

# V27.0.2 — fast offline circuit breaker. A temporary DNS/network failure must not
# block an entire Streamlit page while each provider is attempted independently.
V27_NETWORK_FAILURE_UNTIL = 0.0

def _v27_http_get(url: str, *, binary: bool = False, cache_key: Optional[str] = None, max_age_hours: float = V27_CACHE_MAX_AGE_HOURS):
        global V27_NETWORK_FAILURE_UNTIL
        key = cache_key or ("http_" + url)
        cached = _v27_read_blob_cache(key, max_age_hours=max_age_hours, text=not binary)
        if cached is not None:
                return cached, "cache"
        now = _v27_time.time()
        if now < V27_NETWORK_FAILURE_UNTIL:
                stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
                return stale, "stale cache" if stale is not None else "offline circuit"
        if not REQUESTS_AVAILABLE or requests is None:
                stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
                return stale, "stale cache" if stale is not None else "offline"
        headers = {
                "User-Agent": "QuantTerminal/27 (+public macro research; contact local operator)",
                "Accept": "application/octet-stream,*/*" if binary else "text/html,application/json,*/*",
        }
        last_error = None
        for attempt in range(2):
                try:
                        response = requests.get(url, timeout=(4, 15), headers=headers, allow_redirects=True)
                        response.raise_for_status()
                        payload = response.content if binary else response.text
                        _v27_write_blob_cache(key, payload, text=not binary)
                        V27_NETWORK_FAILURE_UNTIL = 0.0
                        return payload, "live"
                except Exception as exc:
                        last_error = exc
                        if attempt == 0:
                                _v27_time.sleep(0.25)
        # One failed endpoint should not trigger dozens of sequential waits.
        V27_NETWORK_FAILURE_UNTIL = _v27_time.time() + 45.0
        stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
        if stale is not None:
                return stale, "stale cache"
        return None, f"error: {last_error}" if last_error else "error"

# =============================================================================
# MACRO CENTRAL BANKS V27.1 — PROVIDER RECOVERY HOTFIX
# Fixes a V27 design flaw where one retired ONS API endpoint opened a global
# circuit breaker and prevented all www.ons.gov.uk XLSX providers from loading.
# Stable routing and all non-High-Speed modules remain unchanged.
# =============================================================================
from urllib.parse import urlparse as _v271_urlparse
from io import StringIO as _v271_StringIO

V271_HOST_FAILURE_UNTIL: Dict[str, float] = {}
V271_PROVIDER_ERRORS: Dict[str, str] = {}

# Current official ONS time-series pages. The legacy api.ons.gov.uk/v0 route is
# no longer the primary path; server-rendered ONS tables are parsed instead.
