def _v27_http_get(url: str, *, binary: bool = False, cache_key: Optional[str] = None,
                                    max_age_hours: float = V27_CACHE_MAX_AGE_HOURS):
        """Host-isolated HTTP/cache layer.

        V27 used one global 45-second circuit breaker. A failure on the retired
        api.ons.gov.uk endpoint therefore suppressed otherwise healthy downloads
        from www.ons.gov.uk. V27.1 isolates failures by host and resource family.
        """
        key = cache_key or ("http_" + url)
        cached = _v27_read_blob_cache(key, max_age_hours=max_age_hours, text=not binary)
        if cached is not None:
                return cached, "cache"

        host = (_v271_urlparse(str(url)).netloc or "unknown").lower()
        now = _v27_time.time()
        blocked_until = float(V271_HOST_FAILURE_UNTIL.get(host, 0.0))
        if now < blocked_until:
                stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
                return stale, "stale cache" if stale is not None else f"offline circuit:{host}"

        if not REQUESTS_AVAILABLE or requests is None:
                stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
                return stale, "stale cache" if stale is not None else "offline"

        headers = {
                "User-Agent": "Mozilla/5.0 (compatible; QuantTerminal/27.1; public-statistics-client)",
                "Accept": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/octet-stream,*/*" if binary else "text/html,application/json;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-GB,en;q=0.8",
                "Cache-Control": "no-cache",
        }
        last_error: Optional[Exception] = None
        for attempt in range(3):
                try:
                        response = requests.get(url, timeout=(6, 35), headers=headers, allow_redirects=True)
                        response.raise_for_status()
                        payload = response.content if binary else response.text
                        if binary and payload and bytes(payload[:2]) != b"PK":
                                content_type = str(response.headers.get("content-type", "")).lower()
                                if "spreadsheet" in content_type or str(url).lower().endswith((".xls", ".xlsx")):
                                        raise ValueError(f"non-XLSX payload from {host}: {content_type}")
                        _v27_write_blob_cache(key, payload, text=not binary)
                        V271_HOST_FAILURE_UNTIL.pop(host, None)
                        V271_PROVIDER_ERRORS.pop(host, None)
                        return payload, "live"
                except Exception as exc:
                        last_error = exc
                        if attempt < 2:
                                _v27_time.sleep(0.35 * (attempt + 1))

        # Only the failing host is paused. www.ons.gov.uk remains available when an
        # API host fails, and vice versa.
        V271_HOST_FAILURE_UNTIL[host] = _v27_time.time() + 20.0
        V271_PROVIDER_ERRORS[host] = str(last_error)
        stale = _v27_read_blob_cache(key, allow_stale=True, text=not binary)
        if stale is not None:
                return stale, "stale cache"
        return None, f"error:{host}: {last_error}" if last_error else f"error:{host}"


def _v271_strip_html(value: Any) -> str:
        text = _v27_re.sub(r"<script[^>]*>.*?</script>", " ", str(value or ""), flags=_v27_re.I | _v27_re.S)
        text = _v27_re.sub(r"<style[^>]*>.*?</style>", " ", text, flags=_v27_re.I | _v27_re.S)
        text = _v27_re.sub(r"<[^>]+>", " ", text)
        return " ".join(_v27_html_module.unescape(text).split())


def _v271_parse_ons_timeseries_html(html_text: str) -> pd.DataFrame:
        """Parse the server-rendered ONS Period/Value table without old v0 APIs."""
        candidates: List[Tuple[int, pd.DataFrame]] = []
        try:
                tables = pd.read_html(_v271_StringIO(str(html_text)))
        except Exception:
                tables = []
        for table in tables:
                if not isinstance(table, pd.DataFrame) or table.empty:
                        continue
                cols = {_v27_norm_name(c): c for c in table.columns}
                pcol = next((v for k, v in cols.items() if k in {"period", "date", "time"} or "period" in k), None)
                vcol = next((v for k, v in cols.items() if k == "value" or k.endswith(" value")), None)
                if pcol is None or vcol is None:
                        continue
                rows: List[Tuple[pd.Timestamp, float, str]] = []
                for _, row in table.iterrows():
                        raw_period = str(row.get(pcol, "")).strip()
                        dt = _v27_parse_period(raw_period)
                        val = pd.to_numeric(row.get(vcol), errors="coerce")
                        if pd.notna(dt) and pd.notna(val):
                                rows.append((pd.Timestamp(dt), float(val), raw_period))
                if len(rows) < 4:
                        continue
                # Prefer monthly over quarterly over annual observations when a page
                # carries all frequencies in the same table.
                month_count = sum(bool(_v27_re.search(r"\b(?:JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)\b", p.upper())) for _, _, p in rows)
                quarter_count = sum(bool(_v27_re.search(r"\bQ[1-4]\b", p.upper())) for _, _, p in rows)
                if month_count >= 4:
                        chosen = [(d, v) for d, v, p in rows if _v27_re.search(r"\b(?:JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)\b", p.upper())]
                        score = 3
                elif quarter_count >= 4:
                        chosen = [(d, v) for d, v, p in rows if _v27_re.search(r"\bQ[1-4]\b", p.upper())]
                        score = 2
                else:
                        chosen = [(d, v) for d, v, _ in rows]
                        score = 1
                frame = _v27_clean_series_frame(pd.DataFrame(chosen, columns=["date", "value"]))
                if len(frame) >= 4:
                        candidates.append((score * 100000 + len(frame), frame))

        if candidates:
                return sorted(candidates, key=lambda x: x[0], reverse=True)[0][1]

        # Dependency-free fallback for a conventional HTML table.
        records: List[Tuple[pd.Timestamp, float]] = []
        for tr in _v27_re.findall(r"<tr[^>]*>(.*?)</tr>", str(html_text), flags=_v27_re.I | _v27_re.S):
                cells = [_v271_strip_html(x) for x in _v27_re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", tr, flags=_v27_re.I | _v27_re.S)]
                if len(cells) < 2:
                        continue
                dt = _v27_parse_period(cells[0])
                val = pd.to_numeric(str(cells[1]).replace(",", ""), errors="coerce")
                if pd.notna(dt) and pd.notna(val):
                        records.append((pd.Timestamp(dt), float(val)))
        return _v27_clean_series_frame(pd.DataFrame(records, columns=["date", "value"]))


def _v27_ons_timeseries(cdid: str, dataset: str, transform: str = "level", years: int = 10) -> Tuple[pd.DataFrame, str]:
        """Current ONS page loader with cache and transparent transformation."""
        cdid_u, dataset_u = str(cdid).upper(), str(dataset).upper()
        cache_key = f"ons_ts_v271_{cdid_u}_{dataset_u}_{transform}"
        cached = _v27_read_frame_cache(cache_key, max_age_hours=6)
        if not cached.empty:
                return _v27_clean_series_frame(cached, years), "ONS cache"

        page_url = V271_ONS_TIME_SERIES_PAGES.get((cdid_u, dataset_u))
        if not page_url:
                return pd.DataFrame(columns=["date", "value"]), "Provider required"
        html_text, mode = _v27_http_get(page_url, binary=False, cache_key=cache_key + "_html", max_age_hours=6)
        if not html_text:
                stale = _v27_read_frame_cache(cache_key, allow_stale=True)
                return _v27_clean_series_frame(stale, years), "ONS stale cache" if not stale.empty else mode

        frame = _v271_parse_ons_timeseries_html(str(html_text))
        tr = str(transform or "level").lower()
        if not frame.empty and tr == "yoy":
                diffs = frame["date"].diff().dt.days.dropna()
                median_days = float(diffs.median()) if not diffs.empty else 30.0
                lag = 12 if median_days < 45 else 4 if median_days < 130 else 1
                frame["value"] = frame["value"].pct_change(lag) * 100.0
                frame = frame.dropna().reset_index(drop=True)
        elif not frame.empty and tr == "diff":
                frame["value"] = frame["value"].diff()
                frame = frame.dropna().reset_index(drop=True)

        if not frame.empty:
                _v27_write_frame_cache(cache_key, frame, {"url": page_url, "mode": mode, "provider": "ONS HTML time series"})
                return _v27_clean_series_frame(frame, years), "ONS live" if mode == "live" else "ONS cache"
        stale = _v27_read_frame_cache(cache_key, allow_stale=True)
        return _v27_clean_series_frame(stale, years), "ONS stale cache" if not stale.empty else "Provider parse error"


def _v27_resolve_xlsx_url(dataset_key: str) -> Tuple[Optional[str], str]:
        """Resolve the latest official workbook, then use a verified direct URL."""
        cfg = V27_ONS_XLSX_DATASETS.get(dataset_key, {})
        page = str(cfg.get("page") or "")
        mode = "no page"
        if page:
                html_text, mode = _v27_http_get(page, binary=False, cache_key=f"ons_page_v271_{dataset_key}", max_age_hours=6)
                if html_text:
                        matches = _v27_re.findall(r'href=["\']([^"\']*(?:/file\?uri=[^"\']+?\.xlsx|[^"\']+?\.xlsx)(?:\?[^"\']*)?)["\']', str(html_text), flags=_v27_re.I)
                        ranked: List[Tuple[int, str]] = []
                        for raw in matches:
                                href = _v27_html_module.unescape(str(raw)).replace("&amp;", "&")
                                full = urljoin("https://www.ons.gov.uk", href)
                                low = full.lower()
                                score = 0
                                if "/previous/" not in low:
                                        score += 100
                                if "/current/" in low or "/2026/" in low:
                                        score += 20
                                if "latest" in low:
                                        score += 5
                                ranked.append((score, full))
                        if ranked:
                                return sorted(ranked, key=lambda x: x[0], reverse=True)[0][1], mode
        fallback = str(cfg.get("fallback") or "")
        if fallback and (".xlsx" in fallback.lower() or "/file?uri=" in fallback.lower()):
                return fallback, "verified fallback URL"
        return None, mode

