def _v28_secret(name: str) -> str:
        try:
                value = st.secrets.get(name, "")
                if value:
                        return str(value).strip()
        except Exception:
                pass
        return str(os.getenv(name, "") or "").strip()


def _v28_clean_frame(frame: Any, value_name: str = "value") -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame) or frame.empty:
                return pd.DataFrame(columns=["date", value_name])
        df = frame.copy()
        lower = {str(c).lower(): c for c in df.columns}
        dcol = lower.get("date") or lower.get("observation_date") or df.columns[0]
        vcol = lower.get(value_name.lower()) or lower.get("value")
        if vcol is None:
                candidates = [c for c in df.columns if c != dcol]
                if not candidates:
                        return pd.DataFrame(columns=["date", value_name])
                vcol = candidates[0]
        out = pd.DataFrame({"date": pd.to_datetime(df[dcol], errors="coerce"), value_name: pd.to_numeric(df[vcol], errors="coerce")})
        out = out.dropna().drop_duplicates("date").sort_values("date")
        return out.reset_index(drop=True)


def _v28_fred_series(series_id: str, start: str = "1990-01-01") -> Tuple[pd.DataFrame, str]:
        series_id = str(series_id).upper().strip()
        key = f"v28_china_fred_{series_id}_{start}"
        if key in V28_CHINA_MEM:
                return V28_CHINA_MEM[key].copy(), "memory cache"
        if "_v27_read_frame_cache" in globals():
                try:
                        cached = _v27_read_frame_cache(key, max_age_hours=V28_CHINA_CACHE_HOURS)
                        cached = _v28_clean_frame(cached)
                        if not cached.empty:
                                V28_CHINA_MEM[key] = cached
                                return cached.copy(), "disk cache"
                except Exception:
                        pass
        result = pd.DataFrame(columns=["date", "value"])
        status = "unavailable"
        api_key = _v28_secret("FRED_API_KEY")
        if REQUESTS_AVAILABLE and requests is not None and api_key:
                try:
                        resp = requests.get(
                                "https://api.stlouisfed.org/fred/series/observations",
                                params={"series_id": series_id, "api_key": api_key, "file_type": "json", "observation_start": start},
                                timeout=(7, 22),
                                headers={"User-Agent": "QuantTerminal/28 China macro research"},
                        )
                        resp.raise_for_status()
                        obs = resp.json().get("observations", [])
                        result = pd.DataFrame({"date": [x.get("date") for x in obs], "value": [x.get("value") for x in obs]})
                        result = _v28_clean_frame(result)
                        status = "FRED API"
                except Exception:
                        result = pd.DataFrame(columns=["date", "value"])
        if result.empty:
                try:
                        raw = fetch_fred_series(series_id, start_date=start)
                        result = _v28_clean_frame(raw)
                        status = "FRED public CSV" if not result.empty else status
                except Exception:
                        pass
        if not result.empty:
                V28_CHINA_MEM[key] = result.copy()
                if "_v27_write_frame_cache" in globals():
                        try:
                                _v27_write_frame_cache(key, result, {"series_id": series_id, "status": status})
                        except Exception:
                                pass
        return result, status


def _v28_market_series(symbol: str, period: str = "20y") -> Tuple[pd.DataFrame, str]:
        key = f"v28_china_market_{symbol}_{period}"
        if key in V28_CHINA_MEM:
                return V28_CHINA_MEM[key].copy(), "memory cache"
        if "_v27_read_frame_cache" in globals():
                try:
                        cached = _v27_read_frame_cache(key, max_age_hours=V28_CHINA_CACHE_HOURS)
                        cached = _v28_clean_frame(cached, "value")
                        if not cached.empty:
                                V28_CHINA_MEM[key] = cached
                                return cached.copy(), "disk cache"
                except Exception:
                        pass
        out = pd.DataFrame(columns=["date", "value"])
        try:
                raw = fetch_yahoo_history(symbol, period=period, interval="1d")
                if isinstance(raw, pd.DataFrame) and not raw.empty:
                        out = pd.DataFrame({"date": raw["date"], "value": raw["close"]})
                        out = _v28_clean_frame(out)
        except Exception:
                pass
        if not out.empty:
                V28_CHINA_MEM[key] = out.copy()
                if "_v27_write_frame_cache" in globals():
                        try:
                                _v27_write_frame_cache(key, out, {"symbol": symbol, "status": "Yahoo market history"})
                        except Exception:
                                pass
        return out, "Yahoo market history" if not out.empty else "unavailable"


def _v28_anchor(frame: pd.DataFrame, date: str, value: float) -> pd.DataFrame:
        base = _v28_clean_frame(frame)
        row = pd.DataFrame({"date": [pd.to_datetime(date)], "value": [float(value)]})
        out = pd.concat([base, row], ignore_index=True)
        return out.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


