        # Public NBS/OECD quarterly growth snapshots. Explicit table avoids synthetic interpolation.
        dates = pd.to_datetime([
                "2021-03-31","2021-06-30","2021-09-30","2021-12-31",
                "2022-03-31","2022-06-30","2022-09-30","2022-12-31",
                "2023-03-31","2023-06-30","2023-09-30","2023-12-31",
                "2024-03-31","2024-06-30","2024-09-30","2024-12-31",
                "2025-03-31","2025-06-30","2025-09-30","2025-12-31","2026-03-31",
        ])
        values = [18.3,7.9,4.9,4.0,4.8,0.4,3.9,2.9,4.5,6.3,4.9,5.2,5.3,4.7,4.6,5.4,5.2,4.8,4.5,5.0,5.0]
        return pd.DataFrame({"date": dates, "value": values})


