def _v28_step_rate() -> pd.DataFrame:
        dates = pd.to_datetime(["2021-01-01","2022-01-01","2023-08-01","2024-02-01","2024-07-01","2025-01-01","2025-09-01","2026-03-01"])
        values = [3.85,3.70,3.55,3.45,3.45,3.35,3.20,3.60]
        return pd.DataFrame({"date": dates, "value": values})


def _v28_load_data() -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, Any]]]:
        data: Dict[str, pd.DataFrame] = {}
        provenance: List[Dict[str, Any]] = []
        for key, (sid, label, unit, source) in V28_CHINA_FRED.items():
                frame, status = _v28_fred_series(sid)
                data[key] = frame
                provenance.append({"Series": label, "Identifier": sid, "Source": source, "Rows": len(frame), "Latest": frame["date"].max().date().isoformat() if not frame.empty else "—", "Status": status})
        data["gdp_yoy"] = _v28_gdp_history()
        provenance.append({"Series":"Real GDP YoY","Identifier":"NBS quarterly snapshot table","Source":"NBS / OECD public releases","Rows":len(data["gdp_yoy"]),"Latest":"2026-03-31","Status":"Verified public snapshots"})
        cpi = pd.concat([data.get("cpi_yoy", pd.DataFrame()), _v28_recent_cpi_anchors()], ignore_index=True)
        data["cpi_yoy"] = _v28_clean_frame(cpi)
        ppi_old, ppi_status = _v28_fred_series("CHNPIEATI01GYM")
        data["ppi_yoy"] = _v28_clean_frame(pd.concat([ppi_old, _v28_recent_ppi_anchors()], ignore_index=True))
        provenance.append({"Series":"PPI YoY","Identifier":"CHNPIEATI01GYM + NBS anchors","Source":"OECD/FRED + NBS public releases","Rows":len(data["ppi_yoy"]),"Latest":"2026-07-08","Status":ppi_status + " / snapshot bridge"})
        data["policy_rate"] = _v28_clean_frame(pd.concat([data.get("policy_rate", pd.DataFrame()), _v28_step_rate()], ignore_index=True))
        csi, csi_status = _v28_market_series("000300.SS")
        hsi, hsi_status = _v28_market_series("^HSI")
        data["csi300"] = csi; data["hang_seng"] = hsi
        provenance.extend([
                {"Series":"CSI 300","Identifier":"000300.SS","Source":"Yahoo market data","Rows":len(csi),"Latest":csi["date"].max().date().isoformat() if not csi.empty else "—","Status":csi_status},
                {"Series":"Hang Seng","Identifier":"^HSI","Source":"Yahoo market data","Rows":len(hsi),"Latest":hsi["date"].max().date().isoformat() if not hsi.empty else "—","Status":hsi_status},
        ])
        # Ensure the dashboard remains informative if a public endpoint is temporarily unavailable.
        if data["usd_cny"].empty: data["usd_cny"] = _v28_anchor(data["usd_cny"], "2026-07-02", 6.7886)
        if data["neer"].empty: data["neer"] = _v28_anchor(data["neer"], "2026-05-01", 111.83)
        if data["exports_yoy"].empty: data["exports_yoy"] = _v28_anchor(data["exports_yoy"], "2026-04-01", 13.75159)
        if data["imports_yoy"].empty: data["imports_yoy"] = _v28_anchor(data["imports_yoy"], "2026-04-01", 25.05253)
        if data["fx_reserves"].empty: data["fx_reserves"] = _v28_anchor(data["fx_reserves"], "2026-04-01", 3477516.92314)
        if data["consumer_conf"].empty: data["consumer_conf"] = _v28_anchor(data["consumer_conf"], "2026-04-01", 89.0)
        if data["property_real_yoy"].empty: data["property_real_yoy"] = _v28_anchor(data["property_real_yoy"], "2026-03-31", -7.0745)
        return data, provenance


def _v28_latest(frame: pd.DataFrame, default: Optional[float] = None) -> Tuple[Optional[float], str]:
        df = _v28_clean_frame(frame)
        if df.empty:
                return default, "—"
        return float(df["value"].iloc[-1]), df["date"].iloc[-1].date().isoformat()


def _v28_rebase(frame: pd.DataFrame) -> pd.DataFrame:
        df = _v28_clean_frame(frame)
        if df.empty:
                return df
        first = float(df["value"].iloc[0])
        if not np.isfinite(first) or first == 0:
                return df
        df["value"] = df["value"] / first * 100.0
        return df


def _v28_range_buttons() -> list:
        return [
                dict(count=1, label="1Y", step="year", stepmode="backward"),
                dict(count=3, label="3Y", step="year", stepmode="backward"),
                dict(count=5, label="5Y", step="year", stepmode="backward"),
                dict(count=10, label="10Y", step="year", stepmode="backward"),
                dict(count=20, label="20Y", step="year", stepmode="backward"),
                dict(step="all", label="Max"),
        ]


def _v28_dual_figure(left: pd.DataFrame, right: pd.DataFrame, left_name: str, right_name: str,
                                          left_unit: str, right_unit: str, rebase: bool = False) -> go.Figure:
        ldf = _v28_rebase(left) if rebase else _v28_clean_frame(left)
        rdf = _v28_rebase(right) if rebase else _v28_clean_frame(right)
        fig = go.Figure()
        if not ldf.empty:
                fig.add_trace(go.Scatter(x=ldf["date"], y=ldf["value"], name=left_name, mode="lines", line=dict(color="#d8b52f", width=2.6), hovertemplate=f"%{{x|%Y-%m-%d}}<br>{left_name}: %{{y:.2f}} {left_unit}<extra></extra>"))
        if not rdf.empty:
                fig.add_trace(go.Scatter(x=rdf["date"], y=rdf["value"], name=right_name, mode="lines", yaxis="y2", line=dict(color="#72b7e8", width=2.5), hovertemplate=f"%{{x|%Y-%m-%d}}<br>{right_name}: %{{y:.2f}} {right_unit}<extra></extra>"))
        fig.update_layout(
                height=405, margin=dict(l=50,r=58,t=38,b=42), paper_bgcolor="#050c15", plot_bgcolor="#08131f",
                font=dict(color="#dce5ed", size=12), hovermode="x unified", legend=dict(orientation="h", y=-.18, x=0, bgcolor="rgba(0,0,0,0)"),
                xaxis=dict(showgrid=True, gridcolor="rgba(130,150,170,.17)", rangeselector=dict(buttons=_v28_range_buttons(), bgcolor="#091725", activecolor="#c4a62f", font=dict(color="#dce5ed", size=10)), rangeslider=dict(visible=False)),
                yaxis=dict(title=("Rebased = 100" if rebase else left_unit), showgrid=True, gridcolor="rgba(130,150,170,.17)", zerolinecolor="rgba(200,200,200,.25)"),
                yaxis2=dict(title=("Rebased = 100" if rebase else right_unit), overlaying="y", side="right", showgrid=False, zeroline=False),
                modebar=dict(bgcolor="rgba(0,0,0,0)", color="#7f8b99", activecolor="#d6bd65"),
        )
        return fig


def _v28_single_figure(frame: pd.DataFrame, name: str, unit: str, color: str = "#d8b52f") -> go.Figure:
        df = _v28_clean_frame(frame)
        fig = go.Figure()
        if not df.empty:
                fig.add_trace(go.Scatter(x=df["date"], y=df["value"], name=name, mode="lines", line=dict(color=color, width=2.6), hovertemplate=f"%{{x|%Y-%m-%d}}<br>{name}: %{{y:.2f}} {unit}<extra></extra>"))
        fig.update_layout(height=380, margin=dict(l=50,r=30,t=35,b=40), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed"), hovermode="x unified", legend=dict(orientation="h", y=-.18), xaxis=dict(showgrid=True, gridcolor="rgba(130,150,170,.17)", rangeselector=dict(buttons=_v28_range_buttons(), bgcolor="#091725", activecolor="#c4a62f", font=dict(color="#dce5ed", size=10))), yaxis=dict(title=unit, showgrid=True, gridcolor="rgba(130,150,170,.17)"))
        return fig


def _v28_chart_card(title: str, subtitle: str, fig: go.Figure, left_meta: str, right_meta: str = "", asof: str = "") -> None:
        try:
                ctx = st.container(border=True)
        except Exception:
                ctx = st.container()
        with ctx:
                _v16_html(f'<div class="m28-chart-title">{_v16_esc(title)}</div><div class="m28-chart-sub">{_v16_esc(subtitle)}</div><div class="m28-chart-asof">{_v16_esc(asof)}</div>')
                st.plotly_chart(fig, use_container_width=True, config={"displaylogo":False,"responsive":True,"scrollZoom":True,"modeBarButtonsToRemove":["lasso2d","select2d"]})
                badges = f'<div class="m28-badges"><span class="m28-badge live">{_v16_esc(left_meta)}</span>'
                if right_meta:
                        badges += f'<span class="m28-badge live">{_v16_esc(right_meta)}</span>'
                badges += '</div>'
                _v16_html(badges)


def _v28_metric_rows(data: Optional[Dict[str, pd.DataFrame]] = None) -> List[Dict[str, Any]]:
        rows = [dict(x) for x in V28_CHINA_SNAPSHOT]
        if not isinstance(data, dict):
                return rows
        mapping = {
                "GDP YoY": ("gdp_yoy", lambda x: f"{x:.1f}%"),
                "Consumer Confidence": ("consumer_conf", lambda x: f"{x:.0f}"),
                "CPI YoY": ("cpi_yoy", lambda x: f"{x:.1f}%"),
                "PPI YoY": ("ppi_yoy", lambda x: f"{x:.1f}%"),
                "Exports YoY": ("exports_yoy", lambda x: f"{x:.1f}%"),
                "Imports YoY": ("imports_yoy", lambda x: f"{x:.1f}%"),
                "FX Reserves": ("fx_reserves", lambda x: f"${x/1_000_000:.2f}tn"),
                "USD/CNY": ("usd_cny", lambda x: f"{x:.4f}"),
                "CSI 300": ("csi300", lambda x: f"{x:,.1f}"),
                "Hang Seng": ("hang_seng", lambda x: f"{x:,.0f}"),
                "CNY NEER": ("neer", lambda x: f"{x:.2f}"),
        }
        for row in rows:
                cfg = mapping.get(row["label"])
                if not cfg:
                        continue
                value, date = _v28_latest(data.get(cfg[0], pd.DataFrame()), None)
                if value is None or date == "—":
                        continue
                # Never replace a newer verified headline snapshot with an older public history.
                if str(date) < str(row.get("date", "")):
                        continue
                try:
                        row["display"] = cfg[1](float(value))
                        row["value"] = float(value)
                        row["date"] = str(date)
                        row["status"] = "Connected public history"
                except Exception:
                        pass
        return rows


def _v28_render_metrics(data: Optional[Dict[str, pd.DataFrame]] = None, groups: Optional[List[str]] = None) -> None:
        use_groups = groups or ["Activity","Inflation & Policy","External","Markets"]
        all_rows = _v28_metric_rows(data)
        for group in use_groups:
                _v16_html(f'<div class="m28-group-title">{_v16_esc(group)}</div>')
                rows = [x for x in all_rows if x["group"] == group]
                cols = st.columns(4, gap="medium")
                for col, row in zip(cols, rows):
                        with col:
                                _v16_html(
                                        f'<div class="m28-metric"><div class="m28-metric-label">{_v16_esc(row["label"])}</div>'
                                        f'<div class="m28-metric-value">{_v16_esc(row["display"])}</div>'
                                        f'<div class="m28-metric-date">{_v16_esc(row["date"])}</div>'
                                        f'<div class="m28-metric-source" title="{_v16_esc(row["source"])}">{_v16_esc(row["source"])}</div></div>'
                                )


def _v28_dashboard(data: Dict[str, pd.DataFrame]) -> None:
        _v28_render_metrics(data)
        c1, c2 = st.columns(2, gap="large")
        with c1:
                gdp_latest, gdp_date = _v28_latest(data["gdp_yoy"], 5.0); cpi_latest, cpi_date = _v28_latest(data["cpi_yoy"], 1.0)
                _v28_chart_card("Growth & Inflation", "Real GDP growth vs consumer inflation — the reflation gap (CPI on the right).", _v28_dual_figure(data["gdp_yoy"], data["cpi_yoy"], "Real GDP YoY", "CPI YoY", "%", "%"), f"GDP {gdp_latest:.2f}% · {gdp_date}", f"CPI {cpi_latest:.2f}% · {cpi_date}", f"As of {max(gdp_date,cpi_date)}")
                csi_latest, csi_date = _v28_latest(data["csi300"], 4780.79); hsi_latest, hsi_date = _v28_latest(data["hang_seng"], 24030.18)
                _v28_chart_card("Chinese Equities", "Rebased to 100 at the selected window start — mainland CSI 300 vs Hong Kong Hang Seng.", _v28_dual_figure(data["csi300"], data["hang_seng"], "CSI 300", "Hang Seng", "index", "index", rebase=True), f"CSI 300 {csi_latest:,.1f} · {csi_date}", f"Hang Seng {hsi_latest:,.1f} · {hsi_date}", f"As of {max(csi_date,hsi_date)}")
        with c2:
                fx_latest, fx_date = _v28_latest(data["usd_cny"], 6.7886); neer_latest, neer_date = _v28_latest(data["neer"], 111.83)
                _v28_chart_card("The Yuan", "Onshore USD/CNY (higher = weaker yuan) vs the trade-weighted nominal effective exchange rate.", _v28_dual_figure(data["usd_cny"], data["neer"], "USD/CNY", "CNY NEER", "CNY per USD", "2020=100"), f"USD/CNY {fx_latest:.4f} · {fx_date}", f"NEER {neer_latest:.2f} · {neer_date}", f"As of {max(fx_date,neer_date)}")
                ex_latest, ex_date = _v28_latest(data["exports_yoy"], 13.75159); im_latest, im_date = _v28_latest(data["imports_yoy"], 25.05253)
                _v28_chart_card("Trade Pulse", "Exports vs imports, % YoY — external demand against domestic demand.", _v28_dual_figure(data["exports_yoy"], data["imports_yoy"], "Exports YoY", "Imports YoY", "%", "%"), f"Exports {ex_latest:.2f}% · {ex_date}", f"Imports {im_latest:.2f}% · {im_date}", f"As of {max(ex_date,im_date)}")


def _v28_activity(data: Dict[str, pd.DataFrame]) -> None:
        _v28_render_metrics(data, ["Activity"])
        c1, c2 = st.columns(2, gap="large")
        with c1:
                _v28_chart_card("Real Growth", "Quarterly year-on-year real GDP growth from public NBS/OECD releases.", _v28_single_figure(data["gdp_yoy"], "Real GDP YoY", "%"), "NBS/OECD quarterly public snapshots", asof="Latest: 2026 Q1")
        with c2:
                _v28_chart_card("Consumer Confidence", "OECD composite consumer-confidence balance. Lower readings indicate weaker household sentiment.", _v28_single_figure(data["consumer_conf"], "Consumer Confidence", "balance", "#72b7e8"), "OECD via FRED", asof="Monthly")
        _v16_html('<div class="m28-note">Caixin manufacturing and services PMI are shown as verified latest snapshots. Their complete historical feeds are copyrighted/provider-dependent, so this module does not fabricate an implied history.</div>')


def _v28_inflation_policy(data: Dict[str, pd.DataFrame]) -> None:
        _v28_render_metrics(data, ["Inflation & Policy"])
        c1, c2 = st.columns(2, gap="large")
        with c1:
                _v28_chart_card("Consumer & Producer Inflation", "CPI and PPI year-on-year inflation. Recent NBS readings bridge older OECD histories where required.", _v28_dual_figure(data["cpi_yoy"], data["ppi_yoy"], "CPI YoY", "PPI YoY", "%", "%"), "CPI OECD/FRED + NBS bridge", "PPI OECD/FRED + NBS bridge", "Latest public readings")
        with c2:
                _v28_chart_card("PBoC Policy & Property", "Central-bank rate proxy against BIS real residential property-price growth. The dashboard snapshot for NBS new-home prices remains separate.", _v28_dual_figure(data["policy_rate"], data["property_real_yoy"], "Policy rate proxy", "Real house prices YoY", "%", "%"), "PBoC/OECD policy proxy", "BIS real property prices", "Different property definitions are not merged")
        credit = _v28_clean_frame(data.get("private_credit", pd.DataFrame()))
        if len(credit) >= 8:
                credit = credit.copy(); credit["value"] = credit["value"].pct_change(4) * 100.0
                credit = credit.dropna()
                _v28_chart_card("Credit Growth Diagnostic", "BIS private non-financial credit, four-quarter growth. This is a transparent credit-cycle proxy, not RoboMacro's proprietary credit impulse.", _v28_single_figure(credit, "Private credit YoY", "%", "#86c28b"), "BIS via FRED", asof="Quarterly diagnostic")


def _v28_trade(data: Dict[str, pd.DataFrame]) -> None:
        _v28_render_metrics(data, ["External"])
        c1, c2 = st.columns(2, gap="large")
        with c1:
                _v28_chart_card("Trade Pulse", "Exports vs imports, % YoY — external demand against domestic demand.", _v28_dual_figure(data["exports_yoy"], data["imports_yoy"], "Exports YoY", "Imports YoY", "%", "%"), "OECD trade statistics", "OECD trade statistics", "Monthly")
        with c2:
                reserves = _v28_clean_frame(data["fx_reserves"])
                if not reserves.empty:
                        reserves = reserves.copy(); reserves["value"] = reserves["value"] / 1_000_000.0
                _v28_chart_card("Foreign-Exchange Reserves", "Total reserves excluding gold, expressed in USD trillions.", _v28_single_figure(reserves, "FX Reserves", "USD tn", "#72b7e8"), "IMF IFS via FRED", asof="Monthly")
        _v16_html('<div class="m28-note">The headline trade cards use newer China Customs snapshots, while the long histories use OECD monthly series. Both are shown with their own dates rather than silently spliced as if they were identical vintages.</div>')


def _v28_markets(data: Dict[str, pd.DataFrame]) -> None:
        _v28_render_metrics(data, ["Markets"])
        c1, c2 = st.columns(2, gap="large")
        with c1:
                _v28_chart_card("The Yuan", "Onshore USD/CNY against the BIS trade-weighted nominal effective exchange rate.", _v28_dual_figure(data["usd_cny"], data["neer"], "USD/CNY", "CNY NEER", "CNY per USD", "2020=100"), "Federal Reserve/FRED", "BIS/FRED", "Daily vs monthly")
        with c2:
                _v28_chart_card("Chinese Equities", "Mainland CSI 300 vs Hong Kong Hang Seng, rebased to 100 at the visible window start.", _v28_dual_figure(data["csi300"], data["hang_seng"], "CSI 300", "Hang Seng", "index", "index", rebase=True), "Yahoo market history", "Yahoo market history", "Daily")


def _v28_render_provenance(provenance: List[Dict[str, Any]]) -> None:
        with st.expander("Data sources, definitions and integrity", expanded=False):
                st.caption("Public APIs and official/public snapshots are preferred. A missing provider produces an empty or snapshot state; no sinusoidal or randomly generated China history is used in V28.")
                try:
                        st.dataframe(pd.DataFrame(provenance), use_container_width=True, hide_index=True)
                except Exception:
                        _v16_html_table(pd.DataFrame(provenance), max_rows=30)
                st.markdown("**Definition notes**")
                st.markdown("- The NBS 70-city new-home price snapshot and the BIS real residential property-price series are different measures and remain separate.\n- Headline export/import cards can be newer China Customs readings than the OECD history used in the chart.\n- Caixin PMI history is not reconstructed from synthetic values.\n- The credit diagnostic is a BIS private-credit growth proxy, not a proprietary credit-impulse series.")


def _v28_render_china() -> None:
        _v28_css()
        _v16_html(
                '<div class="m28-hero"><div class="m28-eyebrow">China Macro</div>'
                '<div class="m28-title">China Dashboard — Growth, PBoC, Trade & Markets</div>'
                '<div class="m28-sub">Growth, inflation, PBoC policy, trade flows, the yuan and Chinese equity markets — every principal chart pairs related series so the relationship is visible, not just the level. Public-data first; provider gaps are disclosed rather than fabricated.</div>'
                '<div class="m28-cache">Reference structure: NBS · PBoC · Caixin · OECD · BIS · SAFE · IMF · FRED · market data</div></div>'
        )
        tab = st.radio("China workspace", ["Dashboard","Activity & Sentiment","Inflation & Policy","Trade & External","Markets & FX"], horizontal=True, key="m28_china_workspace", label_visibility="collapsed")
        with st.spinner("Loading China public data…"):
                try:
                        data, provenance = _v28_load_data()
                except Exception as exc:
                        data, provenance = {}, []
                        st.warning(f"China providers partially unavailable: {exc}")
        required = ["gdp_yoy","cpi_yoy","usd_cny","neer","exports_yoy","imports_yoy","csi300","hang_seng","consumer_conf","ppi_yoy","policy_rate","property_real_yoy","private_credit","fx_reserves"]
