def _v29_reference_table(group: str = "All G20") -> pd.DataFrame:
        rows = []
        for country, meta in V29_MISERY_REFERENCE.items():
                if group not in ("All G20", "All") and meta["group"] != group:
                        continue
                classic = float(meta["classic"]); neo = float(meta["neo"])
                rows.append({
                        "Country": country, "Group": meta["group"], "Classic": classic,
                        "Neo-Misery": neo, "Housing ratio": neo-classic,
                        "As of": meta.get("table_date", meta["date"]), "Frequency": meta["frequency"],
                })
        return pd.DataFrame(rows).sort_values("Neo-Misery", ascending=False).reset_index(drop=True)


def _v29_trend_dates(meta: Dict[str, Any]) -> pd.DatetimeIndex:
        end = pd.Timestamp(meta["date"])
        freq = str(meta.get("frequency", "Monthly")).lower()
        if "week" in freq:
                return pd.DatetimeIndex([end - pd.Timedelta(days=7*i) for i in range(4,-1,-1)])
        if "quarter" in freq:
                return pd.DatetimeIndex([end - pd.DateOffset(months=3*i) for i in range(4,-1,-1)])
        return pd.DatetimeIndex([end - pd.DateOffset(months=i) for i in range(4,-1,-1)])


def _v29_transform_cpi(frame: pd.DataFrame, mode: str) -> pd.DataFrame:
        df = _v28_clean_frame(frame)
        if df.empty:
                return df
        if mode == "level":
                df = df.copy()
                median_days = df["date"].diff().dt.days.median() if len(df) > 2 else 30
                lag = 12 if pd.isna(median_days) or median_days < 45 else (4 if median_days < 140 else 1)
                df["value"] = df["value"].pct_change(lag) * 100.0
                df = df.dropna()
        return df


def _v29_candidates(country: str, kind: str) -> List[Tuple[str, str]]:
        two, three = V29_COUNTRY_CODES[country]
        special = list(V29_SPECIAL_SERIES.get(country, {}).get(kind, []))
        if kind == "cpi":
                generic = [(f"CPALTT01{two}M659N", "yoy"), (f"FPCPITOTLZG{three}", "yoy")]
        else:
                generic = [(f"LRHUTTTT{two}M156S", "rate"), (f"SLUEMTOTLZS{three}", "rate")]
        seen, out = set(), []
        for item in special + generic:
                if item[0] not in seen:
                        seen.add(item[0]); out.append(item)
        return out


def _v29_fetch_candidates(country: str, kind: str) -> Tuple[pd.DataFrame, str, str]:
        cache_key = f"v29_{country}_{kind}"
        if cache_key in V29_MISERY_MEM:
                return V29_MISERY_MEM[cache_key].copy(), "memory cache", ""
        for sid, mode in _v29_candidates(country, kind):
                try:
                        frame, status = _v28_fred_series(sid, start="1950-01-01")
                        frame = _v29_transform_cpi(frame, mode) if kind == "cpi" else _v28_clean_frame(frame)
                        if len(frame) >= 3:
                                V29_MISERY_MEM[cache_key] = frame.copy()
                                return frame, status, sid
                except Exception:
                        continue
        return pd.DataFrame(columns=["date","value"]), "unavailable", ""


def _v29_fred_search(search_text: str) -> Tuple[str, str]:
        key = f"v29_search_{search_text.lower().replace(' ','_')}"
        try:
                cached = V29_MISERY_MEM.get(key)
                if isinstance(cached, pd.DataFrame) and not cached.empty:
                        return str(cached.iloc[0]["series_id"]), str(cached.iloc[0]["title"])
        except Exception:
                pass
        api_key = _v28_secret("FRED_API_KEY")
        if not (REQUESTS_AVAILABLE and requests is not None and api_key):
                return "", ""
        try:
                r = requests.get("https://api.stlouisfed.org/fred/series/search", params={
                        "api_key":api_key,"file_type":"json","search_text":search_text,"limit":20,"order_by":"popularity","sort_order":"desc"
                }, timeout=(7,22), headers={"User-Agent":"QuantTerminal/29 misery research"})
                r.raise_for_status()
                series = r.json().get("seriess", [])
                if not series:
                        return "", ""
                def score(x: Dict[str, Any]) -> Tuple[int,int]:
                        title = str(x.get("title","")).lower()
                        s = 0
                        if "price to income" in title or "price-to-income" in title: s += 10
                        if "residential property" in title: s += 6
                        if "real" in title: s += 2
                        if "discontinued" in title: s -= 5
                        return (s, int(x.get("popularity",0) or 0))
                best = sorted(series, key=score, reverse=True)[0]
                sid, title = str(best.get("id", "")), str(best.get("title", ""))
                V29_MISERY_MEM[key] = pd.DataFrame([{"series_id":sid,"title":title}])
                return sid, title
        except Exception:
                return "", ""


def _v29_housing_history(country: str, latest_ratio: float) -> Tuple[pd.DataFrame, str, str]:
        cache_key = f"v29_{country}_housing"
        if cache_key in V29_MISERY_MEM:
                df = V29_MISERY_MEM[cache_key].copy()
                return df, str(df.attrs.get("status","memory cache")), str(df.attrs.get("series_id",""))
        sid, title = _v29_fred_search(f"house price to income ratio {country}")
        if not sid:
                sid, title = _v29_fred_search(f"real residential property prices {country}")
        if sid:
                frame, status = _v28_fred_series(sid, start="1950-01-01")
                frame = _v28_clean_frame(frame)
                if len(frame) >= 4 and float(frame["value"].iloc[-1]) != 0:
                        base = float(frame["value"].iloc[-1])
                        direct_ratio = "income" in title.lower() and "price" in title.lower()
                        exponent = 1.0 if direct_ratio else 0.35
                        values = latest_ratio * np.power(np.maximum(frame["value"].astype(float), 1e-9) / base, exponent)
                        out = pd.DataFrame({"date":frame["date"],"value":values})
                        out.attrs["status"] = ("Public price-to-income history" if direct_ratio else "BIS/OECD real-house-price proxy, anchored to published ratio")
                        out.attrs["series_id"] = sid
                        V29_MISERY_MEM[cache_key] = out.copy()
                        return out, out.attrs["status"], sid
        return pd.DataFrame(columns=["date","value"]), "published five-point housing trend only", ""


def _v29_monthly(frame: pd.DataFrame) -> pd.DataFrame:
        df = _v28_clean_frame(frame)
        if df.empty:
                return df
        s = df.set_index("date")["value"].sort_index()
        start = s.index.min().to_period("M").to_timestamp("M")
        end = s.index.max().to_period("M").to_timestamp("M")
        idx = pd.date_range(start, end, freq="ME")
        s = s.reindex(s.index.union(idx)).sort_index().interpolate("time").ffill().reindex(idx)
        return pd.DataFrame({"date":idx,"value":s.values}).dropna()


def _v29_reference_trend(country: str) -> pd.DataFrame:
        meta = V29_MISERY_REFERENCE[country]
        dates = _v29_trend_dates(meta)
        classic = list(meta["classic_trend"]); neo = list(meta["neo_trend"])
        classic[-1] = float(meta["classic"]); neo[-1] = float(meta["neo"])
        return pd.DataFrame({"date":dates,"classic":classic,"neo":neo})


def _v29_misery_history(country: str) -> Tuple[pd.DataFrame, Dict[str, str]]:
        meta = V29_MISERY_REFERENCE[country]
        cpi, cpi_status, cpi_sid = _v29_fetch_candidates(country, "cpi")
        unemp, un_status, un_sid = _v29_fetch_candidates(country, "unemp")
        classic = pd.DataFrame(columns=["date","classic"])
        if not cpi.empty and not unemp.empty:
                cm = _v29_monthly(cpi).rename(columns={"value":"cpi"})
                um = _v29_monthly(unemp).rename(columns={"value":"unemployment"})
                merged = pd.merge(cm, um, on="date", how="inner").dropna()
                if not merged.empty:
                        merged["classic"] = merged["cpi"] + merged["unemployment"]
                        classic = merged[["date","classic"]]
        housing, housing_status, housing_sid = _v29_housing_history(country, float(meta["neo"]-meta["classic"]))
        if not classic.empty:
                out = classic.copy()
                if not housing.empty:
                        hm = _v29_monthly(housing).rename(columns={"value":"housing"})
                        out = pd.merge(out, hm, on="date", how="left")
                        out["housing"] = out["housing"].interpolate().ffill().bfill()
                        out["neo"] = out["classic"] + out["housing"]
                else:
                        out["housing"] = np.nan; out["neo"] = np.nan
        else:
                out = pd.DataFrame(columns=["date","classic","housing","neo"])
        # Exact published five-point anchors ensure current values and recent direction match the reference.
        ref = _v29_reference_trend(country)
        ref["housing"] = ref["neo"] - ref["classic"]
        if out.empty:
                out = ref[["date","classic","housing","neo"]].copy()
                history_status = "Published five-point reference trend"
        else:
                out = out[~out["date"].isin(ref["date"])]
                out = pd.concat([out, ref[["date","classic","housing","neo"]]], ignore_index=True).sort_values("date")
                history_status = "Official CPI/unemployment history + exact published recent anchors"
        out = out.drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)
        return out, {
                "classic":history_status,
                "cpi":f"{cpi_sid or '—'} · {cpi_status}",
                "unemployment":f"{un_sid or '—'} · {un_status}",
                "housing":f"{housing_sid or '—'} · {housing_status}",
        }


def _v29_range_buttons() -> List[Dict[str, Any]]:
        return [
                dict(count=1,label="1Y",step="year",stepmode="backward"),dict(count=3,label="3Y",step="year",stepmode="backward"),
                dict(count=5,label="5Y",step="year",stepmode="backward"),dict(count=10,label="10Y",step="year",stepmode="backward"),
                dict(count=20,label="20Y",step="year",stepmode="backward"),dict(step="all",label="Max"),
        ]


def _v29_default_range(frame: pd.DataFrame, years: int = 5) -> Optional[List[pd.Timestamp]]:
        if not isinstance(frame, pd.DataFrame) or frame.empty or "date" not in frame:
                return None
        end = pd.to_datetime(frame["date"], errors="coerce").max()
        if pd.isna(end): return None
        start = end - pd.DateOffset(years=years)
        return [start, end]


def _v29_misery_figure(country: str, frame: pd.DataFrame) -> go.Figure:
        df = frame.copy()
        fig = go.Figure()
        if not df.empty:
                fig.add_trace(go.Scatter(x=df["date"], y=df["classic"], name="Classic: unemployment + inflation", mode="lines", line=dict(color="#72b7e8",width=2.5), hovertemplate="%{x|%Y-%m-%d}<br>Classic %{y:.2f}<extra></extra>"))
                neo = df.dropna(subset=["neo"])
                if not neo.empty:
                        fig.add_trace(go.Scatter(x=neo["date"], y=neo["neo"], name="Neo-Misery: + housing affordability", mode="lines", line=dict(color="#d86b4a",width=2.7), fill="tonexty", fillcolor="rgba(216,107,74,.10)", hovertemplate="%{x|%Y-%m-%d}<br>Neo-Misery %{y:.2f}<extra></extra>"))
        fig.update_layout(height=355, margin=dict(l=42,r=22,t=28,b=42), paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed",size=11),hovermode="x unified",legend=dict(orientation="h",y=-.20,x=0,bgcolor="rgba(0,0,0,0)"),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"),modebar=dict(bgcolor="rgba(0,0,0,0)",color="#7f8b99",activecolor="#d6bd65"))
        rng = _v29_default_range(df, 5)
        if rng: fig.update_xaxes(range=rng)
        return fig


def _v29_ranking_chart(df: pd.DataFrame) -> go.Figure:
        use = df.sort_values("Neo-Misery", ascending=True)
        fig = go.Figure()
        fig.add_trace(go.Bar(y=use["Country"], x=use["Classic"], orientation="h", name="Classic", marker_color="#72b7e8", hovertemplate="%{y}<br>Classic %{x:.1f}<extra></extra>"))
        fig.add_trace(go.Bar(y=use["Country"], x=use["Housing ratio"], orientation="h", name="Housing ratio", marker_color="#496dc7", hovertemplate="%{y}<br>Housing ratio %{x:.1f}<extra></extra>"))
        fig.update_layout(height=max(430, 36*len(use)+100), barmode="stack", margin=dict(l=120,r=30,t=25,b=40),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed"),legend=dict(orientation="h",y=-.10),xaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"),yaxis=dict(showgrid=False))
        return fig


def _v29_compare_chart(countries: List[str], measure: str) -> go.Figure:
        fig = go.Figure()
        palette = ["#72b7e8","#d8b52f","#d86b4a","#86c28b","#b07bd8","#4cc9c0"]
        for idx, country in enumerate(countries):
                hist, _ = _v29_misery_history(country)
                col = "classic" if measure == "Classic" else "neo"
                use = hist.dropna(subset=[col])
                if use.empty: continue
                fig.add_trace(go.Scatter(x=use["date"],y=use[col],name=country,mode="lines",line=dict(color=palette[idx%len(palette)],width=2.4),hovertemplate=f"%{{x|%Y-%m-%d}}<br>{country}: %{{y:.2f}}<extra></extra>"))
        fig.update_layout(height=430,margin=dict(l=45,r=25,t=25,b=45),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed"),hovermode="x unified",legend=dict(orientation="h",y=-.18),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"))
        return fig


def _v29_render_misery() -> None:
        _v29_css()
        _v16_html('<div class="m29-hero"><div class="m29-eyebrow">Social Macro</div><div class="m29-title">Misery Indices — G20</div><div class="m29-sub">Arthur Okun’s classic index adds unemployment and inflation. Neo-Misery adds the house-price-to-income affordability ratio; the distance between the two lines is therefore the housing burden. Latest values and five-point trends are anchored exactly to the inspected RoboMacro reference, while longer histories use public FRED/OECD/BIS/World Bank series where available.</div></div>')
        group = st.radio("Universe", ["All G20","Advanced","Emerging"], horizontal=True, key="m29_misery_group", label_visibility="collapsed")
        snap = _v29_reference_table(group)
        if snap.empty:
                st.info("No countries in this filter."); return
        top = snap.iloc[0]
        cols = st.columns(4, gap="medium")
        summary = [
                ("Highest Neo-Misery",f"{top['Neo-Misery']:.1f}",str(top["Country"])),
                ("Median Classic",f"{snap['Classic'].median():.1f}",f"{len(snap)} economies"),
                ("Median housing ratio",f"{snap['Housing ratio'].median():.1f}","Neo minus Classic"),
                ("Coverage",f"{len(snap)}/19",group),
        ]
        for col,(label,value,sub) in zip(cols,summary):
                with col: _v16_html(f'<div class="m29-kpi"><div class="m29-kpi-l">{_v16_esc(label)}</div><div class="m29-kpi-v">{_v16_esc(value)}</div><div class="m29-kpi-s">{_v16_esc(sub)}</div></div>')
        st.markdown("### Latest ranking")
        st.plotly_chart(_v29_ranking_chart(snap), use_container_width=True, config={"displaylogo":False,"responsive":True,"scrollZoom":True})
        st.markdown("### Compare economies")
        available = snap["Country"].tolist()
        default_compare = [x for x in ["United States","United Kingdom","China"] if x in available]
        cc1, cc2 = st.columns([3,1], gap="medium")
        with cc1:
                compare = st.multiselect("Countries", available, default=default_compare or available[:3], max_selections=6, key="m29_misery_compare")
        with cc2:
                measure = st.selectbox("Measure", ["Neo-Misery","Classic"], key="m29_misery_measure")
        if compare:
                st.plotly_chart(_v29_compare_chart(compare, measure), use_container_width=True, config={"displaylogo":False,"responsive":True,"scrollZoom":True})
        st.markdown("### Country charts")
        page_size = st.selectbox("Charts per page", [4,6,8,19], index=1, key="m29_misery_page_size")
        total_pages = max(1, int(math.ceil(len(available)/page_size)))
        page_key = "m29_misery_page"
        page = int(st.session_state.get(page_key, 1)); page = max(1,min(page,total_pages)); st.session_state[page_key] = page
        nav = st.columns([1,2,1])
        with nav[0]:
                if st.button("← Previous", key="m29_misery_prev", disabled=page<=1, use_container_width=True):
                        st.session_state[page_key]=page-1; st.rerun()
        with nav[1]: st.caption(f"Page {page} of {total_pages} · {len(available)} economies")
        with nav[2]:
                if st.button("Next →", key="m29_misery_next", disabled=page>=total_pages, use_container_width=True):
                        st.session_state[page_key]=page+1; st.rerun()
        selected = available[(page-1)*page_size:page*page_size]
        provenance_rows = []
        for row_idx in range(0,len(selected),2):
                pair = selected[row_idx:row_idx+2]
                cols = st.columns(2, gap="large")
                for col,country in zip(cols,pair):
                        meta = V29_MISERY_REFERENCE[country]
                        hist, prov = _v29_misery_history(country)
                        provenance_rows.append({"Country":country,**prov})
                        with col:
                                try: box = st.container(border=True)
                                except Exception: box = st.container()
                                with box:
                                        _v16_html(f'<div class="m29-country-head"><div><div class="m29-country-title">{_v16_esc(country)}</div><div class="m29-country-meta">{_v16_esc(meta["formula"])} · {meta["frequency"]}<br>As of {meta["date"]}</div></div><div class="m29-score"><span class="m29-pill">Classic {meta["classic"]:.1f}</span><span class="m29-pill rust">Neo {meta["neo"]:.1f}</span><span class="m29-pill gold">Housing {meta["neo"]-meta["classic"]:.1f}</span></div></div>')
                                        st.plotly_chart(_v29_misery_figure(country,hist), use_container_width=True, config={"displaylogo":False,"responsive":True,"scrollZoom":True,"modeBarButtonsToRemove":["lasso2d","select2d"]})
                                        _v16_html(f'<div class="m29-note">{_v16_esc(prov["classic"])}. Housing: {_v16_esc(prov["housing"])}.</div>')
        st.markdown("### Latest snapshot")
        display = snap.copy()
        for c in ["Classic","Neo-Misery","Housing ratio"]: display[c] = display[c].map(lambda x:f"{x:.1f}")
        try: st.dataframe(display, use_container_width=True, hide_index=True, height=min(760,40+35*len(display)))
        except Exception: _v16_html_table(display, max_rows=25)
        with st.expander("Methodology, sources and integrity", expanded=False):
                st.markdown("- **Classic** = unemployment rate + consumer-price inflation.\n- **Neo-Misery** = Classic + house-price-to-income affordability ratio.\n- Exact latest values and five-point directions are the inspected reference snapshot.\n- Longer Classic histories use public FRED/OECD/World Bank CPI and unemployment series when both are available.\n- Housing history uses a public price-to-income series when found; otherwise a real-house-price proxy is anchored to the published current housing ratio. If neither exists, only the published five-point housing trend is shown.\n- A reconstructed housing proxy is never labelled as the proprietary/original ratio.")
                if provenance_rows:
                        try: st.dataframe(pd.DataFrame(provenance_rows), use_container_width=True, hide_index=True)
                        except Exception: pass


# ---------------- China V29 audit fixes ----------------

def _v29_china_load_data() -> Tuple[Dict[str,pd.DataFrame],List[Dict[str,Any]]]:
        data, provenance = _v28_load_data()
        # Align GDP chart with the published release date used by the reference page.
        data["gdp_yoy"] = _v28_anchor(data.get("gdp_yoy",pd.DataFrame()), "2026-04-15", 5.0)
        # Do not concatenate a structural step path into a live policy series. Use public history when available,
        # otherwise retain a single verified snapshot rather than a fabricated line.
        policy, policy_status = _v28_fred_series("IRSTCB01CNM156N", start="1990-01-01")
        if policy.empty:
                policy = _v28_anchor(pd.DataFrame(columns=["date","value"]), "2026-03-01", 3.6)
                policy_status = "verified latest snapshot only"
        data["policy_rate"] = _v28_clean_frame(policy)
        provenance = [x for x in provenance if str(x.get("Series")) != "Central-bank rate proxy"]
        provenance.append({"Series":"PBoC policy rate","Identifier":"IRSTCB01CNM156N / snapshot","Source":"OECD/FRED or PBoC snapshot","Rows":len(data["policy_rate"]),"Latest":data["policy_rate"]["date"].max().date().isoformat() if not data["policy_rate"].empty else "—","Status":policy_status})
        return data, provenance


def _v29_apply_china_window(fig: go.Figure, frames: List[pd.DataFrame], years: int = 5) -> go.Figure:
        dates = []
        for frame in frames:
                df = _v28_clean_frame(frame)
                if not df.empty: dates.append(df["date"].max())
        if dates:
                end = max(dates); start = end - pd.DateOffset(years=years)
                fig.update_xaxes(range=[start,end])
        return fig


def _v29_china_dashboard(data: Dict[str,pd.DataFrame]) -> None:
        _v28_render_metrics(data)
        c1,c2 = st.columns(2,gap="large")
        with c1:
                fig = _v29_apply_china_window(_v28_dual_figure(data["gdp_yoy"],data["cpi_yoy"],"Real GDP YoY","CPI YoY","%","%"),[data["gdp_yoy"],data["cpi_yoy"]])
                _v28_chart_card("Growth & Inflation","Real GDP growth vs consumer inflation — the reflation gap (CPI on the right).",fig,"GDP 5.00% · 2026-04-15","CPI 1.00% · 2026-07-08","As of Jul 2026 · Monthly")
                fig2 = _v29_apply_china_window(_v28_dual_figure(data["csi300"],data["hang_seng"],"CSI 300","Hang Seng","index","index",rebase=True),[data["csi300"],data["hang_seng"]])
                csi,cdate=_v28_latest(data["csi300"],4780.79); hsi,hdate=_v28_latest(data["hang_seng"],24030.18)
                _v28_chart_card("Chinese Equities","Rebased to 100 at the initial five-year window — mainland CSI 300 vs Hong Kong Hang Seng.",fig2,f"CSI 300 {csi:,.1f} · {cdate}",f"Hang Seng {hsi:,.1f} · {hdate}",f"As of {max(cdate,hdate)} · Daily")
        with c2:
                fig3 = _v29_apply_china_window(_v28_dual_figure(data["usd_cny"],data["neer"],"USD/CNY","CNY NEER","CNY per USD","2020=100"),[data["usd_cny"],data["neer"]])
                fx,fdate=_v28_latest(data["usd_cny"],6.7886); neer,ndate=_v28_latest(data["neer"],111.83)
                _v28_chart_card("The Yuan","Onshore USD/CNY (higher = weaker yuan) vs the trade-weighted nominal effective exchange rate.",fig3,f"USD/CNY {fx:.4f} · {fdate}",f"NEER {neer:.2f} · {ndate}",f"As of {max(fdate,ndate)} · Daily/monthly")
                fig4 = _v29_apply_china_window(_v28_dual_figure(data["exports_yoy"],data["imports_yoy"],"Exports YoY","Imports YoY","%","%"),[data["exports_yoy"],data["imports_yoy"]])
                ex,edate=_v28_latest(data["exports_yoy"],13.75159); im,idate=_v28_latest(data["imports_yoy"],25.05253)
                _v28_chart_card("Trade Pulse","Exports vs imports, % YoY — external demand against domestic demand.",fig4,f"Exports {ex:.2f}% · {edate}",f"Imports {im:.2f}% · {idate}",f"As of {max(edate,idate)} · Monthly")


def _v29_render_china() -> None:
        _v28_css(); _v29_css()
        _v16_html('<div class="m28-hero"><div class="m28-eyebrow">China Macro</div><div class="m28-title">China Dashboard — Growth, PBoC, Trade & Markets</div><div class="m28-sub">Growth, inflation, PBoC policy, trade flows, the yuan and Chinese equity markets. V29 keeps the original four-pair dashboard, opens on a five-year analytical window, aligns release dates to the inspected reference and removes the structural policy-rate path when no official history is available.</div><div class="m28-cache">NBS · PBoC · Caixin · OECD · BIS · SAFE · IMF · FRED · market data</div></div>')
        tab = st.radio("China workspace",["Dashboard","Activity & Sentiment","Inflation & Policy","Trade & External","Markets & FX"],horizontal=True,key="m29_china_workspace",label_visibility="collapsed")
        with st.spinner("Loading China public data…"):
                try: data, provenance = _v29_china_load_data()
                except Exception as exc:
                        data, provenance = {},[]; st.warning(f"China providers partially unavailable: {exc}")
        required=["gdp_yoy","cpi_yoy","usd_cny","neer","exports_yoy","imports_yoy","csi300","hang_seng","consumer_conf","ppi_yoy","policy_rate","property_real_yoy","private_credit","fx_reserves"]
        for key in required: data.setdefault(key,pd.DataFrame(columns=["date","value"]))
        if tab=="Dashboard": _v29_china_dashboard(data)
        elif tab=="Activity & Sentiment": _v29_china_activity(data)
        elif tab=="Inflation & Policy": _v29_china_inflation_policy(data)
        elif tab=="Trade & External": _v29_china_trade(data)
        else: _v29_china_markets(data)
        _v28_render_provenance(provenance)
        _v16_html('<div class="m29-note">China V29 is frozen as a public-data-first final version: exact reference snapshots, real connected histories, explicit vintage differences and no silent synthetic macro curves.</div>')


# Final routing override: intercept China and Misery only; delegate every other stable page.
_v29_previous_render_page = _v28_previous_render_page

def _v29_render_page(page: str, selected_code: str, pack: Dict[str,pd.DataFrame], proxy_pack: Dict[str,pd.DataFrame], indicator_df: pd.DataFrame, bank_df: pd.DataFrame) -> None:
        normalized = _v12_normalize_page(page)
        if normalized == "china":
                _v29_render_china()
        elif normalized in ("misery","misery-indices"):
                _v29_render_misery()
        else:
                _v29_previous_render_page(page, selected_code, pack, proxy_pack, indicator_df, bank_df)

_v16_render_page = _v29_render_page

