def _v29_china_inflation_policy(data: Dict[str,pd.DataFrame]) -> None:
        _v28_render_metrics(data,["Inflation & Policy"])
        c1,c2=st.columns(2,gap="large")
        with c1:
                fig=_v29_apply_china_window(_v28_dual_figure(data["cpi_yoy"],data["ppi_yoy"],"CPI YoY","PPI YoY","%","%"),[data["cpi_yoy"],data["ppi_yoy"]])
                _v28_chart_card("Consumer & Producer Inflation","CPI and PPI year-on-year inflation. Recent NBS observations bridge older OECD histories without hiding the vintage difference.",fig,"CPI OECD/FRED + NBS anchors","PPI OECD/FRED + NBS anchors","Latest public readings")
        with c2:
                rate=_v28_clean_frame(data["policy_rate"]); prop=_v28_clean_frame(data["property_real_yoy"])
                if len(rate)>1:
                        fig=_v29_apply_china_window(_v28_dual_figure(rate,prop,"Policy rate","Real house prices YoY","%","%"),[rate,prop])
                        _v28_chart_card("PBoC Policy & Property","Official/public rate history against BIS real residential property-price growth. The NBS 70-city new-home snapshot remains separate.",fig,"PBoC/OECD policy history","BIS real property prices","Different definitions are not merged")
                else:
                        fig=_v29_apply_china_window(_v28_single_figure(prop,"Real house prices YoY","%","#72b7e8"),[prop])
                        _v28_chart_card("PBoC Policy & Property","Only the verified 3.6% policy snapshot is available; the chart therefore shows the connected BIS property history without inventing a policy path.",fig,"Policy rate 3.6% · 2026-03-01","BIS real property prices","Snapshot-safe mode")
        credit=_v28_clean_frame(data.get("private_credit",pd.DataFrame()))
        if len(credit)>=8:
                credit=credit.copy(); credit["value"]=credit["value"].pct_change(4)*100.0; credit=credit.dropna()
                fig=_v29_apply_china_window(_v28_single_figure(credit,"Private credit YoY","%","#86c28b"),[credit],10)
                _v28_chart_card("Credit Growth Diagnostic","BIS private non-financial credit, four-quarter growth. This is a transparent credit-cycle proxy, not a proprietary credit impulse.",fig,"BIS via FRED",asof="Quarterly diagnostic")


