def _v30_upsert(frame: pd.DataFrame, date: str, value: float) -> pd.DataFrame:
        df = _v28_clean_frame(frame)
        row = pd.DataFrame({"date":[pd.Timestamp(date)],"value":[float(value)]})
        out = pd.concat([df,row],ignore_index=True)
        return out.drop_duplicates("date",keep="last").sort_values("date").reset_index(drop=True)


def _v30_china_apply_official(data: Dict[str,pd.DataFrame]) -> Dict[str,pd.DataFrame]:
        out = {k:_v28_clean_frame(v) for k,v in dict(data or {}).items()}
        mapping = {
                "GDP YoY":"gdp_yoy","CPI YoY":"cpi_yoy","PPI YoY":"ppi_yoy",
                "Exports YoY":"exports_yoy","Imports YoY":"imports_yoy",
        }
        for label,key in mapping.items():
                meta = V30_CHINA_OFFICIAL[label]
                out[key] = _v30_upsert(out.get(key,pd.DataFrame()), meta["obs_date"], meta["value"])
        # FRED reserve history is in USD millions; SAFE official snapshot is USD billions.
        reserve_meta = V30_CHINA_OFFICIAL["FX Reserves"]
        out["fx_reserves"] = _v30_upsert(out.get("fx_reserves",pd.DataFrame()), reserve_meta["obs_date"], reserve_meta["value"]*1000.0)
        out["trade_balance"] = _v30_upsert(out.get("trade_balance",pd.DataFrame()), V30_CHINA_OFFICIAL["Trade Balance"]["obs_date"], V30_CHINA_OFFICIAL["Trade Balance"]["value"])
        out["urban_unemployment"] = _v30_upsert(out.get("urban_unemployment",pd.DataFrame()), V30_CHINA_OFFICIAL["Urban Unemployment"]["obs_date"], V30_CHINA_OFFICIAL["Urban Unemployment"]["value"])
        out["retail_sales_yoy"] = _v30_upsert(out.get("retail_sales_yoy",pd.DataFrame()), V30_CHINA_OFFICIAL["Retail Sales YoY"]["obs_date"], V30_CHINA_OFFICIAL["Retail Sales YoY"]["value"])
        return out


def _v30_china_metric_rows(data: Optional[Dict[str,pd.DataFrame]]=None) -> List[Dict[str,Any]]:
        rows = [dict(x) for x in V28_CHINA_SNAPSHOT]
        official_labels = set(V30_CHINA_OFFICIAL)
        for row in rows:
                label = row["label"]
                if label in official_labels:
                        meta = V30_CHINA_OFFICIAL[label]
                        row.update({
                                "value":meta["value"],"display":meta["display"],"date":meta["release_date"],
                                "source":meta["source"],"status":meta["status"],"period":meta["period"],
                                "obs_date":meta["obs_date"],
                        })
        # Dynamic market data may update beyond the inspected reference.
        if isinstance(data,dict):
                mapping = {
                        "Consumer Confidence":("consumer_conf",lambda x:f"{x:.0f}"),
                        "USD/CNY":("usd_cny",lambda x:f"{x:.4f}"),
                        "CSI 300":("csi300",lambda x:f"{x:,.1f}"),
                        "Hang Seng":("hang_seng",lambda x:f"{x:,.0f}"),
                        "CNY NEER":("neer",lambda x:f"{x:.2f}"),
                }
                for row in rows:
                        cfg=mapping.get(row["label"])
                        if not cfg: continue
                        val,date=_v28_latest(data.get(cfg[0],pd.DataFrame()),None)
                        if val is None or date=="—" or str(date)<str(row.get("date","")): continue
                        row.update({"value":float(val),"display":cfg[1](float(val)),"date":str(date),"obs_date":str(date),"period":"Latest connected observation","status":"Connected public/market history"})
        return rows


def _v30_render_china_metrics(data: Dict[str,pd.DataFrame], groups: Optional[List[str]]=None) -> None:
        for group in (groups or ["Activity","Inflation & Policy","External","Markets"]):
                _v16_html(f'<div class="m28-group-title">{_v16_esc(group)}</div>')
                rows=[r for r in _v30_china_metric_rows(data) if r["group"]==group]
                cols=st.columns(4,gap="medium")
                for col,row in zip(cols,rows):
                        with col:
                                period=row.get("period",row.get("date",""))
                                _v16_html(
                                        f'<div class="m28-metric"><div class="m28-metric-label">{_v16_esc(row["label"])}</div>'
                                        f'<div class="m28-metric-value">{_v16_esc(row["display"])}</div>'
                                        f'<div class="m28-metric-date">{_v16_esc(period)}</div>'
                                        f'<div class="m28-metric-source" title="Released { _v16_esc(row.get("date","—")) } · { _v16_esc(row["source"]) }">{_v16_esc(row["source"])} · rel. {_v16_esc(row.get("date","—"))}</div></div>'
                                )


def _v30_add_anchor_marker(fig: go.Figure, trace_name: str, date: str, value: float, label: str) -> go.Figure:
        # Add an isolated official marker. It is deliberately not connected to a different-vintage history.
        color="#f1cf4d"
        for tr in fig.data:
                if getattr(tr,"name","")==trace_name:
                        try: color=tr.line.color or color
                        except Exception: pass
                        break
        fig.add_trace(go.Scatter(x=[pd.Timestamp(date)],y=[float(value)],name=label,mode="markers",marker=dict(size=10,color=color,symbol="diamond",line=dict(width=1,color="#f7f8fa")),hovertemplate=f"%{{x|%Y-%m-%d}}<br>{label}: %{{y:.2f}}<extra></extra>",showlegend=True))
        return fig


def _v30_china_parity_table(data: Dict[str,pd.DataFrame]) -> pd.DataFrame:
        rows=[]
        for label, ref in V30_CHINA_ROBOMACRO_REFERENCE.items():
                official=V30_CHINA_OFFICIAL.get(label)
                if official:
                        latest=float(official["value"]); latest_date=official["release_date"]; source=official["source"]
                else:
                        key={"USD/CNY":"usd_cny","CSI 300":"csi300","Hang Seng":"hang_seng","CNY NEER":"neer"}.get(label)
                        latest,latest_date=_v28_latest(data.get(key,pd.DataFrame()),ref["value"])
                        latest=float(latest) if latest is not None else float(ref["value"]); source="Connected market/FRED"
                rows.append({"Metric":label,"Current terminal":latest,"Current date":latest_date,"Source":source,"RoboMacro cache":float(ref["value"]),"RoboMacro date":ref["date"],"Difference":latest-float(ref["value"])})
        return pd.DataFrame(rows)


