def _v30_cache_read(key: str) -> pd.DataFrame:
        if key in V30_MEM and isinstance(V30_MEM[key],pd.DataFrame): return V30_MEM[key].copy()
        if "_v27_read_frame_cache" in globals():
                try:
                        df=_v27_read_frame_cache(key,max_age_hours=V30_CACHE_HOURS,allow_stale=True)
                        df=_v28_clean_frame(df)
                        if not df.empty: V30_MEM[key]=df.copy(); return df
                except Exception: pass
        return pd.DataFrame(columns=["date","value"])


def _v30_cache_write(key: str, frame: pd.DataFrame, meta: Optional[Dict[str,Any]]=None) -> None:
        df=_v28_clean_frame(frame)
        if df.empty: return
        V30_MEM[key]=df.copy()
        if "_v27_write_frame_cache" in globals():
                try: _v27_write_frame_cache(key,df,meta=meta or {})
                except Exception: pass


def _v30_world_bank_series(country: str, indicator: str) -> Tuple[pd.DataFrame,Dict[str,str]]:
        iso3=V29_COUNTRY_CODES[country][1]
        key=f"v30_wb_{iso3}_{indicator.replace('.','_')}"
        cached=_v30_cache_read(key)
        if not cached.empty: return cached,{"provider":"World Bank","series":indicator,"frequency":"Annual","status":"cache"}
        if not (REQUESTS_AVAILABLE and requests is not None): return pd.DataFrame(columns=["date","value"]),{"provider":"World Bank","series":indicator,"frequency":"Annual","status":"unavailable"}
        try:
                url=f"https://api.worldbank.org/v2/country/{iso3}/indicator/{indicator}"
                r=requests.get(url,params={"format":"json","per_page":2000,"date":"1950:2026"},timeout=(7,25),headers={"User-Agent":"QuantTerminal/30 macro research"})
                r.raise_for_status(); payload=r.json(); rows=payload[1] if isinstance(payload,list) and len(payload)>1 else []
                vals=[]
                for item in rows:
                        val=item.get("value"); year=item.get("date")
                        if val is None or not str(year).isdigit(): continue
                        vals.append({"date":pd.Timestamp(f"{year}-12-31"),"value":float(val)})
                df=_v28_clean_frame(pd.DataFrame(vals))
                _v30_cache_write(key,df,{"provider":"World Bank","series":indicator})
                return df,{"provider":"World Bank","series":indicator,"frequency":"Annual","status":"live" if not df.empty else "empty"}
        except Exception as exc:
                return pd.DataFrame(columns=["date","value"]),{"provider":"World Bank","series":indicator,"frequency":"Annual","status":f"error: {type(exc).__name__}"}


def _v30_imf_series(country: str, indicator: str) -> Tuple[pd.DataFrame,Dict[str,str]]:
        iso3=V29_COUNTRY_CODES[country][1]
        key=f"v30_imf_{iso3}_{indicator}"
        cached=_v30_cache_read(key)
        if not cached.empty: return cached,{"provider":"IMF DataMapper","series":indicator,"frequency":"Annual","status":"cache"}
        if not (REQUESTS_AVAILABLE and requests is not None): return pd.DataFrame(columns=["date","value"]),{"provider":"IMF DataMapper","series":indicator,"frequency":"Annual","status":"unavailable"}
        try:
                r=requests.get(f"https://www.imf.org/external/datamapper/api/v1/{indicator}/{iso3}",timeout=(7,25),headers={"User-Agent":"QuantTerminal/30 macro research"})
                r.raise_for_status(); raw=r.json().get("values",{}).get(indicator,{}).get(iso3,{})
                vals=[]
                for year,val in dict(raw or {}).items():
                        if val is None or not str(year).isdigit() or int(year)>2026: continue
                        vals.append({"date":pd.Timestamp(f"{year}-12-31"),"value":float(val)})
                df=_v28_clean_frame(pd.DataFrame(vals)); _v30_cache_write(key,df,{"provider":"IMF","series":indicator})
                return df,{"provider":"IMF DataMapper","series":indicator,"frequency":"Annual","status":"live" if not df.empty else "empty"}
        except Exception as exc:
                return pd.DataFrame(columns=["date","value"]),{"provider":"IMF DataMapper","series":indicator,"frequency":"Annual","status":f"error: {type(exc).__name__}"}


def _v30_fetch_macro(country: str, kind: str) -> Tuple[pd.DataFrame,Dict[str,str]]:
        # 1) deterministic FRED/OECD high-frequency series; 2) World Bank annual; 3) IMF annual.
        df,status,sid=_v29_fetch_candidates(country,kind)
        df=_v28_clean_frame(df)
        if len(df)>=3:
                med=df["date"].diff().dt.days.median() if len(df)>2 else np.nan
                freq="Monthly" if pd.notna(med) and med<60 else ("Quarterly" if pd.notna(med) and med<180 else "Annual")
                return df,{"provider":"FRED/OECD","series":sid or "candidate","frequency":freq,"status":status}
        wb_ind="FP.CPI.TOTL.ZG" if kind=="cpi" else "SL.UEM.TOTL.ZS"
        wb,meta=_v30_world_bank_series(country,wb_ind)
        if len(wb)>=3: return wb,meta
        imf_ind="PCPIPCH" if kind=="cpi" else "LUR"
        imf,meta2=_v30_imf_series(country,imf_ind)
        if len(imf)>=3: return imf,meta2
        return pd.DataFrame(columns=["date","value"]),{"provider":"Reference only","series":"—","frequency":"Reference tail","status":"unavailable"}


def _v30_parse_oecd_csv(text: str) -> pd.DataFrame:
        try: raw=pd.read_csv(_V30StringIO(text))
        except Exception: return pd.DataFrame(columns=["date","value"])
        if raw.empty: return pd.DataFrame(columns=["date","value"])
        cols={str(c).strip().upper():c for c in raw.columns}
        tcol=cols.get("TIME_PERIOD"); vcol=cols.get("OBS_VALUE")
        if tcol is None or vcol is None: return pd.DataFrame(columns=["date","value"])
        def parse_period(x: Any) -> pd.Timestamp:
                s=str(x)
                try:
                        if "-Q" in s.upper():
                                y,q=s.upper().split("-Q"); return pd.Period(f"{y}Q{q}",freq="Q").end_time.normalize()
                        if len(s)==4 and s.isdigit(): return pd.Timestamp(f"{s}-12-31")
                        return pd.Timestamp(s)
                except Exception: return pd.NaT
        return _v28_clean_frame(pd.DataFrame({"date":raw[tcol].map(parse_period),"value":pd.to_numeric(raw[vcol],errors="coerce")}))


def _v30_oecd_price_income(country: str) -> Tuple[pd.DataFrame,Dict[str,str]]:
        if country not in V30_OECD_PTI_SUPPORTED:
                return pd.DataFrame(columns=["date","value"]),{"provider":"OECD","series":"HPI_YDH","frequency":"Quarterly","status":"not covered"}
        iso3=V29_COUNTRY_CODES[country][1]
        key=f"v30_oecd_pti_{iso3}"
        cached=_v30_cache_read(key)
        if not cached.empty: return cached,{"provider":"OECD Data Explorer","series":"HPI_YDH","frequency":"Quarterly","status":"cache"}
        if not (REQUESTS_AVAILABLE and requests is not None): return pd.DataFrame(columns=["date","value"]),{"provider":"OECD Data Explorer","series":"HPI_YDH","frequency":"Quarterly","status":"unavailable"}
        paths=[
                f"https://sdmx.oecd.org/public/rest/v1/data/OECD.ECO.MPD,DSD_AN_HOUSE_PRICES@DF_HOUSE_PRICES,1.0/{iso3}.Q.HPI_YDH.",
                f"https://sdmx.oecd.org/public/rest/data/OECD.ECO.MPD,DSD_AN_HOUSE_PRICES@DF_HOUSE_PRICES,1.0/{iso3}.Q.HPI_YDH.",
                f"https://sdmx.oecd.org/public/rest/data/OECD.ECO.MPD,DSD_AN_HOUSE_PRICES@DF_HOUSE_PRICES/{iso3}.Q.HPI_YDH.",
        ]
        params={"startPeriod":"1970-Q1","dimensionAtObservation":"AllDimensions","format":"csvfilewithlabels"}
        last_error="unavailable"
        for url in paths:
                try:
                        r=requests.get(url,params=params,timeout=(8,30),headers={"User-Agent":"QuantTerminal/30 OECD responsible client"})
                        if r.status_code>=400: last_error=f"HTTP {r.status_code}"; continue
                        df=_v30_parse_oecd_csv(r.text)
                        if len(df)>=4:
                                _v30_cache_write(key,df,{"provider":"OECD","series":"HPI_YDH"})
                                return df,{"provider":"OECD Data Explorer","series":"HPI_YDH","frequency":"Quarterly","status":"live"}
                except Exception as exc: last_error=type(exc).__name__
        return pd.DataFrame(columns=["date","value"]),{"provider":"OECD Data Explorer","series":"HPI_YDH","frequency":"Quarterly","status":last_error}


def _v30_frequency(frame: pd.DataFrame) -> str:
        df=_v28_clean_frame(frame)
        if len(df)<3: return "Unknown"
        med=df["date"].diff().dt.days.median()
        if pd.isna(med): return "Unknown"
        if med<10:return "Weekly"
        if med<60:return "Monthly"
        if med<180:return "Quarterly"
        return "Annual"


def _v30_align_classic(cpi: pd.DataFrame, unemp: pd.DataFrame) -> Tuple[pd.DataFrame,str]:
        c=_v28_clean_frame(cpi); u=_v28_clean_frame(unemp)
        if c.empty or u.empty: return pd.DataFrame(columns=["date","classic"]),"Reference only"
        ranks={"Weekly":0,"Monthly":1,"Quarterly":2,"Annual":3,"Unknown":3}
        cf,uf=_v30_frequency(c),_v30_frequency(u); target=max([cf,uf],key=lambda x:ranks[x])
        rule={"Weekly":"W-FRI","Monthly":"ME","Quarterly":"QE","Annual":"YE"}[target]
        cs=c.set_index("date")["value"].resample(rule).last().dropna().rename("cpi")
        us=u.set_index("date")["value"].resample(rule).last().dropna().rename("unemployment")
        merged=pd.concat([cs,us],axis=1,join="inner").dropna().reset_index()
        merged["classic"]=merged["cpi"]+merged["unemployment"]
        return merged[["date","classic"]],target


def _v30_reference_tail(country: str) -> pd.DataFrame:
        meta=V30_MISERY_REFERENCE[country]
        dates=_v29_trend_dates(meta)
        classic=list(meta["classic_trend"]); neo=list(meta["neo_trend"])
        classic[-1]=float(meta["classic"]); neo[-1]=float(meta["neo"])
        return pd.DataFrame({"date":dates,"classic_ref":classic,"neo_ref":neo,"housing_ref":np.array(neo)-np.array(classic)})


def _v30_build_misery(country: str) -> Tuple[pd.DataFrame,Dict[str,Any]]:
        meta=V30_MISERY_REFERENCE[country]
        cpi,cmeta=_v30_fetch_macro(country,"cpi"); unemp,umeta=_v30_fetch_macro(country,"unemp")
        classic,classic_freq=_v30_align_classic(cpi,unemp)
        pti,pmeta=_v30_oecd_price_income(country)
        public=pd.DataFrame(columns=["date","classic_public","housing_public","neo_public"])
        if not classic.empty:
                public=classic.rename(columns={"classic":"classic_public"})
                if not pti.empty and float(pti["value"].iloc[-1])!=0:
                        latest_gap=float(meta["neo"]-meta["classic"])
                        norm=pti.copy(); norm["housing_public"]=latest_gap*norm["value"]/float(norm["value"].iloc[-1])
                        norm=norm[["date","housing_public"]]
                        # Align at the coarser quarterly cadence without linear interpolation.
                        pc=public.set_index("date")["classic_public"].resample("QE").last().dropna()
                        ph=norm.set_index("date")["housing_public"].resample("QE").last().dropna()
                        joined=pd.concat([pc,ph],axis=1,join="inner").dropna().reset_index()
                        joined["neo_public"]=joined["classic_public"]+joined["housing_public"]
                        public=joined
                else:
                        public["housing_public"]=np.nan; public["neo_public"]=np.nan
        ref=_v30_reference_tail(country)
        # Public observations and exact reference tail are kept in separate columns. No estimate is
        # inserted into the exact reference table and no annual series is linearly interpolated monthly.
        all_dates=pd.Index([])
        for df in [public,ref]:
                if not df.empty: all_dates=all_dates.union(pd.DatetimeIndex(df["date"]))
        out=pd.DataFrame({"date":pd.DatetimeIndex(all_dates).sort_values()}) if len(all_dates) else ref.copy()
        if not public.empty: out=out.merge(public,on="date",how="left")
        else:
                out["classic_public"]=np.nan;out["housing_public"]=np.nan;out["neo_public"]=np.nan
        out=out.merge(ref,on="date",how="left")
        status={
                "classic_provider":f"{cmeta['provider']} {cmeta['series']} + {umeta['provider']} {umeta['series']}",
                "classic_frequency":classic_freq,
                "classic_points":int(public["classic_public"].notna().sum()) if "classic_public" in public else 0,
                "housing_provider":f"{pmeta['provider']} {pmeta['series']} ({pmeta['status']})" if not pti.empty else "Exact published five-point reference tail only",
                "housing_method":"OECD price-to-income index level-normalized to the exact latest housing gap" if not pti.empty else "No reconstructed long housing history",
                "reference_points":5,
                "mixed_vintage":str(meta["classic_date"])!=str(meta["neo_date"]),
        }
        return out.sort_values("date").reset_index(drop=True),status


def _v30_misery_figure(country: str, frame: pd.DataFrame, mode: str="Best available") -> go.Figure:
        fig=go.Figure(); df=frame.copy()
        if mode!="Reference tail only":
                pc=df.dropna(subset=["classic_public"])
                if not pc.empty:
                        fig.add_trace(go.Scatter(x=pc["date"],y=pc["classic_public"],name="Classic · public history",mode="lines",line=dict(color="#72b7e8",width=2.2),hovertemplate="%{x|%Y-%m-%d}<br>Classic public %{y:.2f}<extra></extra>"))
                pn=df.dropna(subset=["neo_public"])
                if not pn.empty and mode=="Best available":
                        fig.add_trace(go.Scatter(x=pn["date"],y=pn["neo_public"],name="Neo · OECD PTI-normalized history",mode="lines",line=dict(color="#d86b4a",width=2.3),fill="tonexty",fillcolor="rgba(216,107,74,.08)",hovertemplate="%{x|%Y-%m-%d}<br>Neo public proxy %{y:.2f}<extra></extra>"))
        ref=df.dropna(subset=["classic_ref"])
        if not ref.empty:
                fig.add_trace(go.Scatter(x=ref["date"],y=ref["classic_ref"],name="Classic · exact reference tail",mode="lines+markers",line=dict(color="#a9d8f5",width=2.5,dash="dot"),marker=dict(size=6),hovertemplate="%{x|%Y-%m-%d}<br>Classic reference %{y:.2f}<extra></extra>"))
                if mode!="Public classic only":
                        fig.add_trace(go.Scatter(x=ref["date"],y=ref["neo_ref"],name="Neo · exact reference tail",mode="lines+markers",line=dict(color="#ef805f",width=2.6,dash="dot"),marker=dict(size=6),hovertemplate="%{x|%Y-%m-%d}<br>Neo reference %{y:.2f}<extra></extra>"))
        fig.update_layout(height=365,margin=dict(l=42,r=22,t=28,b=52),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed",size=11),hovermode="x unified",legend=dict(orientation="h",y=-.23,x=0,bgcolor="rgba(0,0,0,0)"),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"),modebar=dict(bgcolor="rgba(0,0,0,0)",color="#7f8b99",activecolor="#d6bd65"))
        rng=_v29_default_range(df,5)
        if rng: fig.update_xaxes(range=rng)
        return fig


def _v30_reference_table(group: str="All G20") -> pd.DataFrame:
        rows=[]
        for country,meta in V30_MISERY_REFERENCE.items():
                if group not in ("All G20","All") and meta["group"]!=group: continue
                classic=float(meta["classic"]);neo=float(meta["neo"])
                rows.append({
                        "Country":country,"Group":meta["group"],"Classic":classic,"Classic as of":meta["classic_date"],
                        "Neo-Misery":neo,"Neo as of":meta["neo_date"],"Housing gap":neo-classic,
                        "Frequency":meta["neo_frequency"],"Mixed vintage":"Yes" if meta["classic_date"]!=meta["neo_date"] else "No",
                        "Latest values":"Exact reference",
                })
        return pd.DataFrame(rows).sort_values("Neo-Misery",ascending=False).reset_index(drop=True)


def _v30_ranking_chart(df: pd.DataFrame) -> go.Figure:
        use=df.sort_values("Neo-Misery",ascending=True)
        fig=go.Figure()
        fig.add_trace(go.Bar(y=use["Country"],x=use["Classic"],orientation="h",name="Classic",marker_color="#72b7e8",hovertemplate="%{y}<br>Classic %{x:.2f}<extra></extra>"))
        fig.add_trace(go.Bar(y=use["Country"],x=use["Housing gap"],orientation="h",name="Housing gap",marker_color="#496dc7",hovertemplate="%{y}<br>Housing gap %{x:.2f}<extra></extra>"))
        fig.update_layout(height=max(430,36*len(use)+100),barmode="stack",margin=dict(l=120,r=30,t=25,b=40),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed"),legend=dict(orientation="h",y=-.10),xaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"),yaxis=dict(showgrid=False))
        return fig


def _v30_compare_chart(countries: List[str],measure: str,mode: str) -> go.Figure:
        fig=go.Figure();palette=["#72b7e8","#d8b52f","#d86b4a","#86c28b","#b07bd8","#4cc9c0"]
        for idx,country in enumerate(countries):
                hist,_=_v30_build_misery(country)
                if mode=="Reference tail only": col="classic_ref" if measure=="Classic" else "neo_ref"
                else:
                        col="classic_public" if measure=="Classic" else "neo_public"
                        if hist[col].notna().sum()<3: col="classic_ref" if measure=="Classic" else "neo_ref"
                use=hist.dropna(subset=[col])
                if use.empty: continue
                fig.add_trace(go.Scatter(x=use["date"],y=use[col],name=country,mode="lines",line=dict(color=palette[idx%len(palette)],width=2.4),hovertemplate=f"%{{x|%Y-%m-%d}}<br>{country}: %{{y:.2f}}<extra></extra>"))
        fig.update_layout(height=430,margin=dict(l=45,r=25,t=25,b=45),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed"),hovermode="x unified",legend=dict(orientation="h",y=-.18),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"))
        return fig


def _v30_render_misery() -> None:
        _v29_css()
        _v16_html('<div class="m29-hero"><div class="m29-eyebrow">Social Macro</div><div class="m29-title">Misery Indices — G20</div><div class="m29-sub">Exact latest reference values are kept separate from reconstructed histories. Classic public history uses FRED/OECD, World Bank or IMF data at native/coarser cadence; housing history uses the OECD price-to-income index where available. No annual or quarterly observation is linearly interpolated into fake monthly data.</div></div>')
        group=st.radio("Universe",["All G20","Advanced","Emerging"],horizontal=True,key="m30_misery_group",label_visibility="collapsed")
        snap=_v30_reference_table(group)
        if snap.empty: st.info("No countries in this filter."); return
        top=snap.iloc[0]; mixed=int((snap["Mixed vintage"]=="Yes").sum())
        cols=st.columns(4,gap="medium")
        summary=[("Highest Neo-Misery",f"{top['Neo-Misery']:.1f}",str(top["Country"])),("Median Classic",f"{snap['Classic'].median():.1f}",f"{len(snap)} economies"),("Median housing gap",f"{snap['Housing gap'].median():.1f}","Neo minus Classic"),("Mixed vintages",str(mixed),"separate Classic/Neo dates")]
        for col,(label,value,sub) in zip(cols,summary):
                with col:_v16_html(f'<div class="m29-kpi"><div class="m29-kpi-l">{_v16_esc(label)}</div><div class="m29-kpi-v">{_v16_esc(value)}</div><div class="m29-kpi-s">{_v16_esc(sub)}</div></div>')
        st.markdown("### Latest ranking · exact reference values")
        st.plotly_chart(_v30_ranking_chart(snap),use_container_width=True,config={"displaylogo":False,"responsive":True,"scrollZoom":True})
        st.markdown("### Compare economies")
        available=snap["Country"].tolist(); defaults=[x for x in ["United States","United Kingdom","China"] if x in available]
        cc1,cc2,cc3=st.columns([3,1,1.4],gap="medium")
        with cc1: compare=st.multiselect("Countries",available,default=defaults or available[:3],max_selections=6,key="m30_misery_compare")
        with cc2: measure=st.selectbox("Measure",["Neo-Misery","Classic"],key="m30_misery_measure")
        with cc3: history_mode=st.selectbox("History mode",["Best available","Reference tail only","Public classic only"],key="m30_misery_history_mode",help="Best available never converts a real-house-price index into the exact housing ratio. OECD price-to-income history is used where available; otherwise Neo history remains the exact five-point reference tail.")
        if compare: st.plotly_chart(_v30_compare_chart(compare,measure,history_mode),use_container_width=True,config={"displaylogo":False,"responsive":True,"scrollZoom":True})
        st.markdown("### Country charts")
        page_size=st.selectbox("Charts per page",[4,6,8,19],index=1,key="m30_misery_page_size")
        total_pages=max(1,int(math.ceil(len(available)/page_size)));page_key="m30_misery_page";page=int(st.session_state.get(page_key,1));page=max(1,min(page,total_pages));st.session_state[page_key]=page
        nav=st.columns([1,2,1])
        with nav[0]:
                if st.button("← Previous",key="m30_misery_prev",disabled=page<=1,use_container_width=True):st.session_state[page_key]=page-1;st.rerun()
        with nav[1]:st.caption(f"Page {page} of {total_pages} · {len(available)} economies")
        with nav[2]:
                if st.button("Next →",key="m30_misery_next",disabled=page>=total_pages,use_container_width=True):st.session_state[page_key]=page+1;st.rerun()
        selected=available[(page-1)*page_size:page*page_size];quality_rows=[]
        for row_idx in range(0,len(selected),2):
                pair=selected[row_idx:row_idx+2];chart_cols=st.columns(2,gap="large")
                for col,country in zip(chart_cols,pair):
                        meta=V30_MISERY_REFERENCE[country];hist,status=_v30_build_misery(country);quality_rows.append({"Country":country,**status})
                        with col:
                                try:box=st.container(border=True)
                                except Exception:box=st.container()
                                with box:
                                        vintage=f"Classic {meta['classic_date']} · Neo {meta['neo_date']}" if meta['classic_date']!=meta['neo_date'] else f"As of {meta['neo_date']}"
                                        _v16_html(f'<div class="m29-country-head"><div><div class="m29-country-title">{_v16_esc(country)}</div><div class="m29-country-meta">{_v16_esc(meta["formula"])} · {meta["neo_frequency"]}<br>{_v16_esc(vintage)}</div></div><div class="m29-score"><span class="m29-pill">Classic {meta["classic"]:.1f}</span><span class="m29-pill rust">Neo {meta["neo"]:.1f}</span><span class="m29-pill gold">Housing {meta["neo"]-meta["classic"]:.1f}</span></div></div>')
                                        st.plotly_chart(_v30_misery_figure(country,hist,history_mode),use_container_width=True,config={"displaylogo":False,"responsive":True,"scrollZoom":True,"modeBarButtonsToRemove":["lasso2d","select2d"]})
                                        classic_badge=f"{status['classic_provider']} · {status['classic_frequency']} · {status['classic_points']} points"
                                        housing_badge=status["housing_provider"]
                                        _v16_html(f'<div class="m29-note"><b>Classic history:</b> {_v16_esc(classic_badge)}.<br><b>Housing history:</b> {_v16_esc(housing_badge)}.<br><b>Method:</b> {_v16_esc(status["housing_method"])}.</div>')
        st.markdown("### Latest snapshot · no estimated values")
        display=snap.copy()
        for c in ["Classic","Neo-Misery","Housing gap"]:display[c]=display[c].map(lambda x:f"{x:.1f}")
        try:st.dataframe(display,use_container_width=True,hide_index=True,height=min(800,42+35*len(display)))
        except Exception:_v16_html_table(display,max_rows=25)
        with st.expander("Methodology, source quality and parity validation",expanded=False):
                st.markdown("- **Snapshot table:** exact values transcribed from the inspected original; no model estimate is written into these cells.\n- **Mixed vintage:** India and South Africa have different Classic and Neo observation dates; V30 displays both instead of hiding the mismatch.\n- **Classic history:** CPI + unemployment at the coarser native cadence. Annual/quarterly observations are never linearly interpolated into monthly pseudo-data.\n- **Housing history:** OECD `HPI_YDH` price-to-income index where available, normalized only to the exact latest housing gap. Where unavailable, only the exact five-point reference tail is shown.\n- **Removed method:** V29's arbitrary 0.35-power scaling of a real-house-price index has been eliminated.\n- **Reference parity:** Germany's first five-point Classic observation is corrected from 9.18 to 6.68.")
                if quality_rows:
                        qdf=pd.DataFrame(quality_rows)
                        try:st.dataframe(qdf,use_container_width=True,hide_index=True)
                        except Exception:pass


