def _v30_render_page(page: str, selected_code: str, pack: Dict[str,pd.DataFrame], proxy_pack: Dict[str,pd.DataFrame], indicator_df: pd.DataFrame, bank_df: pd.DataFrame) -> None:
        normalized=_v12_normalize_page(page)
        if normalized=="china": _v30_render_china()
