def _v31_china_apply_official(data: Dict[str,pd.DataFrame]) -> Dict[str,pd.DataFrame]:
        out=_v30_china_apply_official(data)
        # Never splice a 7-day repo snapshot onto an older series whose definition may be
        # an LPR or OECD lending-rate proxy. Keep a definition-pure one-point observation.
        out["policy_rate"]=pd.DataFrame({"date":[pd.Timestamp("2026-07-15")],"value":[1.40]})
        return out


