# ---------------- Misery V31: separate clocks, reference/public audit ----------------

def _v31_tail_dates(end_date: str, frequency: str, periods: int=5) -> pd.DatetimeIndex:
        end=pd.Timestamp(end_date)
        freq=str(frequency or "Monthly").lower()
        if "week" in freq:return pd.DatetimeIndex([end-pd.Timedelta(days=7*i) for i in range(periods-1,-1,-1)])
        if "quarter" in freq:return pd.DatetimeIndex([end-pd.DateOffset(months=3*i) for i in range(periods-1,-1,-1)])
        if "annual" in freq or "year" in freq:return pd.DatetimeIndex([end-pd.DateOffset(years=i) for i in range(periods-1,-1,-1)])
        return pd.DatetimeIndex([end-pd.DateOffset(months=i) for i in range(periods-1,-1,-1)])


def _v31_reference_tail(country: str) -> pd.DataFrame:
        meta=V30_MISERY_REFERENCE[country]
        classic=list(map(float,meta["classic_trend"]));neo=list(map(float,meta["neo_trend"]))
        classic[-1]=float(meta["classic"]);neo[-1]=float(meta["neo"])
        cd=_v31_tail_dates(meta["classic_date"],meta["classic_frequency"],len(classic))
        nd=_v31_tail_dates(meta["neo_date"],meta["neo_frequency"],len(neo))
        cdf=pd.DataFrame({"date":cd,"classic_ref":classic})
        ndf=pd.DataFrame({"date":nd,"neo_ref":neo})
        out=cdf.merge(ndf,on="date",how="outer").sort_values("date").reset_index(drop=True)
        # Housing reference gap exists only where the two reference clocks genuinely coincide.
        out["housing_ref"]=out["neo_ref"]-out["classic_ref"]
        return out


def _v31_build_misery(country: str) -> Tuple[pd.DataFrame,Dict[str,Any]]:
        meta=V30_MISERY_REFERENCE[country]
        cpi,cmeta=_v30_fetch_macro(country,"cpi");unemp,umeta=_v30_fetch_macro(country,"unemp")
        classic,classic_freq=_v30_align_classic(cpi,unemp)
        pti,pmeta=_v30_oecd_price_income(country)
        public=pd.DataFrame(columns=["date","classic_public","housing_proxy","neo_proxy"])
        if not classic.empty:
                public=classic.rename(columns={"classic":"classic_public"})
                if not pti.empty and float(pti["value"].iloc[-1])!=0:
                        # Trend proxy only: OECD HPI_YDH is an index, not the reference's level ratio.
                        latest_gap=float(meta["neo"]-meta["classic"])
                        norm=pti.copy();norm["housing_proxy"]=latest_gap*norm["value"]/float(norm["value"].iloc[-1])
                        pc=public.set_index("date")["classic_public"].resample("QE").last().dropna()
                        ph=norm.set_index("date")["housing_proxy"].resample("QE").last().dropna()
                        joined=pd.concat([pc,ph],axis=1,join="inner").dropna().reset_index()
                        joined["neo_proxy"]=joined["classic_public"]+joined["housing_proxy"]
                        public=joined
                else:
                        public["housing_proxy"]=np.nan;public["neo_proxy"]=np.nan
        ref=_v31_reference_tail(country)
        dates=pd.DatetimeIndex([])
        for df in (public,ref):
                if not df.empty:dates=dates.union(pd.DatetimeIndex(df["date"]))
        out=pd.DataFrame({"date":dates.sort_values()})
        if not public.empty:out=out.merge(public,on="date",how="left")
        else:
                out["classic_public"]=np.nan;out["housing_proxy"]=np.nan;out["neo_proxy"]=np.nan
        out=out.merge(ref,on="date",how="left")
        pub=out.dropna(subset=["classic_public"])
        latest_public=float(pub["classic_public"].iloc[-1]) if not pub.empty else np.nan
        latest_public_date=str(pub["date"].iloc[-1].date()) if not pub.empty else "—"
        delta=latest_public-float(meta["classic"]) if np.isfinite(latest_public) else np.nan
        has_pti=not pti.empty
        tier="A" if (not pub.empty and has_pti) else ("B" if not pub.empty else "C")
        status={
                "quality_tier":tier,
                "classic_provider":f"{cmeta['provider']} {cmeta['series']} + {umeta['provider']} {umeta['series']}",
                "classic_frequency":classic_freq,
                "classic_points":int(out["classic_public"].notna().sum()),
                "public_classic_latest":latest_public,
                "public_classic_date":latest_public_date,
                "reference_classic":float(meta["classic"]),
                "classic_delta":delta,
                "housing_provider":f"{pmeta['provider']} {pmeta['series']} ({pmeta['status']})" if has_pti else "RoboMacro five-point reference tail only",
                "housing_method":"OECD price-to-income index normalized for trend display only; not an observed ratio level" if has_pti else "No long housing reconstruction",
                "reference_points_classic":int(ref["classic_ref"].notna().sum()),
                "reference_points_neo":int(ref["neo_ref"].notna().sum()),
                "mixed_vintage":str(meta["classic_date"])!=str(meta["neo_date"]),
        }
        return out.sort_values("date").reset_index(drop=True),status


def _v31_reference_table(group: str="All G20") -> pd.DataFrame:
        rows=[]
        for country,meta in V30_MISERY_REFERENCE.items():
                if group not in ("All G20","All") and meta["group"]!=group:continue
                classic=float(meta["classic"]);neo=float(meta["neo"])
                rows.append({
                        "Country":country,"Group":meta["group"],"Classic":classic,"Classic as of":meta["classic_date"],
                        "Classic frequency":meta["classic_frequency"],"Neo-Misery":neo,"Neo as of":meta["neo_date"],
                        "Neo frequency":meta["neo_frequency"],"Housing gap":neo-classic,
                        "Mixed vintage":"Yes" if meta["classic_date"]!=meta["neo_date"] else "No",
                        "Snapshot provenance":"RoboMacro reference",
                })
        return pd.DataFrame(rows).sort_values("Neo-Misery",ascending=False).reset_index(drop=True)


def _v31_misery_figure(country: str, frame: pd.DataFrame, mode: str="Public classic + reference tail") -> go.Figure:
        fig=go.Figure();df=frame.copy()
        if mode!="Reference tail only":
                pc=df.dropna(subset=["classic_public"])
                if not pc.empty:
                        fig.add_trace(go.Scatter(x=pc["date"],y=pc["classic_public"],name="Classic · public reconstruction",mode="lines",line=dict(color="#72b7e8",width=2.3),hovertemplate="%{x|%Y-%m-%d}<br>Classic public %{y:.2f}<extra></extra>"))
        if mode=="OECD PTI-normalized proxy":
                pn=df.dropna(subset=["neo_proxy"])
                if not pn.empty:
                        fig.add_trace(go.Scatter(x=pn["date"],y=pn["neo_proxy"],name="Neo · normalized OECD PTI proxy",mode="lines",line=dict(color="#d86b4a",width=2.2,dash="dash"),hovertemplate="%{x|%Y-%m-%d}<br>Neo proxy %{y:.2f}<extra></extra>"))
        if mode!="Public classic only":
                cr=df.dropna(subset=["classic_ref"])
                nr=df.dropna(subset=["neo_ref"])
                if not cr.empty:
                        fig.add_trace(go.Scatter(x=cr["date"],y=cr["classic_ref"],name="Classic · RoboMacro reference tail",mode="lines+markers",line=dict(color="#a9d8f5",width=2.4,dash="dot"),marker=dict(size=6),hovertemplate="%{x|%Y-%m-%d}<br>Classic reference %{y:.2f}<extra></extra>"))
                if not nr.empty:
                        fig.add_trace(go.Scatter(x=nr["date"],y=nr["neo_ref"],name="Neo · RoboMacro reference tail",mode="lines+markers",line=dict(color="#ef805f",width=2.5,dash="dot"),marker=dict(size=6),hovertemplate="%{x|%Y-%m-%d}<br>Neo reference %{y:.2f}<extra></extra>"))
        fig.update_layout(height=365,margin=dict(l=42,r=22,t=28,b=62),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed",size=11),hovermode="x unified",legend=dict(orientation="h",y=-.28,x=0,bgcolor="rgba(0,0,0,0)"),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"),modebar=dict(bgcolor="rgba(0,0,0,0)",color="#7f8b99",activecolor="#d6bd65"))
        rng=_v29_default_range(df,5)
        if rng:fig.update_xaxes(range=rng)
        return fig


def _v31_compare_chart(countries: List[str],measure: str,mode: str) -> go.Figure:
        fig=go.Figure();palette=["#72b7e8","#d8b52f","#d86b4a","#86c28b","#b07bd8","#4cc9c0"]
        for idx,country in enumerate(countries):
                hist,_=_v31_build_misery(country)
                if measure=="Classic":
                        col="classic_ref" if mode=="Reference tail only" else "classic_public"
                        if hist[col].notna().sum()<3:col="classic_ref"
                else:
                        col="neo_proxy" if mode=="OECD PTI-normalized proxy" else "neo_ref"
                        if hist[col].notna().sum()<3:col="neo_ref"
                use=hist.dropna(subset=[col])
                if use.empty:continue
                fig.add_trace(go.Scatter(x=use["date"],y=use[col],name=country,mode="lines",line=dict(color=palette[idx%len(palette)],width=2.4),hovertemplate=f"%{{x|%Y-%m-%d}}<br>{country}: %{{y:.2f}}<extra></extra>"))
        fig.update_layout(height=430,margin=dict(l=45,r=25,t=25,b=50),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed"),hovermode="x unified",legend=dict(orientation="h",y=-.20),xaxis=dict(showgrid=True,gridcolor="rgba(130,150,170,.17)",rangeselector=dict(buttons=_v29_range_buttons(),bgcolor="#091725",activecolor="#c4a62f",font=dict(color="#dce5ed",size=9))),yaxis=dict(title="Index points",showgrid=True,gridcolor="rgba(130,150,170,.17)"))
        return fig


def _v31_public_audit(countries: List[str]) -> pd.DataFrame:
        rows=[]
        for country in countries:
                _,s=_v31_build_misery(country);meta=V30_MISERY_REFERENCE[country]
                rows.append({
                        "Country":country,"Tier":s["quality_tier"],"Public Classic":s["public_classic_latest"],
                        "Public date":s["public_classic_date"],"Reference Classic":float(meta["classic"]),
                        "Difference":s["classic_delta"],"Public frequency":s["classic_frequency"],
                        "Housing history":s["housing_provider"],
                })
        return pd.DataFrame(rows)


