def _macro_hub_init_state_v32() -> None:
    if MACRO_HUB_SECTION_KEY not in st.session_state:
        st.session_state[MACRO_HUB_SECTION_KEY] = "Economy"
    if MARKET_PAGE_KEY not in st.session_state:
        st.session_state[MARKET_PAGE_KEY] = "fixed-income"
    if "market_subpage" not in st.session_state:
        st.session_state["market_subpage"] = "overview"
    if "market_focus" not in st.session_state:
        st.session_state["market_focus"] = "US"
    if "market_window" not in st.session_state:
        st.session_state["market_window"] = "5Y"
    if "market_view" not in st.session_state:
        st.session_state["market_view"] = "Level"
    if "market_quality_mode" not in st.session_state:
        st.session_state["market_quality_mode"] = "Standard"


def _macro_hub_rerun_v32() -> None:
    try:
        st.rerun()
    except Exception:
        try:
            st.experimental_rerun()
        except Exception:
            pass


def _macro_hub_open_economy_v32(page: str) -> None:
    st.session_state[MACRO_HUB_SECTION_KEY] = "Economy"
    st.session_state["macro_v12_page"] = _v12_normalize_page(page)
    st.session_state["macro_v12_route"] = "overview"
    st.session_state["macro_v12_bank_view"] = "overview"
    _macro_hub_rerun_v32()


def _macro_hub_open_market_v32(page: str) -> None:
    valid = {key for key, _ in _MACRO_HUB_MARKET_PAGES_V32}
    page = str(page or "fixed-income").strip().lower()
    if page not in valid:
        page = "fixed-income"
    st.session_state[MACRO_HUB_SECTION_KEY] = "Markets"
    st.session_state[MARKET_PAGE_KEY] = page
    st.session_state["market_subpage"] = "overview"
    _macro_hub_rerun_v32()


def _macro_hub_label_v32(items, active_key: str, default: str) -> str:
    for key, label in items:
        if str(key) == str(active_key):
            return str(label)
    return default


