def _macro_hub_render_popovers_v32(active_section: str, economy_page: str, market_page: str) -> None:
    economy_items = _macro_hub_economy_items_v32()
    market_items = list(_MACRO_HUB_MARKET_PAGES_V32)
    economy_label = _macro_hub_label_v32(economy_items, economy_page, "Central Banks")
    market_label = _macro_hub_label_v32(market_items, market_page, "Fixed Income")

    _v16_html(
        '<div class="mhub-wrap"><div class="mhub-brand">'
        '<div class="mhub-title">JARVIS Intelligence Hub<small>Macro · Policy · Cross-Asset</small></div>'
        f'<div class="mhub-state">{_v16_esc(MACRO_HUB_VERSION)} · active { _v16_esc(active_section) }</div>'
        '</div></div>'
    )

    c1, c2, c3 = st.columns([1.0, 1.0, 3.0], gap="small")
    popover_available = hasattr(st, "popover")

    if popover_available:
        with c1:
            with st.popover(
                f"Economy  ·  {economy_label}" if active_section == "Economy" else "Economy",
                use_container_width=True,
            ):
                st.markdown('<div class="mhub-menu">', unsafe_allow_html=True)
                for key, label in economy_items:
                    marker = "● " if active_section == "Economy" and key == economy_page else ""
                    if st.button(
                        marker + label,
                        key=f"mhub_v32_economy_{key}",
                        use_container_width=True,
                    ):
                        _macro_hub_open_economy_v32(key)
                st.markdown('</div>', unsafe_allow_html=True)
        with c2:
            with st.popover(
                f"Markets  ·  {market_label}" if active_section == "Markets" else "Markets",
                use_container_width=True,
            ):
                st.markdown('<div class="mhub-menu">', unsafe_allow_html=True)
                for key, label in market_items:
                    marker = "● " if active_section == "Markets" and key == market_page else ""
                    if st.button(
                        marker + label,
                        key=f"mhub_v32_market_{key}",
                        use_container_width=True,
                    ):
                        _macro_hub_open_market_v32(key)
                st.markdown('</div>', unsafe_allow_html=True)
    else:
        # Compatibility fallback for older Streamlit versions.
        with c1:
            economy_keys = [key for key, _ in economy_items]
            selected_economy = st.selectbox(
                "Economy",
                economy_keys,
                index=economy_keys.index(economy_page) if economy_page in economy_keys else 0,
                format_func=lambda x: _macro_hub_label_v32(economy_items, x, x),
                key="mhub_v32_economy_fallback",
            )
            if active_section == "Economy" and selected_economy != economy_page:
                _macro_hub_open_economy_v32(selected_economy)
        with c2:
            market_keys = [key for key, _ in market_items]
            selected_market = st.selectbox(
                "Markets",
                market_keys,
                index=market_keys.index(market_page) if market_page in market_keys else 0,
                format_func=lambda x: _macro_hub_label_v32(market_items, x, x),
                key="mhub_v32_market_fallback",
            )
            if active_section == "Markets" and selected_market != market_page:
                _macro_hub_open_market_v32(selected_market)
        with c3:
            switch = st.radio(
                "Active desk",
                ["Economy", "Markets"],
                horizontal=True,
                index=0 if active_section == "Economy" else 1,
                key="mhub_v32_section_fallback",
            )
            if switch != active_section:
                if switch == "Economy":
                    _macro_hub_open_economy_v32(selected_economy)
                else:
                    _macro_hub_open_market_v32(selected_market)

    with c3:
        _v16_html(
            '<div class="mhub-active"><span class="mhub-dot"></span>'
            f'<b>{_v16_esc(active_section)}</b> · '
            f'{_v16_esc(economy_label if active_section == "Economy" else market_label)}'
            '</div>'
        )


def _macro_hub_render_economy_v32(
    ticker: str,
    price_data,
    analysis=None,
) -> None:
    """Exact V27/V31 Economy loading contract, without the former button row."""
    page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
    selected_code = str(st.session_state.get("macro_v12_bank", "FED")).upper().strip()
    if selected_code not in G10_BANKS_V6:
        selected_code = "FED"
        st.session_state["macro_v12_bank"] = selected_code
    if page != "central-banks":
        st.session_state["macro_v12_route"] = "overview"

    with st.spinner("Loading macro desk data…"):
        try:
            pack = build_macro_pack_cached("2000-01-01", True)
        except Exception:
            pack = {}
        try:
            proxy_pack = fetch_market_proxy_pack("2y")
        except Exception:
            proxy_pack = {}
        try:
            indicator_df = compute_indicator_table(pack)
        except Exception:
            indicator_df = pd.DataFrame()
        try:
            policy_pack = _v19_merge_pack(pack, _v19_load_policy_pack("1990-01-01"))
        except Exception:
            policy_pack = pack
        try:
            bank_df = _v19_bank_df(policy_pack)
        except Exception:
            bank_df = pd.DataFrame()

    _v16_html('<div class="m16-shell">')
    try:
        _v16_render_page(page, selected_code, policy_pack, proxy_pack, indicator_df, bank_df)
        _v16_html(
            '<div class="m16-footer">Macro V31 frozen · Economy routes delegated unchanged · '
            'China and Misery use the V31 integrity layer.</div>'
        )
    finally:
        _v16_html('</div>')


def _macro_hub_render_markets_v32(
    ticker: str,
    price_data,
    analysis=None,
) -> None:
    try:
        from market_intelligence import render_market_intelligence
    except Exception as exc:
        _v16_html(
            '<div class="m16-warning"><b>Markets module unavailable.</b><br>'
            'Place <code>market_intelligence.py</code> beside '
            '<code>macro_central_bank.py</code>.<br>'
            f'Import error: {_v16_esc(exc)}</div>'
        )
        return

    render_market_intelligence(
        ticker=ticker,
        price_data=price_data,
        analysis=analysis,
    )


def render_macro_central_bank_lab(ticker: str, price_data, analysis=None) -> None:
    """V32 final public entry point — Economy and Markets inside one Macro mode."""
    ticker = str(ticker or "").upper().strip()
    analysis = analysis or {}

    # Preserve every CSS/state dependency required by the frozen V31 pages.
    _v12_css()
    _v13_css()
    _v14_css()
    _v15_css()
    _v16_css()
    _v17_css()
    _v18_css()
    _v19_css()
    _v20_css()
    _v21_css()
    _v22_css()
    _v23_css()
    _v24_css()
    _v25_css()
    _v12_init_state()
    _macro_hub_init_state_v32()
    _macro_hub_css_v32()

    section = str(st.session_state.get(MACRO_HUB_SECTION_KEY, "Economy"))
    if section not in {"Economy", "Markets"}:
        section = "Economy"
        st.session_state[MACRO_HUB_SECTION_KEY] = section

    economy_page = _v12_normalize_page(st.session_state.get("macro_v12_page", "central-banks"))
    market_page = str(st.session_state.get(MARKET_PAGE_KEY, "fixed-income"))

    _macro_hub_render_popovers_v32(section, economy_page, market_page)

    if section == "Markets":
        _macro_hub_render_markets_v32(ticker, price_data, analysis)
    else:
        _macro_hub_render_economy_v32(ticker, price_data, analysis)


